    def _add_legacy_stl_placement_controls(self, plotter, positions: dict[str, object]) -> None:
        controls = (
            ("Fit+Z", lambda _state: self._legacy_3d_stl_fit_axis(plotter, "+Z")),
            ("Fit+X", lambda _state: self._legacy_3d_stl_fit_axis(plotter, "+X")),
            ("Fit+Y", lambda _state: self._legacy_3d_stl_fit_axis(plotter, "+Y")),
            ("X-90", lambda _state: self._legacy_3d_stl_rotate(plotter, "x", -90.0)),
            ("X+90", lambda _state: self._legacy_3d_stl_rotate(plotter, "x", 90.0)),
            ("Y-90", lambda _state: self._legacy_3d_stl_rotate(plotter, "y", -90.0)),
            ("Y+90", lambda _state: self._legacy_3d_stl_rotate(plotter, "y", 90.0)),
            ("Center", lambda _state: self._legacy_3d_stl_center_xy(plotter)),
            ("Front", lambda _state: self._legacy_3d_stl_front_on_row(plotter)),
            ("Done2D", lambda _state: self._legacy_3d_finish_stl_placement(plotter)),
        )
        for label, callback in controls:
            if label not in positions:
                continue
            self._add_legacy_3d_action_button(
                plotter,
                label=label,
                position=positions[label],
                callback=callback,
                color="#0891b2" if label != "Done2D" else "#0f766e",
            )

    def _legacy_3d_start_stl_placement(self, plotter, row_index: int) -> None:
        if plotter is None:
            return
        try:
            row_index = int(row_index)
        except Exception:
            self.status_var.set("Select an optical STL row first.")
            return
        if self._file_backed_stl_row_at(row_index) is None:
            self.status_var.set("Selected row is not a file-backed optical STL solid.")
            return
        setattr(plotter, "_kraken_stl_placement_row", row_index)
        self._select_table_row(row_index)
        self._legacy_3d_set_selected_row(plotter, row_index)
        self.status_var.set(f"Legacy 3D STL placement target S{row_index}. Use the STL buttons, then Done2D or close.")

    def _legacy_3d_active_stl_row(self, plotter) -> int | None:
        if plotter is None:
            self.status_var.set("Open 3D view before STL placement.")
            return None
        for candidate in (
            getattr(plotter, "_kraken_stl_placement_row", None),
            getattr(plotter, "_kraken_selected_row", None),
            self._current_selected_row_index(),
        ):
            if candidate is None:
                continue
            try:
                row_index = int(candidate)
            except Exception:
                continue
            if self._file_backed_stl_row_at(row_index) is not None:
                setattr(plotter, "_kraken_stl_placement_row", row_index)
                return row_index
        self.status_var.set("Select an optical STL row before using STL controls.")
        return None

    def _legacy_3d_stl_fit_axis(self, plotter, axis: str) -> None:
        row_index = self._legacy_3d_active_stl_row(plotter)
        if row_index is None:
            return
        try:
            self.apply_stl_axis_fit(row_index, axis)
            self._legacy_3d_update_stl_row_actor(plotter, row_index)
            self.status_var.set(f"STL S{row_index}: fitted {axis} to layout +Z.")
        except Exception as exc:
            self.status_var.set(f"STL fit failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy STL fit failed: {exc}")

    def _legacy_3d_stl_rotate(self, plotter, axis: str, delta_deg: float) -> None:
        row_index = self._legacy_3d_active_stl_row(plotter)
        if row_index is None:
            return
        try:
            self.rotate_stl_row_pose(row_index, axis, delta_deg)
            self._legacy_3d_update_stl_row_actor(plotter, row_index)
            self.status_var.set(f"STL S{row_index}: rotated {axis.upper()} {float(delta_deg):+.0f} deg.")
        except Exception as exc:
            self.status_var.set(f"STL rotation failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy STL rotation failed: {exc}")

    def _legacy_3d_stl_center_xy(self, plotter) -> None:
        row_index = self._legacy_3d_active_stl_row(plotter)
        if row_index is None:
            return
        try:
            self.center_stl_row_xy(row_index)
            self._legacy_3d_update_stl_row_actor(plotter, row_index)
            self.status_var.set(f"STL S{row_index}: centered X/Y.")
        except Exception as exc:
            self.status_var.set(f"STL centering failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy STL centering failed: {exc}")

    def _legacy_3d_stl_front_on_row(self, plotter) -> None:
        row_index = self._legacy_3d_active_stl_row(plotter)
        if row_index is None:
            return
        try:
            self.place_stl_row_front_on_station(row_index)
            self._legacy_3d_update_stl_row_actor(plotter, row_index)
            self.status_var.set(f"STL S{row_index}: min Z placed on row plane.")
        except Exception as exc:
            self.status_var.set(f"STL front placement failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy STL front placement failed: {exc}")

    def _legacy_3d_finish_stl_placement(self, plotter) -> None:
        if plotter is not None:
            setattr(plotter, "_kraken_stl_placement_dirty", False)
        try:
            self.refresh_plot(suppress_analysis=True)
            self.status_var.set("STL placement applied to 2D layout.")
        except Exception as exc:
            self.status_var.set(f"STL placement saved; 2D refresh failed: {_short_error_message(exc)}")
            self.append_debug(f"Legacy STL Done2D failed: {exc}")

    def _legacy_3d_update_stl_row_actor(self, plotter, row_index: int) -> None:
        if plotter is None or pv is None:
            return
        selected = self._file_backed_stl_row_at(row_index)
        if selected is None:
            raise RuntimeError("Selected row is not a file-backed optical STL solid")
        row, path = selected
        mesh = pv.read(path).extract_surface(algorithm="dataset_surface").copy(deep=True)
        pts = np.asarray(mesh.points, dtype=float)
        if pts.ndim != 2 or pts.shape[0] == 0 or pts.shape[1] < 3:
            raise RuntimeError("STL mesh has no previewable points")
        rotation = _rotation_matrix_from_kraken_tilts(row.tilt_x, row.tilt_y, row.tilt_z)
        transformed = pts[:, :3] @ rotation.T
        transformed[:, 0] += float(row.desp_x)
        transformed[:, 1] += float(row.desp_y)
        transformed[:, 2] += self._stl_row_z_station(row_index) + float(row.desp_z)
        mesh.points = transformed

        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        row_actor_map = scene_info.setdefault("row_actor_map", {})
        actor_row_map = scene_info.setdefault("actor_row_map", {})
        for actor in list(row_actor_map.get(int(row_index), []) or []):
            try:
                actor_key = Kraken3DInspector._actor_key(actor)
                if actor_key is not None:
                    actor_row_map.pop(actor_key, None)
                plotter.remove_actor(actor, render=False)
            except Exception:
                try:
                    actor.SetVisibility(False)
                except Exception:
                    pass

        new_actors = []
        actor = plotter.add_mesh(
            mesh,
            color="#0ccfe8",
            opacity=0.68,
            smooth_shading=True,
            show_edges=False,
            pickable=True,
        )
        self._legacy_3d_register_row_actor(actor, int(row_index), actor_row_map, new_actors)
        try:
            edges = mesh.extract_feature_edges(
                feature_angle=15,
                boundary_edges=True,
                feature_edges=True,
                manifold_edges=False,
            )
            if int(getattr(edges, "n_points", 0)) > 0:
                edge_actor = plotter.add_mesh(edges, color="#1f2937", line_width=1.0, pickable=False)
                self._legacy_3d_register_row_actor(edge_actor, int(row_index), actor_row_map, new_actors)
        except Exception:
            pass
        row_actor_map[int(row_index)] = new_actors
        setattr(plotter, "_kraken_scene", scene_info)
        setattr(plotter, "_kraken_stl_placement_row", int(row_index))
        setattr(plotter, "_kraken_stl_placement_dirty", True)
        setattr(plotter, "_kraken_selected_row", None)
        self._legacy_3d_set_selected_row(plotter, int(row_index))
        try:
            plotter.render()
        except Exception:
            pass

    @staticmethod
    def _legacy_3d_register_row_actor(actor, row_index: int, actor_row_map: dict, row_actors: list) -> None:
        if actor is None:
            return
        try:
            actor.SetPickable(True)
        except Exception:
            pass
        actor_key = Kraken3DInspector._actor_key(actor)
        if actor_key is not None:
            actor_row_map[actor_key] = int(row_index)
        try:
            prop = actor.GetProperty()
            if prop is not None:
                actor._kraken_base_style = {
                    "edge_visibility": int(prop.GetEdgeVisibility()),
                    "line_width": float(prop.GetLineWidth()),
                    "edge_color": tuple(float(v) for v in prop.GetEdgeColor()),
                    "opacity": float(prop.GetOpacity()),
                    "ambient": float(prop.GetAmbient()),
                    "diffuse": float(prop.GetDiffuse()),
                }
        except Exception:
            pass
        row_actors.append(actor)

    @staticmethod
    def _legacy_3d_control_positions(plotter) -> dict[str, object]:
        try:
            width = int(plotter.window_size[0])
        except Exception:
            width = 1200
        # Use the full lower edge and reserve a left gutter for category names.
        category_x = 18
        start_x = 118 if width >= 900 else 96
        right_margin = 110
        rows = [
            ("View", ["Save", "Close", "Iso", "YZ", "XZ", "Top", "Bottom", "Home"], "#334155"),
            ("Show/CAD", ["Rays", "Mirrors", "Lenses", "Helpers", "Full Pupil", "Lens CAD", "LED CAD", "Cam CAD"], "#0f766e"),
            ("STEP", ["Z -90", "Z +90", "X 180", "Axis LED", "Obj-LED", "Axis Cam", "Axis Lens", "Clear Axis"], "#7c3aed"),
            ("STL", ["Fit+Z", "Fit+X", "Fit+Y", "X-90", "X+90", "Y-90", "Y+90", "Center", "Front", "Done2D"], "#0891b2"),
        ]
        y_positions = [12, 50, 88, 126]
        positions: dict[str, object] = {"__categories__": []}
        usable = max(width - start_x - right_margin, 480)
        for (category, row, color), y_pos in zip(rows, y_positions):
            positions["__categories__"].append((category, (category_x, y_pos + 4), color))
            step_x = max(int(usable / max(len(row) - 1, 1)), 96)
            for index, label in enumerate(row):
                positions[label] = (start_x + int(index * step_x), y_pos)
        return positions

    def _enable_legacy_3d_close_handling(self, plotter) -> None:
        def request_close(*_args):
            try:
                self.after(0, self._close_legacy_3d_plotter)
            except Exception:
                self._close_legacy_3d_plotter()

        try:
            if getattr(plotter, "iren", None) is not None:
                plotter.iren.add_observer("ExitEvent", request_close)
        except Exception as exc:
            self.append_debug(f"Legacy 3D close observer unavailable: {exc}")
        try:
            if getattr(plotter, "render_window", None) is not None:
                plotter.render_window.AddObserver("DeleteEvent", request_close)
        except Exception:
            pass

    def _enable_legacy_3d_picking(self, plotter) -> None:
        if vtkCellPicker is None or getattr(plotter, "iren", None) is None:
            return
        try:
            picker = vtkCellPicker()
            picker.SetTolerance(0.0015)
            setattr(plotter, "_kraken_picker", picker)
            setattr(plotter, "_kraken_selected_row", None)
            setattr(plotter, "_kraken_selected_ray", None)
            plotter.iren.add_observer(
                "LeftButtonPressEvent",
                lambda *_args: self._legacy_3d_pick_click(plotter),
            )
            plotter.iren.add_observer(
                "MouseMoveEvent",
                lambda *_args: self._legacy_3d_hover_move(plotter),
            )
        except Exception as exc:
            self.append_debug(f"Legacy 3D picking unavailable: {exc}")

    def _legacy_3d_hover_move(self, plotter) -> None:
        requested_label = self._cad_axis_pick_label
        led_edge_pick = bool(getattr(self, "_cad_led_object_edge_pick", False))
        target_label = "led" if led_edge_pick else requested_label
        if target_label is None:
            self._legacy_3d_set_step_hover_outline(plotter, None, None)
            self._legacy_3d_set_cursor(plotter, False)
            return
        picker = getattr(plotter, "_kraken_picker", None)
        if picker is None or getattr(plotter, "iren", None) is None:
            return
        try:
            x, y = plotter.iren.get_event_position()
            renderer = plotter.iren.get_poked_renderer(x, y)
            if renderer is None:
                renderer = getattr(plotter, "renderer", None)
            if renderer is None:
                return
            picker.Pick(x, y, 0.0, renderer)
            actor = picker.GetActor()
        except Exception:
            actor = None
        actor_key = Kraken3DInspector._actor_key(actor)
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        step_label = scene_info.get("cad_step_actor_map", {}).get(actor_key) if actor_key is not None else None
        if step_label == target_label:
            try:
                cell_id = int(picker.GetCellId())
            except Exception:
                cell_id = -1
            hover_key = (actor_key, cell_id)
            outline = None
            if hover_key != getattr(plotter, "_kraken_step_hover_key", None):
                feature = Kraken3DInspector._picked_feature_info(actor, picker)
                outline = Kraken3DInspector._hover_overlay_for_feature(feature[0], feature[1]) if feature is not None else None
            self._legacy_3d_set_step_hover_outline(plotter, outline, hover_key)
            self._legacy_3d_set_cursor(plotter, True)
            if led_edge_pick:
                self.status_var.set("Click orange LED edge used for Object-to-LED distance.")
            else:
                self.status_var.set(f"Click orange {step_label} edge/feature to align optical axis.")
            return
        self._legacy_3d_set_step_hover_outline(plotter, None, None)
        self._legacy_3d_set_cursor(plotter, False)

    def _legacy_3d_set_step_hover_outline(self, plotter, outline_mesh, hover_key) -> None:
        if hover_key is not None and hover_key == getattr(plotter, "_kraken_step_hover_key", None):
            return
        previous = getattr(plotter, "_kraken_step_hover_outline_actor", None)
        if previous is not None:
            try:
                plotter.remove_actor(previous, render=False)
            except Exception:
                try:
                    previous.SetVisibility(False)
                except Exception:
                    pass
        setattr(plotter, "_kraken_step_hover_outline_actor", None)
        setattr(plotter, "_kraken_step_hover_key", hover_key)
        if outline_mesh is not None and int(getattr(outline_mesh, "n_points", 0)) > 0:
            try:
                actor = plotter.add_mesh(
                    outline_mesh,
                    color="#ff2d00",
                    line_width=9.0,
                    opacity=1.0,
                    lighting=False,
                    ambient=1.0,
                    render_lines_as_tubes=True,
                    pickable=False,
                )
                try:
                    actor.SetPickable(False)
                except Exception:
                    pass
                setattr(plotter, "_kraken_step_hover_outline_actor", actor)
            except Exception as exc:
                self.append_debug(f"3D STEP hover outline failed: {exc}")
        try:
            plotter.render()
        except Exception:
            pass

    @staticmethod
    def _legacy_3d_set_cursor(plotter, hand: bool) -> None:
        try:
            if getattr(plotter, "iren", None) is not None and getattr(plotter.iren, "interactor", None) is not None:
                cursor = 9 if hand else 0
                plotter.iren.interactor.SetCurrentCursor(cursor)
                try:
                    render_window = plotter.iren.interactor.GetRenderWindow()
                    if render_window is not None:
                        render_window.SetCurrentCursor(cursor)
                except Exception:
                    pass
        except Exception:
            pass

    def _legacy_3d_pick_click(self, plotter) -> None:
        picker = getattr(plotter, "_kraken_picker", None)
        if picker is None or getattr(plotter, "iren", None) is None:
            return
        try:
            x, y = plotter.iren.get_event_position()
            renderer = plotter.iren.get_poked_renderer(x, y)
            if renderer is None:
                renderer = getattr(plotter, "renderer", None)
            if renderer is None:
                return
            picker.Pick(x, y, 0.0, renderer)
            actor = picker.GetActor()
        except Exception as exc:
            self.append_debug(f"Legacy 3D pick failed: {exc}")
            return
        actor_key = Kraken3DInspector._actor_key(actor)
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        step_label = scene_info.get("cad_step_actor_map", {}).get(actor_key) if actor_key is not None else None
        if step_label is not None:
            if self._cad_led_object_edge_pick:
                if step_label != "led":
                    self.status_var.set("Pick an edge on the LED STEP for Object-to-LED distance.")
                    return
                feature = Kraken3DInspector._picked_feature_info(actor, picker)
                if feature is None:
                    try:
                        center = np.asarray(picker.GetPickPosition(), dtype=float)
                    except Exception:
                        center = None
                else:
                    center = feature[0]
                if center is None or center.size < 3 or not np.all(np.isfinite(center[:3])):
                    self.status_var.set("Could not detect LED object-edge center.")
                    return
                self._legacy_3d_set_step_hover_outline(plotter, None, None)
                self._legacy_3d_set_cursor(plotter, False)
                self.apply_led_object_edge_pick(center[:3])
                return
            requested_label = self._cad_axis_pick_label
            if requested_label is None:
                self.select_step_component(step_label)
                self._legacy_3d_set_selected_step(plotter, step_label)
                return
            if requested_label != step_label:
                self.status_var.set(f"CAD STEP picked: {step_label}. Click Axis LED/Cam/Lens first.")
                return
            feature = Kraken3DInspector._picked_feature_info(actor, picker)
            if feature is None:
                try:
                    center = np.asarray(picker.GetPickPosition(), dtype=float)
                except Exception:
                    center = None
            else:
                center = feature[0]
            if center is None or center.size < 3 or not np.all(np.isfinite(center[:3])):
                self.status_var.set(f"Could not detect {step_label} feature center.")
                return
            self._legacy_3d_set_step_hover_outline(plotter, None, None)
            self._legacy_3d_set_cursor(plotter, False)
            self.apply_step_axis_pick(step_label, center[:3])
            return
        row_index = scene_info.get("actor_row_map", {}).get(actor_key) if actor_key is not None else None
        ray_index = scene_info.get("actor_ray_map", {}).get(actor_key) if actor_key is not None else None
        if ray_index is not None:
            self._legacy_3d_set_selected_row(plotter, None)
            self._legacy_3d_set_selected_ray(plotter, int(ray_index))
            self._select_ray_inspector_ray(int(ray_index))
            self.status_var.set(f"3D selected ray {int(ray_index)} in Ray Inspector.")
            return
        if row_index is None:
            self._legacy_3d_set_selected_row(plotter, None)
            self._legacy_3d_set_selected_ray(plotter, None)
            self.status_var.set("3D view ready")
            return
        self._legacy_3d_set_selected_row(plotter, int(row_index))
        self._legacy_3d_set_selected_ray(plotter, None)
        self._select_table_row(int(row_index))
        row_name = self.rows[int(row_index)].name if 0 <= int(row_index) < len(self.rows) else "Surface"
        if self._file_backed_stl_row_at(int(row_index)) is not None:
            setattr(plotter, "_kraken_stl_placement_row", int(row_index))
            self.status_var.set(f"3D selected STL row {int(row_index)}: {row_name}. Use the STL buttons, then Done2D or close.")
        else:
            self.status_var.set(f"3D selected row {int(row_index)}: {row_name}")

    def _legacy_3d_set_selected_row(self, plotter, row_index: int | None) -> None:
        current = getattr(plotter, "_kraken_selected_row", None)
        if current == row_index:
            return
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        row_actor_map = dict(scene_info.get("row_actor_map", {}) or {})
        if current is not None:
            for actor in row_actor_map.get(int(current), []):
                self._legacy_3d_set_actor_highlight(actor, False)
        if row_index is not None:
            for actor in row_actor_map.get(int(row_index), []):
                self._legacy_3d_set_actor_highlight(actor, True)
        setattr(plotter, "_kraken_selected_row", row_index)
        try:
            plotter.render()
        except Exception:
            pass

    def _legacy_3d_set_selected_ray(self, plotter, ray_index: int | None) -> None:
        current = getattr(plotter, "_kraken_selected_ray", None)
        if current == ray_index:
            return
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        ray_actor_map = dict(scene_info.get("ray_actor_map", {}) or {})
        if current is not None:
            for actor in ray_actor_map.get(int(current), []):
                Kraken3DInspector._set_ray_actor_selected(actor, False)
        if ray_index is not None:
            for actor in ray_actor_map.get(int(ray_index), []):
                Kraken3DInspector._set_ray_actor_selected(actor, True)
        setattr(plotter, "_kraken_selected_ray", ray_index)
        try:
            plotter.render()
        except Exception:
            pass

    def _legacy_3d_set_selected_step(self, plotter, label: str | None) -> None:
        label = str(label).strip().lower() if label is not None else None
        if label not in {"lens", "led", "camera"}:
            label = None
        current = getattr(plotter, "_kraken_selected_step", None)
        if current == label:
            return
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        cad_step_actors = dict(scene_info.get("cad_step_actors", {}) or {})
        if current is not None:
            for _kind, actor in list(cad_step_actors.get(current, []) or []):
                Kraken3DInspector._set_step_actor_selected(actor, False)
        if label is not None:
            for _kind, actor in list(cad_step_actors.get(label, []) or []):
                Kraken3DInspector._set_step_actor_selected(actor, True)
        setattr(plotter, "_kraken_selected_step", label)
        try:
            plotter.render()
        except Exception:
            pass

    @staticmethod
    def _legacy_3d_set_actor_highlight(actor, selected: bool) -> None:
        if actor is None:
            return
        try:
            prop = actor.GetProperty()
        except Exception:
            return
        if prop is None:
            return
        base = getattr(actor, "_kraken_base_style", None)
        if not isinstance(base, dict):
            try:
                base = {
                    "edge_visibility": int(prop.GetEdgeVisibility()),
                    "line_width": float(prop.GetLineWidth()),
                    "edge_color": tuple(float(v) for v in prop.GetEdgeColor()),
                    "opacity": float(prop.GetOpacity()),
                    "ambient": float(prop.GetAmbient()),
                    "diffuse": float(prop.GetDiffuse()),
                }
                actor._kraken_base_style = base
            except Exception:
                base = {}
        if selected:
            try:
                prop.SetEdgeVisibility(1)
                prop.SetEdgeColor(1.0, 0.45, 0.05)
                prop.SetLineWidth(max(float(base.get("line_width", 1.0)), 2.5))
                prop.SetOpacity(min(max(float(base.get("opacity", 1.0)), 0.3) + 0.08, 1.0))
                prop.SetAmbient(max(float(base.get("ambient", 0.0)), 0.18))
            except Exception:
                return
            return
        try:
            prop.SetEdgeVisibility(int(base.get("edge_visibility", 0)))
            edge_color = tuple(base.get("edge_color", (0.0, 0.0, 0.0)))
            if len(edge_color) == 3:
                prop.SetEdgeColor(*edge_color)
            prop.SetLineWidth(float(base.get("line_width", 1.0)))
            prop.SetOpacity(float(base.get("opacity", 1.0)))
            prop.SetAmbient(float(base.get("ambient", 0.0)))
            prop.SetDiffuse(float(base.get("diffuse", 1.0)))
        except Exception:
            pass

    def _add_legacy_3d_action_button(
        self,
        plotter,
        *,
        label: str,
        position: tuple[int, int],
        callback,
        value: bool = False,
        color: str = "#2563eb",
    ) -> None:
        plotter.add_checkbox_button_widget(
            callback,
            value=value,
            position=position,
            size=22,
            border_size=3,
            color_on=color,
            color_off=color,
            background_color="white",
        )
        plotter.add_text(
            label,
            position=(position[0] + 28, position[1] + 1),
            font_size=9,
            color="black",
        )

    def _legacy_3d_set_actor_visibility(self, actors, visible: bool, plotter, group: str | None = None) -> None:
        if group:
            state = dict(getattr(plotter, "_kraken_visibility", {}) or {})
            state[group] = bool(visible)
            setattr(plotter, "_kraken_visibility", state)
        for actor in actors:
            try:
                actor.SetVisibility(bool(visible))
            except Exception:
                continue
        plotter.render()

    def _legacy_3d_set_scene_actor_visibility(self, plotter, actor_key: str, visible: bool, group: str) -> None:
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        self._legacy_3d_set_actor_visibility(scene_info.get(actor_key, []) or [], visible, plotter, group)

    def _legacy_3d_set_step_visibility(self, plotter, label: str, visible: bool) -> None:
        label = str(label).strip().lower()
        if label not in {"lens", "led", "camera"}:
            return
        state = dict(getattr(plotter, "_kraken_visibility", {}) or {})
        state[f"step_{label}"] = bool(visible)
        setattr(plotter, "_kraken_visibility", state)
        scene_info = dict(getattr(plotter, "_kraken_scene", {}) or {})
        actors = list(scene_info.get("cad_step_actors", {}).get(label, []) or [])
        for _kind, actor in actors:
            try:
                actor.SetVisibility(bool(visible))
            except Exception:
                continue
        if not visible and self._selected_step_label == label:
            self._legacy_3d_set_selected_step(plotter, None)
            self._selected_step_label = None
        self.status_var.set(f"{label.upper()} STEP {'shown' if visible else 'hidden'}.")
        try:
            plotter.render()
        except Exception:
            pass

    def _legacy_3d_toggle_full_pupil(self, plotter, state: bool) -> None:
        """Toggle full-pupil ray mode and retrace.

        Only the ray actors are swapped — buttons / lens / mirror actors stay
        put. Rebuilding the entire scene used to stack a fresh Full Pupil
        checkbox on top of the previous one each click, which made the toggle
        appear to be one-way (ON → ON → ON…).
        """
        # PyVista fires the callback on widget creation with the initial value.
        # Skip the no-op so we don't retrace on startup.
        if bool(state) == self._is_full_pupil_mode():
            return
        self.emit_full_ray_var.set(bool(state))
        try:
            self._legacy_3d_replace_rays(plotter)
        except Exception as exc:
            self.append_debug(f"Full Pupil refresh failed: {exc}")

    def _legacy_3d_replace_rays(self, plotter) -> None:
        """Rebuild only the ray actors in the existing 3D scene, in place."""
        scene_info = getattr(plotter, "_kraken_scene", None)
        if not isinstance(scene_info, dict):
            scene_info = {}
            setattr(plotter, "_kraken_scene", scene_info)
        ray_actors = scene_info.setdefault("ray_actors", [])
        for actor in list(ray_actors):
            try:
                plotter.renderer.RemoveActor(actor)
            except Exception:
                pass
        ray_actors.clear()
        scene_info["actor_ray_map"] = {}
        scene_info["ray_actor_map"] = {}
        setattr(plotter, "_kraken_selected_ray", None)
        system, rays = self._build_preview_system_and_rays()
        scene_bundle = self._last_scene_bundle
        setattr(plotter, "_kraken_system", system)
        setattr(plotter, "_kraken_rays", rays)
        setattr(plotter, "_kraken_scene_bundle", scene_bundle)
        rays_visible = bool(dict(getattr(plotter, "_kraken_visibility", {}) or {}).get("rays", True))
        for ray_index, color, ray_pts in self._iter_3d_scene_ray_items(rays, scene_bundle):
            try:
                line = pv.lines_from_points(ray_pts)
            except Exception:
                continue
            if int(getattr(line, "n_points", 0)) < 2:
                continue
            actor = plotter.add_mesh(
                line,
                color=color,
                opacity=0.88,
                line_width=1.0,
                pickable=True,
            )
            actor_key = Kraken3DInspector._actor_key(actor)
            if actor_key is not None:
                scene_info["actor_ray_map"][actor_key] = int(ray_index)
                scene_info["ray_actor_map"].setdefault(int(ray_index), []).append(actor)
            try:
                actor.SetPickable(True)
                prop = actor.GetProperty()
                if prop is not None:
                    actor._kraken_ray_select_style = {
                        "color": tuple(float(v) for v in prop.GetColor()),
                        "line_width": float(prop.GetLineWidth()),
                        "opacity": float(prop.GetOpacity()),
                        "ambient": float(prop.GetAmbient()),
                        "diffuse": float(prop.GetDiffuse()),
                    }
            except Exception:
                pass
            try:
                actor.SetVisibility(rays_visible)
            except Exception:
                pass
            ray_actors.append(actor)
        try:
            plotter.render()
        except Exception:
            pass

    def _save_legacy_3d_screenshot(self, plotter) -> None:
        try:
            default_name = f"kraken_3d_{time.strftime('%Y%m%d_%H%M%S')}.png"
            try:
                SCREENSHOT_DIR.mkdir(parents=True, exist_ok=True)
            except Exception:
                pass
            selected_path = filedialog.asksaveasfilename(
                parent=self,
                title="Save 3D view as PNG",
                initialdir=str(SCREENSHOT_DIR),
                initialfile=default_name,
                defaultextension=".png",
                filetypes=[("PNG image", "*.png")],
            )
            if not selected_path:
                self.status_var.set("3D PNG save cancelled")
                return
            image_path = Path(selected_path)
            system = getattr(plotter, "_kraken_system", None)
            rays = getattr(plotter, "_kraken_rays", None)
            scene_bundle = getattr(plotter, "_kraken_scene_bundle", None)
            if system is None or rays is None:
                raise RuntimeError("3D scene data unavailable for clean screenshot")
            self._last_scene_bundle = scene_bundle if isinstance(scene_bundle, SceneBundle) else self._last_scene_bundle
            clean_plotter = self._build_clean_legacy_3d_plotter(system, rays)
            clean_scene = dict(getattr(clean_plotter, "_kraken_scene", {}) or {})
            visibility = dict(getattr(plotter, "_kraken_visibility", {}) or {})
            if not visibility.get("rays", True):
                self._legacy_3d_set_actor_visibility(clean_scene.get("ray_actors", []), False, clean_plotter)
            if not visibility.get("mirrors", True):
                self._legacy_3d_set_actor_visibility(clean_scene.get("mirror_actors", []), False, clean_plotter)
            if not visibility.get("lenses", True):
                self._legacy_3d_set_actor_visibility(clean_scene.get("lens_actors", []), False, clean_plotter)
            if not visibility.get("helpers", True):
                self._legacy_3d_set_actor_visibility(clean_scene.get("helper_actors", []), False, clean_plotter)
            try:
                clean_plotter.camera_position = plotter.camera_position
                clean_plotter.camera.parallel_projection = bool(plotter.camera.parallel_projection)
                clean_plotter.camera.parallel_scale = float(plotter.camera.parallel_scale)
            except Exception:
                self._set_legacy_3d_camera(clean_plotter, "iso")
            clean_plotter.screenshot(str(image_path))
            try:
                rw = getattr(clean_plotter, "render_window", None)
                if rw is not None:
                    rw.Finalize()
                clean_plotter.close()
            except Exception:
                pass
            self.status_var.set(f"Saved 3D PNG: {image_path.name}")
            self.append_progress(f"Saved 3D PNG: {image_path}")
        except Exception as exc:
            self.append_debug(f"3D screenshot failed: {exc}")
            self.status_var.set(f"3D screenshot failed: {_short_error_message(exc)}")

    @staticmethod
    def _set_legacy_3d_camera(plotter, preset: str) -> None:
        cx, cy, cz = plotter.center
        bounds = np.asarray(plotter.bounds, dtype=float)
        span_x = float(bounds[1] - bounds[0]) if bounds.size >= 2 else 0.0
        span_y = float(bounds[3] - bounds[2]) if bounds.size >= 4 else 0.0
        span_z = float(bounds[5] - bounds[4]) if bounds.size >= 6 else 0.0
        span = max(span_x, span_y, span_z, 1.0)
        distance = max(span * 2.6, 180.0)
        try:
            width, height = plotter.window_size
            aspect = max(float(width) / max(float(height), 1.0), 0.1)
        except Exception:
            aspect = 1.4

        def orthographic_scale(horizontal_span: float, vertical_span: float) -> float:
            horizontal_scale = float(horizontal_span) / (2.0 * aspect)
            vertical_scale = float(vertical_span) * 0.5
            return max(horizontal_scale, vertical_scale, 1.0) * 1.08

        if preset == "yz":
            position = (cx - distance, cy, cz)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = orthographic_scale(span_z, span_y)
        elif preset == "top":
            # Exact top view. This used to conflict only because VTK binds the numeric `3` key to stereo.
            position = (cx, cy, cz + distance)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = orthographic_scale(span_x, span_y)
        elif preset == "bottom":
            position = (cx, cy, cz - distance)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = orthographic_scale(span_x, span_y)
        elif preset == "xz":
            position = (cx, cy + distance, cz)
            view_up = (1.0, 0.0, 0.0)
            parallel_scale = orthographic_scale(span_z, span_x)
        else:
            position = (cx - distance, cy + distance * 0.55, cz + distance * 0.75)
            view_up = (0.0, 1.0, 0.0)
            parallel_scale = None
        plotter.camera_position = [position, (cx, cy, cz), view_up]
        try:
            plotter.camera.parallel_projection = parallel_scale is not None
            if parallel_scale is not None:
                plotter.camera.parallel_scale = float(parallel_scale)
        except Exception:
            pass
        plotter.reset_camera_clipping_range()
        plotter.set_background("white", top="white")
        plotter.render()

    def _refresh_3d_inspector_if_open(self) -> None:
        if self._three_d_inspector is None:
            return
        try:
            if not self._three_d_inspector.winfo_exists():
                self._three_d_inspector = None
                return
        except Exception:
            self._three_d_inspector = None
            return
        try:
            if self.last_system is None or self.last_rays is None:
                return
            row_names = [row.name for row in self.rows]
            self._three_d_inspector.refresh_scene(
                self.last_system,
                self.last_rays,
                row_names,
                scene_bundle=self._last_scene_bundle,
                reset_camera=False,
            )
        except Exception as exc:
            self.append_debug(f"3D inspector sync failed: {exc}")

    @staticmethod
    def _flatten_table_item_args(*items: object) -> list[str]:
        flattened: list[str] = []
        for item in items:
            if item is None:
                continue
            if isinstance(item, str):
                if item:
                    flattened.append(item)
                continue
            if isinstance(item, (list, tuple, set)):
                flattened.extend(KrakenLayoutEditor._flatten_table_item_args(*item))
                continue
            text = str(item)
            if text:
                flattened.append(text)
        return flattened

    def _install_border_only_table_selection(self) -> None:
        self._native_table_selection = self.table.selection
        self._native_table_selection_set = self.table.selection_set
        self._native_table_selection_remove = self.table.selection_remove

        def selection() -> tuple[str, ...]:
            selected = tuple(item for item in self._table_selected_items if self.table.exists(item))
            if len(selected) != len(self._table_selected_items):
                self._table_selected_items = list(selected)
            return selected

        def selection_set(*items: object) -> None:
            ordered: list[str] = []
            seen: set[str] = set()
            for item in self._flatten_table_item_args(*items):
                if self.table.exists(item) and item not in seen:
                    ordered.append(item)
                    seen.add(item)
            self._table_selected_items = ordered
            self._clear_native_table_selection()
            self._schedule_custom_table_selection_changed()

        def selection_remove(*items: object) -> None:
            remove = set(self._flatten_table_item_args(*items))
            if remove:
                self._table_selected_items = [item for item in self._table_selected_items if item not in remove]
            self._clear_native_table_selection()
            self._schedule_custom_table_selection_changed()

        def selection_add(*items: object) -> None:
            selected = list(selection())
            seen = set(selected)
            for item in self._flatten_table_item_args(*items):
                if self.table.exists(item) and item not in seen:
                    selected.append(item)
                    seen.add(item)
            self._table_selected_items = selected
            self._clear_native_table_selection()
            self._schedule_custom_table_selection_changed()

        def selection_toggle(*items: object) -> None:
            selected = list(selection())
            selected_set = set(selected)
            for item in self._flatten_table_item_args(*items):
                if not self.table.exists(item):
                    continue
                if item in selected_set:
                    selected_set.remove(item)
                    selected = [candidate for candidate in selected if candidate != item]
                else:
                    selected.append(item)
                    selected_set.add(item)
            self._table_selected_items = selected
            self._clear_native_table_selection()
            self._schedule_custom_table_selection_changed()

        self.table.selection = selection  # type: ignore[method-assign]
        self.table.selection_set = selection_set  # type: ignore[method-assign]
        self.table.selection_remove = selection_remove  # type: ignore[method-assign]
        self.table.selection_add = selection_add  # type: ignore[method-assign]
        self.table.selection_toggle = selection_toggle  # type: ignore[method-assign]

    def _clear_native_table_selection(self) -> None:
        native_selection = self._native_table_selection
        native_remove = self._native_table_selection_remove
        if native_selection is None or native_remove is None:
            return
        try:
            selected = tuple(native_selection())
        except Exception:
            selected = ()
        if selected:
            try:
                native_remove(*selected)
            except Exception:
                pass

    def _schedule_custom_table_selection_changed(self) -> None:
        if self._table_selection_after_id is not None:
            return
        self._table_selection_after_id = self.after_idle(self._emit_custom_table_selection_changed)

    def _emit_custom_table_selection_changed(self) -> None:
        self._table_selection_after_id = None
        self._on_table_selection_changed()

    def _current_selected_row_index(self) -> int | None:
        items = self.table.selection()
        if not items:
            return None
        return self._table_item_row_index(items[0])

    def _on_table_selection_changed(self, _event: tk.Event | None = None) -> None:
        self._update_selection_row_borders()
        self._sync_surface_selection(self._current_selected_row_index(), from_table=True)

    def _clear_table_selection(self) -> None:
        items = list(self.table.get_children())
        if items:
            self.table.selection_remove(*items)
        self.table.focus("")
        self._active_cell = None
        self._hide_active_cell_border()
        self._clear_selection_row_borders()
        self._selection_anchor_row = None
        self._sync_surface_selection(None, from_table=True)
        self.status_var.set("No surface selected")

    def _select_table_indices(self, indices: list[int], *, focus_index: int | None = None) -> None:
        selected_items = [
            item
            for index in indices
            for item in [self._table_item_for_row_index(index)]
            if item is not None
        ]
        if not selected_items:
            return
        self.table.selection_set(selected_items)
        focus_item = self._table_item_for_row_index(focus_index) if focus_index is not None else None
        if focus_item is None:
            focus_item = selected_items[0]
        self.table.focus(focus_item)
        self.table.see(focus_item)
        self._selection_anchor_row = focus_item
        self.after_idle(self._update_active_cell_border)

    def _clear_table_selection_event(self, _event: tk.Event | None = None) -> str:
        self._clear_table_selection()
        return "break"

    def _sync_surface_selection(self, row_index: int | None, *, from_table: bool = False) -> None:
        if self._three_d_inspector is not None:
            try:
                if self._three_d_inspector.winfo_exists() and self._three_d_inspector.available:
                    self._three_d_inspector.highlight_row(row_index)
            except Exception:
                pass
        if self._legacy_3d_plotter is not None:
            try:
                self._legacy_3d_set_selected_row(self._legacy_3d_plotter, row_index)
            except Exception:
                pass
        self._update_layout_selection_overlay(row_index)
        if from_table and row_index is not None and 0 <= row_index < len(self.rows):
            self.status_var.set(f"Selected row {row_index}: {self.rows[row_index].name}")

    def _select_table_row(self, index: int) -> None:
        row_id = self._table_item_for_row_index(index)
        if row_id is None:
            return
        self.table.selection_set(row_id)
        self.table.focus(row_id)
        self.table.see(row_id)
        self._active_cell = (row_id, "#1")
        self._update_active_cell_border()
        self._sync_surface_selection(index)

    def _startup_refresh_plot(self) -> None:
        if not self.rows:
            return
        self.refresh_plot(suppress_analysis=True)

    def _load_reset_system(self) -> None:
        """Reset to a minimal Object + Image system."""
        self.rows = [
            SurfaceRow(surface="Object", name="Object", thickness=100.0, diameter=25.0, glass="AIR"),
            SurfaceRow(surface="Image", name="Image", thickness=0.0, diameter=25.0, glass="AIR"),
        ]
        self.current_layout_file = None
        self.metal_catalogs = []
        self.imported_camera_step_path = None
        self.imported_lens_step_path = None
        self.imported_led_step_path = None
        self.camera_step_rotation_x_deg = 0.0
        self.lens_step_rotation_x_deg = 0.0
        self.led_step_rotation_x_deg = 0.0
        self.camera_step_rotation_z_deg = 0.0
        self.lens_step_rotation_z_deg = 0.0
        self.led_step_rotation_z_deg = 0.0
        self.led_object_edge_distance_mm = 0.0
        self.led_step_object_edge_local_z = None
        self.lens_step_axis_offset_xy = (0.0, 0.0)
        self.camera_step_axis_offset_xy = (0.0, 0.0)
        self.led_step_axis_offset_xy = (0.0, 0.0)
        self._cad_axis_pick_label = None
        self._cad_led_object_edge_pick = False
        self._selected_step_label = None
        self._sync_table()
        self.layout_var.set("Common Optical Layout")
        self.machine_vision_var.set("Machine Vision Lens")
        self.example_var.set("Examples")
        self._apply_initial_layout_view_defaults("Reset")

    def reset_layout(self) -> None:
        """Fast UI reset: clear prescription and preview without ray tracing."""
        self._begin_history_capture()
        self._load_reset_system()
        self._commit_history_capture()
        self._clear_preview_after_reset()

    def load_layout_by_name(self, name: str, *, refresh: bool = True) -> None:
        path = self.layout_files.get(name)
        if path is None:
            return
        if self.rows:
            self._begin_history_capture()
        self.current_layout_file = path
        had_existing_rows = bool(self.rows)
        info: dict[str, object] = {"surfaces": [], "settings": {}}
        try:
            info = _load_python_data(path)
            loaded_rows = [self._row_from_layout_item(item) for item in info["surfaces"]]
        except Exception:
            surfaces = self._extract_surfaces_from_example(path)
            loaded_rows = [self._row_from_surface(surface, index, len(surfaces)) for index, surface in enumerate(surfaces)]

        loaded_rows = self._normalized_rows_copy(loaded_rows)
        self._auto_assign_missing_elements(loaded_rows)
        replace_existing = self._is_empty_starter_rows(self.rows)
        append_to_existing = (
            had_existing_rows
            and not replace_existing
            and self._is_insertable_common_layout(name, loaded_rows, info)
        )
        insert_after = self._selected_insert_index() if append_to_existing else None
        if append_to_existing:
            self.rows = self._append_layout_rows(
                self.rows,
                loaded_rows,
                insert_after=insert_after,
                element_name=name,
            )
        else:
            self.rows = loaded_rows
            self._apply_initial_field_defaults()
            self._apply_initial_layout_view_defaults(name)
            self._apply_layout_settings(info.get("settings", {}))

        self._normalize_special_rows()
        self._sync_table()
        if append_to_existing:
            self._select_inserted_layout_rows(loaded_rows, insert_after=insert_after)
        if had_existing_rows:
            self._commit_history_capture()
        if refresh:
            self.refresh_plot(suppress_analysis=True)
        if path.stem.startswith("machine_vision_"):
            self.layout_var.set("Common Optical Layout")
            self.machine_vision_var.set(name)
        else:
            self.layout_var.set(name)
            self.machine_vision_var.set("Machine Vision Lens")
        self.example_var.set("Examples")
        action = "Appended" if append_to_existing else "Loaded"
        self.status_var.set(f"{action} {name}. Click Update to run analysis.")

    @staticmethod
    def _is_insertable_common_layout(name: str, _loaded_rows: list[SurfaceRow], info: dict[str, object]) -> bool:
        settings = info.get("settings", {}) if isinstance(info, dict) else {}
        role = ""
        if isinstance(settings, dict):
            role = str(settings.get("layout_role", settings.get("load_mode", ""))).strip().lower()
        if role in {"component", "insert", "insertable"}:
            return True
        if role in {"layout", "replace", "example", "system"}:
            return False
        if name in INSERTABLE_COMMON_LAYOUT_TITLES:
            return True
        return False

    def _selected_operand_labels(self) -> list[str]:
        if not hasattr(self, "merit_mode_list"):
            return []
        return [self.merit_mode_list.get(i) for i in self.merit_mode_list.curselection()]

    def _set_selected_operand_labels(self, labels: list[str]) -> None:
        if not hasattr(self, "merit_mode_list"):
            return
        self.merit_mode_list.selection_clear(0, "end")
        wanted = {str(label) for label in labels}
        for index in range(self.merit_mode_list.size()):
            label = self.merit_mode_list.get(index)
            if label in wanted:
                self.merit_mode_list.selection_set(index)
        self._update_operand_setup_visibility()

    def _capture_editor_state(self) -> dict[str, object]:
        selected_indices = []
        if hasattr(self, "table"):
            try:
                selected_indices = self._selected_table_indices()
            except Exception:
                selected_indices = []
        active_cell = None
        if self._active_cell is not None:
            row_id, field = self._active_cell
            try:
                row_index = self._table_item_row_index(row_id)
                active_cell = None if row_index is None else {"row": int(row_index), "field": str(field)}
            except Exception:
                active_cell = None
        layout_path = str(self.current_layout_file) if self.current_layout_file is not None else None
        return {
            "rows": [asdict(row) for row in self.rows],
            "settings": self._collect_layout_settings(),
            "selected_indices": selected_indices,
            "active_cell": active_cell,
            "current_layout_file": layout_path,
        }

    def _begin_history_capture(self, _event: tk.Event | None = None) -> None:
        if self._history_restoring or self._history_pending_state is not None:
            return
        self._history_pending_state = self._capture_editor_state()

    def _commit_history_capture(self) -> None:
        if self._history_restoring:
            self._history_pending_state = None
            return
        snapshot = self._history_pending_state
        self._history_pending_state = None
        if snapshot is None:
            return
        current = self._capture_editor_state()
        if snapshot == current:
            return
        self._undo_stack.append(snapshot)
        if len(self._undo_stack) > self._history_limit:
            self._undo_stack = self._undo_stack[-self._history_limit :]
        self._redo_stack.clear()
        self._update_undo_redo_buttons()

    def _push_history_snapshot(self) -> None:
        if self._history_restoring:
            return
        self._history_pending_state = self._capture_editor_state()
        self._commit_history_capture()

    def _restore_history_state(self, state: dict[str, object]) -> None:
        self._history_restoring = True
        try:
            rows = state.get("rows", [])
            restored_rows = [SurfaceRow(**dict(item)) for item in rows if isinstance(item, dict)]
            self.rows = self._normalized_rows_copy(restored_rows)
            layout_path = state.get("current_layout_file")
            self.current_layout_file = Path(layout_path) if isinstance(layout_path, str) and layout_path else None
            self._sync_table()
            self._apply_layout_settings(state.get("settings", {}))
            self._normalize_special_rows()
            self._sync_table()
            selected_indices = [int(index) for index in state.get("selected_indices", []) if isinstance(index, int)]
            items = list(self.table.get_children())
            selected_items = [items[index] for index in selected_indices if 0 <= index < len(items)]
            if selected_items:
                self.table.selection_set(selected_items)
                self.table.focus(selected_items[0])
                self.table.see(selected_items[0])
            else:
                self.table.selection_remove(*items)
            active_cell = state.get("active_cell")
            self._active_cell = None
            if isinstance(active_cell, dict):
                row_index = int(active_cell.get("row", -1))
                field = str(active_cell.get("field", ""))
                if 0 <= row_index < len(items) and field in FIELDS:
                    self._active_cell = (items[row_index], field)
            self._update_active_cell_border()
            self._refresh_analysis_surface_choices()
            self._refresh_operand_surface_choices()
        finally:
            self._history_restoring = False
            self._history_pending_state = None
        self.refresh_plot()
        self._update_undo_redo_buttons()

    def _update_undo_redo_buttons(self) -> None:
        undo_state = "normal" if self._undo_stack else "disabled"
        redo_state = "normal" if self._redo_stack else "disabled"
        if self._edit_menu is not None:
            try:
                self._edit_menu.entryconfigure("Undo", state=undo_state)
                self._edit_menu.entryconfigure("Redo", state=redo_state)
            except tk.TclError:
                pass
        if self._undo_button is not None:
            self._undo_button.configure(state=undo_state)
        if self._redo_button is not None:
            self._redo_button.configure(state=redo_state)

    def undo(self) -> None:
        if not self._undo_stack:
            return
        current = self._capture_editor_state()
        state = self._undo_stack.pop()
        self._redo_stack.append(current)
        self._restore_history_state(state)
        self.status_var.set("Undo applied.")

    def redo(self) -> None:
        if not self._redo_stack:
            return
        current = self._capture_editor_state()
        state = self._redo_stack.pop()
        self._undo_stack.append(current)
        self._restore_history_state(state)
        self.status_var.set("Redo applied.")

    def _undo_event(self, _event=None) -> str:
        self.undo()
        return "break"

    def _redo_event(self, _event=None) -> str:
        self.redo()
        return "break"

    def _collect_layout_settings(self) -> dict[str, object]:
        operand_settings: dict[str, dict[str, object]] = {}
        all_labels = {spec.label for spec in OPERAND_REGISTRY.values()}
        for label in all_labels:
            payload: dict[str, object] = {}
            var = self.operand_weight_vars.get(label)
            if var is not None:
                payload["weight"] = var.get()
            var = self.operand_target_vars.get(label)
            if var is not None:
                payload["target"] = var.get()
            var = self.operand_wavelength_vars.get(label)
            if var is not None:
                payload["wavelength"] = var.get()
            var = self.operand_field_vars.get(label)
            if var is not None:
                payload["field"] = var.get()
            var = self.operand_field_x_vars.get(label)
            if var is not None:
                payload["field_x"] = var.get()
            var = self.operand_field_y_vars.get(label)
            if var is not None:
                payload["field_y"] = var.get()
            var = self.operand_surface_vars.get(label)
            if var is not None:
                payload["surface"] = var.get()
            var = self.operand_aperture_type_vars.get(label)
            if var is not None:
                payload["aperture_type"] = var.get()
            var = self.operand_aperture_value_vars.get(label)
            if var is not None:
                payload["aperture_value"] = var.get()
            var = self.operand_frequency_vars.get(label)
            if var is not None:
                payload["frequency"] = var.get()
            var = self.operand_mtf_mode_vars.get(label)
            if var is not None:
                payload["mtf_mode"] = var.get()
            var = self.operand_mtf_algorithm_vars.get(label)
            if var is not None:
                payload["mtf_algorithm"] = var.get()
            if payload:
                operand_settings[label] = payload

        return {
            "object_mode": self._left_mode_text("object_mode_var", "Finite"),
            "display_orientation": self.display_orientation_var.get().strip(),
            "wavelength": self.wavelength_var.get().strip(),
            "ray_count": self.ray_count_var.get().strip(),
            "ray_height_factor": self._left_mode_text("ray_height_factor_var", "0.8"),
            "full_pupil": bool(self.emit_full_ray_var.get()),
            "source_model": self._current_source_model(),
            "pupil_pattern": self._left_mode_text("pupil_pattern_var", PUPIL_PATTERN_DEFAULT),
            "source_radius": self._left_mode_text("source_radius_var", "5.0"),
            "source_cone_angle": self._left_mode_text("source_cone_angle_var", "5.0"),
            "gaussian_input_mode": self._left_mode_text("gaussian_input_mode_var", GAUSSIAN_INPUT_MODE_DEFAULT),
            "gaussian_waist_radius": self._left_mode_text("gaussian_waist_radius_var", "0.5"),
            "gaussian_waist_offset": self._left_mode_text("gaussian_waist_offset_var", "0.0"),
            "gaussian_beam_diameter": self._left_mode_text("gaussian_beam_diameter_var", "1.0"),
            "gaussian_full_divergence": self._left_mode_text("gaussian_full_divergence_var", "1.0"),
            "gaussian_waist_side": self._left_mode_text("gaussian_waist_side_var", GAUSSIAN_WAIST_SIDE_DEFAULT),
            "gaussian_m2": self._left_mode_text("gaussian_m2_var", "1.0"),
            "pupil_rad": self._left_mode_text("pupil_rad_var", "0.0"),
            "pupil_theta": self._left_mode_text("pupil_theta_var", "0.0"),
            "source_power": self._left_mode_text("source_power_var", "1.0"),
            "source_seed": self._left_mode_text("source_seed_var", "1"),
            "source_x": self._left_mode_text("source_x_var", "0.0"),
            "source_y": self._left_mode_text("source_y_var", "0.0"),
            "source_z": self._left_mode_text("source_z_var", "0.0"),
            "source_l": self._left_mode_text("source_l_var", "0.0"),
            "source_m": self._left_mode_text("source_m_var", "0.0"),
            "source_n": self._left_mode_text("source_n_var", "1.0"),
            "source_angular_weight": self._left_mode_text("source_angular_weight_var", SOURCE_ANGULAR_WEIGHT_DEFAULT),
            "analysis_surface": self.analysis_surface_var.get().strip(),
            "analysis_branch_filter": self._current_analysis_branch_filter(),
            "detector_bins": self._left_mode_text("detector_bins_var", DETECTOR_BINS_DEFAULT),
            "aperture_type": self._current_aperture_type_label(),
            "aperture_value": self.aperture_value_var.get().strip(),
            "spot_view_mode": self.spot_view_mode_var.get().strip(),
            "wavefront_style": self._current_wavefront_style(),
            "show_clipped_rays": bool(self.show_clipped_rays_var.get()),
            "show_cardinals": bool(self.show_cardinals_var.get()),
            "show_physical_distances": bool(self.show_physical_distances_var.get()),
            "field_type": self._normalize_field_type(self._left_mode_text("field_type_var", self._current_field_type())),
            "field_value": self._left_mode_text("field_value_var", "0.0"),
            "field_count": self._left_mode_text("field_count_var", "1"),
            "atmos_plot_mode": self._current_atmos_plot_mode(),
            "atmos_observatory": self._current_atmos_observatory(),
            "atmos_wavelength_min": self.atmos_wavelength_min_var.get().strip() if hasattr(self, "atmos_wavelength_min_var") else "0.45",
            "atmos_wavelength_max": self.atmos_wavelength_max_var.get().strip() if hasattr(self, "atmos_wavelength_max_var") else "0.75",
            "atmos_wavelength_count": self.atmos_wavelength_count_var.get().strip() if hasattr(self, "atmos_wavelength_count_var") else "11",
            "atmos_zenith_deg": self.atmos_zenith_deg_var.get().strip() if hasattr(self, "atmos_zenith_deg_var") else "45.0",
            "atmos_temperature_k": self.atmos_temperature_k_var.get().strip() if hasattr(self, "atmos_temperature_k_var") else "283.15",
            "atmos_pressure_pa": self.atmos_pressure_pa_var.get().strip() if hasattr(self, "atmos_pressure_pa_var") else "101300",
            "atmos_humidity": self.atmos_humidity_var.get().strip() if hasattr(self, "atmos_humidity_var") else "0.5",
            "atmos_co2_ppm": self.atmos_co2_ppm_var.get().strip() if hasattr(self, "atmos_co2_ppm_var") else "400",
            "atmos_latitude_deg": self.atmos_latitude_deg_var.get().strip() if hasattr(self, "atmos_latitude_deg_var") else "31.0",
            "atmos_altitude_m": self.atmos_altitude_m_var.get().strip() if hasattr(self, "atmos_altitude_m_var") else "2800",
            "image_diameter_mode": self.image_diameter_mode_var.get().strip() if hasattr(self, "image_diameter_mode_var") else "Auto",
            "trace_mode": self._requested_trace_mode(),
            "nonseq_target_surface": self.nonseq_target_surface_var.get().strip() if hasattr(self, "nonseq_target_surface_var") else "Auto",
            "nonseq_ns_limit": self.nonseq_ns_limit_var.get().strip() if hasattr(self, "nonseq_ns_limit_var") else "200",
            "nonseq_energy_probability": self._current_nonseq_energy_probability(),
            "camera_model": self.camera_model_var.get().strip() if hasattr(self, "camera_model_var") else CAMERA_NONE_LABEL,
            "camera_step_path": str(self.imported_camera_step_path) if self.imported_camera_step_path is not None else "",
            "camera_step_rotation_x_deg": float(getattr(self, "camera_step_rotation_x_deg", 0.0)),
            "camera_step_rotation_z_deg": float(getattr(self, "camera_step_rotation_z_deg", 0.0)),
            "camera_step_axis_offset_xy": list(self._step_axis_offset_xy("camera")),
            "lens_step_path": str(self.imported_lens_step_path) if self.imported_lens_step_path is not None else "",
            "lens_step_rotation_x_deg": float(getattr(self, "lens_step_rotation_x_deg", 0.0)),
            "lens_step_rotation_z_deg": float(getattr(self, "lens_step_rotation_z_deg", 0.0)),
            "lens_step_axis_offset_xy": list(self._step_axis_offset_xy("lens")),
            "led_step_path": str(self.imported_led_step_path) if self.imported_led_step_path is not None else "",
            "led_step_rotation_x_deg": float(getattr(self, "led_step_rotation_x_deg", 0.0)),
            "led_step_rotation_z_deg": float(getattr(self, "led_step_rotation_z_deg", 0.0)),
            "led_object_edge_distance_mm": float(getattr(self, "led_object_edge_distance_mm", 0.0)),
            "led_step_object_edge_local_z": (
                "" if getattr(self, "led_step_object_edge_local_z", None) is None else float(self.led_step_object_edge_local_z)
            ),
            "led_step_axis_offset_xy": list(self._step_axis_offset_xy("led")),
            "analysis_mode": str(self.analysis_mode or "none").strip(),
            "analysis_modes": list(self.selected_analysis_modes),
            "layout_preview_mode": "none",
            "auto_save_plot": bool(self.auto_save_plot_var.get()),
            "external_camera": self.external_camera_var.get().strip() if hasattr(self, "external_camera_var") else "None",
            "camera_overlay_mode": self.camera_overlay_mode_var.get().strip() if hasattr(self, "camera_overlay_mode_var") else "Rough envelope",
            "metal_catalogs": _normalize_metal_catalog_specs(getattr(self, "metal_catalogs", [])),
            "optimization_workers": self.optimization_workers_var.get().strip() if hasattr(self, "optimization_workers_var") else "Auto",
            "selected_operands": self._selected_operand_labels(),
            "operands": operand_settings,
        }

    def _apply_layout_settings(self, settings: object) -> None:
        if not isinstance(settings, dict):
            return
        self.metal_catalogs = _normalize_metal_catalog_specs(settings.get("metal_catalogs", []))

        def _parse_bool(value) -> bool:
            if isinstance(value, str):
                return value.strip().lower() in {"1", "true", "yes", "on"}
            return bool(value)

        def _set_text(var, key: str) -> None:
            value = settings.get(key)
            if value is not None:
                var.set(str(value).strip())

        def _path_setting(key: str) -> Path | None:
            value = settings.get(key)
            if value is None:
                return None
            text = str(value).strip()
            if not text or text.lower() in {"none", "null"}:
                return None
            return Path(text).expanduser()

        def _offset_setting(key: str) -> tuple[float, float]:
            value = settings.get(key)
            if isinstance(value, (list, tuple)) and len(value) >= 2:
                try:
                    return (float(value[0]), float(value[1]))
                except Exception:
                    return (0.0, 0.0)
            if isinstance(value, str):
                parts = [part.strip() for part in value.replace(";", ",").split(",") if part.strip()]
                if len(parts) >= 2:
                    try:
                        return (float(parts[0]), float(parts[1]))
                    except Exception:
                        return (0.0, 0.0)
            return (0.0, 0.0)

        display_orientation = str(settings.get("display_orientation", "")).strip()
        if display_orientation in {"Vertical", "Horizontal"}:
            self.display_orientation_var.set(display_orientation)

        object_mode = str(settings.get("object_mode", "")).strip()
        if object_mode in {"Finite", "Infinity"}:
            self.object_mode_var.set(object_mode)

        _set_text(self.wavelength_var, "wavelength")
        _set_text(self.ray_count_var, "ray_count")
        _set_text(self.ray_height_factor_var, "ray_height_factor")
        if hasattr(self, "source_model_var"):
            source_model = str(settings.get("source_model", "")).strip()
            if source_model in SOURCE_MODEL_VALUES:
                self.source_model_var.set(source_model)
        if hasattr(self, "pupil_pattern_var"):
            pupil_pattern = str(settings.get("pupil_pattern", "")).strip()
            if pupil_pattern in PUPIL_PATTERN_VALUES:
                self.pupil_pattern_var.set(pupil_pattern)
        if hasattr(self, "source_radius_var"):
            _set_text(self.source_radius_var, "source_radius")
        if hasattr(self, "source_cone_angle_var"):
            _set_text(self.source_cone_angle_var, "source_cone_angle")
        if hasattr(self, "gaussian_input_mode_var"):
            mode = str(settings.get("gaussian_input_mode", "")).strip()
            if mode in GAUSSIAN_INPUT_MODE_VALUES:
                self.gaussian_input_mode_var.set(mode)
        if hasattr(self, "gaussian_waist_radius_var"):
            _set_text(self.gaussian_waist_radius_var, "gaussian_waist_radius")
        if hasattr(self, "gaussian_waist_offset_var"):
            _set_text(self.gaussian_waist_offset_var, "gaussian_waist_offset")
        if hasattr(self, "gaussian_beam_diameter_var"):
            _set_text(self.gaussian_beam_diameter_var, "gaussian_beam_diameter")
        if hasattr(self, "gaussian_full_divergence_var"):
            _set_text(self.gaussian_full_divergence_var, "gaussian_full_divergence")
        if hasattr(self, "gaussian_waist_side_var"):
            side = str(settings.get("gaussian_waist_side", "")).strip()
            if side in GAUSSIAN_WAIST_SIDE_VALUES:
                self.gaussian_waist_side_var.set(side)
        if hasattr(self, "gaussian_m2_var"):
            _set_text(self.gaussian_m2_var, "gaussian_m2")
        if hasattr(self, "pupil_rad_var"):
            _set_text(self.pupil_rad_var, "pupil_rad")
        if hasattr(self, "pupil_theta_var"):
            _set_text(self.pupil_theta_var, "pupil_theta")
        if hasattr(self, "source_power_var"):
            _set_text(self.source_power_var, "source_power")
        if hasattr(self, "source_seed_var"):
            _set_text(self.source_seed_var, "source_seed")
        if hasattr(self, "source_x_var"):
            _set_text(self.source_x_var, "source_x")
        if hasattr(self, "source_y_var"):
            _set_text(self.source_y_var, "source_y")
        if hasattr(self, "source_z_var"):
            _set_text(self.source_z_var, "source_z")
        if hasattr(self, "source_l_var"):
            _set_text(self.source_l_var, "source_l")
        if hasattr(self, "source_m_var"):
            _set_text(self.source_m_var, "source_m")
        if hasattr(self, "source_n_var"):
            _set_text(self.source_n_var, "source_n")
        if hasattr(self, "source_angular_weight_var"):
            weight = str(settings.get("source_angular_weight", "")).strip()
            if weight in SOURCE_ANGULAR_WEIGHT_VALUES:
                self.source_angular_weight_var.set(weight)
        if hasattr(self, "atmos_observatory_var"):
            observatory = str(settings.get("atmos_observatory", "Manual")).strip() or "Manual"
            if observatory in self._atmos_observatory_names():
                self.atmos_observatory_var.set(observatory)
                if observatory != "Manual" and not any(
                    key in settings
                    for key in (
                        "atmos_temperature_k",
                        "atmos_pressure_pa",
                        "atmos_humidity",
                        "atmos_co2_ppm",
                        "atmos_latitude_deg",
                        "atmos_altitude_m",
                    )
                ):
                    self._apply_atmos_observatory(observatory)
        if "atmos_plot_mode" in settings and hasattr(self, "atmos_plot_mode_var"):
            atmos_plot_mode = str(settings.get("atmos_plot_mode", "")).strip()
            if atmos_plot_mode in ATMOS_PLOT_MODE_VALUES:
                self.atmos_plot_mode_var.set(atmos_plot_mode)
        for setting_key, attr_name in (
            ("atmos_wavelength_min", "atmos_wavelength_min_var"),
            ("atmos_wavelength_max", "atmos_wavelength_max_var"),
            ("atmos_wavelength_count", "atmos_wavelength_count_var"),
            ("atmos_zenith_deg", "atmos_zenith_deg_var"),
            ("atmos_temperature_k", "atmos_temperature_k_var"),
            ("atmos_pressure_pa", "atmos_pressure_pa_var"),
            ("atmos_humidity", "atmos_humidity_var"),
            ("atmos_co2_ppm", "atmos_co2_ppm_var"),
            ("atmos_latitude_deg", "atmos_latitude_deg_var"),
            ("atmos_altitude_m", "atmos_altitude_m_var"),
        ):
            if hasattr(self, attr_name):
                _set_text(getattr(self, attr_name), setting_key)
        self._update_atmosphere_summary()

        aperture_type = str(settings.get("aperture_type", "")).strip().upper()
        if aperture_type in {"STOP", "EPD", "FNO"}:
            self.aperture_type_var.set(aperture_type)
        _set_text(self.aperture_value_var, "aperture_value")

        if "spot_view_mode" in settings:
            spot_view_mode = str(settings.get("spot_view_mode", "")).strip()
            if spot_view_mode in {"Grid", "Absolute", "Centroid"}:
                self.spot_view_mode_var.set(spot_view_mode)

        if "analysis_branch_filter" in settings and hasattr(self, "analysis_branch_filter_var"):
            analysis_branch_filter = _normalize_path_filter_label(settings.get("analysis_branch_filter", ANALYSIS_PATH_FILTER_DEFAULT))
            self.analysis_branch_filter_var.set(analysis_branch_filter)

        if "detector_bins" in settings and hasattr(self, "detector_bins_var"):
            detector_bins = str(settings.get("detector_bins", DETECTOR_BINS_DEFAULT)).strip() or DETECTOR_BINS_DEFAULT
            self.detector_bins_var.set(detector_bins)

        if "wavefront_style" in settings and hasattr(self, "wavefront_style_var"):
            wavefront_style = str(settings.get("wavefront_style", "")).strip()
            if wavefront_style in WAVEFRONT_STYLE_VALUES:
                self.wavefront_style_var.set(wavefront_style)

        field_count = settings.get("field_count")
        if field_count is not None:
            self.field_count_var.set(str(field_count).strip())

        image_diameter_mode = str(settings.get("image_diameter_mode", "")).strip()
        if image_diameter_mode in {"Auto", "Manual"} and hasattr(self, "image_diameter_mode_var"):
            self.image_diameter_mode_var.set(image_diameter_mode)

        trace_mode = str(settings.get("trace_mode", "")).strip()
        if trace_mode in {"Auto", "Sequential", "Folded Preview", "Non-Sequential Preview"} and hasattr(self, "trace_mode_var"):
            self.trace_mode_var.set(trace_mode)
            self.trace_mode = trace_mode
        if hasattr(self, "nonseq_ns_limit_var"):
            _set_text(self.nonseq_ns_limit_var, "nonseq_ns_limit")
        if "nonseq_energy_probability" in settings and hasattr(self, "nonseq_energy_probability_var"):
            self.nonseq_energy_probability_var.set(_parse_bool(settings.get("nonseq_energy_probability")))
        if "nonseq_target_surface" in settings and hasattr(self, "nonseq_target_surface_var"):
            target = str(settings.get("nonseq_target_surface", "Auto")).strip() or "Auto"
            self.nonseq_target_surface_var.set(target)

        camera_model = str(settings.get("camera_model", CAMERA_NONE_LABEL)).strip()
        if hasattr(self, "camera_model_var"):
            if camera_model == CAMERA_NONE_LABEL or camera_record(camera_model) is not None:
                self.camera_model_var.set(camera_model)
            else:
                self.camera_model_var.set(CAMERA_NONE_LABEL)
        self.imported_camera_step_path = _path_setting("camera_step_path")
        self.imported_lens_step_path = _path_setting("lens_step_path")
        self.imported_led_step_path = _path_setting("led_step_path")
        self.camera_step_axis_offset_xy = _offset_setting("camera_step_axis_offset_xy")
        self.lens_step_axis_offset_xy = _offset_setting("lens_step_axis_offset_xy")
        self.led_step_axis_offset_xy = _offset_setting("led_step_axis_offset_xy")
        self._cad_axis_pick_label = None
        self._cad_led_object_edge_pick = False
        self._selected_step_label = None
        try:
            self.camera_step_rotation_x_deg = float(settings.get("camera_step_rotation_x_deg", 0.0)) % 360.0
        except Exception:
            self.camera_step_rotation_x_deg = 0.0
        try:
            self.camera_step_rotation_z_deg = float(settings.get("camera_step_rotation_z_deg", 0.0)) % 360.0
        except Exception:
            self.camera_step_rotation_z_deg = 0.0
        try:
            self.lens_step_rotation_x_deg = float(settings.get("lens_step_rotation_x_deg", 0.0)) % 360.0
        except Exception:
            self.lens_step_rotation_x_deg = 0.0
        try:
            self.lens_step_rotation_z_deg = float(settings.get("lens_step_rotation_z_deg", 0.0)) % 360.0
        except Exception:
            self.lens_step_rotation_z_deg = 0.0
        try:
            self.led_step_rotation_x_deg = float(settings.get("led_step_rotation_x_deg", 0.0)) % 360.0
        except Exception:
            self.led_step_rotation_x_deg = 0.0
        try:
            self.led_step_rotation_z_deg = float(settings.get("led_step_rotation_z_deg", 0.0)) % 360.0
        except Exception:
            self.led_step_rotation_z_deg = 0.0
        try:
            self.led_object_edge_distance_mm = max(float(settings.get("led_object_edge_distance_mm", 0.0)), 0.0)
        except Exception:
            self.led_object_edge_distance_mm = 0.0
        led_object_edge_local_z = settings.get("led_step_object_edge_local_z", "")
        if str(led_object_edge_local_z).strip():
            try:
                self.led_step_object_edge_local_z = float(led_object_edge_local_z)
            except Exception:
                self.led_step_object_edge_local_z = None
        else:
            self.led_step_object_edge_local_z = None

        self._sync_field_mode_ui()

        field_type = self._normalize_field_type(str(settings.get("field_type", "")).strip())
        if field_type in FIELD_TYPE_CANONICAL_VALUES:
            self.field_type_var.set(self._field_type_display_label(field_type))
            self._last_field_type = field_type

        field_value = settings.get("field_value")
        if field_value is not None:
            field_value_text = str(field_value).strip()
            self.field_value_var.set(field_value_text)
            self._field_type_defaults[self._current_field_type()] = field_value_text

        analysis_surface = settings.get("analysis_surface")
        if analysis_surface is not None:
            analysis_surface_text = str(analysis_surface).strip()
            if analysis_surface_text == "Auto":
                self.analysis_surface_var.set("Auto")
            elif analysis_surface_text in set(self.analysis_surface_menu["values"]):
                self.analysis_surface_var.set(analysis_surface_text)
            else:
                try:
                    index = int(float(analysis_surface_text))
                except (TypeError, ValueError):
                    index = -1
                if 0 <= index < len(self.rows):
                    self.analysis_surface_var.set(f"{index}: {self.rows[index].name}")

        bool_vars = {
            "show_clipped_rays": self.show_clipped_rays_var,
            "show_cardinals": self.show_cardinals_var,
            "show_physical_distances": self.show_physical_distances_var,
            "auto_save_plot": self.auto_save_plot_var,
            "full_pupil": self.emit_full_ray_var,
        }
        for key, var in bool_vars.items():
            if key in settings:
                var.set(_parse_bool(settings.get(key)))

        if hasattr(self, "optimization_workers_var") and "optimization_workers" in settings:
            worker_text = str(settings.get("optimization_workers", "Auto")).strip() or "Auto"
            self.optimization_workers_var.set(worker_text)

        if hasattr(self, "external_camera_var"):
            self.external_camera_var.set("None")
        if hasattr(self, "camera_overlay_mode_var"):
            self.camera_overlay_mode_var.set("Off")

        selected_operands = settings.get("selected_operands")
        if isinstance(selected_operands, (list, tuple)):
            self._set_selected_operand_labels([str(label) for label in selected_operands])

        operand_settings = settings.get("operands")
        if isinstance(operand_settings, dict):
            for label, payload in operand_settings.items():
                if not isinstance(payload, dict):
                    continue
                if label in self.operand_weight_vars and "weight" in payload:
                    self.operand_weight_vars[label].set(str(payload["weight"]).strip())
                if label in self.operand_target_vars and "target" in payload:
                    self.operand_target_vars[label].set(str(payload["target"]).strip())
                if label in self.operand_wavelength_vars and "wavelength" in payload:
                    self.operand_wavelength_vars[label].set(str(payload["wavelength"]).strip())
                if label in self.operand_field_vars and "field" in payload:
                    self.operand_field_vars[label].set(str(payload["field"]).strip())
                if label in self.operand_field_x_vars and "field_x" in payload:
                    self.operand_field_x_vars[label].set(str(payload["field_x"]).strip())
                if label in self.operand_field_y_vars and "field_y" in payload:
                    self.operand_field_y_vars[label].set(str(payload["field_y"]).strip())
                if label in self.operand_surface_vars and "surface" in payload:
                    surface_text = str(payload["surface"]).strip()
                    if surface_text:
                        self.operand_surface_vars[label].set(surface_text)
                if label in self.operand_aperture_type_vars and "aperture_type" in payload:
                    aperture_text = str(payload["aperture_type"]).strip().upper()
                    if aperture_text in {"STOP", "EPD", "FNO"}:
                        self.operand_aperture_type_vars[label].set(aperture_text)
                if label in self.operand_aperture_value_vars and "aperture_value" in payload:
                    self.operand_aperture_value_vars[label].set(str(payload["aperture_value"]).strip())
                if label in self.operand_frequency_vars and "frequency" in payload:
                    self.operand_frequency_vars[label].set(str(payload["frequency"]).strip())
                if label in self.operand_mtf_mode_vars and "mtf_mode" in payload:
                    mode_text = str(payload["mtf_mode"]).strip()
                    if mode_text in {"Average", "Tangential", "Sagittal"}:
                        self.operand_mtf_mode_vars[label].set(mode_text)
                if label in self.operand_mtf_algorithm_vars and "mtf_algorithm" in payload:
                    algorithm_text = str(payload["mtf_algorithm"]).strip()
                    if algorithm_text in {"Diffraction FFT", "PSF FFT", "LSF FFT"}:
                        self.operand_mtf_algorithm_vars[label].set(algorithm_text)

        self.layout_preview_mode = "none"
        analysis_modes = settings.get("analysis_modes")
        valid_analysis_modes = {
            "spot",
            "psf",
            "psf_map",
            "rms",
            "field_curvature",
            "relative_illumination",
            "polarization",
            "lateral_color",
            "detector_map",
            "coherent_detector",
            "field_map",
            "illum_map",
            "wavefront_map",
            "atmosphere",
            "pupil",
            "seidel",
            "wavefront",
            "zernike",
            "interferogram",
            "mtf",
        }
        if isinstance(analysis_modes, (list, tuple)):
            self.selected_analysis_modes = [str(item).strip() for item in analysis_modes if str(item).strip() in valid_analysis_modes][:2]
        else:
            analysis_mode = str(settings.get("analysis_mode", "")).strip()
            self.selected_analysis_modes = [analysis_mode] if analysis_mode in valid_analysis_modes else []
            if analysis_mode == "none":
                self.layout_preview_mode = "none"
        self.analysis_mode = self.selected_analysis_modes[0] if self.selected_analysis_modes else "none"
        self.secondary_analysis_mode = self.selected_analysis_modes[1] if len(self.selected_analysis_modes) > 1 else None
        self._sync_analysis_mode_buttons()

        if self._apply_image_diameter_mode():
            self._sync_image_row_table_value()
        self._sync_object_controls()
        self._update_field_status_hint()
        self._sync_left_mode_controls()

    def load_example_by_name(self, name: str) -> None:
        path = self.example_files.get(name)
        if path is None:
            return
        if self.rows:
            self._begin_history_capture()
        info: dict[str, object] | None = None
        try:
            code = path.read_text(encoding="utf-8", errors="ignore")
            if "SURFACES" in code and "SETTINGS" in code:
                info = _load_python_data(path)
                self.rows = [self._row_from_layout_item(item) for item in info["surfaces"]]
                self.rows = self._normalized_rows_copy(self.rows)
            else:
                surfaces = self._extract_surfaces_from_example(path)
                self.rows = [self._row_from_surface(surface, index, len(surfaces)) for index, surface in enumerate(surfaces)]
        except Exception as exc:
            self._history_pending_state = None
            self.status_var.set(f"Failed to load example {name}: {exc}")
            return
        self.current_layout_file = None
        self.imported_camera_step_path = None
        self.imported_lens_step_path = None
        self.imported_led_step_path = None
        self.camera_step_rotation_x_deg = 0.0
        self.lens_step_rotation_x_deg = 0.0
        self.led_step_rotation_x_deg = 0.0
        self.camera_step_rotation_z_deg = 0.0
        self.lens_step_rotation_z_deg = 0.0
        self.led_step_rotation_z_deg = 0.0
        self.led_object_edge_distance_mm = 0.0
        self.led_step_object_edge_local_z = None
        self.lens_step_axis_offset_xy = (0.0, 0.0)
        self.camera_step_axis_offset_xy = (0.0, 0.0)
        self.led_step_axis_offset_xy = (0.0, 0.0)
        self._cad_axis_pick_label = None
        self._cad_led_object_edge_pick = False
        self._selected_step_label = None
        self._normalize_special_rows()
        self._apply_example_display_defaults(path)
        if info is not None:
            self._apply_layout_settings(info.get("settings", {}))
        self._sync_table()
        self._commit_history_capture()
        self.refresh_plot(suppress_analysis=True)
        self.layout_var.set("Common Optical Layout")
        self.machine_vision_var.set("Machine Vision Lens")
        self.example_var.set(name)
        warned = False if info is not None else self._report_example_feature_gaps(name, path, surfaces)
        if not warned:
            self.status_var.set(f"Loaded example {name}. Click Update to run analysis.")

    def _on_layout_selected(self, _event: tk.Event | None = None) -> None:
        selected = self.layout_var.get().strip()
        if selected == "Common Optical Layout":
            return
        self.load_layout_by_name(selected)

    def _on_machine_vision_selected(self, _event: tk.Event | None = None) -> None:
        selected = self.machine_vision_var.get().strip()
        if selected == "Machine Vision Lens":
            return
        self.load_layout_by_name(selected)

    def _on_example_selected(self, _event: tk.Event | None = None) -> None:
        selected = self.example_var.get().strip()
        if selected == "Examples":
            return
        self.load_example_by_name(selected)

    @staticmethod
    def _element_tag_palette() -> tuple[tuple[str, str], ...]:
        return (
            ("element_group_0", "#e8f5e9"),
            ("element_group_1", "#e3f2fd"),
            ("element_group_2", "#fff3e0"),
            ("element_group_3", "#f3e5f5"),
            ("element_group_4", "#e0f7fa"),
            ("element_group_5", "#fce4ec"),
        )

    @staticmethod
    def _element_key(row: SurfaceRow) -> str:
        return str(getattr(row, "element", "") or "").strip()

    @staticmethod
    def _element_metadata(row: SurfaceRow) -> dict[str, object]:
        return _normalize_element_metadata((row.advanced or {}).get(ELEMENT_ADVANCED_ATTR))

    @staticmethod
    def _row_has_detector_output_metadata(row: SurfaceRow) -> bool:
        advanced = getattr(row, "advanced", {}) or {}
        if not isinstance(advanced, dict):
            return False
        metadata = _normalize_element_metadata(advanced.get(ELEMENT_ADVANCED_ATTR))
        if str(metadata.get("arm_role", "") or "") == "Detector":
            return True
        display_settings = advanced.get("Display2D")
        if isinstance(display_settings, dict) and isinstance(display_settings.get("branch_output_targets"), dict):
            return True
        return isinstance(advanced.get("Interferogram"), dict)

    @staticmethod
    def _set_element_metadata(row: SurfaceRow, metadata: dict[str, object]) -> None:
        normalized = _normalize_element_metadata(metadata)
        row.advanced = dict(row.advanced or {})
        if _element_metadata_is_default(normalized):
            row.advanced.pop(ELEMENT_ADVANCED_ATTR, None)
        else:
            row.advanced[ELEMENT_ADVANCED_ATTR] = normalized

    @classmethod
    def _element_arm_role_for_index(cls, rows: list[SurfaceRow], index: int) -> str:
        if not (0 <= index < len(rows)):
            return ELEMENT_ARM_ROLE_DEFAULT
        start, _end = cls._element_block_for_index(rows, index)
        return str(cls._element_metadata(rows[start]).get("arm_role", ELEMENT_ARM_ROLE_DEFAULT))

    @classmethod
    def _element_arm_badge_for_index(cls, rows: list[SurfaceRow], index: int) -> str:
        if not (0 <= index < len(rows)):
            return ""
        start, _end = cls._element_block_for_index(rows, index)
        if index != start:
            return ""
        role = cls._element_arm_role_for_index(rows, index)
        return ELEMENT_ARM_BADGES.get(role, "")

    @staticmethod
    def _leg_badge_text(short_label: str) -> str:
        text = str(short_label or "").strip()
        match = re.fullmatch(r"(?:Leg|Path)\s+(\d+)", text, flags=re.IGNORECASE)
        return f"P{match.group(1)}" if match else text

    def _layout_interferometer_hint(self) -> str:
        texts: list[str] = []
        for row in getattr(self, "rows", []) or []:
            texts.extend(
                [
                    str(getattr(row, "element", "") or ""),
                    str(getattr(row, "name", "") or ""),
                    str(getattr(row, "surface", "") or ""),
                ]
            )
            advanced = getattr(row, "advanced", {}) or {}
            if isinstance(advanced, dict):
                for key in ("Note", "Interferogram", "Display2D"):
                    value = advanced.get(key)
                    if isinstance(value, dict):
                        texts.extend(str(item) for item in value.values())
                    elif value is not None:
                        texts.append(str(value))
        return " ".join(texts).lower()

    def _auto_leg_entries(self) -> list[dict[str, object]]:
        return list(getattr(self, "_last_auto_leg_entries", []) or [])

    def _auto_leg_entry_for_id(self, leg_id: str) -> dict[str, object] | None:
        target = str(leg_id or "").strip().lower()
        if not target:
            return None
        for entry in self._auto_leg_entries():
            if str(entry.get("leg_id", "") or "").strip().lower() == target:
                return entry
        return None

    @staticmethod
    def _auto_leg_point_key(point: np.ndarray, tolerance: float = 0.25) -> str:
        arr = np.asarray(point, dtype=float).ravel()
        if arr.size < 2 or not np.all(np.isfinite(arr[:2])):
            return "nan"
        scale = max(float(tolerance), 1e-9)
        return f"{round(float(arr[0]) / scale):.0f},{round(float(arr[1]) / scale):.0f}"

    @staticmethod
    def _auto_leg_node_label(node: dict[str, object]) -> str:
        label = str(node.get("label", "") or "").strip()
        return label or str(node.get("key", "") or "node").strip()

    def _auto_leg_node_for_hit(
        self,
        point: np.ndarray,
        surface_id: int | None,
        *,
        branch_path: str = "",
        branch_label: str = "",
    ) -> dict[str, object]:
        if surface_id is None or not (0 <= int(surface_id) < len(self.rows)):
            branch_path = str(branch_path or "").strip()
            branch_label = str(branch_label or "").strip().lower()
            if branch_path and branch_path != "primary":
                stable = hashlib.sha1(branch_path.encode("utf-8")).hexdigest()[:10]
                key = f"term:path:{stable}"
            elif branch_label and branch_label != "primary":
                key = f"term:label:{branch_label}"
            else:
                key = f"term:{self._auto_leg_point_key(point)}"
            return {
                "key": key,
                "label": "Terminal",
                "row_index": None,
                "kind": "terminal",
            }
        row = self.rows[int(surface_id)]
        if row.surface == BEAM_SPLITTER_SURFACE:
            kind = "beam_splitter"
            key = f"bs:{int(surface_id)}"
        else:
            kind = "terminal"
            key = f"row:{int(surface_id)}"
        return {
            "key": key,
            "label": str(row.name or row.element or f"S{int(surface_id)}").strip(),
            "row_index": int(surface_id),
            "kind": kind,
        }

    @staticmethod
    def _auto_leg_hit_point_index(points: np.ndarray, surface_ids: np.ndarray, hit_index: int) -> int:
        if points.shape[0] >= surface_ids.size + 1:
            return min(max(int(hit_index) + 1, 0), points.shape[0] - 1)
        return min(max(int(hit_index), 0), points.shape[0] - 1)

    def _auto_leg_candidate_key(
        self,
        start_node: dict[str, object],
        end_node: dict[str, object],
        non_branch_surface_ids: tuple[int, ...],
    ) -> tuple[tuple[str, str], tuple[int, ...]]:
        node_pair = tuple(sorted((str(start_node.get("key", "")), str(end_node.get("key", "")))))
        reverse_ids = tuple(reversed(non_branch_surface_ids))
        surface_key = min(non_branch_surface_ids, reverse_ids)
        return node_pair, surface_key

    @staticmethod
    def _auto_leg_midpoint(polyline: np.ndarray) -> np.ndarray:
        arr = np.asarray(polyline, dtype=float)
        if arr.ndim != 2 or arr.shape[0] == 0:
            return np.zeros(2, dtype=float)
        if arr.shape[0] == 1:
            return np.asarray(arr[0, :2], dtype=float)
        lengths = np.linalg.norm(np.diff(arr[:, :2], axis=0), axis=1)
        total = float(np.sum(lengths))
        if total <= 1e-12:
            return np.asarray(arr[arr.shape[0] // 2, :2], dtype=float)
        target = 0.5 * total
        accumulated = 0.0
        for index, length in enumerate(lengths):
            if accumulated + float(length) >= target:
                local = (target - accumulated) / max(float(length), 1e-12)
                return arr[index, :2] + (arr[index + 1, :2] - arr[index, :2]) * local
            accumulated += float(length)
        return np.asarray(arr[-1, :2], dtype=float)

    def _auto_leg_representative_polyline(self, polylines: list[np.ndarray]) -> np.ndarray:
        clean = [np.asarray(polyline, dtype=float) for polyline in polylines if np.asarray(polyline, dtype=float).ndim == 2]
        clean = [polyline[:, :2] for polyline in clean if polyline.shape[0] >= 2]
        if not clean:
            return np.empty((0, 2), dtype=float)
        midpoints = np.vstack([self._auto_leg_midpoint(polyline) for polyline in clean])
        median_midpoint = np.median(midpoints, axis=0)
        return min(clean, key=lambda polyline: float(np.linalg.norm(self._auto_leg_midpoint(polyline) - median_midpoint)))

    def _auto_leg_direction_from_node(self, entry: dict[str, object], node_key: str) -> np.ndarray:
        polyline = np.asarray(entry.get("polyline", []), dtype=float)
        if polyline.ndim != 2 or polyline.shape[0] < 2:
            return np.array([1.0, 0.0], dtype=float)
        start_key = str(entry.get("start_node_key", "") or "")
        if str(node_key) == start_key:
            pairs = zip(polyline[:-1], polyline[1:])
        else:
            pairs = zip(polyline[:0:-1], polyline[-2::-1])
        for p0, p1 in pairs:
            direction = np.asarray(p1, dtype=float) - np.asarray(p0, dtype=float)
            norm = float(np.linalg.norm(direction))
            if norm > 1e-9:
                return direction / norm
        return np.array([1.0, 0.0], dtype=float)

    def _ordered_auto_leg_keys(self, legs: dict[tuple[tuple[str, str], tuple[int, ...]], dict[str, object]]) -> list[tuple[tuple[str, str], tuple[int, ...]]]:
        adjacency: dict[str, list[tuple[tuple[str, str], tuple[int, ...]]]] = {}
        for key, entry in legs.items():
            for node_key in (str(entry.get("start_node_key", "")), str(entry.get("end_node_key", ""))):
                if node_key:
                    adjacency.setdefault(node_key, []).append(key)

        def sort_key(edge_key: tuple[tuple[str, str], tuple[int, ...]], node_key: str) -> tuple[float, str]:
            entry = legs[edge_key]
            direction = self._auto_leg_direction_from_node(entry, node_key)
            angle = float(np.rad2deg(np.arctan2(float(direction[1]), float(direction[0]))))
            if angle < 0.0:
                angle += 360.0
            return angle, str(entry.get("stable_signature", ""))

        ordered: list[tuple[tuple[str, str], tuple[int, ...]]] = []
        visited_edges: set[tuple[tuple[str, str], tuple[int, ...]]] = set()
        visited_nodes: set[str] = set()
        queue: list[str] = ["source"] if "source" in adjacency else sorted(adjacency)[:1]
        while queue:
            node_key = queue.pop(0)
            if node_key in visited_nodes:
                continue
            visited_nodes.add(node_key)
            for edge_key in sorted(adjacency.get(node_key, []), key=lambda key: sort_key(key, node_key)):
                if edge_key in visited_edges:
                    continue
                visited_edges.add(edge_key)
                ordered.append(edge_key)
                entry = legs[edge_key]
                other = (
                    str(entry.get("end_node_key", "") or "")
                    if str(entry.get("start_node_key", "") or "") == node_key
                    else str(entry.get("start_node_key", "") or "")
                )
                if other and other not in visited_nodes and other not in queue:
                    queue.append(other)
        for edge_key in sorted(legs, key=lambda key: str(legs[key].get("stable_signature", ""))):
            if edge_key not in visited_edges:
                ordered.append(edge_key)
        return ordered

    def _build_auto_leg_entries_from_projected(self, projected: ProjectedScene2D) -> list[dict[str, object]]:
        if not any(row.surface == BEAM_SPLITTER_SURFACE for row in getattr(self, "rows", []) or []):
            return []
        legs: dict[tuple[tuple[str, str], tuple[int, ...]], dict[str, object]] = {}
        for ray in getattr(projected, "rays", []) or []:
            points = np.asarray(getattr(ray, "points_2d", []), dtype=float)
            surface_ids = np.asarray(getattr(ray, "surface_ids", []), dtype=int).ravel()
            branch_path = str(getattr(ray, "branch_path", "") or "").strip()
            branch_label = str(getattr(ray, "branch_label", "") or "").strip()
            if points.ndim != 2 or points.shape[0] < 2:
                continue
            breakpoints: list[tuple[int, dict[str, object]]] = [
                (
                    0,
                    {
                        "key": "source",
                        "label": "Input",
                        "row_index": 0 if self.rows else None,
                        "kind": "source",
                    },
                )
            ]
            point_index_by_hit: dict[int, int] = {}
            for hit_index, raw_surface_id in enumerate(surface_ids.tolist()):
                surface_id = int(raw_surface_id)
                point_index = self._auto_leg_hit_point_index(points, surface_ids, hit_index)
                point_index_by_hit[hit_index] = point_index
                if 0 <= surface_id < len(self.rows) and self.rows[surface_id].surface == BEAM_SPLITTER_SURFACE:
                    breakpoints.append((point_index, self._auto_leg_node_for_hit(points[point_index], surface_id)))
            if surface_ids.size:
                terminal_surface_id = int(surface_ids[-1])
                terminal_hit_index = int(surface_ids.size - 1)
                terminal_point_index = point_index_by_hit.get(
                    terminal_hit_index,
                    self._auto_leg_hit_point_index(points, surface_ids, terminal_hit_index),
                )
                if not (0 <= terminal_surface_id < len(self.rows) and self.rows[terminal_surface_id].surface == BEAM_SPLITTER_SURFACE):
                    breakpoints.append(
                        (
                            terminal_point_index,
                            self._auto_leg_node_for_hit(
                                points[terminal_point_index],
                                terminal_surface_id,
                                branch_path=branch_path,
                                branch_label=branch_label,
                            ),
                        )
                    )
            last_surface_is_splitter = (
                bool(surface_ids.size)
                and 0 <= int(surface_ids[-1]) < len(self.rows)
                and self.rows[int(surface_ids[-1])].surface == BEAM_SPLITTER_SURFACE
            )
            if breakpoints[-1][0] < points.shape[0] - 1 and (len(breakpoints) == 1 or last_surface_is_splitter):
                breakpoints.append(
                    (
                        points.shape[0] - 1,
                        self._auto_leg_node_for_hit(
                            points[-1],
                            None,
                            branch_path=branch_path,
                            branch_label=branch_label,
                        ),
                    )
                )

            deduped: list[tuple[int, dict[str, object]]] = []
            for point_index, node in sorted(breakpoints, key=lambda item: item[0]):
                point_index = min(max(int(point_index), 0), points.shape[0] - 1)
                if deduped and point_index == deduped[-1][0] and str(node.get("key", "")) == str(deduped[-1][1].get("key", "")):
                    continue
                if deduped and point_index == deduped[-1][0]:
                    deduped[-1] = (point_index, node)
                else:
                    deduped.append((point_index, node))
            if len(deduped) < 2:
                continue

            for (start_point_index, start_node), (end_point_index, end_node) in zip(deduped[:-1], deduped[1:]):
                if end_point_index <= start_point_index:
                    continue
                polyline = np.asarray(points[start_point_index : end_point_index + 1, :2], dtype=float)
                if polyline.shape[0] < 2 or not np.all(np.isfinite(polyline)):
                    continue
                segment_surface_ids: list[int] = []
                non_branch_surface_ids: list[int] = []
                for hit_index, surface_id_raw in enumerate(surface_ids.tolist()):
                    point_index = point_index_by_hit.get(hit_index)
                    if point_index is None or point_index <= start_point_index or point_index > end_point_index:
                        continue
                    surface_id = int(surface_id_raw)
                    if not (0 <= surface_id < len(self.rows)):
                        continue
                    segment_surface_ids.append(surface_id)
                    if self.rows[surface_id].surface != BEAM_SPLITTER_SURFACE:
                        non_branch_surface_ids.append(surface_id)
                candidate_key = self._auto_leg_candidate_key(start_node, end_node, tuple(non_branch_surface_ids))
                stable_signature = "|".join(
                    [
                        ",".join(candidate_key[0]),
                        ",".join(str(value) for value in candidate_key[1]),
                    ]
                )
                if candidate_key not in legs:
                    legs[candidate_key] = {
                        "start_node": start_node,
                        "end_node": end_node,
                        "start_node_key": str(start_node.get("key", "")),
                        "end_node_key": str(end_node.get("key", "")),
                        "stable_signature": stable_signature,
                        "polylines": [],
                        "surface_indices": set(),
                        "context_indices": set(),
                        "segment_surface_ids": set(),
                    }
                entry = legs[candidate_key]
                entry["polylines"].append(polyline)
                entry["surface_indices"].update(non_branch_surface_ids)
                entry["segment_surface_ids"].update(segment_surface_ids)
                for node in (start_node, end_node):
                    row_index = node.get("row_index")
                    if row_index is not None:
                        entry["context_indices"].add(int(row_index))

        ordered_keys = self._ordered_auto_leg_keys(legs)
        entries: list[dict[str, object]] = []
        for leg_number, key in enumerate(ordered_keys, start=1):
            entry = legs[key]
            polyline = self._auto_leg_representative_polyline(list(entry.get("polylines", []) or []))
            if polyline.shape[0] < 2:
                continue
            stable_hash = hashlib.sha1(str(entry.get("stable_signature", "")).encode("utf-8")).hexdigest()[:10]
            start_label = self._auto_leg_node_label(dict(entry.get("start_node", {}) or {}))
            end_label = self._auto_leg_node_label(dict(entry.get("end_node", {}) or {}))
            via_surface_indices = set(entry.get("surface_indices", set()) or set()) - set(entry.get("context_indices", set()) or set())
            via_names = [
                str(self.rows[index].name or self.rows[index].element or f"S{index}").strip()
                for index in sorted(via_surface_indices)
                if 0 <= int(index) < len(self.rows)
            ]
            if start_label == "Input":
                detail = f"Input to {end_label}"
            else:
                detail = f"{start_label} to {end_label}"
            if via_names:
                detail = f"{detail} via {', '.join(via_names[:3])}"
                if len(via_names) > 3:
                    detail = f"{detail}, +{len(via_names) - 3} more"
            entries.append(
                {
                    "leg_id": f"auto_{stable_hash}",
                    "short_label": f"Path {leg_number}",
                    "detail": detail,
                    "polyline": polyline,
                    "segments": self._leg_geometry_from_points([point for point in polyline]),
                    "surface_indices": set(entry.get("surface_indices", set()) or set()),
                    "context_indices": set(entry.get("context_indices", set()) or set()),
                    "segment_surface_ids": set(entry.get("segment_surface_ids", set()) or set()),
                    "start_node_key": str(entry.get("start_node_key", "")),
                    "end_node_key": str(entry.get("end_node_key", "")),
                }
            )
        return entries

    def _refresh_auto_leg_graph(self, projected: ProjectedScene2D | None) -> None:
        if projected is None:
            self._last_auto_leg_entries = []
            return
        try:
            self._last_auto_leg_entries = self._build_auto_leg_entries_from_projected(projected)
        except Exception as exc:
            self._last_auto_leg_entries = []
            self.append_debug(f"Automatic path graph skipped: {_short_error_message(exc)}")

    def _physical_leg_workflow(self) -> str:
        if not getattr(self, "rows", None):
            return ""
        hint = self._layout_interferometer_hint()
        if "mach" in hint and "zehnder" in hint:
            return "mach_zehnder"
        if "michelson" in hint or "twyman" in hint:
            return "michelson"
        target_codes = set(self._branch_output_display_targets())
        if {"TT", "TR", "RT", "RR"}.issubset(target_codes):
            return "michelson"
        return ""

    def _physical_leg_definitions(self) -> tuple[tuple[str, str, str], ...]:
        workflow = self._physical_leg_workflow()
        if workflow == "mach_zehnder":
            return MACH_ZEHNDER_LEG_DEFINITIONS
        if workflow == "michelson":
            return MICHELSON_LEG_DEFINITIONS
        auto_entries = self._auto_leg_entries()
        if auto_entries:
            return tuple(
                (
                    str(entry.get("leg_id", "") or "").strip().lower(),
                    str(entry.get("short_label", "") or "").strip(),
                    str(entry.get("detail", "") or "").strip(),
                )
                for entry in auto_entries
                if str(entry.get("leg_id", "") or "").strip()
            )
        return ()

    def _physical_leg_ids(self) -> set[str]:
        ids = {leg_id for leg_id, _short_label, _detail in self._physical_leg_definitions()}
        for row in getattr(self, "rows", []) or []:
            leg_id = str(self._element_metadata(row).get("leg_id", "") or "").strip().lower()
            if leg_id:
                ids.add(leg_id)
        return ids

    def _leg_short_label(self, leg_id: str) -> str:
        leg_id = str(leg_id or "").strip().lower()
        for defined_id, short_label, _detail in self._physical_leg_definitions():
            if leg_id == defined_id:
                return short_label
        return ""

    def _leg_id_from_element_metadata(
        self,
        metadata: dict[str, object],
        *,
        row: SurfaceRow | None = None,
        row_index: int | None = None,
    ) -> str:
        valid_leg_ids = self._physical_leg_ids()
        explicit = str(metadata.get("leg_id", "") or "").strip().lower()
        if explicit in valid_leg_ids:
            return explicit
        workflow = self._physical_leg_workflow()
        role = str(metadata.get("arm_role", ELEMENT_ARM_ROLE_DEFAULT) or ELEMENT_ARM_ROLE_DEFAULT).strip()
        selector = str(metadata.get("branch_selector", "") or "").strip().lower()
        parent = str(metadata.get("parent_splitter", "") or "").strip().lower()
        row_text = ""
        if row is not None:
            row_text = " ".join(
                [
                    str(getattr(row, "element", "") or ""),
                    str(getattr(row, "name", "") or ""),
                    str(getattr(row, "surface", "") or ""),
                    str(metadata.get("element_id", "") or ""),
                    str(metadata.get("element_name", "") or ""),
                ]
            ).lower()
        if workflow == "mach_zehnder":
            if row_index == 0:
                return "input"
            if role == "Common":
                if selector == "primary" or "bs1" in row_text or "input splitter" in row_text:
                    return "input"
                return ""
            if selector == "transmit" and role in {"Transmit", "Return"}:
                return "transmit"
            if selector == "reflect" and role in {"Reflect", "Return"}:
                return "reflect"
            if role == "Detector":
                if selector == "transmit" or "cross" in row_text:
                    return "cross"
                if selector == "reflect" or "return" in row_text:
                    return "return"
            if parent == "bs2" and selector == "transmit":
                return "cross"
            if parent == "bs2" and selector == "reflect":
                return "return"
            return ""
        if workflow == "michelson":
            if row_index == 0:
                return "input"
            if role == "Common" or selector == "primary":
                return "input"
            if row is not None and self._row_has_detector_output_metadata(row):
                return "detector"
            if role == "Detector":
                return "detector"
            if role == "Reflect" or selector == "reflect":
                return "reflect"
            if role == "Transmit" or selector == "transmit":
                return "transmit"
        return ""

    def _michelson_leg_badge_for_index(self, index: int) -> str:
        if not self._uses_michelson_leg_workflow() or not (0 <= index < len(self.rows)):
            return ""
        row = self.rows[index]
        metadata = self._element_metadata(row)
        leg_id = self._leg_id_from_element_metadata(metadata, row=row, row_index=index)
        return self._leg_badge_text(self._leg_short_label(leg_id)) if leg_id else ""

    @staticmethod
    def _branch_selector_for_arm_role(role: str) -> str:
        if role == "Transmit":
            return "transmit"
        if role == "Reflect":
            return "reflect"
        return ""

    @staticmethod
    def _arm_key_from_metadata(metadata: dict[str, object]) -> str:
        leg_id = str(metadata.get("leg_id", "") or "").strip().lower()
        if leg_id:
            return f"leg|{leg_id}"
        role = str(metadata.get("arm_role", ELEMENT_ARM_ROLE_DEFAULT) or ELEMENT_ARM_ROLE_DEFAULT).strip()
        if role in {"", ELEMENT_ARM_ROLE_DEFAULT, "Common"}:
            return ""
        selector = str(metadata.get("branch_selector", "") or "").strip().lower()
        parent = str(metadata.get("parent_splitter", "") or "").strip()
        if selector in {"primary", "transmit", "reflect", "return"}:
            return f"branch|{parent}|{selector}"
        return f"role|{role}"

    @staticmethod
    def _arm_key_from_branch_path(branch_path: str) -> str:
        path = str(branch_path or "").strip()
        if not path or path == "primary":
            return ""
        return f"path|{path}"

    @staticmethod
    def _leg_key(leg_id: str) -> str:
        return f"leg|{str(leg_id or '').strip().lower()}"

    @staticmethod
    def _leg_id_from_arm_key(key: str) -> str:
        text = str(key or "").strip()
        if not text.startswith("leg|"):
            return ""
        return text.split("|", 1)[1].strip().lower()

    @staticmethod
    def _branch_path_for_arm_key(key: str) -> str:
        text = str(key or "").strip()
        if text.startswith("path|"):
            return text.split("|", 1)[1].strip()
        return ""

    @staticmethod
    def _branch_path_leaf_selector(branch_path: str) -> str:
        leaf = str(branch_path or "").split("->")[-1].strip()
        if "/" not in leaf:
            return ""
        return leaf.rsplit("/", 1)[1].strip().lower()

    @staticmethod
    def _branch_path_surface_indices(branch_path: str) -> set[int]:
        indices: set[int] = set()
        for match in re.finditer(r"(?:^|\s)S(\d+):", str(branch_path or "")):
            try:
                indices.add(int(match.group(1)))
            except ValueError:
                continue
        return indices

    @staticmethod
    def _branch_path_detail(branch_path: str) -> str:
        parts: list[str] = []
        for component in str(branch_path or "").split("->"):
            text = component.strip()
            if not text:
                continue
            surface_text, _, selector = text.rpartition("/")
            if not surface_text:
                surface_text = text
            if ":" in surface_text:
                surface_text = surface_text.split(":", 1)[1].strip()
            surface_text = surface_text.strip()
            selector = selector.strip()
            if surface_text and selector:
                parts.append(f"{surface_text} {selector}")
            elif selector:
                parts.append(selector)
            elif surface_text:
                parts.append(surface_text)
        return " -> ".join(parts) if parts else str(branch_path or "").strip()

    @staticmethod
    def _branch_path_depth(branch_path: str) -> int:
        return sum(1 for component in str(branch_path or "").split("->") if component.strip())

    @staticmethod
    def _branch_path_selector_sequence(branch_path: str) -> list[str]:
        selectors: list[str] = []
        for component in str(branch_path or "").split("->"):
            text = component.strip()
            if "/" not in text:
                continue
            selector = text.rsplit("/", 1)[1].strip().lower()
            selectors.append({"transmit": "T", "reflect": "R"}.get(selector, selector or "?"))
        return selectors

    @staticmethod
    def _branch_path_compact_detail(branch_path: str) -> str:
        selectors = KrakenLayoutEditor._branch_path_selector_sequence(branch_path)
        if selectors:
            return " -> ".join(selectors)
        return KrakenLayoutEditor._branch_path_detail(branch_path)

    def _arm_key_detail(self, key: str) -> str:
        parts = str(key or "").split("|")
        if len(parts) >= 2 and parts[0] == "leg":
            leg_id = parts[1].strip().lower()
            for defined_id, _short_label, detail in self._physical_leg_definitions():
                if leg_id == defined_id:
                    return detail
            return leg_id
        if len(parts) >= 2 and parts[0] == "path":
            path = "|".join(parts[1:])
            if KrakenLayoutEditor._branch_path_depth(path) > 1:
                return KrakenLayoutEditor._branch_path_compact_detail(path)
            return KrakenLayoutEditor._branch_path_detail(path)
        if len(parts) >= 3 and parts[0] == "branch":
            parent = parts[1].strip()
            selector = parts[2].strip()
            return f"{parent} {selector}".strip() if parent else selector
        if len(parts) >= 2 and parts[0] == "role":
            return parts[1].strip()
        return str(key or "").strip()

    def _traced_branch_paths(self) -> list[str]:
        bundle = getattr(self, "_last_scene_bundle", None)
        paths: list[str] = []
        seen: set[str] = set()
        for path in getattr(bundle, "ray_paths", []) or []:
            branch_path = str(getattr(path, "branch_path", "") or "").strip()
            if not branch_path or branch_path == "primary" or branch_path in seen:
                continue
            seen.add(branch_path)
            paths.append(branch_path)
        return paths

    @classmethod
    def _metadata_arm_key_matches_branch_path(cls, arm_key: str, branch_path: str) -> bool:
        parts = str(arm_key or "").split("|")
        if len(parts) < 3 or parts[0] != "branch":
            return False
        parent = parts[1].strip().lower()
        selector = parts[2].strip().lower()
        if selector and selector != cls._branch_path_leaf_selector(branch_path):
            return False
        if not parent:
            return True
        path_text = str(branch_path or "").lower()
        if parent in path_text:
            return True
        # Saved Element metadata often uses a stable splitter id such as BS1,
        # while traced paths use the KrakenOS surface label. A matching leaf
        # selector is still the same logical path and should not create a
        # duplicate metadata label beside the traced branch/path label.
        return bool(selector)

    def _uses_michelson_leg_workflow(self) -> bool:
        return bool(self._physical_leg_definitions())

    def _leg_catalog(self) -> list[dict[str, str]]:
        definitions = self._physical_leg_definitions()
        if not definitions:
            return []
        catalog: list[dict[str, str]] = []
        for leg_id, short_label, detail in definitions:
            catalog.append(
                {
                    "key": self._leg_key(leg_id),
                    "short_label": short_label,
                    "label": f"{short_label}: {detail}",
                    "detail": detail,
                    "kind": "leg",
                }
            )
        return catalog

    def _arm_catalog(self) -> list[dict[str, str]]:
        catalog: list[dict[str, str]] = []
        seen: set[str] = set()
        if not self.rows:
            return catalog
        leg_catalog = self._leg_catalog()
        if leg_catalog:
            return leg_catalog

        def add_entry(key: str, detail: str, prefix: str = "Path") -> None:
            if not key or key in seen:
                return
            seen.add(key)
            arm_number = len(catalog) + 1
            label = f"{prefix} {arm_number}: {detail}" if detail else f"{prefix} {arm_number}"
            catalog.append(
                {
                    "key": key,
                    "short_label": f"{prefix} {arm_number}",
                    "label": label,
                    "detail": detail,
                    "kind": prefix.lower(),
                }
            )

        traced_paths = self._traced_branch_paths()
        for branch_path in traced_paths:
            depth = self._branch_path_depth(branch_path)
            detail = (
                self._branch_path_compact_detail(branch_path)
                if depth > 1
                else self._branch_path_detail(branch_path)
            )
            add_entry(self._arm_key_from_branch_path(branch_path), detail, prefix="Path")

        index = 1
        while index < len(self.rows) - 1:
            start, end = self._element_block_for_index(self.rows, index)
            metadata = self._element_metadata(self.rows[start])
            key = self._arm_key_from_metadata(metadata)
            if key and not any(self._metadata_arm_key_matches_branch_path(key, path) for path in traced_paths):
                add_entry(key, self._arm_key_detail(key))
            index = max(end + 1, index + 1)
        return catalog

    @classmethod
    def _element_block_for_index(cls, rows: list[SurfaceRow], index: int) -> tuple[int, int]:
        if not (0 <= index < len(rows)):
            return index, index
        key = cls._element_key(rows[index])
        if not key:
            return index, index
        start = index
        end = index
        while start > 0 and cls._element_key(rows[start - 1]) == key:
            start -= 1
        while end + 1 < len(rows) and cls._element_key(rows[end + 1]) == key:
            end += 1
        return start, end

    @classmethod
    def _swap_element_block_same_arm(
        cls,
        rows: list[SurfaceRow],
        selected_index: int,
        direction: str,
    ) -> tuple[list[SurfaceRow], int, int, bool]:
        start, end = cls._element_block_for_index(rows, selected_index)
        role = cls._element_arm_role_for_index(rows, selected_index)
        if role == ELEMENT_ARM_ROLE_DEFAULT:
            return rows, start, end, False
        current = rows[start : end + 1]
        if direction == "up":
            scan = start - 1
            while scan > 0:
                previous_start, previous_end = cls._element_block_for_index(rows, scan)
                if cls._element_arm_role_for_index(rows, previous_start) == role:
                    previous = rows[previous_start : previous_end + 1]
                    middle = rows[previous_end + 1 : start]
                    new_rows = rows[:previous_start] + current + middle + previous + rows[end + 1 :]
                    new_start = previous_start
                    return new_rows, new_start, new_start + len(current) - 1, True
                scan = previous_start - 1
            return rows, start, end, False
        if direction == "down":
            scan = end + 1
            while scan < len(rows) - 1:
                next_start, next_end = cls._element_block_for_index(rows, scan)
                if cls._element_arm_role_for_index(rows, next_start) == role:
                    next_block = rows[next_start : next_end + 1]
                    middle = rows[end + 1 : next_start]
                    new_rows = rows[:start] + next_block + middle + current + rows[next_end + 1 :]
                    new_start = start + len(next_block) + len(middle)
                    return new_rows, new_start, new_start + len(current) - 1, True
                scan = next_end + 1
            return rows, start, end, False
        return rows, start, end, False

    @classmethod
    def _swap_element_block(
        cls,
        rows: list[SurfaceRow],
        selected_index: int,
        direction: str,
        *,
        same_arm_only: bool = False,
    ) -> tuple[list[SurfaceRow], int, int, bool]:
        if not rows or not (0 <= selected_index < len(rows)):
            return rows, selected_index, selected_index, False
        start, end = cls._element_block_for_index(rows, selected_index)
        if same_arm_only:
            arm_rows, arm_start, arm_end, arm_moved = cls._swap_element_block_same_arm(rows, selected_index, direction)
            if arm_moved:
                return arm_rows, arm_start, arm_end, True
            if cls._element_arm_role_for_index(rows, selected_index) != ELEMENT_ARM_ROLE_DEFAULT:
                return rows, start, end, False
        if direction == "up":
            if start <= 1:
                return rows, start, end, False
            previous_start, previous_end = cls._element_block_for_index(rows, start - 1)
            if previous_start <= 0:
                return rows, start, end, False
            current = rows[start : end + 1]
            previous = rows[previous_start : previous_end + 1]
            new_rows = rows[:previous_start] + current + previous + rows[end + 1 :]
            new_start = previous_start
            return new_rows, new_start, new_start + len(current) - 1, True
        if direction == "down":
            if end >= len(rows) - 2:
                return rows, start, end, False
            next_start, next_end = cls._element_block_for_index(rows, end + 1)
            if next_end >= len(rows) - 1:
                return rows, start, end, False
            current = rows[start : end + 1]
            next_block = rows[next_start : next_end + 1]
            new_rows = rows[:start] + next_block + current + rows[next_end + 1 :]
            new_start = start + len(next_block)
            return new_rows, new_start, new_start + len(current) - 1, True
        return rows, start, end, False

    @classmethod
    def _element_indices_for_index(cls, rows: list[SurfaceRow], index: int) -> list[int]:
        if not (0 <= index < len(rows)):
            return []
        start, end = cls._element_block_for_index(rows, index)
        return list(range(start, end + 1))

    @staticmethod
    def _table_iid_for_row_index(index: int) -> str:
        return f"row_{int(index)}"

    def _table_item_row_index(self, item: str | None) -> int | None:
        if not item:
            return None
        text = str(item)
        mapped = self.__dict__.get("_table_iid_to_row_index", {}).get(text)
        if mapped is not None:
            return int(mapped)
        if text.startswith("row_"):
            try:
                return int(text.split("_", 1)[1])
            except ValueError:
                return None
        try:
            return int(self.table.index(text))
        except Exception:
            return None

    def _table_item_for_row_index(self, row_index: int) -> str | None:
        item = self._table_iid_for_row_index(row_index)
        try:
            return item if self.table.exists(item) else None
        except Exception:
            return None

    def _current_arm_view_key(self) -> str:
        return self._arm_key_for_view_label(str(self.arm_view_var.get() or ARM_VIEW_DEFAULT))

    def _default_insert_index_for_arm_key(self, arm_key: str) -> int:
        leg_id = self._leg_id_from_arm_key(arm_key)
        arm_indices = self._indices_for_arm_key(arm_key)
        if leg_id == "input":
            for index in range(1, max(len(self.rows) - 1, 1)):
                if self.rows[index].surface == BEAM_SPLITTER_SURFACE:
                    return index
            return 1
        if leg_id in {"reflect", "transmit", "detector", "cross", "return"} and arm_indices:
            return min(arm_indices)
        return (max(arm_indices) + 1) if arm_indices else max(1, len(self.rows) - 1)

    def _visible_row_indices_for_current_arm_view(self) -> list[int]:
        if not self.rows:
            return []
        arm_key = self._current_arm_view_key()
        if not arm_key:
            return list(range(len(self.rows)))
        allowed = self._context_surface_indices_for_arm_key(arm_key) | self._surface_indices_for_arm_key(arm_key)
        return [index for index in range(len(self.rows)) if index in allowed]

    def _sync_table(self) -> None:
        self._apply_image_diameter_mode()
        self.table.delete(*self.table.get_children())
        self._table_iid_to_row_index = {}
        self._refresh_arm_view_choices()
        visible_indices = self._visible_row_indices_for_current_arm_view()
        self._table_visible_row_indices = list(visible_indices)
        palette = self._element_tag_palette()
        element_tags: dict[str, str] = {}
        for index in visible_indices:
            row = self.rows[index]
            row.label = str(index)
            if row.surface == "Mirror":
                overlay_slants = self._mirror_overlay_display_slants_for_rows(self.rows, index)
                tilt_x_text = _format_float_sequence(overlay_slants) if len(overlay_slants) > 1 else self._format_numeric_cell(
                    "tilt_x",
                    row,
                    display_value=self._mirror_display_slant_deg_for_rows(self.rows, index),
                )
            else:
                tilt_x_text = self._format_numeric_cell("tilt_x", row)
            arm_badge = self._michelson_leg_badge_for_index(index) or self._element_arm_badge_for_index(self.rows, index)
            label_text = f"{index} {arm_badge}" if arm_badge else str(index)
            raw_values = {
                "label": label_text,
                "surface": row.surface,
                "name": row.name,
                "glass": row.glass,
                "rc": self._format_numeric_cell("rc", row),
                "k": self._format_numeric_cell("k", row),
                "axicon": self._format_table_float(row.axicon),
                "diff_ord": self._format_table_float(row.diff_ord),
                "grating_d": self._format_numeric_cell("grating_d", row),
                "grating_angle": self._format_numeric_cell("grating_angle", row),
                "thickness": self._format_numeric_cell("thickness", row),
                "diameter": self._format_table_float(row.diameter),
                "in_diameter": self._format_table_float(row.in_diameter),
                "tilt_x": tilt_x_text,
                "tilt_y": self._format_numeric_cell("tilt_y", row),
                "tilt_z": self._format_numeric_cell("tilt_z", row),
                "desp_x": self._format_numeric_cell("desp_x", row),
                "desp_y": self._format_numeric_cell("desp_y", row),
                "desp_z": self._format_numeric_cell("desp_z", row),
                "axis_move": self._format_numeric_cell("axis_move", row),
            }
            values = [self._table_display_value(row, field, raw_values[field]) for field in FIELDS]
            tags: list[str] = []
            if self._row_has_optimization(row):
                tags.append("optimize")
            element_key = self._element_key(row)
            if element_key:
                tag = element_tags.get(element_key)
                if tag is None:
                    tag = palette[len(element_tags) % len(palette)][0]
                    element_tags[element_key] = tag
                tags.append(tag)
            iid = self._table_iid_for_row_index(index)
            self._table_iid_to_row_index[iid] = index
            self.table.insert("", "end", iid=iid, values=values, tags=tags)
        self._refresh_analysis_surface_choices()
        self._refresh_operand_surface_choices()
        self._schedule_table_grid_update(delay=1)

    def _sync_image_row_table_value(self) -> None:
        table = self.__dict__.get("table")
        if table is None or not self.rows:
            return
        items = table.get_children()
        if not items:
            return
        image_item = self._table_item_for_row_index(len(self.rows) - 1)
        if image_item is None:
            return
        values = list(table.item(image_item, "values"))
        diameter_index = FIELDS.index("diameter")
        if len(values) <= diameter_index:
            return
        values[diameter_index] = self._table_display_value(
            self.rows[-1],
            "diameter",
            self._format_table_float(self.rows[-1].diameter),
        )
        table.item(image_item, values=values)

    def _refresh_analysis_surface_choices(self) -> None:
        options = ["Auto"]
        for index, row in enumerate(self.rows):
            options.append(f"{index}: {row.name}")
        current = self.analysis_surface_var.get()
        self.analysis_surface_menu["values"] = options
        if current not in options:
            self.analysis_surface_var.set("Auto")
        if hasattr(self, "nonseq_target_surface_menu") and hasattr(self, "nonseq_target_surface_var"):
            target_current = self.nonseq_target_surface_var.get()
            self.nonseq_target_surface_menu["values"] = options
            if target_current not in options:
                self.nonseq_target_surface_var.set("Auto")
        self._schedule_table_grid_update()
        self.after_idle(self._update_active_cell_border)

    @staticmethod
    def _parse_numeric_display(value: str) -> float:
        return float(value.replace("*", "").strip())

    @staticmethod
    def _normalized_rows_copy(rows: list[SurfaceRow]) -> list[SurfaceRow]:
        copied = [SurfaceRow(**asdict(row)) for row in rows]
        if copied:
            copied[0].element = ""
            copied[0].advanced = dict(copied[0].advanced or {})
            copied[0].advanced.pop(ELEMENT_ADVANCED_ATTR, None)
            copied[0].surface = "Object"
            if not copied[0].name or copied[0].name == "Surface":
                copied[0].name = "Object"
            copied[-1].element = ""
            copied[-1].advanced = dict(copied[-1].advanced or {})
            copied[-1].advanced.pop(ELEMENT_ADVANCED_ATTR, None)
            copied[-1].surface = "Image"
            if not copied[-1].name or copied[-1].name == "Surface":
                copied[-1].name = "Image"
        return copied

    @staticmethod
    def _is_air_like_glass(glass: str) -> bool:
        value = str(glass or "").strip().upper()
        return value in {"", "AIR", "VACUUM", "NONE", "NULL"} or value.startswith("AIR")

    @classmethod
    def _auto_element_label_for_group(
        cls,
        rows: list[SurfaceRow],
        group: list[int],
        element_number: int,
    ) -> tuple[str, bool]:
        if len(group) == 1:
            row = rows[group[0]]
            if row.surface == "Aperture":
                return (str(row.name or "Stop").strip() or "Stop"), False
            if row.surface in {"Mirror", BEAM_SPLITTER_SURFACE, "Thin Lens", "Grating"}:
                return (str(row.name or row.surface).strip() or row.surface), True
        materials: list[str] = []
        for index in group:
            glass = str(rows[index].glass or "").strip()
            if not cls._is_air_like_glass(glass) and glass.upper() != "MIRROR" and glass not in materials:
                materials.append(glass)
        suffix = f" {'/'.join(materials)}" if materials else ""
        return f"E{element_number}{suffix}", True

    @classmethod
    def _auto_assign_missing_elements(cls, rows: list[SurfaceRow]) -> None:
        """Infer Element groups for legacy sequential layouts with no metadata."""
        if not rows or any(cls._element_key(row) for row in rows[1:-1]):
            return
        groups: list[list[int]] = []
        current_group: list[int] = []
        for index, row in enumerate(rows[1:-1], start=1):
            if row.surface in {"Object", "Image"}:
                continue
            if row.surface == "Aperture":
                if current_group:
                    groups.append(current_group)
                    current_group = []
                groups.append([index])
                continue
            if row.surface in {"Mirror", BEAM_SPLITTER_SURFACE, "Thin Lens", "Grating"}:
                if current_group:
                    groups.append(current_group)
                    current_group = []
                groups.append([index])
                continue
            if cls._is_air_like_glass(row.glass):
                if current_group:
                    current_group.append(index)
                    groups.append(current_group)
                    current_group = []
                continue
            current_group.append(index)
        if current_group:
            groups.append(current_group)

        element_number = 1
        for group in groups:
            label, consumes_number = cls._auto_element_label_for_group(rows, group, element_number)
            for index in group:
                rows[index].element = label
            if consumes_number:
                element_number += 1

    @staticmethod
    def _is_empty_starter_rows(rows: list[SurfaceRow]) -> bool:
        return (
            len(rows) == 2
            and rows[0].surface == "Object"
            and rows[-1].surface == "Image"
            and rows[0].glass == "AIR"
            and rows[-1].glass == "AIR"
        )

    def _selected_insert_index(self) -> int | None:
        selected = self.table.selection()
        if not selected:
            return None
        indices = self._selected_table_indices()
        if not indices:
            return None
        return indices[-1]

    def _select_inserted_layout_rows(self, layout_rows: list[SurfaceRow], insert_after: int | None) -> None:
        additions = max(len(layout_rows) - 2, 0)
        if additions <= 0:
            return
        if insert_after is None:
            insert_at = len(self.rows) - additions
            if self.rows and self.rows[-1].surface == "Image":
                insert_at -= 1
        else:
            insert_at = min(insert_after + 1, len(self.rows) - additions)
        self._select_table_indices(list(range(insert_at, insert_at + additions)), focus_index=insert_at)

    @staticmethod
    def _append_layout_rows(
        existing_rows: list[SurfaceRow],
        layout_rows: list[SurfaceRow],
        insert_after: int | None = None,
        element_name: str = "",
    ) -> list[SurfaceRow]:
        base = [SurfaceRow(**asdict(row)) for row in existing_rows]
        additions = [SurfaceRow(**asdict(row)) for row in layout_rows[1:-1]]
        if not additions:
            return base
        component_element = str(element_name).strip()
        if not component_element:
            component_element = next((KrakenLayoutEditor._element_key(row) for row in additions if KrakenLayoutEditor._element_key(row)), "")
        if not component_element and len(additions) > 1:
            component_element = str(additions[0].name or "Element").strip()
        if component_element:
            for row in additions:
                if not KrakenLayoutEditor._element_key(row):
                    row.element = component_element
        if insert_after is None:
            insert_at = len(base)
            if base and base[-1].surface == "Image":
                insert_at -= 1
        else:
            insert_at = max(0, min(insert_after + 1, len(base)))
            if base and base[-1].surface == "Image":
                insert_at = min(insert_at, len(base) - 1)
        for offset, row in enumerate(additions):
            base.insert(insert_at + offset, row)
        return base

    @classmethod
    def _format_numeric_cell(cls, field: str, row: SurfaceRow, *, display_value: float | None = None) -> str:
        spec = VARIABLE_REGISTRY.get(field)
        value = getattr(row, spec.field if spec is not None else field, 0.0)
        if display_value is not None:
            value = display_value
        mark = bool(spec is not None and spec.is_supported(row) and cls._variable_enabled_for_row(row, spec))
        text = KrakenLayoutEditor._format_table_float(value)
        if mark:
            text += " *"
        return text

    @staticmethod
    def _format_table_float(value: float) -> str:
        return f"{float(value):.12g}"

    @staticmethod
    def _surface_type_enabled_fields(surface_type: str) -> set[str]:
        return set(SURFACE_TYPE_ENABLED_FIELDS.get(str(surface_type), SURFACE_TYPE_ENABLED_FIELDS["Standard"]))

    @classmethod
    def _surface_type_field_enabled(cls, row: SurfaceRow, field: str) -> bool:
        return field in cls._surface_type_enabled_fields(row.surface)

    @classmethod
    def _table_display_value(cls, row: SurfaceRow, field: str, value: object) -> str:
        if not cls._surface_type_field_enabled(row, field):
            return DISABLED_TABLE_CELL_TEXT
        return str(value)

    def _table_cell_enabled(self, row_index: int, field: str) -> bool:
        if not (0 <= row_index < len(self.rows)):
            return True
        return self._surface_type_field_enabled(self.rows[row_index], field)

    def _surface_type_disabled_message(self, row_index: int, field: str) -> str:
        row = self.rows[row_index]
        return (
            f"{COLUMN_LABELS.get(field, field)} is not used by {row.surface} rows. "
            "Use Advanced... for KrakenOS-native attributes outside this template."
        )

    @staticmethod
    def _normalize_mirror_slant_deg(angle_deg: float) -> float:
        angle = float(angle_deg)
        while angle <= -90.0:
            angle += 180.0
        while angle > 90.0:
            angle -= 180.0
        if abs(angle) < 1e-12:
            return 0.0
        return angle

    @classmethod
    def _mirror_branch_after_slant_deg(cls, branch_angle_deg: float, slant_angle_deg: float) -> float:
        direction = np.array(
            [np.cos(np.deg2rad(float(branch_angle_deg))), np.sin(np.deg2rad(float(branch_angle_deg)))],
            dtype=float,
        )
        reflected = cls._reflect_2d(direction, float(slant_angle_deg))
        return float(np.rad2deg(np.arctan2(reflected[1], reflected[0])))

    @classmethod
    def _mirror_display_slant_deg_for_rows(cls, rows: list[SurfaceRow], row_index: int) -> float:
        branch_angle = 0.0
        for index, row in enumerate(rows):
            if row.surface != "Mirror":
                continue
            slant_angle = cls._normalize_mirror_slant_deg(branch_angle - 90.0 + float(row.tilt_x))
            if index == row_index:
                return slant_angle
            branch_angle = cls._mirror_branch_after_slant_deg(branch_angle, slant_angle)
        return float(rows[row_index].tilt_x)

    @classmethod
    def _mirror_local_tilt_deg_from_display(
        cls,
        branch_angle_deg: float,
        display_slant_deg: float,
    ) -> float:
        return cls._normalize_mirror_slant_deg(float(display_slant_deg) - branch_angle_deg + 90.0)

    @classmethod
    def _mirror_branch_angle_before_index(cls, rows: list[SurfaceRow], row_index: int) -> float:
        branch_angle = 0.0
        for index, row in enumerate(rows):
            if index >= row_index:
                break
            if row.surface != "Mirror":
                continue
            slant_angle = cls._normalize_mirror_slant_deg(branch_angle - 90.0 + float(row.tilt_x))
            branch_angle = cls._mirror_branch_after_slant_deg(branch_angle, slant_angle)
        return branch_angle

    @staticmethod
    def _advanced_with_galvo_scan_overlay(advanced: dict | None, values: list[float]) -> dict:
        updated = dict(advanced or {})
        display = dict(updated.get("Display2D", {}) or {})
        if values:
            display[GALVO_SCAN_OVERLAY_KEY] = [float(value) for value in values]
            updated["Display2D"] = display
        else:
            display.pop(GALVO_SCAN_OVERLAY_KEY, None)
            if display:
                updated["Display2D"] = display
            else:
                updated.pop("Display2D", None)
        return updated

    @classmethod
    def _mirror_overlay_display_slants_for_rows(cls, rows: list[SurfaceRow], row_index: int) -> list[float]:
        if not (0 <= row_index < len(rows)) or rows[row_index].surface != "Mirror":
            return []
        local_values = cls._galvo_scan_overlay_values(rows[row_index])
        if not local_values:
            return []
        branch_angle = cls._mirror_branch_angle_before_index(rows, row_index)
        return [
            cls._normalize_mirror_slant_deg(branch_angle - 90.0 + float(local_tilt))
            for local_tilt in local_values
        ]

    def _read_rows_from_table(self) -> None:
        rows = [SurfaceRow(**asdict(row)) for row in self.rows]
        for item in self.table.get_children():
            row_index = self._table_item_row_index(item)
            if row_index is None or not (0 <= row_index < len(rows)):
                continue
            values = self.table.item(item, "values")
            fields = {field: values[index] if index < len(values) else "" for index, field in enumerate(FIELDS)}
            previous = self.rows[row_index] if row_index < len(self.rows) else SurfaceRow(label=str(row_index))
            surface = str(fields["surface"] or previous.surface)
            enabled_fields = self._surface_type_enabled_fields(surface)
            advanced = dict(previous.advanced)

            def text_field(field: str, attr: str) -> str:
                value = str(fields.get(field, "")).strip()
                if field not in fields or field not in enabled_fields:
                    return str(getattr(previous, attr))
                return value

            def numeric_field(field: str, attr: str) -> float:
                value = str(fields.get(field, "")).strip()
                if field not in fields or field not in enabled_fields or not value or value.upper() == DISABLED_TABLE_CELL_TEXT:
                    return float(getattr(previous, attr))
                if field in {"rc", "thickness"}:
                    return self._parse_numeric_display(value)
                return float(value)

            def tilt_x_field() -> float:
                nonlocal advanced
                value = str(fields.get("tilt_x", "")).replace("*", "").strip()
                if "tilt_x" not in fields or "tilt_x" not in enabled_fields or not value or value.upper() == DISABLED_TABLE_CELL_TEXT:
                    return float(previous.tilt_x)
                if surface != "Mirror":
                    advanced = self._advanced_with_galvo_scan_overlay(advanced, [])
                    return float(value)
                display_values = _parse_float_sequence_text(value)
                if not display_values:
                    return float(previous.tilt_x)
                branch_angle = self._mirror_branch_angle_before_index(rows, row_index)
                local_values = [
                    self._mirror_local_tilt_deg_from_display(branch_angle, display_value)
                    for display_value in display_values
                ]
                if len(local_values) > 1:
                    if len(local_values) > 25:
                        raise ValueError("TiltX scan overlay supports 25 or fewer values.")
                    advanced = self._advanced_with_galvo_scan_overlay(advanced, local_values)
                    return float(local_values[len(local_values) // 2])
                advanced = self._advanced_with_galvo_scan_overlay(advanced, [])
                return float(local_values[0])

            tilt_x_value = tilt_x_field()
            rows[row_index] = (
                SurfaceRow(
                    label=str(row_index),
                    element=previous.element,
                    surface=surface,
                    name=text_field("name", "name"),
                    glass=text_field("glass", "glass"),
                    optimize_rc=previous.optimize_rc,
                    optimize_rc_bounds=previous.optimize_rc_bounds,
                    rc=numeric_field("rc", "rc"),
                    k=numeric_field("k", "k"),
                    axicon=numeric_field("axicon", "axicon"),
                    diff_ord=numeric_field("diff_ord", "diff_ord"),
                    grating_d=numeric_field("grating_d", "grating_d"),
                    grating_angle=numeric_field("grating_angle", "grating_angle"),
                    optimize_thickness=previous.optimize_thickness,
                    optimize_thickness_bounds=previous.optimize_thickness_bounds,
                    thickness=numeric_field("thickness", "thickness"),
                    diameter=numeric_field("diameter", "diameter"),
                    in_diameter=numeric_field("in_diameter", "in_diameter"),
                    drawing=previous.drawing,
                    extra_data=previous.extra_data,
                    uda=previous.uda,
                    advanced=advanced,
                    tilt_x=tilt_x_value,
                    tilt_y=numeric_field("tilt_y", "tilt_y"),
                    tilt_z=numeric_field("tilt_z", "tilt_z"),
                    desp_x=numeric_field("desp_x", "desp_x"),
                    desp_y=numeric_field("desp_y", "desp_y"),
                    desp_z=numeric_field("desp_z", "desp_z"),
                    axis_move=numeric_field("axis_move", "axis_move"),
                )
            )
        self.rows = rows

    def _on_table_click(self, event: tk.Event) -> str | None:
        region = self.table.identify_region(event.x, event.y)
        if region == "separator":
            self._table_column_resize_active = True
            self._clear_table_grid()
            self._hide_active_cell_border()
            self._schedule_table_grid_update(delay=1)
            return None
        if region == "heading":
            return None
        self._table_column_resize_active = False
        row_id = self.table.identify_row(event.y)
        column_id = self.table.identify_column(event.x)
        self.table.focus_set()
        if not row_id or not column_id:
            self._clear_table_selection()
            return "break"
        self._active_cell = (row_id, column_id)
        children = list(self.table.get_children())
        shift_pressed = bool(event.state & 0x0001)
        control_pressed = bool(event.state & 0x0004)
        if column_id == "#1" and children and not shift_pressed:
            row_index = self._table_item_row_index(row_id)
            if row_index is None:
                return "break"
            block_indices = self._element_indices_for_index(self.rows, row_index)
            block_items = [
                item
                for index in block_indices
                for item in [self._table_item_for_row_index(index)]
                if item is not None
            ]
            self._active_cell = None
            if control_pressed:
                selected = set(self.table.selection())
                if block_items and all(item in selected for item in block_items):
                    selected.difference_update(block_items)
                else:
                    selected.update(block_items or [row_id])
                ordered = [item for item in children if item in selected]
                if ordered:
                    self.table.selection_set(ordered)
                else:
                    self.table.selection_remove(*children)
                self._selection_anchor_row = row_id
                self.table.focus(row_id)
            else:
                self.table.selection_set(block_items or [row_id])
                self._selection_anchor_row = row_id
                self.table.focus(row_id)
            self.after_idle(self._update_active_cell_border)
            return "break"
        if shift_pressed and children:
            anchor = self._selection_anchor_row
            if anchor not in children:
                anchor = self.table.focus() or row_id
            if anchor not in children:
                anchor = row_id
            start = children.index(anchor)
            end = children.index(row_id)
            if start <= end:
                selected_range = children[start : end + 1]
            else:
                selected_range = children[end : start + 1]
            if control_pressed:
                selected = set(self.table.selection())
                selected.update(selected_range)
                ordered = [item for item in children if item in selected]
                self.table.selection_set(ordered)
            else:
                self.table.selection_set(selected_range)
            self.table.focus(row_id)
            self.after_idle(self._update_active_cell_border)
            return "break"
        elif control_pressed:
            selected = set(self.table.selection())
            if row_id in selected:
                selected.remove(row_id)
            else:
                selected.add(row_id)
            ordered = [item for item in children if item in selected]
            self.table.selection_set(ordered)
            self._selection_anchor_row = row_id
            self.table.focus(row_id)
            self.after_idle(self._update_active_cell_border)
            return "break"
        else:
            self.table.selection_set(row_id)
            self._selection_anchor_row = row_id
        self.table.focus(row_id)
        self.after_idle(self._update_active_cell_border)
        return "break"

    def _on_table_drag(self, event: tk.Event) -> str | None:
        if self._table_column_resize_active:
            self._schedule_table_grid_update(delay=1)
            self.after(1, self._update_active_cell_border)
        return None

    def _on_table_button_release(self, event: tk.Event) -> str | None:
        if self._table_column_resize_active:
            self._table_column_resize_active = False
            self._schedule_table_grid_update(delay=1)
            self.after(1, self._update_active_cell_border)
        return None

    def _move_active_cell(self, event: tk.Event) -> str:
        self.table.focus_set()
        children = list(self.table.get_children())
        if not children:
            return "break"
        if self._active_cell is None:
            row_id = children[0]
            column_id = "#2"
        else:
            row_id, column_id = self._active_cell
            if row_id not in children:
                row_id = children[0]
            column_index = int(column_id.replace("#", ""))
            row_index = children.index(row_id)
            if event.keysym == "Left":
                column_index = max(2, column_index - 1)
            elif event.keysym == "Right":
                column_index = min(len(FIELDS), column_index + 1)
            elif event.keysym == "Up":
                row_index = max(0, row_index - 1)
            elif event.keysym == "Down":
                row_index = min(len(children) - 1, row_index + 1)
            row_id = children[row_index]
            column_id = f"#{column_index}"
        self._active_cell = (row_id, column_id)
        self.table.focus(row_id)
        self.table.selection_set(row_id)
        self._ensure_active_cell_visible(row_id, column_id)
        self.after_idle(self._update_active_cell_border)
        self.after_idle(self._schedule_table_grid_update)
        return "break"

    def _ensure_active_cell_visible(self, row_id: str, column_id: str) -> None:
        self.table.see(row_id)
        self.update_idletasks()
        columns = list(self.table["columns"])
        if column_id == "#2":
            self.table.xview_moveto(0.0)
            self.update_idletasks()
        target_bbox = self.table.bbox(row_id, column_id)
        if target_bbox:
            x, _y, width, _height = target_bbox
            visible_width = max(self.table.winfo_width(), 1)
            if x >= 0 and (x + width) <= visible_width:
                self.after_idle(self._update_active_cell_border)
                self.after_idle(self._schedule_table_grid_update)
                return

        total_width = 0
        target_left = 0
        target_width = 0
        target_field = FIELDS[int(column_id.replace("#", "")) - 1]
        for field in columns:
            width = int(self.table.column(field, "width"))
            if field == target_field:
                target_left = total_width
                target_width = width
            total_width += width
        if total_width <= 0:
            return
        visible_width = max(self.table.winfo_width(), 1)
        view_left, _view_right = self.table.xview()
        visible_left = view_left * total_width
        visible_right = visible_left + visible_width
        if target_left < visible_left:
            desired_left = max(0.0, target_left - 16.0)
            self.table.xview_moveto(desired_left / total_width)
        elif target_left + target_width > visible_right:
            desired_left = max(0.0, target_left + target_width - visible_width + 16.0)
            self.table.xview_moveto(min(1.0, desired_left / total_width))
        self.update_idletasks()
        self.after_idle(self._update_active_cell_border)
        self.after_idle(self._schedule_table_grid_update)

    def _hide_active_cell_border(self) -> None:
        for part in self._cell_border_parts:
            part.place_forget()

    def _clear_selection_row_borders(self) -> None:
        overlays = self.__dict__.get("_selection_border_overlays", [])
        for part in overlays:
            try:
                part.destroy()
            except Exception:
                pass
        self._selection_border_overlays = []

    def _update_selection_row_borders(self) -> None:
        if "table" not in self.__dict__:
            return
        self._clear_selection_row_borders()
        selected = list(self.table.selection())
        if not selected:
            return
        border_color = "#2563eb"
        table_width = max(int(self.table.winfo_width()), 1)
        columns = list(self.table["columns"])
        children = list(self.table.get_children())
        selected_indices = sorted(children.index(item) for item in selected if item in children)
        if not selected_indices:
            return

        blocks: list[list[int]] = []
        for index in selected_indices:
            if not blocks or index != blocks[-1][-1] + 1:
                blocks.append([index])
            else:
                blocks[-1].append(index)

        def row_bbox(item: str) -> tuple[int, int, int, int] | None:
            for column_index in range(1, len(columns) + 1):
                bbox = self.table.bbox(item, f"#{column_index}")
                if bbox and len(bbox) == 4:
                    return bbox
            return None

        for block in blocks:
            visible_ranges: list[tuple[int, int]] = []
            for index in block:
                item = children[index]
                if not self.table.exists(item):
                    continue
                bbox = row_bbox(item)
                if not bbox:
                    continue
                _x, y, _width, height = bbox
                if height <= 0:
                    continue
                visible_ranges.append((y, y + height))
            if not visible_ranges:
                continue
            y_top = min(start for start, _end in visible_ranges)
            y_bottom = max(end for _start, end in visible_ranges)
            height = max(0, y_bottom - y_top)
            if height <= 0:
                continue
            top = tk.Frame(self.table, bg=border_color, height=2)
            bottom = tk.Frame(self.table, bg=border_color, height=2)
            left = tk.Frame(self.table, bg=border_color, width=2)
            right = tk.Frame(self.table, bg=border_color, width=2)
            top.place(x=0, y=y_top, width=table_width, height=2)
            bottom.place(x=0, y=y_bottom - 2, width=table_width, height=2)
            left.place(x=0, y=y_top, width=2, height=height)
            right.place(x=table_width - 2, y=y_top, width=2, height=height)
            self._selection_border_overlays.extend([top, bottom, left, right])

    def _update_active_cell_border(self, _event: tk.Event | None = None) -> None:
        if self._active_cell is None:
            self._hide_active_cell_border()
            self._update_selection_row_borders()
            return
        row_id, column_id = self._active_cell
        if not self.table.exists(row_id):
            self._active_cell = None
            self._hide_active_cell_border()
            self._update_selection_row_borders()
            return
        try:
            bbox = self.table.bbox(row_id, column_id)
        except tk.TclError:
            self._hide_active_cell_border()
            self._update_selection_row_borders()
            return
        if not bbox or len(bbox) != 4:
            self._hide_active_cell_border()
            self._update_selection_row_borders()
            return
        x, y, width, height = bbox
        if width <= 0 or height <= 0:
            self._hide_active_cell_border()
            self._update_selection_row_borders()
            return
        self._update_selection_row_borders()
        top, bottom, left, right = self._cell_border_parts
        top.place(x=x, y=y, width=width, height=2)
        bottom.place(x=x, y=y + height - 2, width=width, height=2)
        left.place(x=x, y=y, width=2, height=height)
        right.place(x=x + width - 2, y=y, width=2, height=height)

    def _on_table_scroll(self, scrollbar: ttk.Scrollbar, first: str, last: str) -> None:
        scrollbar.set(first, last)
        self._schedule_table_grid_update()
        self.after_idle(self._update_active_cell_border)

    def _on_table_xview(self, *args: object) -> None:
        self.table.xview(*args)
        self._schedule_table_grid_update(delay=16)
        self._update_active_cell_border()

    def _on_table_xscroll(self, scrollbar: ttk.Scrollbar, first: str, last: str) -> None:
        scrollbar.set(first, last)
        self._update_active_cell_border()

    def _clear_table_grid(self) -> None:
        for part in self._grid_overlays:
            part.destroy()
        self._grid_overlays.clear()

    def _table_grid_context(self) -> tuple[list[str], tuple[str, ...], list[tuple[str, tuple[int, int, int, int]]]]:
        columns = list(self.table["columns"])
        items = tuple(self.table.get_children())
        visible_bboxes = []
        if columns and items:
            column_ids = [f"#{column_index}" for column_index in range(1, len(columns) + 1)]
            for item in items:
                for column_id in column_ids:
                    bbox = self.table.bbox(item, column_id)
                    if bbox:
                        visible_bboxes.append((item, bbox))
                        break
        return columns, items, visible_bboxes

    def _schedule_table_grid_update(self, _event: tk.Event | None = None, delay: int = 30) -> None:
        if self._grid_after_id is not None:
            self.after_cancel(self._grid_after_id)
        self._grid_after_id = self.after(max(0, int(delay)), self._update_table_grid)

    def _update_table_grid(self, _event: tk.Event | None = None) -> None:
        self._grid_after_id = None
        self._clear_table_grid()
        columns, items, visible_bboxes = self._table_grid_context()
        grid_color = "#e2e7ef"
        if not columns or not items or not visible_bboxes:
            return
        data_top = min(bbox[1] for _, bbox in visible_bboxes)
        data_bottom = max(bbox[1] + bbox[3] for _, bbox in visible_bboxes)
        data_height = max(0, data_bottom - data_top)
        if data_height <= 0:
            return

        first_item = visible_bboxes[0][0]
        for column_index in range(1, len(columns)):
            bbox = self.table.bbox(first_item, f"#{column_index}")
            if not bbox:
                continue
            x, _y, width, _height = bbox
            separator = tk.Frame(self.table, bg=grid_color, width=1)
            separator.place(x=x + width - 1, y=data_top, width=1, height=data_height)
            self._grid_overlays.append(separator)

        for item, bbox in visible_bboxes:
            _x, y, width, height = bbox
            row_line = tk.Frame(self.table, bg=grid_color, height=1)
            row_line.place(x=0, y=y + height - 1, relwidth=1.0, height=1)
            self._grid_overlays.append(row_line)

        self.after_idle(self._update_active_cell_border)

    def _refresh_operand_surface_choices(self) -> None:
        values = ["Auto"]
        for index, row in enumerate(self.rows):
            if row.surface in {"Object", "Image"}:
                continue
            values.append(f"{index}: {row.name}")
        for label, var in self.operand_surface_vars.items():
            current = var.get().strip() if var.get() else "Auto"
            if current not in values:
                var.set("Auto")
        for widget in self.winfo_children():
            self._apply_surface_values_to_descendants(widget, values)

    def _apply_surface_values_to_descendants(self, widget, values) -> None:
        if isinstance(widget, ttk.Combobox):
            textvar = widget.cget("textvariable")
            for var in self.operand_surface_vars.values():
                if str(var) == textvar:
                    widget["values"] = values
                    break
        for child in widget.winfo_children():
            self._apply_surface_values_to_descendants(child, values)

    def _sync_object_controls(self) -> None:
        if not hasattr(self, "field_summary_var"):
            return
        self._apply_image_diameter_mode()
        self._sync_field_mode_ui()
        metrics = self._field_metrics()
        self.field_summary_var.set(
            "Field half-angle: {angle:.3g} deg\nObject semi-height: {obj:.3g} mm\nParaxial image semi-height: {parax:.3g} mm\nReal image semi-height: {real:.3g} mm".format(
                angle=metrics["angle_deg"],
                obj=metrics["object_height"],
                parax=metrics["paraxial_image_height"],
                real=metrics["real_image_height"],
            )
        )
        warning = ""
        if self.rows and self._current_object_mode() == "Finite":
            object_half_size = max(float(self.rows[0].diameter) / 2.0, 0.0)
            if abs(metrics["object_height"]) > object_half_size + 1e-9:
                warning = f"Field semi-height exceeds object half-size ({object_half_size:.3g} mm)."
        self.field_warning_var.set(warning)
        self._update_field_status_hint()

    def _on_object_mode_changed(self, _event=None) -> None:
        self._sync_field_default_from_current_type()
        self._sync_field_mode_ui()
        self._sync_object_controls()
        self._mark_plot_update_pending()

    def _on_image_diameter_mode_changed(self, _event=None) -> None:
        self._apply_image_diameter_mode()
        self._sync_table()
        self._sync_object_controls()
        self._mark_plot_update_pending()

    def _on_camera_model_changed(self, _event=None) -> None:
        self._begin_history_capture()
        camera_name = self._current_camera_model()
        if camera_name == CAMERA_NONE_LABEL:
            self._commit_history_capture()
            self._mark_plot_update_pending()
            return
        diameter = camera_image_diameter_mm(camera_name)
        if diameter is None or not self.rows or self.rows[-1].surface != "Image":
            self._commit_history_capture()
            self._mark_plot_update_pending()
            self.status_var.set(f"Camera selected: {camera_name}; no sensor size available.")
            return
        self._set_image_diameter_mode("Manual")
        self.rows[-1].diameter = float(diameter)
        camera_info = self._current_camera_record() or {}
        step_path = camera_info.get("step_path")
        if self.imported_camera_step_path is None and step_path:
            candidate = Path(step_path).expanduser()
            if candidate.exists():
                self.imported_camera_step_path = candidate
        self._sync_object_diameter_from_manual_image()
        self._sync_table()
        self._sync_object_controls()
        self._commit_history_capture()
        self._mark_plot_update_pending()
        summary = camera_short_summary(camera_name)
        detail = f" ({summary})" if summary else ""
        self.status_var.set(
            f"Camera selected: {camera_name}{detail}; image diameter set to {float(diameter):.6g} mm. Click Update."
        )

    def _apply_initial_field_defaults(self) -> None:
        if self._field_defaults_initialized or not hasattr(self, "field_type_var"):
            return
        if self._current_object_mode() == "Infinity":
            self.field_type_var.set(self._field_type_display_label("Angle"))
            self._last_field_type = "Angle"
            self._field_type_defaults["Angle"] = "0.0"
            self.field_value_var.set("0.0")
        else:
            self.field_type_var.set(self._field_type_display_label("Object Height"))
            self._last_field_type = "Object Height"
            self._field_type_defaults["Object Height"] = "0.0"
            self.field_value_var.set("0.0")
        self._field_defaults_initialized = True
        self._sync_field_mode_ui()

    def _apply_initial_layout_view_defaults(self, name: str) -> None:
        if not hasattr(self, "display_orientation_var"):
            return
        if name == FOLDED_STARTER_LAYOUT_TITLE:
            self.display_orientation_var.set("Horizontal")
            self.object_mode_var.set("Finite")
            self.field_type_var.set(self._field_type_display_label("Object Height"))
            self._last_field_type = "Object Height"
            self._field_type_defaults["Object Height"] = "0.0"
            self.field_value_var.set("0.0")
            self._sync_field_mode_ui()
        elif name == "Doublet Lens":
            self.display_orientation_var.set("Vertical")
            self.object_mode_var.set("Infinity")
            self.field_type_var.set(self._field_type_display_label("Angle"))
            self._last_field_type = "Angle"
            self._field_type_defaults["Angle"] = "0.0"
            self.field_value_var.set("0.0")
            self._sync_field_mode_ui()
        else:
            self.display_orientation_var.set("Vertical")
            self.object_mode_var.set("Finite")
            self.field_type_var.set(self._field_type_display_label("Object Height"))
            self._last_field_type = "Object Height"
            self._field_type_defaults["Object Height"] = "0.0"
            self.field_value_var.set("0.0")
            self._sync_field_mode_ui()

    def _on_field_type_changed(self, _event=None) -> None:
        self._sync_field_default_from_current_type()
        self._sync_field_mode_ui()
        self._sync_object_controls()
        self._mark_plot_update_pending()

    def _sync_field_default_from_current_type(self) -> None:
        if not hasattr(self, "field_value_var"):
            return
        previous_type = getattr(self, "_last_field_type", self._current_field_type())
        field_type = self._current_field_type()
        current_text = self.field_value_var.get().strip()
        if current_text:
            self._field_type_defaults[previous_type] = current_text
        default_text = self._field_type_defaults.get(field_type, "0.0")
        self._last_field_type = field_type
        if current_text != default_text:
            self.field_value_var.set(default_text)

    def _sync_field_mode_ui(self) -> None:
        if not hasattr(self, "field_type_menu"):
            return
        current_type = self._current_field_type()
        if self._current_object_mode() == "Infinity":
            values = [
                "Angle",
                "Paraxial Image Height",
                "Real Image Height",
                "Object Height",
            ]
            note = "Preferred: Field half-angle for infinity object. Image semi-height modes are derived targets."
        else:
            values = [
                "Object Height",
                "Paraxial Image Height",
                "Real Image Height",
                "Angle",
            ]
            note = "Preferred: Object semi-height for finite object. Field half-angle remains available as a derived field."
        self.field_type_menu["values"] = [self._field_type_display_label(value) for value in values]
        self.field_type_var.set(self._field_type_display_label(current_type))
        if hasattr(self, "field_mode_note_var"):
            self.field_mode_note_var.set(note)
        if hasattr(self, "field_value_label_var"):
            self.field_value_label_var.set(self._field_type_value_label(current_type))
        self._update_field_status_hint()

    def add_surface(self) -> None:
        self._begin_history_capture()
        arm_key = self._current_arm_view_key()
        selected_indices = self._selected_table_indices()
        if selected_indices:
            insert_at = max(selected_indices) + 1
        elif arm_key:
            insert_at = self._default_insert_index_for_arm_key(arm_key)
        else:
            insert_at = len(self.rows)
            if self.rows and self.rows[-1].surface == "Image":
                insert_at -= 1
        insert_at = max(1, min(insert_at, len(self.rows) - (1 if self.rows and self.rows[-1].surface == "Image" else 0)))
        row = SurfaceRow()
        if arm_key:
            self._apply_arm_key_metadata_to_row(row, arm_key)
        self.rows.insert(insert_at, row)
        self._sync_table()
        self._select_table_indices([insert_at], focus_index=insert_at)
        self._commit_history_capture()
        self.refresh_plot()

    def delete_selected(self) -> None:
        selected = self.table.selection()
        if not selected:
            return
        self._begin_history_capture()
        indices = self._selected_table_indices()
        for index in reversed(indices):
            del self.rows[index]
        self._sync_table()
        self._commit_history_capture()
        self.refresh_plot()

    def duplicate_selected(self) -> None:
        selected = self.table.selection()
        if not selected:
            return
        self._begin_history_capture()
        indices = self._selected_table_indices()
        insert_at = indices[-1] + 1
        duplicates = [SurfaceRow(**asdict(self.rows[index])) for index in indices]
        for offset, row in enumerate(duplicates):
            self.rows.insert(insert_at + offset, row)
        self._normalize_special_rows()
        self._sync_table()
        self._select_table_indices(list(range(insert_at, insert_at + len(duplicates))), focus_index=insert_at)
        self._commit_history_capture()
        self.refresh_plot()

    def _selected_table_indices(self) -> list[int]:
        indices = [
            index
            for item in self.table.selection()
            for index in [self._table_item_row_index(item)]
            if index is not None
        ]
        return sorted(indices)

    @staticmethod
    def _indices_are_contiguous(indices: list[int]) -> bool:
        return bool(indices) and indices == list(range(indices[0], indices[-1] + 1))

    def _next_manual_element_label(self) -> str:
        used = {self._element_key(row) for row in self.rows if self._element_key(row)}
        counter = 1
        while f"Element {counter}" in used:
            counter += 1
        return f"Element {counter}"

    def group_selected_as_element(self) -> None:
        selected = self.table.selection()
        if not selected:
            return
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror("Group Element", f"Could not read the surface table:\n\n{exc}", parent=self)
            return
        indices = self._selected_table_indices()
        if len(indices) < 2:
            messagebox.showinfo("Group Element", "Select two or more contiguous surface rows first.", parent=self)
            return
        if indices[0] <= 0 or indices[-1] >= len(self.rows) - 1:
            messagebox.showinfo("Group Element", "Object and Image rows cannot be grouped into an element.", parent=self)
            return
        if not self._indices_are_contiguous(indices):
            messagebox.showinfo("Group Element", "Select a contiguous block of rows before grouping.", parent=self)
            return

        self._begin_history_capture()
        label = self._next_manual_element_label()
        for index in indices:
            self.rows[index].element = label
        self._normalize_special_rows()
        self._sync_table()
        self._select_table_indices(indices, focus_index=indices[0])
        self._commit_history_capture()
        self.status_var.set(f"Grouped rows {indices[0]}-{indices[-1]} as one element.")

    def ungroup_selected_elements(self) -> None:
        selected = self.table.selection()
        if not selected:
            return
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror("Ungroup Element", f"Could not read the surface table:\n\n{exc}", parent=self)
            return
        selected_keys = {
            self._element_key(self.rows[index])
            for index in self._selected_table_indices()
            if 0 <= index < len(self.rows)
        }
        selected_keys.discard("")
        if not selected_keys:
            messagebox.showinfo("Ungroup Element", "The selected rows are not part of an element.", parent=self)
            return

        self._begin_history_capture()
        ungrouped_indices = []
        for index, row in enumerate(self.rows):
            if self._element_key(row) in selected_keys:
                row.element = ""
                row.advanced = dict(row.advanced or {})
                row.advanced.pop(ELEMENT_ADVANCED_ATTR, None)
                ungrouped_indices.append(index)
        self._normalize_special_rows()
        self._sync_table()
        self._select_table_indices(ungrouped_indices, focus_index=ungrouped_indices[0] if ungrouped_indices else None)
        self._commit_history_capture()
        self.status_var.set(f"Ungrouped {len(ungrouped_indices)} surface row(s).")

    @staticmethod
    def _element_id_from_label(label: str) -> str:
        text = re.sub(r"[^A-Za-z0-9]+", "_", str(label or "").strip()).strip("_")
        return text or "Element"

    def _selected_element_blocks(self) -> list[list[int]]:
        blocks: list[list[int]] = []
        seen: set[tuple[int, int]] = set()
        for index in self._selected_table_indices():
            if index <= 0 or index >= len(self.rows) - 1:
                continue
            if self._element_key(self.rows[index]):
                start, end = self._element_block_for_index(self.rows, index)
            else:
                start, end = index, index
            key = (start, end)
            if key in seen:
                continue
            seen.add(key)
            blocks.append(list(range(start, end + 1)))
        return blocks

    def _ensure_element_for_block(self, indices: list[int]) -> str:
        existing = next((self._element_key(self.rows[index]) for index in indices if self._element_key(self.rows[index])), "")
        label = existing or str(self.rows[indices[0]].name or self._next_manual_element_label()).strip()
        if not label:
            label = self._next_manual_element_label()
        for index in indices:
            self.rows[index].element = label
        return label

    def _beam_splitter_element_choices(self) -> list[str]:
        choices = [""]
        for index, row in enumerate(self.rows):
            if row.surface != BEAM_SPLITTER_SURFACE:
                continue
            label = self._element_key(row) or str(row.name or f"S{index}").strip() or f"S{index}"
            if label not in choices:
                choices.append(label)
        return choices

    def _metadata_matches_leg_id(
        self,
        metadata: dict[str, object],
        leg_id: str,
        *,
        row: SurfaceRow | None = None,
        row_index: int | None = None,
    ) -> bool:
        return self._leg_id_from_element_metadata(metadata, row=row, row_index=row_index) == str(leg_id or "").strip().lower()

    def _indices_for_leg_key(self, arm_key: str) -> list[int]:
        leg_id = self._leg_id_from_arm_key(arm_key)
        if not leg_id or not self.rows:
            return []
        indices: list[int] = []
        auto_entry = self._auto_leg_entry_for_id(leg_id)
        if auto_entry is not None:
            for index in sorted(set(auto_entry.get("surface_indices", set()) or set())):
                if 0 <= int(index) < len(self.rows):
                    indices.append(int(index))
        seen_blocks: set[tuple[int, int]] = set()
        index = 0 if leg_id == "input" else 1
        last_inclusive = len(self.rows) if leg_id in {"detector", "cross", "return"} or auto_entry is not None else max(len(self.rows) - 1, 0)
        while index < last_inclusive:
            start, end = self._element_block_for_index(self.rows, index)
            block_key = (start, end)
            metadata = self._element_metadata(self.rows[start])
            if block_key not in seen_blocks and self._metadata_matches_leg_id(
                metadata,
                leg_id,
                row=self.rows[start],
                row_index=start,
            ):
                indices.extend(candidate for candidate in range(start, end + 1) if candidate not in indices)
                seen_blocks.add(block_key)
            index = max(end + 1, index + 1)
        return indices

    def _indices_for_arm_key(self, arm_key: str) -> list[int]:
        key = str(arm_key or "").strip()
        if not key or not self.rows:
            return []
        if self._leg_id_from_arm_key(key):
            return self._indices_for_leg_key(key)
        indices: list[int] = []
        seen_blocks: set[tuple[int, int]] = set()
        index = 1
        while index < len(self.rows) - 1:
            start, end = self._element_block_for_index(self.rows, index)
            block_key = (start, end)
            metadata = self._element_metadata(self.rows[start])
            metadata_key = self._arm_key_from_metadata(metadata)
            path = self._branch_path_for_arm_key(key)
            matches_key = metadata_key == key
            if path and self._metadata_arm_key_matches_branch_path(metadata_key, path):
                matches_key = True
            if block_key not in seen_blocks and matches_key:
                indices.extend(range(start, end + 1))
                seen_blocks.add(block_key)
            index = max(end + 1, index + 1)
        return indices

    def _move_blocks_to_physical_leg_position(
        self,
        blocks: list[list[int]],
        leg_id: str,
    ) -> list[int]:
        leg_id = str(leg_id or "").strip().lower()
        leg_order = {
            defined_id: order
            for order, (defined_id, _short_label, _detail) in enumerate(self._physical_leg_definitions())
        }
        target_order = leg_order.get(leg_id)
        if target_order is None or not blocks:
            return []

        selected_positions: set[int] = set()
        for block in blocks:
            for index in block:
                if 0 < index < len(self.rows) - 1:
                    selected_positions.add(int(index))
        if not selected_positions:
            return []

        selected_rows = [row for index, row in enumerate(self.rows) if index in selected_positions]
        remaining_rows = [row for index, row in enumerate(self.rows) if index not in selected_positions]
        if not selected_rows or len(remaining_rows) < 2:
            return []

        def block_leg_id(rows: list[SurfaceRow], start: int) -> str:
            if not (0 <= start < len(rows)):
                return ""
            metadata = self._element_metadata(rows[start])
            return self._leg_id_from_element_metadata(metadata, row=rows[start], row_index=start)

        insert_at = max(1, len(remaining_rows) - 1)
        index = 1
        while index < len(remaining_rows):
            start, end = self._element_block_for_index(remaining_rows, index)
            if remaining_rows[start].surface == "Image":
                insert_at = start
                break
            existing_order = leg_order.get(block_leg_id(remaining_rows, start))
            if existing_order is not None and existing_order > target_order:
                insert_at = start
                break
            index = max(end + 1, index + 1)

        self.rows = remaining_rows[:insert_at] + selected_rows + remaining_rows[insert_at:]
        return list(range(insert_at, insert_at + len(selected_rows)))

    def _surface_indices_for_arm_key(self, arm_key: str) -> set[int]:
        indices = set(self._indices_for_arm_key(arm_key))
        path = self._branch_path_for_arm_key(arm_key)
        if path:
            indices.update(self._branch_path_surface_indices(path))
        return indices

    def _refresh_arm_view_choices(self) -> None:
        menu = self.__dict__.get("arm_view_menu")
        if menu is None:
            return
        choices = [ARM_VIEW_DEFAULT]
        for entry in self._arm_catalog():
            label = entry["label"]
            if label not in choices:
                choices.append(label)
        menu["values"] = choices
        current = str(self.arm_view_var.get() or ARM_VIEW_DEFAULT).strip()
        if current not in choices:
            self.arm_view_var.set(ARM_VIEW_DEFAULT)

    def _arm_key_for_view_label(self, label: str) -> str:
        text = str(label or ARM_VIEW_DEFAULT).strip()
        if text == ARM_VIEW_DEFAULT:
            return ""
        for entry in self._arm_catalog():
            if entry["label"] == text:
                return entry["key"]
        return ""

    def set_arm_view(self, _event: tk.Event | None = None) -> None:
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror("Path View", f"Could not read the surface table:\n\n{exc}", parent=self)
            self.arm_view_var.set(ARM_VIEW_DEFAULT)
            return
        self._refresh_arm_view_choices()
        focus_label = str(self.arm_view_var.get() or ARM_VIEW_DEFAULT).strip()
        self._sync_table()
        if focus_label == ARM_VIEW_DEFAULT:
            self.status_var.set("Path view set to All paths; all components, table rows, and traced paths are shown.")
        else:
            key = self._arm_key_for_view_label(focus_label)
            indices = self._indices_for_arm_key(key)
            if indices and self.__dict__.get("table") is not None:
                self._select_table_indices(indices, focus_index=indices[0])
            self.status_var.set(
                f"Path view set to {focus_label}; table and 2-D plot show common path plus this path."
            )
        self.refresh_plot()

    @staticmethod
    def _normalized_vector(values) -> np.ndarray:
        vector = np.asarray(values, dtype=float).reshape(3)
        norm = float(np.linalg.norm(vector))
        if norm <= 1e-12:
            raise ValueError("Cannot normalize a zero vector.")
        return vector / norm

    @staticmethod
    def _surface_tilts_for_normal(direction) -> tuple[float, float, float]:
        unit = KrakenLayoutEditor._normalized_vector(direction)
        dx, dy, dz = (float(value) for value in unit)
        tilt_y = float(np.rad2deg(np.arcsin(np.clip(dx, -1.0, 1.0))))
        tilt_x = float(np.rad2deg(np.arctan2(-dy, dz)))
        return (tilt_x, tilt_y, 0.0)

    def _surface_transform_for_rows(self, rows: list[SurfaceRow], row_index: int) -> np.ndarray:
        system = _build_system_from_specs(self._serializable_specs_for_rows(rows))
        transforms = self._system_transform_list(system)
        if transforms is None or not (0 <= row_index < len(transforms)):
            raise RuntimeError("KrakenOS did not provide surface transforms for path placement.")
        return np.asarray(transforms[row_index], dtype=float)

    def _arm_frame_for_splitter(self, splitter_index: int, arm_role: str) -> dict[str, np.ndarray | tuple[float, float, float]]:
        if not (0 <= splitter_index < len(self.rows)):
            raise RuntimeError("Selected splitter row is out of range.")
        row = self.rows[splitter_index]
        if row.surface != BEAM_SPLITTER_SURFACE:
            raise RuntimeError("Path placement starts from a Beam Splitter row.")
        transform = self._surface_transform_for_rows(self.rows, splitter_index)
        origin = np.asarray(transform[:3, 3], dtype=float)
        normal = self._normalized_vector(transform[:3, 2])
        incoming = np.asarray([0.0, 0.0, 1.0], dtype=float)
        role = str(arm_role).strip()
        if role == "Transmit":
            direction = incoming
        elif role == "Reflect":
            direction = incoming - 2.0 * float(np.dot(incoming, normal)) * normal
        else:
            raise RuntimeError(f"Unsupported path role for placement: {arm_role}")
        direction = self._normalized_vector(direction)
        return {
            "origin": origin,
            "direction": direction,
            "tilts": self._surface_tilts_for_normal(direction),
        }

    def _next_detector_element_label(self, arm_role: str) -> str:
        base = f"{arm_role} detector"
        used = {self._element_key(row) for row in self.rows if self._element_key(row)}
        if base not in used:
            return base
        counter = 2
        while f"{base} {counter}" in used:
            counter += 1
        return f"{base} {counter}"

    def _detector_row_for_arm(
        self,
        splitter_index: int,
        arm_role: str,
        distance_mm: float,
        diameter_mm: float,
        *,
        insert_at: int | None = None,
    ) -> SurfaceRow:
        distance = float(distance_mm)
        diameter = float(diameter_mm)
        if not np.isfinite(distance) or distance <= 0.0:
            raise RuntimeError("Detector path distance must be positive.")
        if not np.isfinite(diameter) or diameter <= 0.0:
            raise RuntimeError("Detector diameter must be positive.")
        role = str(arm_role).strip()
        if role not in {"Transmit", "Reflect"}:
            raise RuntimeError("Detector placement supports Transmit or Reflect paths.")
        insert_index = len(self.rows) - 1 if insert_at is None else int(insert_at)
        insert_index = max(1, min(insert_index, len(self.rows) - 1))
        frame = self._arm_frame_for_splitter(splitter_index, role)
        origin = np.asarray(frame["origin"], dtype=float)
        direction = np.asarray(frame["direction"], dtype=float)
        tilt_x, tilt_y, tilt_z = frame["tilts"]  # type: ignore[misc]
        center = origin + direction * distance
        splitter_row = self.rows[splitter_index]
        splitter_metadata = self._element_metadata(splitter_row)
        parent = (
            str(splitter_metadata.get("element_id", "") or "").strip()
            or self._element_key(splitter_row)
            or str(splitter_row.name or f"S{splitter_index}").strip()
        )
        element_label = self._next_detector_element_label(role)
        detector = SurfaceRow(
            element=element_label,
            surface="Standard",
            name=element_label,
            rc=0.0,
            k=0.0,
            thickness=0.0,
            diameter=diameter,
            glass="AIR",
            tilt_x=float(tilt_x),
            tilt_y=float(tilt_y),
            tilt_z=float(tilt_z),
            advanced={
                ELEMENT_ADVANCED_ATTR: {
                    "element_id": self._element_id_from_label(element_label),
                    "element_name": element_label,
                    "arm_role": "Detector",
                    "parent_splitter": parent,
                    "branch_selector": self._branch_selector_for_arm_role(role),
                    "arm_distance": distance,
                    "local_decenter_x": 0.0,
                    "local_decenter_y": 0.0,
                    "local_tilt_x": 0.0,
                    "local_tilt_y": 0.0,
                    "local_tilt_z": 0.0,
                }
            },
        )
        temp_rows = [SurfaceRow(**asdict(row)) for row in self.rows]
        temp_rows.insert(insert_index, SurfaceRow(**asdict(detector)))
        baseline = self._surface_transform_for_rows(temp_rows, insert_index)[:3, 3]
        decenter = center - np.asarray(baseline, dtype=float)
        detector.desp_x = float(decenter[0])
        detector.desp_y = float(decenter[1])
        detector.desp_z = float(decenter[2])
        return detector

    def open_arm_detector_placement(self, splitter_index: int, arm_role: str) -> None:
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror("Path Detector", f"Could not read the surface table:\n\n{exc}", parent=self)
            return
        if not (0 <= splitter_index < len(self.rows)) or self.rows[splitter_index].surface != BEAM_SPLITTER_SURFACE:
            messagebox.showinfo("Path Detector", "Right-click a Beam Splitter row first.", parent=self)
            return
        role = str(arm_role).strip()
        if role not in {"Transmit", "Reflect"}:
            messagebox.showerror("Path Detector", f"Unsupported path: {arm_role}", parent=self)
            return

        window = tk.Toplevel(self)
        window.withdraw()
        window.title(f"Add {role} Path Detector")
        window.transient(self)
        frame = ttk.Frame(window, padding=12)
        frame.grid(row=0, column=0, sticky="nsew")
        frame.columnconfigure(1, weight=1)
        distance_var = tk.StringVar(value="60")
        diameter_var = tk.StringVar(value=self._format_table_float(max(float(self.rows[splitter_index].diameter) * 2.0, 25.0)))
        ttk.Label(
            frame,
            text=(
                f"Insert a Standard AIR detector plane in the {role.lower()} path. "
                "The row is placed before Image and tagged as Detector metadata."
            ),
            wraplength=460,
            foreground="#475569",
        ).grid(row=0, column=0, columnspan=2, sticky="w", pady=(0, 10))
        ttk.Label(frame, text="Distance from splitter [mm]").grid(row=1, column=0, sticky="w", padx=(0, 10), pady=3)
        ttk.Entry(frame, textvariable=distance_var, width=16).grid(row=1, column=1, sticky="ew", pady=3)
        ttk.Label(frame, text="Detector diameter [mm]").grid(row=2, column=0, sticky="w", padx=(0, 10), pady=3)
        ttk.Entry(frame, textvariable=diameter_var, width=16).grid(row=2, column=1, sticky="ew", pady=3)
        status_var = tk.StringVar(value="Distance is measured along the central transmitted/reflected path.")
        ttk.Label(frame, textvariable=status_var, foreground="#475569", wraplength=460).grid(
            row=3,
            column=0,
            columnspan=2,
            sticky="w",
            pady=(10, 0),
        )

        def parse_values() -> tuple[float, float] | None:
            try:
                distance = float(distance_var.get().strip())
                diameter = float(diameter_var.get().strip())
            except ValueError:
                status_var.set("Distance and diameter must be numbers.")
                return None
            if not np.isfinite(distance) or distance <= 0.0:
                status_var.set("Distance must be positive.")
                return None
            if not np.isfinite(diameter) or diameter <= 0.0:
                status_var.set("Diameter must be positive.")
                return None
            status_var.set("Validation passed.")
            return distance, diameter

        def apply_values() -> None:
            parsed = parse_values()
            if parsed is None:
                return
            distance, diameter = parsed
            try:
                detector = self._detector_row_for_arm(splitter_index, role, distance, diameter)
            except Exception as exc:
                status_var.set(_short_error_message(exc))
                return
            insert_index = max(1, len(self.rows) - 1)
            self._begin_history_capture()
            self.rows.insert(insert_index, detector)
            self._normalize_special_rows()
            self._sync_table()
            self._select_table_indices([insert_index], focus_index=insert_index)
            self._commit_history_capture()
            self._mark_plot_update_pending()
            self.status_var.set(
                f"Inserted {detector.name} at {distance:.6g} mm in the {role.lower()} path. Click Update."
            )
            window.destroy()
            self._cleanup_current_popup_menu()

        footer = ttk.Frame(frame)
        footer.grid(row=4, column=0, columnspan=2, sticky="e", pady=(12, 0))
        ttk.Button(footer, text="Validate", command=parse_values).pack(side="right", padx=(0, 8))
        ttk.Button(footer, text="Insert", command=apply_values).pack(side="right")
        ttk.Button(footer, text="Cancel", command=window.destroy).pack(side="right", padx=(0, 8))
        self._show_centered_dialog(window)

    def assign_selected_elements_to_arm(self, role: str) -> None:
        role = _normalize_element_metadata({"arm_role": role})["arm_role"]
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror("Assign Path", f"Could not read the surface table:\n\n{exc}", parent=self)
            return
        blocks = self._selected_element_blocks()
        if not blocks:
            messagebox.showinfo("Assign Path", "Select one or more non-Object/non-Image rows or element groups first.", parent=self)
            return

        self._begin_history_capture()
        selected_indices: list[int] = []
        for indices in blocks:
            if role == ELEMENT_ARM_ROLE_DEFAULT:
                for index in indices:
                    self._set_element_metadata(self.rows[index], {})
                selected_indices.extend(indices)
                continue
            label = self._ensure_element_for_block(indices)
            metadata = self._element_metadata(self.rows[indices[0]])
            metadata["element_name"] = label
            if not str(metadata.get("element_id", "") or "").strip():
                metadata["element_id"] = self._element_id_from_label(label)
            previous_role = str(metadata.get("arm_role", ELEMENT_ARM_ROLE_DEFAULT))
            previous_selector = str(metadata.get("branch_selector", "") or "").strip()
            metadata["arm_role"] = role
            if previous_selector in {"", self._branch_selector_for_arm_role(previous_role)}:
                metadata["branch_selector"] = self._branch_selector_for_arm_role(role)
            metadata["leg_id"] = ""
            for index in indices:
                self._set_element_metadata(self.rows[index], metadata)
            selected_indices.extend(indices)
        self._normalize_special_rows()
        self._sync_table()
        if selected_indices:
            self._select_table_indices(selected_indices, focus_index=selected_indices[0])
        self._commit_history_capture()
        self._mark_plot_update_pending()
        role_text = role if role != ELEMENT_ARM_ROLE_DEFAULT else "Unassigned"
        self.status_var.set(f"Assigned {len(blocks)} element(s) to {role_text} path metadata.")
        self._cleanup_current_popup_menu()

    def _element_metadata_for_arm_key(self, arm_key: str, label: str) -> dict[str, object] | None:
        parts = str(arm_key or "").split("|")
        leg_id = self._leg_id_from_arm_key(arm_key)
        selector = self._branch_selector_for_arm_key(arm_key)
        if leg_id:
            workflow = self._physical_leg_workflow()
            if workflow == "mach_zehnder":
                bs1_parent = self._splitter_id_by_ordinal(0)
                bs2_parent = self._splitter_id_by_ordinal(1)
                role, selector, parent = {
                    "input": ("Common", "primary", bs1_parent),
                    "transmit": ("Return", "transmit", bs1_parent),
                    "reflect": ("Return", "reflect", bs1_parent),
                    "cross": ("Detector", "transmit", bs2_parent),
                    "return": ("Detector", "reflect", bs2_parent),
                }.get(leg_id, (ELEMENT_ARM_ROLE_DEFAULT, "", ""))
            else:
                parent_default = self._default_parent_splitter_id()
                role, selector, parent = {
                    "input": ("Common", "primary", parent_default),
                    "reflect": ("Return", "reflect", parent_default),
                    "transmit": ("Return", "transmit", parent_default),
                    "detector": ("Detector", "reflect", parent_default),
                }.get(leg_id, (ELEMENT_ARM_ROLE_DEFAULT, "", ""))
        else:
            if not selector:
                return None
            role = {
                "transmit": "Transmit",
                "reflect": "Reflect",
                "return": "Return",
            }.get(selector, ELEMENT_ARM_ROLE_DEFAULT)
            parent = parts[1].strip() if len(parts) >= 3 and parts[0] == "branch" else ""
        return _normalize_element_metadata(
            {
                "element_id": self._element_id_from_label(label),
                "element_name": label,
                "leg_id": leg_id,
                "arm_role": role,
                "parent_splitter": parent,
                "branch_selector": selector,
                "arm_distance": 0.0,
                "local_decenter_x": 0.0,
                "local_decenter_y": 0.0,
                "local_tilt_x": 0.0,
                "local_tilt_y": 0.0,
                "local_tilt_z": 0.0,
            }
        )

    def assign_selected_elements_to_arm_key(self, arm_key: str) -> None:
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror("Assign Path", f"Could not read the surface table:\n\n{exc}", parent=self)
            return
        blocks = self._selected_element_blocks()
        if not blocks:
            messagebox.showinfo("Assign Path", "Select one or more non-Object/non-Image rows or element groups first.", parent=self)
            return

        self._begin_history_capture()
        selected_indices: list[int] = []
        detail = self._arm_key_detail(arm_key)
        for indices in blocks:
            label = self._ensure_element_for_block(indices)
            metadata = self._element_metadata_for_arm_key(arm_key, label)
            if metadata is None:
                continue
            for index in indices:
                self.rows[index].element = label
                self._set_element_metadata(self.rows[index], metadata)
            selected_indices.extend(indices)
        if not selected_indices:
            self._history_pending_state = None
            messagebox.showinfo("Assign Path", "The selected path is not assignable for these rows.", parent=self)
            return
        self._normalize_special_rows()
        leg_id = self._leg_id_from_arm_key(arm_key)
        moved_indices = self._move_blocks_to_physical_leg_position(blocks, leg_id) if leg_id else []
        if moved_indices:
            selected_indices = moved_indices
        self._sync_table()
        self._select_table_indices(selected_indices, focus_index=selected_indices[0])
        self._commit_history_capture()
        self._mark_plot_update_pending()
        move_note = " and moved into path order" if moved_indices else ""
        self.status_var.set(f"Assigned {len(blocks)} element(s) to {detail} path metadata{move_note}.")
        self._cleanup_current_popup_menu()

    def open_element_settings(self) -> None:
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror("Element Settings", f"Could not read the surface table:\n\n{exc}", parent=self)
            return
        blocks = self._selected_element_blocks()
        if not blocks:
            messagebox.showinfo("Element Settings", "Select a non-Object/non-Image row or element group first.", parent=self)
            return
        if len(blocks) > 1:
            messagebox.showinfo("Element Settings", "Open Element Settings for one element at a time.", parent=self)
            return
        indices = blocks[0]
        row = self.rows[indices[0]]
        metadata = self._element_metadata(row)
        element_label = self._element_key(row) or str(row.name or self._next_manual_element_label()).strip()
        window = tk.Toplevel(self)
        window.withdraw()
        window.title(f"Element Settings - rows {indices[0]}-{indices[-1]}")
        window.transient(self)
        window.columnconfigure(0, weight=1)
        frame = ttk.Frame(window, padding=12)
        frame.grid(row=0, column=0, sticky="nsew")
        frame.columnconfigure(1, weight=1)

        name_var = tk.StringVar(value=element_label)
        id_var = tk.StringVar(value=str(metadata.get("element_id", "") or self._element_id_from_label(element_label)))
        role_var = tk.StringVar(value=str(metadata.get("arm_role", ELEMENT_ARM_ROLE_DEFAULT)))
        parent_var = tk.StringVar(value=str(metadata.get("parent_splitter", "") or ""))
        selector_value = str(metadata.get("branch_selector", "") or "")
        selector_var = tk.StringVar(value=selector_value if selector_value else "Auto")
        numeric_vars = {
            key: tk.StringVar(value=self._format_table_float(float(metadata.get(key, 0.0))))
            for key in ELEMENT_METADATA_NUMERIC_FIELDS
        }

        rows = [
            ("Element name", ttk.Entry(frame, textvariable=name_var)),
            ("Element ID", ttk.Entry(frame, textvariable=id_var)),
            ("Path role", ttk.Combobox(frame, textvariable=role_var, values=ELEMENT_ARM_ROLE_VALUES, state="readonly")),
            ("Parent splitter", ttk.Combobox(frame, textvariable=parent_var, values=self._beam_splitter_element_choices())),
            ("Split selector", ttk.Combobox(frame, textvariable=selector_var, values=ELEMENT_BRANCH_SELECTOR_VALUES)),
            ("Path distance [mm]", ttk.Entry(frame, textvariable=numeric_vars["arm_distance"])),
            ("Local decenter X [mm]", ttk.Entry(frame, textvariable=numeric_vars["local_decenter_x"])),
            ("Local decenter Y [mm]", ttk.Entry(frame, textvariable=numeric_vars["local_decenter_y"])),
            ("Local tilt X [deg]", ttk.Entry(frame, textvariable=numeric_vars["local_tilt_x"])),
            ("Local tilt Y [deg]", ttk.Entry(frame, textvariable=numeric_vars["local_tilt_y"])),
            ("Local tilt Z [deg]", ttk.Entry(frame, textvariable=numeric_vars["local_tilt_z"])),
        ]
        ttk.Label(
            frame,
            text="Element metadata is saved with each surface row. It is used by path-aware UI tools and future placement/analysis helpers.",
            wraplength=520,
            foreground="#475569",
        ).grid(row=0, column=0, columnspan=2, sticky="w", pady=(0, 10))
        for grid_row, (label, widget) in enumerate(rows, start=1):
            ttk.Label(frame, text=label).grid(row=grid_row, column=0, sticky="w", padx=(0, 10), pady=3)
            widget.grid(row=grid_row, column=1, sticky="ew", pady=3)

        validation_var = tk.StringVar(value="Set Common/Transmit/Reflect/Detector path metadata for this element.")
        ttk.Label(frame, textvariable=validation_var, foreground="#475569", wraplength=520).grid(
            row=len(rows) + 1,
            column=0,
            columnspan=2,
            sticky="w",
            pady=(10, 0),
        )

        def collect_metadata() -> dict[str, object] | None:
            label = name_var.get().strip()
            if not label:
                validation_var.set("Element name cannot be empty.")
                return None
            role = str(role_var.get()).strip()
            if role not in ELEMENT_ARM_ROLE_VALUES:
                validation_var.set("Choose a valid path role.")
                return None
            data: dict[str, object] = {
                "element_id": id_var.get().strip(),
                "element_name": label,
                "arm_role": role,
                "parent_splitter": parent_var.get().strip(),
                "branch_selector": "" if selector_var.get().strip() == "Auto" else selector_var.get().strip(),
            }
            for key, var in numeric_vars.items():
                try:
                    value = float(var.get().strip())
                except ValueError:
                    validation_var.set(f"{key.replace('_', ' ')} expects a number.")
                    return None
                if not np.isfinite(value):
                    validation_var.set(f"{key.replace('_', ' ')} must be finite.")
                    return None
                data[key] = value
            if not data["branch_selector"]:
                data["branch_selector"] = self._branch_selector_for_arm_role(role)
            return _normalize_element_metadata(data)

        def validate_values() -> dict[str, object] | None:
            data = collect_metadata()
            if data is not None:
                validation_var.set("Validation passed: " + _element_metadata_summary(data))
            return data

        def apply_values() -> None:
            data = validate_values()
            if data is None:
                return
            label = str(data.get("element_name", "") or "").strip()
            self._begin_history_capture()
            for index in indices:
                self.rows[index].element = label
                self._set_element_metadata(self.rows[index], data)
            self._normalize_special_rows()
            self._sync_table()
            self._select_table_indices(indices, focus_index=indices[0])
            self._commit_history_capture()
            self._mark_plot_update_pending()
            self.status_var.set(f"Updated element settings for {label}: {_element_metadata_summary(data)}.")
            window.destroy()
            self._cleanup_current_popup_menu()

        footer = ttk.Frame(frame)
        footer.grid(row=len(rows) + 2, column=0, columnspan=2, sticky="e", pady=(12, 0))
        ttk.Button(footer, text="Validate", command=validate_values).pack(side="right", padx=(0, 8))
        ttk.Button(footer, text="Apply", command=apply_values).pack(side="right")
        ttk.Button(footer, text="Cancel", command=window.destroy).pack(side="right", padx=(0, 8))
        self._show_centered_dialog(window)

    def flip_selected(self) -> None:
        selected = self.table.selection()
        if not selected:
            return
        self._begin_history_capture()
        indices = self._selected_table_indices()
        if len(indices) < 2:
            self._history_pending_state = None
            return
        selected_rows = [SurfaceRow(**asdict(self.rows[index])) for index in indices]
        selected_thicknesses = [row.thickness for row in selected_rows]
        selected_glasses = [row.glass for row in selected_rows]
        flipped_rows = list(reversed(selected_rows))

        for row in flipped_rows:
            if row.surface == "Standard" and row.rc != 0.0:
                row.rc = -row.rc
            row.name = self._flipped_name(row.name)

        if len(flipped_rows) >= 2:
            remapped_thicknesses = list(reversed(selected_thicknesses[:-1])) + [selected_thicknesses[-1]]
            remapped_glasses = list(reversed(selected_glasses[:-1])) + [selected_glasses[-1]]
        else:
            remapped_thicknesses = selected_thicknesses
            remapped_glasses = selected_glasses

        for row, thickness, glass in zip(flipped_rows, remapped_thicknesses, remapped_glasses):
            row.thickness = thickness
            row.glass = glass

        for index, row in zip(indices, flipped_rows):
            self.rows[index] = row
        self._normalize_special_rows()
        self._sync_table()
        self._select_table_indices(indices, focus_index=indices[0])
        self._commit_history_capture()
        self.refresh_plot()

    def move_up(self) -> None:
        selected = self.table.selection()
        if not selected:
            return
        self._begin_history_capture()
        selected_indices = self._selected_table_indices()
        if not selected_indices:
            self._history_pending_state = None
            return
        index = min(selected_indices)
        new_rows, new_start, new_end, moved = self._swap_element_block(self.rows, index, "up", same_arm_only=True)
        if not moved:
            if self._element_arm_role_for_index(self.rows, index) != ELEMENT_ARM_ROLE_DEFAULT:
                self.status_var.set("No previous element in the same path to move above.")
            self._history_pending_state = None
            return
        self.rows = new_rows
        self._sync_table()
        self._select_table_indices(list(range(new_start, new_end + 1)), focus_index=new_start)
        self._commit_history_capture()
        self.refresh_plot()

    def move_down(self) -> None:
        selected = self.table.selection()
        if not selected:
            return
        self._begin_history_capture()
        selected_indices = self._selected_table_indices()
        if not selected_indices:
            self._history_pending_state = None
            return
        index = max(selected_indices)
        new_rows, new_start, new_end, moved = self._swap_element_block(self.rows, index, "down", same_arm_only=True)
        if not moved:
            if self._element_arm_role_for_index(self.rows, index) != ELEMENT_ARM_ROLE_DEFAULT:
                self.status_var.set("No next element in the same path to move below.")
            self._history_pending_state = None
            return
        self.rows = new_rows
        self._sync_table()
        self._select_table_indices(list(range(new_start, new_end + 1)), focus_index=new_start)
        self._commit_history_capture()
        self.refresh_plot()

    def begin_edit(self, event: tk.Event) -> None:
        row_id = self.table.identify_row(event.y)
        column_id = self.table.identify_column(event.x)
        if not row_id or not column_id:
            return
        column_index = int(column_id.replace("#", "")) - 1
        field = FIELDS[column_index]
        if field == "label":
            return
        row_index = self._table_item_row_index(row_id)
        if row_index is None:
            return
        if not self._table_cell_enabled(row_index, field):
            self.status_var.set(self._surface_type_disabled_message(row_index, field))
            self.after_idle(self._update_active_cell_border)
            return
        bbox = self.table.bbox(row_id, column_id)
        if not bbox or len(bbox) != 4:
            return
        x, y, width, height = bbox
        current_value = self.table.set(row_id, field)
        if field in {"rc", "thickness"}:
            current_value = current_value.replace("*", "").strip()

        if self.editor is not None:
            self.editor.destroy()
            self.editor = None
            self._editor_row_id = None
            self._editor_field = None

        if field == "surface":
            self._show_choice_menu(row_id, field, SURFACE_TYPES, event.x_root, event.y_root)
            return
        elif field == "glass":
            self._show_choice_menu(
                row_id,
                field,
                ("AIR", "BK7", "F2", "MIRROR"),
                event.x_root,
                event.y_root,
            )
            return
        else:
            editor = ttk.Entry(self.table)
            editor.insert(0, current_value)
            editor.bind("<Return>", lambda e: self._finish_edit(row_id, field))

        editor.place(x=x, y=y, width=width, height=height)
        editor.focus_set()
        editor.bind("<Escape>", lambda e: self._cancel_edit())
        self.editor = editor
        self._editor_row_id = row_id
        self._editor_field = field

    def _selected_surface_row_index(self) -> int | None:
        selected = self.table.selection()
        if selected:
            return self._table_item_row_index(selected[0])
        focused = self.table.focus()
        if focused:
            return self._table_item_row_index(focused)
        return None

    @staticmethod
    def _advanced_surface_default_text(attr: str) -> str:
        try:
            default = getattr(Kos.surf(), attr)
        except Exception:
            return ""
        literal = _layout_literal_value(default)
        if literal is _UNSERIALIZABLE_LAYOUT_VALUE:
            return "<native object>"
        text = " ".join(repr(literal).split())
        return text if len(text) <= 72 else text[:69] + "..."

    @staticmethod
    def _is_default_extra_data(value) -> bool:
        try:
            return bool(np.all(np.asarray(value, dtype=object) == 0))
        except Exception:
            return value in (0, 0.0, "None", None)

    @staticmethod
    def _is_default_uda(value) -> bool:
        if value is None:
            return True
        if isinstance(value, str):
            return value == "None"
        return False

    @staticmethod
    def _short_numeric_list(value, limit: int = 12) -> str:
        try:
            arr = np.asarray(value, dtype=float).ravel()
        except Exception:
            return ""
        if arr.size == 0:
            return ""
        significant = arr[:limit]
        while significant.size and abs(float(significant[-1])) <= 1e-15:
            significant = significant[:-1]
        return pformat(significant.tolist(), width=100) if significant.size else ""

    @staticmethod
    def _decoded_uda_polygon(value) -> tuple[np.ndarray, np.ndarray] | None:
        try:
            decoded = decode_custom_surface_value(value)
        except Exception:
            decoded = value
        if decoded is None or (isinstance(decoded, str) and decoded == "None"):
            return None
        if not isinstance(decoded, (list, tuple)) or len(decoded) != 2:
            return None
        try:
            px = np.asarray(decoded[0], dtype=float).ravel()
            py = np.asarray(decoded[1], dtype=float).ravel()
        except Exception:
            return None
        if px.size != py.size or px.size < 3:
            return None
        return px, py

    @staticmethod
    def _mask_preset_summary(value) -> str:
        if not isinstance(value, dict):
            return ""
        if str(value.get("kind", "")).strip().lower() not in {"mask_shape", "mask", "mask_preset"}:
            return ""
        preset = str(value.get("preset", "")).strip().lower()
        if preset == "ronchi":
            return "Ronchi mask"
        if preset == "spider":
            return "Spider mask"
        return str(value.get("preset", "Mask preset"))

    def _surface_preview_grid(
        self,
        row: SurfaceRow,
        advanced: dict[str, object],
        extra_data,
        *,
        samples: int = 121,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
        radius = max(float(row.diameter) * 0.5, 1.0)
        axis = np.linspace(-radius, radius, int(samples))
        x_grid, y_grid = np.meshgrid(axis, axis)
        r_grid = np.hypot(x_grid, y_grid)
        inside = r_grid <= radius
        sag = np.full_like(x_grid, np.nan, dtype=float)
        c = 1.0 / float(row.rc) if abs(float(row.rc)) > 1e-12 else 0.0
        if abs(c) > 0.0:
            k = float(getattr(row, "k", 0.0))
            root = 1.0 - (1.0 + k) * c * c * r_grid * r_grid
            safe_root = np.maximum(root, 0.0)
            denom = 1.0 + np.sqrt(safe_root)
            base = np.divide(c * r_grid * r_grid, denom, out=np.zeros_like(r_grid), where=np.abs(denom) > 1e-15)
        else:
            base = np.zeros_like(r_grid)
        sag[inside] = base[inside]
        aspher = np.asarray(advanced.get("AspherData", []), dtype=float).ravel() if "AspherData" in advanced else np.empty(0)
        for index, coeff in enumerate(aspher[:12], start=1):
            if abs(float(coeff)) <= 0.0:
                continue
            sag[inside] += float(coeff) * np.power(r_grid[inside], 2 * index)
        znk = np.asarray(advanced.get("ZNK", []), dtype=float).ravel() if "ZNK" in advanced else np.empty(0)
        if znk.size:
            rho = np.divide(r_grid, radius, out=np.zeros_like(r_grid), where=radius > 0.0)
            theta = np.arctan2(y_grid, x_grid)
            z_terms = [
                np.ones_like(rho),
                rho * np.cos(theta),
                rho * np.sin(theta),
                2.0 * rho * rho - 1.0,
                rho * rho * np.cos(2.0 * theta),
                rho * rho * np.sin(2.0 * theta),
                (3.0 * rho**3 - 2.0 * rho) * np.cos(theta),
                (3.0 * rho**3 - 2.0 * rho) * np.sin(theta),
                6.0 * rho**4 - 6.0 * rho * rho + 1.0,
            ]
            for coeff, basis in zip(znk[: len(z_terms)], z_terms):
                if abs(float(coeff)) > 0.0:
                    sag[inside] += float(coeff) * basis[inside]
        try:
            decoded_extra = decode_custom_surface_value(extra_data)
            if isinstance(decoded_extra, (list, tuple)) and len(decoded_extra) == 2 and callable(decoded_extra[0]):
                extra = np.asarray(decoded_extra[0](x_grid, y_grid, decoded_extra[1]), dtype=float)
                if extra.shape == sag.shape:
                    sag[inside] += extra[inside]
        except Exception:
            pass
        return x_grid, y_grid, sag, inside

    def open_surface_shape_builder(self, row_index: int | None = None) -> None:
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror("Surface Shape Builder", f"Could not read the surface table:\n\n{exc}", parent=self)
            return

        if row_index is None:
            row_index = self._selected_surface_row_index()
        if row_index is None or row_index < 0 or row_index >= len(self.rows):
            messagebox.showinfo("Surface Shape Builder", "Select a surface row first.", parent=self)
            return
        row = self.rows[row_index]
        if row.surface in {"Object", "Image"}:
            messagebox.showinfo("Surface Shape Builder", "Shape builders apply to physical surfaces, not Object/Image rows.", parent=self)
            return

        advanced = dict(row.advanced or {})
        candidate_extra = row.extra_data
        candidate_uda = row.uda
        candidate_advanced = dict(advanced)

        window = tk.Toplevel(self)
        window.withdraw()
        window.title(f"Surface Shape Builder - S{row_index}: {row.name}")
        window.geometry("1180x760")
        window.minsize(920, 620)
        window.transient(self)
        window.columnconfigure(1, weight=1)
        window.rowconfigure(0, weight=1)

        controls = ttk.Frame(window, padding=10)
        controls.grid(row=0, column=0, sticky="nsw")
        controls.columnconfigure(1, weight=1)

        figure = Figure(figsize=(7.2, 5.4), dpi=100)
        sag_ax = figure.add_subplot(121)
        aperture_ax = figure.add_subplot(122)
        canvas = FigureCanvasTkAgg(figure, master=window)
        canvas.get_tk_widget().grid(row=0, column=1, sticky="nsew", padx=(0, 10), pady=10)

        row_cursor = 0
        ttk.Label(controls, text=f"S{row_index}: {row.name or row.surface}", font=("TkDefaultFont", 10, "bold")).grid(
            row=row_cursor, column=0, columnspan=3, sticky="w", pady=(0, 8)
        )
        row_cursor += 1

        ttk.Label(controls, text="Asphere coeffs").grid(row=row_cursor, column=0, sticky="w", pady=3)
        aspher_var = tk.StringVar(master=window, value=self._short_numeric_list(candidate_advanced.get("AspherData", []), 12))
        ttk.Entry(controls, textvariable=aspher_var, width=34).grid(row=row_cursor, column=1, columnspan=2, sticky="ew", pady=3)
        row_cursor += 1

        ttk.Label(controls, text="Zernike coeffs").grid(row=row_cursor, column=0, sticky="w", pady=3)
        znk_var = tk.StringVar(master=window, value=self._short_numeric_list(candidate_advanced.get("ZNK", []), 12))
        ttk.Entry(controls, textvariable=znk_var, width=34).grid(row=row_cursor, column=1, columnspan=2, sticky="ew", pady=3)
        row_cursor += 1

        ttk.Separator(controls).grid(row=row_cursor, column=0, columnspan=3, sticky="ew", pady=8)
        row_cursor += 1

        ttk.Label(controls, text="ExtraData preset").grid(row=row_cursor, column=0, sticky="w", pady=3)
        extra_preset_var = tk.StringVar(master=window, value="None")
        extra_menu = ttk.Combobox(
            controls,
            textvariable=extra_preset_var,
            state="readonly",
            values=("None", "xy_cosines", "radial_sine", "micro_lens_array"),
            width=18,
        )
        extra_menu.grid(row=row_cursor, column=1, sticky="ew", pady=3)
        row_cursor += 1
        ttk.Label(controls, text="Extra params").grid(row=row_cursor, column=0, sticky="w", pady=3)
        extra_params_var = tk.StringVar(master=window, value="[8.0, 0.02]")
        ttk.Entry(controls, textvariable=extra_params_var, width=24).grid(row=row_cursor, column=1, columnspan=2, sticky="ew", pady=3)
        row_cursor += 1

        encoded_extra = encode_custom_surface_value(candidate_extra)
        if isinstance(encoded_extra, dict):
            preset = str(encoded_extra.get("preset", "")).strip()
