        ttk.Entry(controls, textvariable=uda_radius_var, width=14).grid(row=row_cursor, column=1, sticky="ew", pady=3)
        row_cursor += 1
        ttk.Label(controls, text="UDA rotation").grid(row=row_cursor, column=0, sticky="w", pady=3)
