    def benchmark_psf_mtf(self) -> None:
        self.append_progress("Benchmark PSF/MTF started.")
        try:
            self._report_compute_backends()
            self._read_rows_from_table()
            system = self.build_system()
            wavelength = self._current_wavelength()
            field_type = "angle" if self._current_object_mode() == "Infinity" else "height"
            field_y = self._current_field_angle_deg() if field_type == "angle" else self._current_field_height()
            sample_count = max(64, self._current_ray_count() * 12)
            self.append_progress(f"Tracing benchmark rays: sample_count={sample_count}")
            x_local, y_local, workers = self._build_geometric_image_samples(
                system,
                wavelength,
                sample_count=sample_count,
                pattern="hexapolar",
                surface_index=self._analysis_surface_index(),
                aperture_type=self._current_aperture_type(),
                aperture_value=self._current_aperture_value(),
                field_type=field_type,
                field_x=0.0,
                field_y=field_y,
            )
            if x_local.size < 4:
                raise RuntimeError("Not enough traced image-plane samples for benchmark")

            span_x = max(float(np.ptp(x_local)), 1e-3)
            span_y = max(float(np.ptp(y_local)), 1e-3)
            span = max(span_x, span_y) * 1.25
            bins = 256

            t0 = time.perf_counter()
            hist_cpu, xedges_cpu, _yedges_cpu = np.histogram2d(
                x_local,
                y_local,
                bins=bins,
                range=[[-span / 2.0, span / 2.0], [-span / 2.0, span / 2.0]],
            )
            psf_cpu = hist_cpu / max(np.sum(hist_cpu), 1.0)
            otf_cpu = np.fft.fftshift(np.fft.fft2(psf_cpu))
            mtf_cpu = np.abs(otf_cpu)
            mtf_cpu /= max(float(np.max(mtf_cpu)), 1e-12)
            _freq_cpu = np.fft.fftshift(np.fft.fftfreq(bins, d=float(xedges_cpu[1] - xedges_cpu[0])))
            cpu_sec = time.perf_counter() - t0

            gpu_results: list[tuple[str, float]] = []

            cp = _optional_cupy()
            if cp is not None:
                try:
                    if int(cp.cuda.runtime.getDeviceCount()) > 0:
                        _ = cp.zeros((1,), dtype=cp.float32)
                        cp.cuda.Stream.null.synchronize()
                        t1 = time.perf_counter()
                        x_gpu = cp.asarray(x_local, dtype=cp.float64)
                        y_gpu = cp.asarray(y_local, dtype=cp.float64)
                        hist_gpu, xedges_gpu, _yedges_gpu = cp.histogram2d(
                            x_gpu,
                            y_gpu,
                            bins=bins,
                            range=[[-span / 2.0, span / 2.0], [-span / 2.0, span / 2.0]],
                        )
                        psf_gpu = hist_gpu / cp.maximum(cp.sum(hist_gpu), 1.0)
                        otf_gpu = cp.fft.fftshift(cp.fft.fft2(psf_gpu))
                        mtf_gpu = cp.abs(otf_gpu)
                        mtf_gpu /= cp.maximum(cp.max(mtf_gpu), 1e-12)
                        _freq_gpu = cp.fft.fftshift(
                            cp.fft.fftfreq(bins, d=float(cp.asnumpy(xedges_gpu[1] - xedges_gpu[0])))
                        )
                        cp.cuda.Stream.null.synchronize()
                        gpu_results.append(("CuPy", time.perf_counter() - t1))
                except Exception as exc:
                    self.append_debug(f"Benchmark CuPy path failed: {_short_error_message(exc)}")

            torch = _optional_torch()
            if torch is not None:
                try:
                    if bool(torch.cuda.is_available()):
                        device = torch.device("cuda")
                        _ = torch.zeros((1,), dtype=torch.float32, device=device)
                        if hasattr(torch.cuda, "synchronize"):
                            torch.cuda.synchronize()
                        t2 = time.perf_counter()
                        lower = -span / 2.0
                        upper = span / 2.0
                        step = (upper - lower) / float(bins)
                        x_t = torch.as_tensor(x_local, dtype=torch.float64, device=device)
                        y_t = torch.as_tensor(y_local, dtype=torch.float64, device=device)
                        ix = torch.floor((x_t - lower) / step).to(torch.int64)
                        iy = torch.floor((y_t - lower) / step).to(torch.int64)
                        valid = (ix >= 0) & (ix < bins) & (iy >= 0) & (iy < bins)
                        ix = ix[valid]
                        iy = iy[valid]
                        lin = ix * bins + iy
                        hist_t = torch.zeros(bins * bins, dtype=torch.float64, device=device)
                        hist_t.scatter_add_(0, lin, torch.ones_like(lin, dtype=torch.float64))
                        hist_t = hist_t.view(bins, bins)
                        psf_t = hist_t / torch.clamp(torch.sum(hist_t), min=1.0)
                        otf_t = torch.fft.fftshift(torch.fft.fft2(psf_t))
                        mtf_t = torch.abs(otf_t)
                        mtf_t = mtf_t / torch.clamp(torch.max(mtf_t), min=1e-12)
                        _freq_t = torch.fft.fftshift(torch.fft.fftfreq(bins, d=step, device=device))
                        if hasattr(torch.cuda, "synchronize"):
                            torch.cuda.synchronize()
                        gpu_results.append(("Torch", time.perf_counter() - t2))
                except Exception as exc:
                    self.append_debug(f"Benchmark Torch path failed: {_short_error_message(exc)}")

            self.append_progress(
                f"Benchmark traced rays={x_local.size} | trace workers={workers} | bins={bins} | CPU post={cpu_sec:.6f}s"
            )
            if gpu_results:
                gpu_results.sort(key=lambda item: item[1])
                best_name, best_sec = gpu_results[0]
                speedup = cpu_sec / max(best_sec, 1e-12)
                for name, timing in gpu_results:
                    self.append_progress(f"Benchmark {name} post={timing:.6f}s")
                self.append_progress(
                    f"Benchmark best GPU={best_name} {best_sec:.6f}s | speedup={speedup:.2f}x"
                )
                gpu_summary = ", ".join(f"{name}={timing:.6f}s" for name, timing in gpu_results)
                self.append_debug(
                    f"PSF/MTF benchmark: rays={x_local.size}, workers={workers}, cpu={cpu_sec:.6f}s, {gpu_summary}, best={best_name}, speedup={speedup:.2f}x"
                )
            else:
                self.append_progress("Benchmark GPU post=unavailable")
                self.append_debug(
                    f"PSF/MTF benchmark: rays={x_local.size}, workers={workers}, cpu={cpu_sec:.6f}s, gpu=unavailable"
                )
            self.status_var.set("Benchmark PSF/MTF completed")
        except Exception as exc:
            self.append_progress(f"Benchmark PSF/MTF failed: {exc}")
            self.append_debug(f"Benchmark PSF/MTF failed: {exc}")
            self.status_var.set("Benchmark PSF/MTF failed")

    def build_system(self, *, require_solids: bool = False, force_rebuild: bool = False):
        row_specs = self._serializable_row_specs()
        signature = _row_specs_signature(row_specs)
        cached_signature = self.__dict__.get("_system_cache_signature")
        cached_system = self.__dict__.get("_system_cache_system")
        cached_has_solids = bool(self.__dict__.get("_system_cache_has_solids", False))
        if not force_rebuild and cached_system is not None and cached_signature == signature:
            if not require_solids or cached_has_solids:
                return cached_system
            try:
                original_build = int(getattr(cached_system, "BUILD", 0))
                cached_system.BUILD = 1
                cached_system.build()
                cached_system.BUILD = original_build
                self._system_cache_has_solids = True
                return cached_system
            except Exception:
                pass

        system = _build_system_from_specs(
            row_specs,
            build=1 if require_solids else 0,
        )
        self._system_cache_signature = signature
        self._system_cache_system = system
        self._system_cache_has_solids = bool(getattr(system.Pr3D, "ExistSolid", 0))
        return system

    def _current_wavelength(self) -> float:
        try:
            return float(self.wavelength_var.get())
        except ValueError:
            return 0.55

    def _current_aperture_type(self) -> str:
        value = self.aperture_type_var.get().strip().upper()
        if value == "FNO":
            return "EPD"
        if value in {"STOP", "EPD"}:
            return value
        return "STOP"

    def _current_aperture_type_label(self) -> str:
        value = self.aperture_type_var.get().strip().upper()
        if value in {"STOP", "EPD", "FNO"}:
            return value
        return "STOP"

    def _current_aperture_value(self) -> float:
        try:
            value = float(self.aperture_value_var.get())
        except ValueError:
            return 1.0
        if value == 0.0:
            return 1.0
        if self._current_aperture_type_label() == "FNO":
            f_number = max(abs(value), 1e-9)
            effl = max(abs(float(self._current_effl_estimate())), 1e-9)
            return effl / f_number
        return value

    def _current_mtf_frequency(self) -> float:
        var = self.__dict__.get("operand_frequency_vars", {}).get("MTF @ freq")
        if var is None:
            return 5.0
        try:
            value = float(var.get())
        except ValueError:
            return 5.0
        return max(0.0, value)

    def _operand_mtf_mode(self, label: str) -> str:
        var = self.__dict__.get("operand_mtf_mode_vars", {}).get(label)
        if var is None:
            return "average"
        value = var.get().strip().lower()
        if value in {"tangential", "sagittal", "average"}:
            return value
        return "average"

    def _operand_mtf_algorithm(self, label: str) -> str:
        var = self.__dict__.get("operand_mtf_algorithm_vars", {}).get(label)
        if var is None:
            return "diffraction_fft"
        value = var.get().strip().lower()
        if value == "diffraction fft":
            return "diffraction_fft"
        if value == "lsf fft":
            return "lsf_fft"
        return "psf_fft"

    def _mtf_analysis_settings(self) -> dict[str, float | int | str]:
        return {
            "wavelength": self._current_wavelength(),
            "surface_index": self._analysis_surface_index(),
            "aperture_type": self._current_aperture_type(),
            "aperture_value": self._current_aperture_value(),
            "field_type": ("angle" if self._current_object_mode() == "Infinity" else "height"),
            "field_x": 0.0,
            "field_y": (self._current_field_angle_deg() if self._current_object_mode() == "Infinity" else self._current_field_height()),
            "algorithm": self._operand_mtf_algorithm("MTF @ freq"),
        }

    @staticmethod
    def _normalize_field_type(field_type: str) -> str:
        return FIELD_TYPE_ALIASES.get(str(field_type).strip(), "Angle")

    @staticmethod
    def _field_type_display_label(field_type: str) -> str:
        return FIELD_TYPE_DISPLAY_LABELS.get(KrakenLayoutEditor._normalize_field_type(field_type), "Field")

    @staticmethod
    def _field_type_value_label(field_type: str) -> str:
        labels = {
            "Angle": "Field Half-Angle [deg]",
            "Object Height": "Object Semi-Height [mm]",
            "Paraxial Image Height": "Paraxial Image Semi-Height [mm]",
            "Real Image Height": "Real Image Semi-Height [mm]",
        }
        return labels.get(KrakenLayoutEditor._normalize_field_type(field_type), "Field value")

    @staticmethod
    def _field_type_unit(field_type: str) -> str:
        units = {
            "Angle": "deg",
            "Object Height": "mm",
            "Paraxial Image Height": "mm",
            "Real Image Height": "mm",
        }
        return units.get(KrakenLayoutEditor._normalize_field_type(field_type), "")

    @staticmethod
    def _format_field_sample_value(value: float) -> str:
        return f"{float(value):.3f}".rstrip("0").rstrip(".")

    def _parse_numeric_series(self, value: str) -> list[float]:
        text = str(value or "").strip()
        if not text:
            return []
        samples: list[float] = []
        invalid: list[str] = []
        for token in re.split(r"[\s,;]+", text):
            if not token:
                continue
            try:
                samples.append(float(token))
            except ValueError:
                invalid.append(token)
        if invalid:
            self.append_debug(f"Ignoring invalid numeric samples: {', '.join(invalid)}")
        return samples

    @staticmethod
    def _name_offset(row: SurfaceRow) -> tuple[float, float]:
        if row.surface not in {"Object", "Image"}:
            return (0.0, 0.0)
        name = row.name.lower()
        base_y = max(row.diameter * 0.08, 0.0)
        if "front" in name:
            return (-max(row.diameter * 0.35, 8.0), base_y)
        if "back" in name:
            return (max(row.diameter * 0.15, 2.0), base_y)
        return (0.0, base_y)

    def refresh_plot(self, *, suppress_analysis: bool = False) -> None:
        active_modes = [] if suppress_analysis else list(self.selected_analysis_modes)
        if active_modes:
            status_label = " + ".join(self._analysis_mode_label(mode) for mode in active_modes)
        else:
            status_label = self._analysis_mode_label(self.layout_preview_mode or "none")
        self._set_analysis_parallel_status(status_label, 1, False)
        self._begin_analysis_progress("Plot refresh")
        self.update_idletasks()
        self._clear_cardinal_marker_artists()
        self._clear_physical_distance_artists()
        self._clear_layout_selection_overlay()
        self._layout_pick_regions = {}
        self._layout_ray_pick_regions = []
        self._last_optics_info = None
        self._analysis_ax = None
        self._analysis_axes = []
        if not self.rows:
            self.last_system = None
            self.last_rays = None
            self._last_scene_bundle = None
            self._last_auto_leg_entries = []
            self.ax.clear()
            self.ax.set_title("Axial Layout")
            self._refresh_ray_inspector_if_open()
            self._refresh_branch_tree_if_open()
            self._refresh_branch_throughput_report_if_open()
            self._refresh_analysis_branch_choices()
            self._refresh_nonseq_scene_graph_if_open()
            self._sync_trace_state_badge({"requested": self._requested_trace_mode(), "active": "Sequential"})
            self._configure_plot_hover_hints()
            self.canvas.draw_idle()
            self._autosave_plot()
            self._finish_analysis_progress("Plot refresh", success=True)
            return

        max_radius = 1.0
        for row in self.rows:
            radius = max(row.diameter / 2.0, 0.5)
            max_radius = max(max_radius, radius)

        self._update_analysis_progress("Building system", 1, 5)
        self.update_idletasks()
        self.figure.clear()
        if not active_modes:
            self.ax = self.figure.add_subplot(111)
            analysis_axes = []
            self._analysis_ax = None
        else:
            right_rows = len(active_modes)
            gs = self.figure.add_gridspec(1, 2, width_ratios=[3.9, 1.75], wspace=0.18)
            right_gs = gs[1].subgridspec(right_rows, 1, hspace=0.28)
            self.ax = self.figure.add_subplot(gs[0])
            analysis_axes = [self.figure.add_subplot(right_gs[i, 0]) for i in range(right_rows)]
            self._analysis_axes = analysis_axes
            self._analysis_ax = analysis_axes[0] if analysis_axes else None

        try:
            wavelength = self._current_wavelength()
            capture = io.StringIO()
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", RuntimeWarning)
                with redirect_stdout(capture), redirect_stderr(capture):
                    system = self.build_system(require_solids=True)
                    rays = Kos.raykeeper(system)
                    # Keep the 2D layout readable: full-pupil mode is for the
                    # 3D inspector, while the 2D plot shows a meridional slice.
                    self._trace_preview_rays(system, rays, wavelength, max_radius, allow_full_pupil=False)
            self.append_debug(capture.getvalue())
            self._update_analysis_progress("Tracing rays", 2, 5)
            self.update_idletasks()
            self.last_system = system
            self.last_rays = rays
            self._last_preview_trace_signature = self._preview_trace_signature()
            if self._apply_image_diameter_mode():
                self._sync_image_row_table_value()
            self._refresh_3d_inspector_if_open()

            # --- Phase 3: scene-bundle pipeline ---
            self._update_analysis_progress("Rendering layout", 3, 5)
            self.update_idletasks()
            orientation = self._current_display_orientation()
            bundle = self._build_scene_bundle(system, rays, max_radius)
            self._last_scene_bundle = bundle
            self._refresh_arm_view_choices()
            self._refresh_analysis_branch_choices()
            trace_requested = str((bundle.extra or {}).get("trace_mode_requested", "Auto"))
            trace_active = str((bundle.extra or {}).get("trace_mode_active", "Sequential"))
            trace_note = str((bundle.extra or {}).get("trace_mode_note", "")).strip()
            self._sync_trace_state_badge({"requested": trace_requested, "active": trace_active, "note": trace_note})
            self.append_progress(f"Trace mode: {trace_requested} -> {trace_active}")
            if trace_note:
                self.append_debug(f"Trace mode note: {trace_note}")
            projector = SceneProjector2D(orientation)
            projected = projector.project_bundle(bundle)
            self._refresh_auto_leg_graph(projected)
            self._refresh_arm_view_choices()
            projected = self._filter_projected_scene_for_arm_view(projected)

            # Pick regions from the bundle (avoids redundant scene rebuild)
            self._layout_pick_regions = {}
            for pr in projected.pick_regions:
                self._layout_pick_regions.setdefault(pr.row_index, []).extend(pr.polylines)
            self._layout_ray_pick_regions = [
                (int(ray.ray_index), np.asarray(ray.points_2d, dtype=float))
                for ray in projected.rays
                if np.asarray(ray.points_2d, dtype=float).ndim == 2
                and np.asarray(ray.points_2d, dtype=float).shape[0] >= 2
            ]

            # Render surfaces, rays, and labels
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", RuntimeWarning)
                render_projected = self._projected_scene_for_layout_render(projected)
                render_scene_2d(
                    render_projected, self.ax,
                    show_clipped_rays=self.show_clipped_rays_var.get(),
                    ray_count_hint=max(1, self._preview_field_ray_count),
                )

            self._draw_lens_mech_overlay()
            gaussian_extent = self._draw_gaussian_beam_overlay(system, wavelength)
            if gaussian_extent is not None:
                max_radius = max(max_radius, float(gaussian_extent))
            scan_bounds = self._draw_folded_scan_overlay(max_radius, system=system)
            plot_bounds = self._combined_plot_bounds(projected.bounds, scan_bounds)
            set_plot_limits(
                self.ax, plot_bounds,
                max_radius=max_radius,
                has_off_axis=bundle.has_off_axis,
                orientation=orientation,
                use_drawn_data=not scan_bounds.is_empty,
            )
            self._draw_arm_labels(projected)

            # Cardinal markers and result-panel summaries are optional
            # diagnostics. They must not force an already-rendered layout into
            # fallback when paraxial/pupil data is unavailable for branched
            # non-sequential systems.
            self._update_analysis_progress("Computing cardinals", 4, 5)
            self.update_idletasks()
            optics_info: dict = {}
            try:
                with warnings.catch_warnings():
                    warnings.simplefilter("ignore", RuntimeWarning)
                    optics_info = self._collect_optics_info(system, rays, wavelength)
                self._last_optics_info = dict(optics_info)
            except Exception as diag_exc:
                self._last_optics_info = None
                self.append_debug(f"Optics summary unavailable: {diag_exc}")
            try:
                if self._last_optics_info is not None:
                    self._draw_optics_markers(optics_info)
            except Exception as diag_exc:
                self.append_debug(f"Optics marker draw skipped: {diag_exc}")
            try:
                self._draw_physical_distances()
            except Exception as diag_exc:
                self.append_debug(f"Physical-distance overlay skipped: {diag_exc}")
            with warnings.catch_warnings():
                warnings.simplefilter("ignore", RuntimeWarning)
                if self._analysis_axes:
                    for axis, mode in zip(self._analysis_axes, active_modes):
                        try:
                            self._plot_analysis_for_mode(axis, system, rays, wavelength, mode)
                        except Exception as diag_exc:
                            axis.clear()
                            axis.text(0.5, 0.5, "Analysis unavailable", ha="center", va="center")
                            axis.set_axis_off()
                            self.append_debug(f"{mode} analysis skipped: {diag_exc}")
                else:
                    self._analysis_ax = None
                try:
                    self._update_results(system, rays, wavelength, optics_info)
                except Exception as diag_exc:
                    self._set_results([("Status", "Layout rendered"), ("Results warning", str(diag_exc))])
                    self.append_debug(f"Results panel skipped: {diag_exc}")
                for label, refresh_fn in (
                    ("Ray inspector", self._refresh_ray_inspector_if_open),
                    ("Trace path inspector", self._refresh_branch_tree_if_open),
                    ("Path throughput", self._refresh_branch_throughput_report_if_open),
                    ("Non-sequential scene graph", self._refresh_nonseq_scene_graph_if_open),
                ):
                    try:
                        refresh_fn()
                    except Exception as diag_exc:
                        self.append_debug(f"{label} refresh skipped: {diag_exc}")
            self._update_analysis_progress("Finalizing", 5, 5)
            self.update_idletasks()
            self.status_var.set(f"Plot refreshed | {self._last_analysis_label} | {self._analysis_compute_summary()}")
        except Exception as exc:
            self.last_system = None
            self.last_rays = None
            self._last_scene_bundle = None
            self.ax.clear()
            self._plot_fallback_preview(max_radius)
            for axis in self._analysis_axes:
                axis.clear()
                axis.text(0.5, 0.5, "Analysis unavailable", ha="center", va="center")
                axis.set_axis_off()
            self._set_results([("Status", "Unavailable"), ("Error", str(exc))])
            self._refresh_ray_inspector_if_open()
            self._refresh_branch_tree_if_open()
            self._refresh_branch_throughput_report_if_open()
            self._refresh_analysis_branch_choices()
            self._refresh_nonseq_scene_graph_if_open()
            self.status_var.set(f"Plot refreshed with fallback preview: {exc}")
            self.append_debug(f"Plot refresh error: {exc}")
            self.append_debug(traceback.format_exc())

        self.ax.grid(True, alpha=0.2)
        if self._current_display_orientation() == "Horizontal":
            self.ax.set_xlabel("Y [mm]")
            self.ax.set_ylabel("-Z [mm]")
        else:
            self.ax.set_xlabel("Z [mm]")
            self.ax.set_ylabel("Y [mm]")
        self.ax.set_title("")
        self.figure.subplots_adjust(left=0.07, right=0.98, bottom=0.15, top=0.92, wspace=0.28)
        self.figure.text(0.5, 0.035, "KrakenOS Layout", ha="center", va="center")
        self._sync_object_controls()
        self._configure_plot_hover_hints()
        self._update_layout_selection_overlay()
        self.canvas.draw_idle()
        self._autosave_plot()
        self._finish_analysis_progress("Plot refresh", success=True)
        if self._initial_layout_passes < 40:
            self.after(50, self._set_initial_pane_layout)

    def _clear_preview_after_reset(self) -> None:
        """Clear UI trace products after Reset without building/tracing."""
        self.last_system = None
        self.last_rays = None
        self._last_preview_trace_signature = None
        self._last_preview_trace_backend = "none"
        self._last_preview_trace_note = ""
        self._last_scene_bundle = None
        self._last_optics_info = None
        self._last_wavefront_samples = []
        self._last_zernike_coefficients = []
        self._preview_field_ray_count = 1
        self._preview_field_bundle_count = 1
        self._system_cache_signature = None
        self._system_cache_system = None
        self._system_cache_has_solids = False
        self._layout_pick_regions = {}
        self._layout_ray_pick_regions = []
        self._analysis_axes = []
        self._analysis_ax = None
        self._clear_cardinal_marker_artists()
        self._clear_physical_distance_artists()
        self._clear_layout_selection_overlay()
        if getattr(self, "results_table", None) is not None:
            self.results_table.delete(*self.results_table.get_children())
        self._refresh_ray_inspector_if_open()
        self._refresh_branch_tree_if_open()
        self._refresh_branch_throughput_report_if_open()
        self._refresh_analysis_branch_choices()
        self._refresh_nonseq_scene_graph_if_open()
        self.figure.clear()
        self.ax = self.figure.add_subplot(111)
        self.ax.set_title("")
        self.ax.set_xlabel("")
        self.ax.set_ylabel("")
        self.ax.grid(False)
        self.figure.subplots_adjust(left=0.07, right=0.98, bottom=0.15, top=0.92, wspace=0.28)
        self._sync_object_controls()
        self._configure_plot_hover_hints()
        self.canvas.draw_idle()
        self.progress_spinner_var.set("idle")
        self.progress_percent_var.set("")
        self.progress_bar_var.set(0.0)
        self.status_var.set("Reset complete. Table contains only Object and Image; click Update to trace.")
        self.append_progress("Reset completed without tracing.")
        if self._initial_layout_passes < 40:
            self.after(50, self._set_initial_pane_layout)

    def _autosave_plot(self) -> None:
        if not self.auto_save_plot_var.get():
            return
        if self._autosave_after_id is not None:
            try:
                self.after_cancel(self._autosave_after_id)
            except Exception:
                pass
        self._autosave_after_id = self.after(400, self._do_autosave_plot)

    def _do_autosave_plot(self) -> None:
        self._autosave_after_id = None
        if not self.auto_save_plot_var.get():
            return
        if self.winfo_width() < 1200 or self.winfo_height() < 700:
            self._autosave_after_id = self.after(400, self._do_autosave_plot)
            return
        try:
            AUTO_PLOT_PATH.parent.mkdir(parents=True, exist_ok=True)
            self.update_idletasks()
            self.canvas.draw()
            self.figure.savefig(AUTO_PLOT_PATH, dpi=150)
        except Exception as exc:
            self.append_debug(f"Auto-save plot failed: {exc}")

    def _plot_atmosphere_image_residual(
        self,
        analysis_ax,
        system,
        reference_wavelength: float,
        settings: dict[str, float | int],
        wavelengths: np.ndarray,
    ) -> None:
        self._update_analysis_progress("Tracing atmospheric residual", 1, 3)
        reference_wavelength = float(np.clip(float(reference_wavelength), float(wavelengths[0]), float(wavelengths[-1])))
        pupil = Kos.PupilCalc(
            system,
            self._analysis_surface_index(),
            reference_wavelength,
            self._current_aperture_type(),
            self._current_aperture_value(),
        )
        pupil.Samp = max(4, min(12, int(np.sqrt(max(1, self._current_ray_count())) * 2)))
        pupil.Ptype = self._current_analysis_pupil_pattern("hexapolar")
        pupil.FieldType = "angle"
        pupil.FieldX = 0.0
        pupil.FieldY = self._current_field_angle_deg() if self._current_object_mode() == "Infinity" else 0.0
        pupil.AtmosRef = 1
        pupil.T = float(settings["temperature_k"])
        pupil.P = float(settings["pressure_pa"])
        pupil.H = float(settings["humidity"])
        pupil.xc = float(settings["co2_ppm"])
        pupil.lat = float(settings["latitude_deg"])
        pupil.h = float(settings["altitude_m"])
        pupil.l1 = reference_wavelength
        pupil.z0 = float(settings["zenith_deg"])

        centroids: list[tuple[float, float, float, float]] = []
        total = max(1, int(wavelengths.size))
        for index, sample_wavelength in enumerate(wavelengths, start=1):
            self._update_analysis_progress(f"ADC residual {index}/{total}", index, total)
            pupil.l2 = float(sample_wavelength)
            x, y, z, l, m, n = pupil.Pattern2Field()
            rays_for_wavelength = Kos.raykeeper(system)
            Kos.TraceLoop(x, y, z, l, m, n, float(sample_wavelength), rays_for_wavelength, clean=1)
            x_img, y_img, _z_img, _l_img, _m_img, _n_img = self._pick_image_plane_data(rays_for_wavelength)
            x_img = np.asarray(x_img, dtype=float).ravel()
            y_img = np.asarray(y_img, dtype=float).ravel()
            finite = np.isfinite(x_img) & np.isfinite(y_img)
            x_img = x_img[finite]
            y_img = y_img[finite]
            if x_img.size == 0:
                continue
            cx = float(np.mean(x_img))
            cy = float(np.mean(y_img))
            radius = np.sqrt((x_img - cx) * (x_img - cx) + (y_img - cy) * (y_img - cy))
            rms = float(np.sqrt(np.mean(radius * radius)))
            centroids.append((float(sample_wavelength), cx, cy, rms))

        if len(centroids) < 2:
            raise RuntimeError("Not enough finite atmospheric image residual samples")

        self._update_analysis_progress("Rendering residual", 3, 3)
        centroid_array = np.asarray(centroids, dtype=float)
        valid_wavelengths = centroid_array[:, 0]
        centroid_x = centroid_array[:, 1]
        centroid_y = centroid_array[:, 2]
        spot_rms_um = centroid_array[:, 3] * 1000.0
        reference_x = float(np.interp(reference_wavelength, valid_wavelengths, centroid_x))
        reference_y = float(np.interp(reference_wavelength, valid_wavelengths, centroid_y))
        residual_x_um = (centroid_x - reference_x) * 1000.0
        residual_y_um = (centroid_y - reference_y) * 1000.0
        residual_mag_um = np.sqrt(residual_x_um * residual_x_um + residual_y_um * residual_y_um)
        blue_red_um = float(
            np.sqrt(
                (residual_x_um[-1] - residual_x_um[0]) * (residual_x_um[-1] - residual_x_um[0])
                + (residual_y_um[-1] - residual_y_um[0]) * (residual_y_um[-1] - residual_y_um[0])
            )
        )
        max_residual_um = float(np.max(residual_mag_um))
        max_spot_rms_um = float(np.max(spot_rms_um))

        line_x, = analysis_ax.plot(valid_wavelengths, residual_x_um, color="#2563eb", marker="o", markersize=3.0)
        line_y, = analysis_ax.plot(valid_wavelengths, residual_y_um, color="#dc2626", marker="s", markersize=3.0)
        line_mag, = analysis_ax.plot(valid_wavelengths, residual_mag_um, color="#111827", linewidth=2.0)
        analysis_ax.axvline(reference_wavelength, color="#64748b", linewidth=0.8, alpha=0.65)
        analysis_ax.axhline(0.0, color="#64748b", linewidth=0.8, alpha=0.45)
        analysis_ax.set_title("Atmospheric Image Residual")
        analysis_ax.set_xlabel("Wavelength [um]")
        analysis_ax.set_ylabel(f"Image residual vs {reference_wavelength:.4g} um [um]")
        analysis_ax.set_box_aspect(0.62)
        analysis_ax.grid(True, alpha=0.2)
        analysis_ax.legend([line_x, line_y, line_mag], ["X", "Y", "Magnitude"], loc="best", fontsize=8)
        analysis_ax.text(
            0.02,
            0.03,
            f"blue-red residual: {blue_red_um:.4g} um\n"
            f"max residual: {max_residual_um:.4g} um\n"
            f"max spot RMS: {max_spot_rms_um:.4g} um",
            transform=analysis_ax.transAxes,
            ha="left",
            va="bottom",
            fontsize=7.5,
            bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.78, "pad": 3},
        )
        result_items = [
            ("Mode", "Atmos image residual"),
            ("Reference wavelength [um]", f"{reference_wavelength:.6g}"),
            ("Samples", str(int(valid_wavelengths.size))),
            ("Zenith angle [deg]", f"{float(settings['zenith_deg']):.6g}"),
            ("Blue-red residual [um]", f"{blue_red_um:.6g}"),
            ("Max residual [um]", f"{max_residual_um:.6g}"),
            ("Max spot RMS [um]", f"{max_spot_rms_um:.6g}"),
        ]
        if getattr(self, "results_table", None) is not None:
            self._set_results(result_items)
        self.append_debug(
            f"Atmos image residual ok: samples={valid_wavelengths.size}, reference_um={reference_wavelength:.6g}, "
            f"blue_red_um={blue_red_um:.6g}, max_residual_um={max_residual_um:.6g}"
        )
        self._finish_analysis_progress("Atmosphere analysis", success=True)

    def _current_interferogram_settings(self) -> dict[str, object]:
        settings: dict[str, object] = {
            "analysis_title": "Interferogram",
            "detector_port": "cross",
            "detector_size_mm": 12.0,
            "pixels": 256,
            "fringe_tilt_x_mrad": 1.5,
            "fringe_tilt_y_mrad": 0.0,
            "opd_offset_um": 0.0,
            "visibility": 1.0,
        }
        for row in getattr(self, "rows", []) or []:
            advanced = getattr(row, "advanced", {}) or {}
            if not isinstance(advanced, dict):
                continue
            row_settings = advanced.get("Interferogram")
            if isinstance(row_settings, dict):
                settings.update(row_settings)
        return settings

    @staticmethod
    def _raykeeper_value(rays, name: str, index: int, default=None):
        values = getattr(rays, name, None)
        if values is None or index >= len(values):
            return default
        arr = np.asarray(values[index]).ravel()
        if arr.size == 0:
            return default
        return arr[-1]

    def _interferogram_output_pair(self, settings: dict[str, object]) -> tuple[str, str, str]:
        port = str(settings.get("detector_port", "cross") or "cross").strip().lower()
        if port in {"return", "source", "source return", "output port 1", "port 1", "tt/rr"}:
            return "TT", "RR", "Output port 1"
        return "TR", "RT", "Detector output port"

    def _interferogram_branch_samples(self, rays, settings: dict[str, object]) -> tuple[dict, dict, str]:
        code_a, code_b, port_label = self._interferogram_output_pair(settings)
        grouped: dict[str, list[dict[str, float | str]]] = {code_a: [], code_b: []}
        branch_paths = list(getattr(rays, "BRANCH_PATH", []) or [])
        for ray_index in range(len(branch_paths)):
            branch_path = str(self._raykeeper_value(rays, "BRANCH_PATH", ray_index, "") or "")
            selectors = self._branch_path_selector_sequence(branch_path)
            if len(selectors) < 2:
                continue
            code = "".join("T" if item in {"T", "transmit"} else "R" for item in selectors[-2:])
            if code not in grouped:
                continue
            try:
                power = float(self._raykeeper_value(rays, "BRANCH_POWER", ray_index, 0.0) or 0.0)
            except Exception:
                power = 0.0
            try:
                source_weight = float(self._raykeeper_value(rays, "SOURCE_WEIGHT", ray_index, 1.0) or 1.0)
            except Exception:
                source_weight = 1.0
            try:
                top_mm = float(self._raykeeper_value(rays, "TOP", ray_index, 0.0) or 0.0)
            except Exception:
                top_mm = 0.0
            try:
                phase_deg = float(self._raykeeper_value(rays, "BRANCH_PHASE", ray_index, 0.0) or 0.0)
            except Exception:
                phase_deg = 0.0
            weight = max(power * max(source_weight, 0.0), 0.0)
            if weight <= 0.0:
                continue
            grouped[code].append(
                {
                    "code": code,
                    "path": branch_path,
                    "power": weight,
                    "top_mm": top_mm,
                    "phase_deg": phase_deg,
                }
            )
        if not grouped[code_a] or not grouped[code_b]:
            raise RuntimeError(f"Need both {code_a} and {code_b} Michelson paths at the detector port")

        def summarize(samples: list[dict[str, float | str]]) -> dict[str, float | str]:
            powers = np.asarray([float(sample["power"]) for sample in samples], dtype=float)
            total = float(np.sum(powers))
            if total <= 0.0:
                raise RuntimeError("Zero path power")
            tops = np.asarray([float(sample["top_mm"]) for sample in samples], dtype=float)
            phases = np.asarray([float(sample["phase_deg"]) for sample in samples], dtype=float)
            return {
                "code": str(samples[0]["code"]),
                "path": str(samples[0]["path"]),
                "power": total,
                "top_mm": float(np.average(tops, weights=powers)),
                "phase_deg": float(np.average(phases, weights=powers)),
                "count": float(len(samples)),
            }

        return summarize(grouped[code_a]), summarize(grouped[code_b]), port_label

    def _plot_interferogram_analysis(self, analysis_ax, system, rays, wavelength: float) -> None:
        del system
        self._set_analysis_parallel_status("Interferogram", 1, False)
        self._begin_analysis_progress("Interferogram analysis")
        try:
            self._update_analysis_progress("Reading path phases", 1, 3)
            settings = self._current_interferogram_settings()
            beam_a, beam_b, port_label = self._interferogram_branch_samples(rays, settings)
            wavelength_um = max(float(wavelength), 1e-12)
            wavelength_mm = wavelength_um * 1e-3
            detector_size = max(float(settings.get("detector_size_mm", 12.0)), 1e-6)
            pixels = max(32, min(int(float(settings.get("pixels", 256))), 1024))
            tilt_x = float(settings.get("fringe_tilt_x_mrad", 1.5)) * 1e-3
            tilt_y = float(settings.get("fringe_tilt_y_mrad", 0.0)) * 1e-3
            opd_offset_um = float(settings.get("opd_offset_um", 0.0))
            visibility_scale = min(max(float(settings.get("visibility", 1.0)), 0.0), 1.0)

            self._update_analysis_progress("Summing coherent fields", 2, 3)
            power_a = max(float(beam_a["power"]), 0.0)
            power_b = max(float(beam_b["power"]), 0.0)
            if power_a <= 0.0 or power_b <= 0.0:
                raise RuntimeError("Detector paths have zero power")
            opd_um = (float(beam_b["top_mm"]) - float(beam_a["top_mm"])) * 1000.0 + opd_offset_um
            branch_phase_deg = float(beam_b["phase_deg"]) - float(beam_a["phase_deg"])
            phase0 = (2.0 * np.pi * opd_um / wavelength_um) + np.deg2rad(branch_phase_deg)
            axis = np.linspace(-0.5 * detector_size, 0.5 * detector_size, pixels)
            grid_x, grid_y = np.meshgrid(axis, axis)
            spatial_phase = (2.0 * np.pi / wavelength_mm) * (tilt_x * grid_x + tilt_y * grid_y)
            fringe = np.cos(phase0 + spatial_phase)
            coherent_term = 2.0 * np.sqrt(power_a * power_b) * visibility_scale
            intensity = power_a + power_b + coherent_term * fringe
            peak = float(np.nanmax(intensity)) if intensity.size else 0.0
            if peak > 0.0:
                intensity = intensity / peak
            radius = np.sqrt(grid_x * grid_x + grid_y * grid_y)
            detector_radius = 0.5 * detector_size
            intensity = np.where(radius <= detector_radius, intensity, np.nan)
            visibility = coherent_term / max(power_a + power_b, 1e-15)

            self._update_analysis_progress("Rendering", 3, 3)
            cmap = colormaps.get_cmap("magma").copy()
            cmap.set_bad("#f8fafc")
            extent = [-0.5 * detector_size, 0.5 * detector_size, -0.5 * detector_size, 0.5 * detector_size]
            image = analysis_ax.imshow(
                intensity,
                origin="lower",
                extent=extent,
                cmap=cmap,
                vmin=0.0,
                vmax=1.0,
                interpolation="bilinear",
            )
            title = str(settings.get("analysis_title", "Interferogram") or "Interferogram").strip()
            analysis_ax.set_title(f"{title}  |  {port_label}")
            analysis_ax.set_xlabel("Detector X [mm]")
            analysis_ax.set_ylabel("Detector Y [mm]")
            analysis_ax.set_aspect("equal", adjustable="box")
            analysis_ax.set_box_aspect(0.82)
            analysis_ax.grid(False)
            self.figure.colorbar(image, ax=analysis_ax, fraction=0.046, pad=0.04, label="Normalized intensity")
            analysis_ax.text(
                0.02,
                0.02,
                f"{beam_a['code']} vs {beam_b['code']}\n"
                f"OPD {opd_um:.4g} um, phase {np.rad2deg(np.mod(phase0, 2*np.pi)):.4g} deg\n"
                f"tilt ({tilt_x*1e3:.3g}, {tilt_y*1e3:.3g}) mrad, V={visibility:.3g}",
                transform=analysis_ax.transAxes,
                ha="left",
                va="bottom",
                fontsize=7.5,
                color="#111827",
                bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.82, "pad": 3},
            )
            self.append_debug(
                f"Interferogram ok: {beam_a['code']} power={power_a:.6g}, {beam_b['code']} power={power_b:.6g}, "
                f"opd_um={opd_um:.6g}, phase_deg={branch_phase_deg:.6g}, pixels={pixels}, port={port_label}"
            )
            self._finish_analysis_progress("Interferogram analysis", success=True)
        except Exception as exc:
            self.append_debug(f"Interferogram analysis error: {exc}")
            analysis_ax.text(
                0.5,
                0.5,
                "Interferogram unavailable\nNeed a beam-splitter layout with recombined paths",
                ha="center",
                va="center",
            )
            analysis_ax.set_axis_off()
            self._finish_analysis_progress("Interferogram analysis", success=False)

    def _plot_analysis(self, analysis_ax, system, rays, wavelength: float) -> None:
        if analysis_ax is None:
            return
        analysis_ax.clear()
        analysis_ax.set_aspect("auto")
        analysis_ax.set_box_aspect(0.62)
        spot_field_series: list[tuple[np.ndarray, np.ndarray, float]] = []
        if self.analysis_mode == "interferogram":
            self._plot_interferogram_analysis(analysis_ax, system, rays, wavelength)
            return
        if self.analysis_mode == "atmosphere":
            try:
                self._set_analysis_parallel_status("Atmosphere", 1, False)
                self._begin_analysis_progress("Atmosphere analysis")
                settings = self._current_atmosphere_settings()
                wavelengths = self._atmosphere_wavelength_samples()
                plot_mode = self._current_atmos_plot_mode()
                if plot_mode == "Image residual (current optics)":
                    self._plot_atmosphere_image_residual(analysis_ax, system, wavelength, settings, wavelengths)
                    return

                self._update_analysis_progress("Computing refraction", 1, 2)
                refraction_deg = np.asarray(
                    [
                        Kos.quick_refraction(
                            float(wl),
                            float(settings["zenith_deg"]),
                            conditions=None,
                            T=float(settings["temperature_k"]),
                            p=float(settings["pressure_pa"]),
                            RH=float(settings["humidity"]),
                            xc=float(settings["co2_ppm"]),
                            lat=float(settings["latitude_deg"]),
                            h=float(settings["altitude_m"]),
                        )
                        for wl in wavelengths
                    ],
                    dtype=float,
                )
                finite = np.isfinite(wavelengths) & np.isfinite(refraction_deg)
                wavelengths = wavelengths[finite]
                refraction_deg = refraction_deg[finite]
                if wavelengths.size < 2:
                    raise RuntimeError("Not enough finite atmosphere samples")

                refraction_arcsec = refraction_deg * 3600.0
                reference_wavelength = float(np.clip(self._current_wavelength(), wavelengths[0], wavelengths[-1]))
                reference_refraction = float(np.interp(reference_wavelength, wavelengths, refraction_arcsec))
                dispersion_arcsec = refraction_arcsec - reference_refraction
                blue_red_arcsec = float(
                    Kos.quick_dispersion(
                        float(wavelengths[0]),
                        float(wavelengths[-1]),
                        float(settings["zenith_deg"]),
                        conditions=None,
                        T=float(settings["temperature_k"]),
                        p=float(settings["pressure_pa"]),
                        RH=float(settings["humidity"]),
                        xc=float(settings["co2_ppm"]),
                        lat=float(settings["latitude_deg"]),
                        h=float(settings["altitude_m"]),
                    )
                    * 3600.0
                )

                line_ref, = analysis_ax.plot(
                    wavelengths,
                    refraction_arcsec,
                    color="#1d4ed8",
                    linewidth=2.0,
                    marker="o",
                    markersize=3.5,
                    label="Refraction",
                )
                ax2 = analysis_ax.twinx()
                line_disp, = ax2.plot(
                    wavelengths,
                    dispersion_arcsec,
                    color="#b45309",
                    linewidth=1.8,
                    linestyle="--",
                    marker="s",
                    markersize=3.0,
                    label=f"Dispersion vs {reference_wavelength:.4g} um",
                )
                analysis_ax.axvline(reference_wavelength, color="#64748b", linewidth=0.8, alpha=0.6)
                analysis_ax.set_title(f"Atmospheric Refraction / Dispersion  |  Z={float(settings['zenith_deg']):.3g} deg")
                analysis_ax.set_xlabel("Wavelength [um]")
                analysis_ax.set_ylabel("Refraction [arcsec]", color="#1d4ed8")
                ax2.set_ylabel("Relative dispersion [arcsec]", color="#b45309")
                analysis_ax.grid(True, alpha=0.2)
                analysis_ax.set_box_aspect(0.62)
                analysis_ax.legend([line_ref, line_disp], ["Refraction", "Relative dispersion"], loc="best", fontsize=8)
                y_min, y_max = analysis_ax.get_ylim()
                analysis_ax.text(
                    0.02,
                    0.03,
                    f"blue-red dispersion: {blue_red_arcsec:.3g} arcsec\n"
                    f"T={float(settings['temperature_k']):.4g} K, P={float(settings['pressure_pa']):.4g} Pa, "
                    f"RH={float(settings['humidity']):.3g}",
                    transform=analysis_ax.transAxes,
                    ha="left",
                    va="bottom",
                    fontsize=7.5,
                    bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.78, "pad": 3},
                )
                analysis_ax.set_ylim(y_min, y_max)
                self.append_debug(
                    f"Atmosphere ok: wavelengths={wavelengths.size}, zenith={float(settings['zenith_deg']):.6g}, "
                    f"blue_red_arcsec={blue_red_arcsec:.6g}, reference_um={reference_wavelength:.6g}"
                )
                self._update_analysis_progress("Rendering", 2, 2)
                self._finish_analysis_progress("Atmosphere analysis", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("Atmosphere", 1, False)
                self.append_debug(f"Atmosphere analysis error: {exc}")
                analysis_ax.text(0.5, 0.5, "Atmosphere analysis unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Atmosphere analysis", success=False)
            return

        if self.analysis_mode in {"spot", "rms"} and not _is_all_path_filter(self._current_analysis_branch_filter()):
            self._plot_branch_detector_spot_analysis(analysis_ax, system, self.analysis_mode)
            return

        if self.analysis_mode == "psf" and not _is_all_path_filter(self._current_analysis_branch_filter()):
            self._plot_branch_detector_psf_analysis(analysis_ax, system, wavelength)
            return

        if self.analysis_mode == "mtf" and not _is_all_path_filter(self._current_analysis_branch_filter()):
            self._plot_branch_detector_mtf_analysis(analysis_ax, system, wavelength)
            return

        if self.analysis_mode == "detector_map":
            self._plot_branch_detector_map_analysis(analysis_ax, system)
            return

        if self.analysis_mode == "coherent_detector":
            self._plot_coherent_detector_analysis(analysis_ax, system, wavelength)
            return

        try:
            if self.analysis_mode in {"spot", "rms"}:
                field_type = "angle" if self._current_object_mode() == "Infinity" else "height"
                center_field = self._current_field_angle_deg() if field_type == "angle" else self._current_field_height()
                sampled_fields = [center_field]
                if self.analysis_mode == "spot" and self._current_source_model() == SOURCE_MODEL_DEFAULT:
                    sampled_fields = self._sample_field_values(center_field)
                    if not sampled_fields:
                        sampled_fields = [center_field]

                field_results = []
                analysis_workers = 1
                for field_value in sampled_fields:
                    Xi, Yi, Zi, Li, Mi, Ni, worker_count = self._build_geometric_image_samples_full(
                        system,
                        wavelength,
                        sample_count=max(24, self._current_ray_count() * 6),
                        pattern="hexapolar",
                        surface_index=self._analysis_surface_index(),
                        aperture_type=self._current_aperture_type(),
                        aperture_value=self._current_aperture_value(),
                        field_type=field_type,
                        field_x=0.0,
                        field_y=float(field_value),
                    )
                    analysis_workers = max(analysis_workers, int(worker_count))
                    if Xi.size == 0:
                        continue
                    field_results.append((Xi, Yi, Zi, Li, Mi, Ni, float(field_value)))

                if not field_results:
                    X = Y = Z = L = M = N = np.asarray([])
                else:
                    X = np.concatenate([result[0] for result in field_results])
                    Y = np.concatenate([result[1] for result in field_results])
                    Z = np.concatenate([result[2] for result in field_results])
                    L = np.concatenate([result[3] for result in field_results])
                    M = np.concatenate([result[4] for result in field_results])
                    N = np.concatenate([result[5] for result in field_results])
                    if self.analysis_mode == "spot":
                        spot_field_series = [
                            (result[0], result[1], result[6]) for result in field_results
                        ]
            else:
                analysis_rays = self._build_analysis_rays(system, wavelength)
                X, Y, Z, L, M, N = self._pick_image_plane_data(analysis_rays)
                analysis_workers = 1
        except Exception as exc:
            self.append_debug(f"{self.analysis_mode.upper()} analysis trace error: {exc}")
            X = Y = Z = L = M = N = np.asarray([])
            analysis_workers = 1

        if X.size == 0 and self.analysis_mode in {"spot", "rms"}:
            analysis_ax.text(0.5, 0.5, "No ray data", ha="center", va="center")
            analysis_ax.set_axis_off()
            return

        if self.analysis_mode == "spot":
            self._set_analysis_parallel_status("Spot", analysis_workers, True)
            spot_mode = self._current_spot_view_mode()
            if spot_field_series:
                colors = self._field_colors(len(spot_field_series))
                field_unit = "deg" if self._current_object_mode() == "Infinity" else "mm"
                prepared_series: list[tuple[np.ndarray, np.ndarray, float]] = []
                if spot_mode == "Absolute":
                    for x_field, y_field, field_value in spot_field_series:
                        prepared_series.append((x_field, y_field, field_value))
                else:
                    centered_series = []
                    max_span = 1e-3
                    for x_field, y_field, field_value in spot_field_series:
                        cx = float(np.mean(x_field))
                        cy = float(np.mean(y_field))
                        sx = x_field - cx
                        sy = y_field - cy
                        max_span = max(max_span, float(max(np.ptp(sx), np.ptp(sy), 1e-6)))
                        centered_series.append((sx, sy, field_value))
                    if spot_mode == "Grid" and centered_series:
                        cols = max(1, int(np.ceil(np.sqrt(len(centered_series)))))
                        rows = int(np.ceil(len(centered_series) / cols))
                        spacing = max(max_span * 1.8, 2e-3)
                        for index, (sx, sy, field_value) in enumerate(centered_series):
                            row = index // cols
                            col = index % cols
                            offset_x = (col - (cols - 1) / 2.0) * spacing
                            offset_y = ((rows - 1) / 2.0 - row) * spacing
                            prepared_series.append((sx + offset_x, sy + offset_y, field_value))
                    else:
                        prepared_series = centered_series
                X_plot = np.concatenate([item[0] for item in prepared_series]) if prepared_series else X
                Y_plot = np.concatenate([item[1] for item in prepared_series]) if prepared_series else Y
                draw_order = sorted(
                    range(len(prepared_series)),
                    key=lambda idx: abs(float(prepared_series[idx][2])),
                    reverse=True,
                )
                for rank, index in enumerate(draw_order):
                    _x_field, _y_field, field_value = prepared_series[index]
                    analysis_ax.scatter(
                        _x_field,
                        _y_field,
                        s=8,
                        c=colors[index],
                        alpha=0.45,
                        label=f"{field_value:.3g} {field_unit}",
                        zorder=3 + rank,
                    )
                if len(spot_field_series) > 1:
                    analysis_ax.legend(loc="upper right", fontsize=7, title="Field")
            else:
                if spot_mode == "Absolute":
                    X_plot = X
                    Y_plot = Y
                else:
                    X_plot = X - float(np.mean(X))
                    Y_plot = Y - float(np.mean(Y))
                analysis_ax.scatter(X_plot, Y_plot, s=18, c="#c0392b", alpha=0.8)
            analysis_ax.axhline(0.0, color="#2c3e50", linewidth=0.6, alpha=0.5)
            analysis_ax.axvline(0.0, color="#2c3e50", linewidth=0.6, alpha=0.5)
            title_suffix = {
                "Absolute": "Absolute",
                "Centroid": "Centroid Referenced",
                "Grid": "Grid View",
            }.get(spot_mode, "Grid View")
            analysis_ax.set_title(f"Spot Diagram ({title_suffix})")
            analysis_ax.set_xlabel("X [mm]")
            analysis_ax.set_ylabel("Y [mm]")
            if np.ptp(X_plot) < 1e-12 and np.ptp(Y_plot) < 1e-12:
                analysis_ax.set_xlim(float(X_plot[0]) - 1.0, float(X_plot[0]) + 1.0)
                analysis_ax.set_ylim(float(Y_plot[0]) - 1.0, float(Y_plot[0]) + 1.0)
            elif np.ptp(X_plot) < 1e-12:
                center_x = float(np.mean(X_plot))
                span_y = max(float(np.ptp(Y_plot)), 1e-6)
                half_width = max(span_y * 0.35, 1e-3)
                analysis_ax.set_xlim(center_x - half_width, center_x + half_width)
            if spot_mode == "Absolute":
                x_min = float(np.min(X_plot))
                x_max = float(np.max(X_plot))
                y_min = float(np.min(Y_plot))
                y_max = float(np.max(Y_plot))
                x_span = max(x_max - x_min, 1e-9)
                y_span = max(y_max - y_min, 1e-9)
                center_x = 0.5 * (x_min + x_max)
                center_y = 0.5 * (y_min + y_max)
                half_x = max(x_span * 0.7, y_span * 0.55, 0.25)
                half_y = max(y_span * 0.55, x_span * 2.0, 0.25)
                analysis_ax.set_xlim(center_x - half_x, center_x + half_x)
                analysis_ax.set_ylim(center_y - half_y, center_y + half_y)
                analysis_ax.set_aspect("auto")
                analysis_ax.set_box_aspect(0.62)
                analysis_ax.xaxis.set_major_locator(MaxNLocator(5))
                analysis_ax.yaxis.set_major_locator(MaxNLocator(7))
                analysis_ax.tick_params(axis="x", labelrotation=0)
            else:
                analysis_ax.set_aspect("auto")
                analysis_ax.set_box_aspect(0.62)
            analysis_ax.grid(True, alpha=0.2)
            self.append_debug(f"Spot analysis ok: rays={len(X)}, workers={analysis_workers}")
            return

        if self.analysis_mode == "psf":
            try:
                self._begin_analysis_progress("PSF analysis")
                field_type = "angle" if self._current_object_mode() == "Infinity" else "height"
                field_y = self._current_field_angle_deg() if field_type == "angle" else self._current_field_height()
                self._update_analysis_progress("Tracing rays", 1, 3)
                x_local, y_local, worker_count = self._build_geometric_image_samples(
                    system,
                    wavelength,
                    sample_count=max(48, self._current_ray_count() * 10),
                    pattern="hexapolar",
                    surface_index=self._analysis_surface_index(),
                    aperture_type=self._current_aperture_type(),
                    aperture_value=self._current_aperture_value(),
                    field_type=field_type,
                    field_x=0.0,
                    field_y=field_y,
                )
                self._update_analysis_progress("Building PSF image", 2, 3)
                if x_local.size < 4:
                    raise RuntimeError("Not enough image-plane samples for PSF")
                span_x = max(float(np.ptp(x_local)), 1e-3)
                span_y = max(float(np.ptp(y_local)), 1e-3)
                span = max(span_x, span_y) * 1.25
                bins = 128
                hist, xedges, yedges, accelerator = self._compute_psf_histogram(x_local, y_local, bins, span)
                psf = hist.T
                psf /= max(float(np.max(psf)), 1e-12)
                extent = [float(xedges[0]), float(xedges[-1]), float(yedges[0]), float(yedges[-1])]
                image = analysis_ax.imshow(psf, origin="lower", extent=extent, cmap="inferno", aspect="equal")
                self._set_analysis_parallel_status("PSF", worker_count, True)
                self._set_analysis_accelerator(accelerator)
                analysis_ax.set_title(f"Geometric PSF  |  {field_type}={field_y:.3g}  |  {wavelength:.4g} um")
                analysis_ax.set_xlabel("X [mm]")
                analysis_ax.set_ylabel("Y [mm]")
                analysis_ax.set_box_aspect(0.62)
                analysis_ax.grid(False)
                self.figure.colorbar(image, ax=analysis_ax, fraction=0.046, pad=0.04, label="Normalized intensity")
                self.append_debug(
                    f"PSF analysis ok: rays={x_local.size}, bins={bins}, workers={worker_count}, accel={accelerator}"
                )
                self._update_analysis_progress("Rendering", 3, 3)
                self._finish_analysis_progress("PSF analysis", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("PSF", 1, True)
                self.append_debug(f"PSF analysis error: {exc}")
                analysis_ax.text(0.5, 0.5, "PSF analysis unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("PSF analysis", success=False)
            return

        if self.analysis_mode == "psf_map":
            try:
                self._set_analysis_parallel_status("PSF map", 1, True)
                self._begin_analysis_progress("PSF map")
                if self._current_source_model() != SOURCE_MODEL_DEFAULT:
                    analysis_ax.text(
                        0.5,
                        0.5,
                        "PSFMap uses Pupil / field sampling.\nUse Illum for random-source throughput.",
                        ha="center",
                        va="center",
                    )
                    analysis_ax.set_axis_off()
                    self._finish_analysis_progress("PSF map", success=False)
                    return
                field_samples = self._resolved_field_grid_samples()
                if not field_samples:
                    raise RuntimeError("No valid PSF-map samples")

                sample_count = max(32, self._current_ray_count() * 6)
                self._update_analysis_progress("Tracing field PSFs", 1, 3)
                sample_results, worker_count = self._build_geometric_image_samples_for_field_samples(
                    wavelength,
                    sample_count=sample_count,
                    pattern=self._current_analysis_pupil_pattern("hexapolar"),
                    surface_index=self._analysis_surface_index(),
                    aperture_type=self._current_aperture_type(),
                    aperture_value=self._current_aperture_value(),
                    field_samples=field_samples,
                )
                if not sample_results:
                    raise RuntimeError("No image-plane PSF samples")

                self._update_analysis_progress("Building PSF tiles", 2, 3)
                display_x = [float(sample["display_x"]) for sample in field_samples]
                display_y = [float(sample["display_y"]) for sample in field_samples]
                x_unique = np.asarray(sorted(set(round(value, 12) for value in display_x)), dtype=float)
                y_unique = np.asarray(sorted(set(round(value, 12) for value in display_y)), dtype=float)
                if x_unique.size == 0 or y_unique.size == 0:
                    raise RuntimeError("No valid PSF-map grid")
                x_lookup = {float(value): i for i, value in enumerate(x_unique)}
                y_lookup = {float(value): i for i, value in enumerate(y_unique)}

                centered_results: list[tuple[np.ndarray, np.ndarray]] = []
                spans: list[float] = []
                for x_local, y_local in sample_results:
                    x_vals, y_vals = self._center_image_plane_samples(x_local, y_local)
                    centered_results.append((x_vals, y_vals))
                    if x_vals.size >= 4:
                        spans.append(max(float(np.ptp(x_vals)), float(np.ptp(y_vals))))
                if not spans:
                    raise RuntimeError("No finite PSF-map ray bundles")

                span = max(max(spans) * 1.25, 1e-3)
                tile_bins = 48 if len(field_samples) <= 9 else 36 if len(field_samples) <= 25 else 28
                gap = max(1, tile_bins // 12)
                height = int(y_unique.size * tile_bins + max(0, y_unique.size - 1) * gap)
                width = int(x_unique.size * tile_bins + max(0, x_unique.size - 1) * gap)
                mosaic = np.full((height, width), np.nan, dtype=float)

                valid_tiles = 0
                for sample, (x_vals, y_vals) in zip(field_samples, centered_results):
                    if x_vals.size < 4:
                        continue
                    hist, _xedges, _yedges = np.histogram2d(
                        x_vals,
                        y_vals,
                        bins=tile_bins,
                        range=[[-span / 2.0, span / 2.0], [-span / 2.0, span / 2.0]],
                    )
                    tile = hist.T
                    peak = float(np.max(tile)) if tile.size else 0.0
                    if peak <= 0.0:
                        continue
                    tile = np.sqrt(tile / peak)
                    x_index = x_lookup[round(float(sample["display_x"]), 12)]
                    y_index = y_lookup[round(float(sample["display_y"]), 12)]
                    x0 = int(x_index * (tile_bins + gap))
                    y0 = int(y_index * (tile_bins + gap))
                    mosaic[y0 : y0 + tile_bins, x0 : x0 + tile_bins] = tile
                    valid_tiles += 1
                if valid_tiles == 0:
                    raise RuntimeError("No valid PSF-map tiles")

                cmap = colormaps.get_cmap("inferno").copy()
                cmap.set_bad("#f3f4f6")
                image = analysis_ax.imshow(
                    mosaic,
                    origin="lower",
                    interpolation="nearest",
                    cmap=cmap,
                    vmin=0.0,
                    vmax=1.0,
                )
                unit = str(field_samples[0]["unit"])
                basis = str(field_samples[0]["basis"])
                label = f"{basis} [{unit}]" if unit else basis
                x_ticks = [index * (tile_bins + gap) + (tile_bins - 1) / 2.0 for index in range(x_unique.size)]
                y_ticks = [index * (tile_bins + gap) + (tile_bins - 1) / 2.0 for index in range(y_unique.size)]
                analysis_ax.set_xticks(x_ticks, [self._format_field_sample_value(value) for value in x_unique])
                analysis_ax.set_yticks(y_ticks, [self._format_field_sample_value(value) for value in y_unique])
                analysis_ax.tick_params(axis="x", labelrotation=35 if x_unique.size > 3 else 0)
                analysis_ax.set_title("Wide-Field Geometric PSF Map")
                analysis_ax.set_xlabel(f"Field X: {label}")
                analysis_ax.set_ylabel(f"Field Y: {label}")
                analysis_ax.set_box_aspect(0.85)
                analysis_ax.grid(False)
                cbar = analysis_ax.figure.colorbar(image, ax=analysis_ax, fraction=0.046, pad=0.04)
                cbar.set_label("Normalized intensity per field")
                self._set_analysis_parallel_status("PSF map", worker_count, True)
                self.append_debug(
                    f"PSFMap ok: samples={len(field_samples)}, tiles={valid_tiles}, "
                    f"rays_per_field={sample_count}, bins={tile_bins}, span={span:.6g}, workers={worker_count}"
                )
                self._update_analysis_progress("Rendering", 3, 3)
                self._finish_analysis_progress("PSF map", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("PSF map", 1, True)
                self.append_debug(f"PSFMap error: {exc}")
                analysis_ax.text(0.5, 0.5, "PSF map unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("PSF map", success=False)
            return

        if self.analysis_mode == "rms":
            self._set_analysis_parallel_status("RMS", analysis_workers, True)
            rms, cenX, cenY = Kos.RMS(X, Y, Z, L, M, N)
            radii = np.sqrt((X - cenX) ** 2 + (Y - cenY) ** 2)
            bins = min(max(5, int(np.sqrt(max(len(radii), 1)))), 20)
            analysis_ax.hist(radii, bins=bins, color="#4f81bd", edgecolor="white")
            analysis_ax.set_title(f"Spot Radius Histogram  |  RMS = {float(rms):.4g} mm")
            analysis_ax.set_xlabel("Radius [mm]")
            analysis_ax.set_ylabel("Count")
            analysis_ax.set_box_aspect(0.52)
            analysis_ax.grid(True, axis="y", alpha=0.2)
            self.append_debug(f"RMS analysis ok: rays={len(X)}, workers={analysis_workers}")
            return

        if self.analysis_mode == "pupil":
            try:
                self._set_analysis_parallel_status("Pupil", 1, False)
                self._begin_analysis_progress("Pupil analysis")
                self._update_analysis_progress("Building pupil", 1, 2)
                pupil = Kos.PupilCalc(
                    system,
                    self._analysis_surface_index(),
                    wavelength,
                    self._current_aperture_type(),
                    self._current_aperture_value(),
                )
                labels = [
                    ("Input Radius", float(pupil.RadPupInp)),
                    ("Input Z", float(pupil.PosPupInp[2])),
                    ("Output Radius", float(pupil.RadPupOut)),
                    ("Output Z", float(pupil.PosPupOut[2])),
                    ("Airy Radius", float(pupil.FocusAiryRadius)),
                ]
                y_pos = np.arange(len(labels))
                values = [item[1] for item in labels]
                analysis_ax.barh(y_pos, values, color="#16a085")
                analysis_ax.set_yticks(y_pos, [item[0] for item in labels])
                analysis_ax.set_title("Pupil Summary")
                analysis_ax.set_xlabel("mm")
                analysis_ax.set_box_aspect(0.52)
                analysis_ax.grid(True, axis="x", alpha=0.2)
                self._update_analysis_progress("Rendering", 2, 2)
                self._finish_analysis_progress("Pupil analysis", success=True)
            except Exception:
                analysis_ax.text(0.5, 0.5, "Pupil analysis unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Pupil analysis", success=False)
            return

        if self.analysis_mode == "seidel":
            try:
                self._set_analysis_parallel_status("Seidel", 1, False)
                self._begin_analysis_progress("Seidel analysis")
                self._update_analysis_progress("Building pupil", 1, 3)
                pupil = Kos.PupilCalc(
                    system,
                    self._analysis_surface_index(),
                    wavelength,
                    self._current_aperture_type(),
                    self._current_aperture_value(),
                )
                self._update_analysis_progress("Computing coefficients", 2, 3)
                seidel = Kos.Seidel(pupil)
                values = np.asarray(seidel.SCW_TOTAL, dtype=float)
                labels = seidel.SCW_NM
                analysis_ax.bar(np.arange(len(values)), values, color="#8e44ad")
                analysis_ax.set_xticks(np.arange(len(values)), labels, rotation=25, ha="right")
                analysis_ax.set_title("Seidel Coefficients in Waves")
                analysis_ax.set_ylabel("Waves")
                analysis_ax.set_box_aspect(0.52)
                analysis_ax.grid(True, axis="y", alpha=0.2)
                self._update_analysis_progress("Rendering", 3, 3)
                self._finish_analysis_progress("Seidel analysis", success=True)
            except Exception:
                analysis_ax.text(0.5, 0.5, "Seidel analysis unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Seidel analysis", success=False)
            return

        if self.analysis_mode == "wavefront":
            try:
                self._last_wavefront_samples = []
                self._set_analysis_parallel_status("Wavefront", 1, False)
                self._begin_analysis_progress("Wavefront analysis")
                self._update_analysis_progress("Building pupil", 1, 3)
                style = self._current_wavefront_style()
                pupil = Kos.PupilCalc(
                    system,
                    self._analysis_surface_index(),
                    wavelength,
                    self._current_aperture_type(),
                    self._current_aperture_value(),
                )
                pupil.Samp = max(8, min(22, int(np.sqrt(max(1, self._current_ray_count())) * 4)))
                pupil.Ptype = self._current_analysis_pupil_pattern("hexapolar")
                field_type = "angle" if self._current_object_mode() == "Infinity" else "height"
                pupil.FieldType = field_type
                pupil.FieldX = 0.0
                pupil.FieldY = self._current_field_angle_deg() if field_type == "angle" else self._current_field_height()
                self._update_analysis_progress("Computing phase", 2, 3)
                phase_method = "Phase"
                try:
                    px, py, phase, _p2v = Kos.Phase(pupil)
                except Exception:
                    capture = io.StringIO()
                    with redirect_stdout(capture), redirect_stderr(capture):
                        px, py, phase, _p2v = Kos.Phase2(pupil)
                    phase_method = "Phase2"
                    phase2_log = capture.getvalue().strip()
                    if phase2_log:
                        self.append_debug(phase2_log)

                px = np.asarray(px, dtype=float).ravel()
                py = np.asarray(py, dtype=float).ravel()
                phase = np.asarray(phase, dtype=float).ravel()
                finite = np.isfinite(px) & np.isfinite(py) & np.isfinite(phase)
                px = px[finite]
                py = py[finite]
                phase = phase[finite]
                if phase.size < 4:
                    raise RuntimeError("Not enough finite wavefront samples")

                plot_x = py
                plot_y = px
                phase_centered = phase - float(np.mean(phase))
                phase_pv = float(np.ptp(phase))
                phase_rms = float(np.sqrt(np.mean(phase_centered * phase_centered)))
                is_wavefront_function = style == WAVEFRONT_FUNCTION_STYLE

                colorbar_label = "Wavefront [waves]"
                cmap_name = "RdBu_r"
                display_values = phase
                metric_note = f"P-V {phase_pv:.4g} waves\nRMS {phase_rms:.4g} waves"
                image = None
                slope_rms = None
                display_pv = phase_pv
                display_rms = phase_rms
                function_reference = "mean piston removed"

                if is_wavefront_function:
                    display_values = self._remove_wavefront_reference_plane(plot_x, plot_y, phase_centered)
                    finite_display = np.isfinite(display_values)
                    if np.any(finite_display):
                        display_pv = float(np.nanmax(display_values[finite_display]) - np.nanmin(display_values[finite_display]))
                        display_rms = float(np.sqrt(np.nanmean(display_values[finite_display] * display_values[finite_display])))
                    function_reference = "best-fit piston/tilt removed"
                    analysis_ax = self._plot_wavefront_function_analysis(
                        analysis_ax,
                        plot_x,
                        plot_y,
                        display_values,
                        phase_pv=display_pv,
                        phase_rms=display_rms,
                        phase_method=phase_method,
                        reference_note=function_reference,
                    )
                elif style == "Wrapped phase":
                    display_values = np.mod(phase + 0.5, 1.0) - 0.5
                    colorbar_label = "Wrapped phase [waves]"
                    cmap_name = "twilight_shifted"
                    metric_note += "\nwrapped to +/-0.5 waves"
                elif style == "Interferogram":
                    display_values = 0.5 + 0.5 * np.cos(2.0 * np.pi * phase)
                    colorbar_label = "Relative intensity"
                    cmap_name = "gray"
                    metric_note += "\ncos(2*pi*W)"

                if not is_wavefront_function and style in {"Slope X", "Slope Y", "Slope magnitude"}:
                    from matplotlib.tri import LinearTriInterpolator, Triangulation

                    if np.ptp(plot_x) <= 1e-12 or np.ptp(plot_y) <= 1e-12:
                        raise RuntimeError("Degenerate pupil samples for slope map")
                    grid_count = max(48, min(120, int(np.sqrt(max(phase.size, 1)) * 6)))
                    x_grid = np.linspace(float(np.min(plot_x)), float(np.max(plot_x)), grid_count)
                    y_grid = np.linspace(float(np.min(plot_y)), float(np.max(plot_y)), grid_count)
                    xx, yy = np.meshgrid(x_grid, y_grid)
                    triangulation = Triangulation(plot_x, plot_y)
                    interpolator = LinearTriInterpolator(triangulation, phase)
                    phase_grid = np.asarray(interpolator(xx, yy).filled(np.nan), dtype=float)
                    grad_y, grad_x = np.gradient(phase_grid, y_grid, x_grid)
                    if style == "Slope X":
                        display_grid = grad_x
                        colorbar_label = "dW/dX [waves/pupil]"
                    elif style == "Slope Y":
                        display_grid = grad_y
                        colorbar_label = "dW/dY [waves/pupil]"
                    else:
                        display_grid = np.sqrt(grad_x * grad_x + grad_y * grad_y)
                        colorbar_label = "|grad W| [waves/pupil]"
                    finite_display = np.isfinite(display_grid)
                    if not np.any(finite_display):
                        raise RuntimeError("Wavefront slope interpolation produced no finite samples")
                    slope_rms = float(np.sqrt(np.nanmean(display_grid[finite_display] * display_grid[finite_display])))
                    metric_note += f"\nRMS slope {slope_rms:.4g}"
                    cmap = colormaps.get_cmap("magma" if style == "Slope magnitude" else "RdBu_r").copy()
                    cmap.set_bad("#f3f4f6")
                    image = analysis_ax.imshow(
                        np.ma.masked_invalid(display_grid),
                        origin="lower",
                        extent=[float(x_grid[0]), float(x_grid[-1]), float(y_grid[0]), float(y_grid[-1])],
                        cmap=cmap,
                        aspect="equal",
                    )
                elif not is_wavefront_function:
                    try:
                        image = analysis_ax.tricontourf(plot_x, plot_y, display_values, levels=48, cmap=cmap_name)
                        if style == "Interferogram":
                            analysis_ax.tricontour(plot_x, plot_y, display_values, levels=[0.5], colors="#2563eb", linewidths=0.45, alpha=0.65)
                    except Exception:
                        image = analysis_ax.scatter(plot_x, plot_y, c=display_values, cmap=cmap_name, s=22)

                if not is_wavefront_function:
                    analysis_ax.set_title(f"Wavefront: {style}")
                    analysis_ax.set_xlabel("X pupil")
                    analysis_ax.set_ylabel("Y pupil")
                    analysis_ax.set_aspect("equal", adjustable="box")
                    analysis_ax.set_box_aspect(0.72)
                    analysis_ax.grid(True, alpha=0.2)
                    analysis_ax.text(
                        0.98,
                        0.03,
                        metric_note,
                        transform=analysis_ax.transAxes,
                        ha="right",
                        va="bottom",
                        fontsize=7.5,
                        bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.78, "pad": 3},
                    )
                    analysis_ax.figure.colorbar(image, ax=analysis_ax, fraction=0.046, pad=0.04, label=colorbar_label)
                result_items = [
                    ("Mode", "Wavefront"),
                    ("Style", style),
                    ("Samples", str(int(phase.size))),
                    ("Phase method", phase_method),
                    ("Phase P-V [waves]", f"{display_pv:.6g}"),
                    ("Phase RMS [waves]", f"{display_rms:.6g}"),
                    ("Display min", f"{float(np.nanmin(display_values)):.6g}" if style not in {"Slope X", "Slope Y", "Slope magnitude"} else "see slope map"),
                    ("Display max", f"{float(np.nanmax(display_values)):.6g}" if style not in {"Slope X", "Slope Y", "Slope magnitude"} else "see slope map"),
                ]
                if slope_rms is not None:
                    result_items.append(("Slope RMS", f"{slope_rms:.6g}"))
                if is_wavefront_function:
                    result_items.append(("Function reference", function_reference))
                if getattr(self, "results_table", None) is not None:
                    self._set_results(result_items)
                display_arr = np.asarray(display_values, dtype=float).ravel()
                if display_arr.shape != phase.shape:
                    display_arr = np.full_like(phase, np.nan, dtype=float)
                self._last_wavefront_samples = [
                    {
                        "sample": sample_index,
                        "x_pupil": float(x_value),
                        "y_pupil": float(y_value),
                        "phase_waves": float(phase_value),
                        "display_value": float(display_value) if np.isfinite(display_value) else "",
                        "style": style,
                        "phase_method": phase_method,
                        "wavelength_um": float(wavelength),
                    }
                    for sample_index, (x_value, y_value, phase_value, display_value) in enumerate(
                        zip(plot_x, plot_y, phase, display_arr)
                    )
                ]
                self.append_debug(
                    f"Wavefront ok: style={style}, samples={phase.size}, phase_rms={phase_rms:.6g}, "
                    f"phase_pv={phase_pv:.6g}, method={phase_method}"
                )
                self._update_analysis_progress("Rendering", 3, 3)
                self._finish_analysis_progress("Wavefront analysis", success=True)
            except Exception as exc:
                self.append_debug(f"Wavefront analysis error: {exc}")
                analysis_ax.clear()
                analysis_ax.text(0.5, 0.5, "Wavefront analysis unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Wavefront analysis", success=False)
            return

        if self.analysis_mode == "zernike":
            try:
                self._last_zernike_coefficients = []
                self._set_analysis_parallel_status("Zernike", 1, False)
                self._begin_analysis_progress("Zernike fit")
                self._update_analysis_progress("Building pupil", 1, 4)
                pupil = Kos.PupilCalc(
                    system,
                    self._analysis_surface_index(),
                    wavelength,
                    self._current_aperture_type(),
                    self._current_aperture_value(),
                )
                pupil.Samp = max(8, min(18, int(np.sqrt(max(1, self._current_ray_count())) * 4)))
                pupil.Ptype = "hexapolar"
                field_type = "angle" if self._current_object_mode() == "Infinity" else "height"
                pupil.FieldType = field_type
                pupil.FieldX = 0.0
                pupil.FieldY = self._current_field_angle_deg() if field_type == "angle" else self._current_field_height()

                self._update_analysis_progress("Computing phase", 2, 4)
                phase_method = "Phase2" if field_type == "height" else "Phase"
                if phase_method == "Phase2":
                    capture = io.StringIO()
                    with redirect_stdout(capture), redirect_stderr(capture):
                        px, py, phase, p2v = Kos.Phase2(pupil)
                    phase2_log = capture.getvalue().strip()
                    if phase2_log:
                        self.append_debug(phase2_log)
                else:
                    try:
                        px, py, phase, p2v = Kos.Phase(pupil)
                    except Exception:
                        capture = io.StringIO()
                        with redirect_stdout(capture), redirect_stderr(capture):
                            px, py, phase, p2v = Kos.Phase2(pupil)
                        phase_method = "Phase2"
                        phase2_log = capture.getvalue().strip()
                        if phase2_log:
                            self.append_debug(phase2_log)
                px = np.asarray(px, dtype=float).ravel()
                py = np.asarray(py, dtype=float).ravel()
                phase = np.asarray(phase, dtype=float).ravel()
                finite = np.isfinite(px) & np.isfinite(py) & np.isfinite(phase)
                px = px[finite]
                py = py[finite]
                phase = phase[finite]
                if px.size < 8:
                    raise RuntimeError("Not enough finite wavefront samples for Zernike fitting")
                if np.unique(np.round(px, 10)).size <= 1 or np.unique(np.round(py, 10)).size <= 1:
                    raise RuntimeError("Degenerate pupil sample for Zernike fitting")

                requested_terms = max(12, min(28, self._current_ray_count() + 8))
                candidate_terms = []
                for term_count in (requested_terms, 28, 21, 15, 10, 6, 4):
                    if 2 <= term_count < px.size and term_count not in candidate_terms:
                        candidate_terms.append(term_count)
                last_error = None
                fit_result = None
                self._update_analysis_progress("Fitting coefficients", 3, 4)
                for term_count in candidate_terms:
                    try:
                        coefficients, labels, rms_chief, rms_centroid, fitting_error = Kos.Zernike_Fitting(
                            px,
                            py,
                            phase,
                            np.ones(term_count, dtype=float),
                        )
                        fit_result = (term_count, coefficients, labels, rms_chief, rms_centroid, fitting_error)
                        break
                    except Exception as exc:
                        last_error = exc
                if fit_result is None:
                    raise RuntimeError(f"Zernike fit failed: {last_error}")

                term_count, coefficients, labels, rms_chief, rms_centroid, fitting_error = fit_result
                coefficients = np.asarray(coefficients, dtype=float).ravel()
                labels = np.asarray(labels, dtype=object).ravel()
                reconstructed = np.asarray(Kos.Wavefront_Zernike_Phase(px, py, coefficients), dtype=float).ravel()
                residual = phase - reconstructed
                phase_centered = phase - float(np.mean(phase))
                phase_rms = float(np.sqrt(np.mean(phase_centered * phase_centered)))
                residual_rms = float(np.sqrt(np.mean(residual * residual)))
                residual_pv = float(np.ptp(residual))
                phase_pv = float(np.ptp(phase))

                coeff_abs = np.abs(coefficients)
                min_visible = max(float(np.max(coeff_abs)) * 1e-4, 1e-12)
                nonzero = np.flatnonzero(coeff_abs > min_visible)
                aberration_nonzero = nonzero[nonzero >= 3]
                chart_note = ""
                if nonzero.size:
                    chart_pool = aberration_nonzero if aberration_nonzero.size else nonzero
                    chart_note = "Chart omits piston/tilt" if aberration_nonzero.size else "Chart includes low-order terms"
                    ranked = np.argsort(coeff_abs[chart_pool])[-10:][::-1]
                    shown_indices = chart_pool[ranked]
                else:
                    chart_note = "No non-zero terms above display threshold"
                    shown_indices = np.arange(min(coefficients.size, 10))
                shown_coefficients = coefficients[shown_indices]
                short_labels = []
                for index in shown_indices:
                    text = str(labels[index]) if index < labels.size else ""
                    descriptor = text.split("   ", 1)[-1].strip() if text else ""
                    if not descriptor:
                        descriptor = f"Z{int(index)}"
                    short_labels.append(f"Z{int(index):02d} {descriptor[:16]}")

                colors = ["#2563eb" if value >= 0.0 else "#dc2626" for value in shown_coefficients]
                y_pos = np.arange(shown_coefficients.size)
                analysis_ax.barh(y_pos, shown_coefficients, color=colors, alpha=0.88)
                analysis_ax.axvline(0.0, color="#111827", linewidth=0.8)
                analysis_ax.set_yticks(y_pos, short_labels)
                analysis_ax.invert_yaxis()
                analysis_ax.set_title(f"Zernike Fit  |  terms={term_count}  |  residual RMS={residual_rms:.4g} waves")
                analysis_ax.set_xlabel("Coefficient [waves]")
                analysis_ax.set_box_aspect(0.78)
                analysis_ax.grid(True, axis="x", alpha=0.2)
                analysis_ax.text(
                    0.98,
                    0.03,
                    f"Phase RMS {phase_rms:.4g} waves\n"
                    f"Phase P-V {phase_pv:.4g} waves\n"
                    f"Residual P-V {residual_pv:.4g} waves\n"
                    f"{chart_note}",
                    transform=analysis_ax.transAxes,
                    ha="right",
                    va="bottom",
                    fontsize=7.5,
                    bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.78, "pad": 3},
                )

                result_items = [
                    ("Mode", "Zernike fit"),
                    ("Terms", str(int(term_count))),
                    ("Samples", str(int(px.size))),
                    ("Phase method", phase_method),
                    ("Phase P-V [waves]", f"{phase_pv:.6g}"),
                    ("Phase RMS [waves]", f"{phase_rms:.6g}"),
                    ("Residual RMS [waves]", f"{residual_rms:.6g}"),
                    ("Residual P-V [waves]", f"{residual_pv:.6g}"),
                    ("RMS to chief [waves]", f"{float(rms_chief):.6g}"),
                    ("RMS to centroid [waves]", f"{float(rms_centroid):.6g}"),
                    ("Fitting error [waves]", f"{float(fitting_error):.6g}"),
                ]
                for index, coefficient in enumerate(coefficients):
                    text = str(labels[index]) if index < labels.size else ""
                    descriptor = text.split("   ", 1)[-1].strip() if text else f"Z{index}"
                    result_items.append((f"Z{index:02d} {descriptor}", f"{float(coefficient):.8g}"))
                if getattr(self, "results_table", None) is not None:
                    self._set_results(result_items)
                self._last_wavefront_fit_report = "\n".join(f"{key}\t{value}" for key, value in result_items)
                zernike_metrics = {
                    "terms": int(term_count),
                    "samples": int(px.size),
                    "phase_method": phase_method,
                    "phase_pv_waves": float(phase_pv),
                    "phase_rms_waves": float(phase_rms),
                    "residual_rms_waves": float(residual_rms),
                    "residual_pv_waves": float(residual_pv),
                    "rms_chief_waves": float(rms_chief),
                    "rms_centroid_waves": float(rms_centroid),
                    "fitting_error_waves": float(fitting_error),
                    "wavelength_um": float(wavelength),
                }
                self._last_zernike_coefficients = [
                    {
                        "index": int(index),
                        "label": str(labels[index]) if index < labels.size else f"Z{index}",
                        "coefficient_waves": float(coefficient),
                        **zernike_metrics,
                    }
                    for index, coefficient in enumerate(coefficients)
                ]
                self._last_wavefront_samples = [
                    {
                        "sample": int(sample_index),
                        "x_pupil": float(x_value),
                        "y_pupil": float(y_value),
                        "phase_waves": float(phase_value),
                        "reconstructed_waves": float(recon_value),
                        "residual_waves": float(residual_value),
                        "style": "Zernike fit",
                        "phase_method": phase_method,
                        "wavelength_um": float(wavelength),
                    }
                    for sample_index, (x_value, y_value, phase_value, recon_value, residual_value) in enumerate(
                        zip(px, py, phase, reconstructed, residual)
                    )
                ]
                self.append_debug(
                    f"Zernike fit ok: samples={px.size}, terms={term_count}, phase_rms={phase_rms:.6g}, "
                    f"residual_rms={residual_rms:.6g}, method={phase_method}"
                )
                self._update_analysis_progress("Rendering", 4, 4)
                self._finish_analysis_progress("Zernike fit", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("Zernike", 1, False)
                self.append_debug(f"Zernike fit error: {exc}")
                analysis_ax.clear()
                analysis_ax.text(0.5, 0.5, "Zernike fit unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Zernike fit", success=False)
            return

        if self.analysis_mode == "polarization":
            try:
                self._set_analysis_parallel_status("Polarization", 1, False)
                self._begin_analysis_progress("Polarization analysis")
                summary = self._polarization_summary(rays)
                surface_rows = list(summary.get("surface_rows", []))
                if not surface_rows:
                    raise RuntimeError("No raykeeper polarization data")

                labels = [f"S{int(row['surface'])}" for row in surface_rows]
                tp = np.asarray([np.nan if row["tp"] is None else float(row["tp"]) for row in surface_rows], dtype=float)
                ts = np.asarray([np.nan if row["ts"] is None else float(row["ts"]) for row in surface_rows], dtype=float)
                rp = np.asarray([np.nan if row["rp"] is None else float(row["rp"]) for row in surface_rows], dtype=float)
                rs = np.asarray([np.nan if row["rs"] is None else float(row["rs"]) for row in surface_rows], dtype=float)
                ttbe = np.asarray([np.nan if row["ttbe"] is None else float(row["ttbe"]) for row in surface_rows], dtype=float)
                x = np.arange(len(surface_rows), dtype=float)
                width = 0.34

                analysis_ax.bar(x - width / 2.0, tp, width=width, label="TP", color="#2563eb", alpha=0.82)
                analysis_ax.bar(x + width / 2.0, ts, width=width, label="TS", color="#f97316", alpha=0.82)
                if np.any(np.isfinite(rp)):
                    analysis_ax.plot(x, rp, label="RP", color="#1d4ed8", linestyle=(0, (3, 2)), linewidth=1.0, marker="o", markersize=3)
                if np.any(np.isfinite(rs)):
                    analysis_ax.plot(x, rs, label="RS", color="#c2410c", linestyle=(0, (3, 2)), linewidth=1.0, marker="s", markersize=3)
                if np.any(np.isfinite(ttbe)):
                    analysis_ax.plot(x, ttbe, label="TTBE", color="#111827", linewidth=1.25, marker="D", markersize=3)

                finite_chunks = [arr[np.isfinite(arr)] for arr in (tp, ts, rp, rs, ttbe) if np.any(np.isfinite(arr))]
                finite_values = np.concatenate(finite_chunks) if finite_chunks else np.empty(0, dtype=float)
                y_max = max(1.05, float(np.max(finite_values)) * 1.12) if finite_values.size else 1.05
                analysis_ax.set_ylim(0.0, y_max)
                analysis_ax.set_xticks(x, labels, rotation=30 if len(labels) > 7 else 0, ha="right" if len(labels) > 7 else "center")
                title_tt = self._format_percent_value(summary.get("image_mean_tt") or summary.get("mean_tt"))
                analysis_ax.set_title(f"Coating / Polarization  |  image TT {title_tt}")
                analysis_ax.set_ylabel("Energy fraction")
                analysis_ax.set_xlabel("Surface")
                analysis_ax.set_box_aspect(0.62)
                analysis_ax.grid(True, axis="y", alpha=0.2)
                analysis_ax.legend(loc="upper right", fontsize=7, ncol=2)
                self._finish_analysis_progress("Polarization analysis", success=True)
                self.append_debug(
                    "Polarization analysis ok: rays={rays}, image_rays={image}, mean_tt={tt}".format(
                        rays=int(summary["total_rays"]),
                        image=int(summary["image_rays"]),
                        tt=self._format_percent_value(summary["mean_tt"]),
                    )
                )
            except Exception as exc:
                self._set_analysis_parallel_status("Polarization", 1, False)
                self.append_debug(f"Polarization analysis error: {exc}")
                analysis_ax.text(0.5, 0.5, "Polarization analysis unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Polarization analysis", success=False)
            return

        if self.analysis_mode == "field_curvature":
            try:
                self._set_analysis_parallel_status("Field curvature / distortion", 1, True)
                self._begin_analysis_progress("Field curvature / distortion")
                field_type = "angle" if self._current_object_mode() == "Infinity" else "height"
                field_limit = self._current_field_angle_deg() if field_type == "angle" else self._current_field_height()
                if field_limit <= 1e-9:
                    field_limit = 5.0 if field_type == "angle" else max(self._current_field_height(), 0.5)
                field_sample_count = max(11, self._current_field_count())
                field_samples = list(np.linspace(-field_limit, field_limit, field_sample_count))
                self.append_debug(
                    f"Field curvature/distortion sampling: type={field_type}, limit={field_limit:.4g}, count={field_sample_count}"
                )
                sample_count = max(18, self._current_ray_count() * 3)
                axis_results: dict[str, dict[str, np.ndarray]] = {}
                axis_defs = {
                    "X": {"color_fc": "#1f77b4", "color_dist": "#6baed6", "marker_fc": "o", "marker_dist": "s"},
                    "Y": {"color_fc": "#d62728", "color_dist": "#ff9896", "marker_fc": "^", "marker_dist": "D"},
                }
                total_steps = len(field_samples) * 2
                completed_steps = 0

                for axis_name in ("X", "Y"):
                    measured_fields: list[float] = []
                    image_heights: list[float] = []
                    focus_shifts: list[float] = []
                    worker_counts: list[int] = []
                    for field_value in field_samples:
                        completed_steps += 1
                        self._update_analysis_progress(
                            f"Sampling {axis_name}-field",
                            completed_steps,
                            total_steps,
                        )
                        field_x = field_value if axis_name == "X" else 0.0
                        field_y = field_value if axis_name == "Y" else 0.0
                        x_local, y_local, _z_local, l_local, m_local, n_local, worker_count = self._build_geometric_image_samples_full(
                            system,
                            wavelength,
                            sample_count=sample_count,
                            pattern="hexapolar",
                            surface_index=self._analysis_surface_index(),
                            aperture_type=self._current_aperture_type(),
                            aperture_value=self._current_aperture_value(),
                            field_type=field_type,
                            field_x=field_x,
                            field_y=field_y,
                        )
                        if x_local.size < 4:
                            continue
                        worker_counts.append(worker_count)

                        slopes_x = l_local / np.where(np.abs(n_local) < 1e-9, np.sign(n_local) * 1e-9 + 1e-9, n_local)
                        slopes_y = m_local / np.where(np.abs(n_local) < 1e-9, np.sign(n_local) * 1e-9 + 1e-9, n_local)

                        if axis_name == "X":
                            image_height = float(np.mean(x_local))
                            denom = float(np.sum(slopes_x**2))
                            focus_shift = 0.0 if denom <= 1e-12 else -float(np.sum(x_local * slopes_x) / denom)
                        else:
                            image_height = float(np.mean(y_local))
                            denom = float(np.sum(slopes_y**2))
                            focus_shift = 0.0 if denom <= 1e-12 else -float(np.sum(y_local * slopes_y) / denom)

                        measured_fields.append(field_value)
                        image_heights.append(image_height)
                        focus_shifts.append(focus_shift)

                    if len(measured_fields) < 2:
                        continue

                    fields = np.asarray(measured_fields, dtype=float)
                    heights = np.asarray(image_heights, dtype=float)
                    focus = np.asarray(focus_shifts, dtype=float)
                    abs_fields = np.abs(fields)
                    abs_heights = np.abs(heights)
                    mask = abs_fields > 1e-9
                    if np.count_nonzero(mask) >= 2:
                        slope = float(np.dot(abs_fields[mask], abs_heights[mask]) / max(np.dot(abs_fields[mask], abs_fields[mask]), 1e-12))
                        ideal = slope * abs_fields
                        distortion = np.zeros_like(abs_heights)
                        valid = ideal > 1e-12
                        distortion[valid] = (abs_heights[valid] - ideal[valid]) / ideal[valid] * 100.0
                    else:
                        distortion = np.zeros_like(abs_heights)

                    axis_results[axis_name] = {
                        "fields": abs_fields,
                        "focus": focus,
                        "distortion": distortion,
                        "workers": np.asarray([max(worker_counts) if worker_counts else 1], dtype=float),
                    }

                if not axis_results:
                    raise RuntimeError("Not enough field samples for field-curvature/distortion")

                ax2 = analysis_ax.twinx()
                legend_lines = []
                legend_labels = []
                for axis_name, data in axis_results.items():
                    style = axis_defs[axis_name]
                    line_fc, = analysis_ax.plot(
                        data["fields"],
                        data["focus"],
                        color=style["color_fc"],
                        marker=style["marker_fc"],
                        linewidth=0.0,
                        markersize=4.5,
                        label=f"{axis_name} focus",
                    )
                    line_dist, = ax2.plot(
                        data["fields"],
                        data["distortion"],
                        color=style["color_dist"],
                        marker=style["marker_dist"],
                        linewidth=0.0,
                        markersize=4.0,
                        label=f"{axis_name} distortion",
                    )
                    if len(data["fields"]) >= 4:
                        smooth_fields = np.linspace(float(np.min(data["fields"])), float(np.max(data["fields"])), 200)
                        focus_degree = min(3, len(data["fields"]) - 1)
                        dist_degree = min(3, len(data["distortion"]) - 1)
                        try:
                            focus_poly = np.poly1d(np.polyfit(data["fields"], data["focus"], deg=focus_degree))
                            dist_poly = np.poly1d(np.polyfit(data["fields"], data["distortion"], deg=dist_degree))
                            analysis_ax.plot(
                                smooth_fields,
                                focus_poly(smooth_fields),
                                color=style["color_fc"],
                                linewidth=2.0,
                                alpha=0.9,
                            )
                            ax2.plot(
                                smooth_fields,
                                dist_poly(smooth_fields),
                                color=style["color_dist"],
                                linewidth=1.8,
                                linestyle="--",
                                alpha=0.9,
                            )
                        except Exception:
                            analysis_ax.plot(
                                data["fields"],
                                data["focus"],
                                color=style["color_fc"],
                                linewidth=2.0,
                                alpha=0.9,
                            )
                            ax2.plot(
                                data["fields"],
                                data["distortion"],
                                color=style["color_dist"],
                                linewidth=1.8,
                                linestyle="--",
                                alpha=0.9,
                            )
                    else:
                        analysis_ax.plot(
                            data["fields"],
                            data["focus"],
                            color=style["color_fc"],
                            linewidth=2.0,
                            alpha=0.9,
                        )
                        ax2.plot(
                            data["fields"],
                            data["distortion"],
                            color=style["color_dist"],
                            linewidth=1.8,
                            linestyle="--",
                            alpha=0.9,
                        )
                    legend_lines.extend([line_fc, line_dist])
                    legend_labels.extend([f"{axis_name} focus", f"{axis_name} distortion"])

                analysis_ax.set_title(f"Field Curvature / Distortion  |  {field_type}")
                analysis_ax.set_xlabel("Field")
                analysis_ax.set_ylabel("Best-focus shift [mm]", color="#2c3e50")
                ax2.set_ylabel("Distortion [%]", color="#2c3e50")
                analysis_ax.set_box_aspect(0.48)
                analysis_ax.grid(True, alpha=0.2)
                analysis_ax.legend(legend_lines, legend_labels, loc="best", fontsize=8)
                self.append_debug(
                    "Field curvature/distortion ok: "
                    + ", ".join(
                        f"{axis}={len(data['fields'])},workers={int(data['workers'][0])}"
                        for axis, data in axis_results.items()
                    )
                )
                self._set_analysis_parallel_status(
                    "Field curvature / distortion",
                    max(int(data["workers"][0]) for data in axis_results.values()),
                    True,
                )
                self._finish_analysis_progress("Field curvature / distortion", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("Field curvature / distortion", 1, True)
                self.append_debug(f"Field curvature/distortion error: {exc}")
                analysis_ax.text(0.5, 0.5, "Field curvature/distortion unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Field curvature / distortion", success=False)
            return

        if self.analysis_mode == "field_map":
            try:
                self._set_analysis_parallel_status("Field map", 1, True)
                self._begin_analysis_progress("Field map")
                if self._current_source_model() != SOURCE_MODEL_DEFAULT:
                    analysis_ax.text(
                        0.5,
                        0.5,
                        "FieldMap uses Pupil / field sampling.\nSwitch Source model to Pupil / field.",
                        ha="center",
                        va="center",
                    )
                    analysis_ax.set_axis_off()
                    self._finish_analysis_progress("Field map", success=False)
                    return
                field_samples = self._resolved_field_grid_samples()
                if not field_samples:
                    raise RuntimeError("No valid field-map samples")
                sample_count = max(8, self._current_ray_count() * 2)
                total_steps = len(field_samples)
                rms_values: list[float] = []
                display_x: list[float] = []
                display_y: list[float] = []
                worker_max = 1
                for index, sample in enumerate(field_samples, start=1):
                    self._update_analysis_progress(f"Field map {index}/{total_steps}", index, total_steps)
                    x_local, y_local, _z_local, _l_local, _m_local, _n_local, worker_count = self._build_geometric_image_samples_full(
                        system,
                        wavelength,
                        sample_count=sample_count,
                        pattern="hexapolar",
                        surface_index=self._analysis_surface_index(),
                        aperture_type=self._current_aperture_type(),
                        aperture_value=self._current_aperture_value(),
                        field_type=str(sample["field_type"]),
                        field_x=float(sample["field_x"]),
                        field_y=float(sample["field_y"]),
                    )
                    worker_max = max(worker_max, int(worker_count))
                    x_centered, y_centered = self._center_image_plane_samples(x_local, y_local)
                    if x_centered.size < 2:
                        rms = np.nan
                    else:
                        rms = float(np.sqrt(np.mean((x_centered * x_centered) + (y_centered * y_centered))))
                    rms_values.append(rms)
                    display_x.append(float(sample["display_x"]))
                    display_y.append(float(sample["display_y"]))
                x_unique = np.asarray(sorted(set(round(value, 12) for value in display_x)), dtype=float)
                y_unique = np.asarray(sorted(set(round(value, 12) for value in display_y)), dtype=float)
                if x_unique.size == 0 or y_unique.size == 0:
                    raise RuntimeError("No valid field-map grid")
                grid = np.full((y_unique.size, x_unique.size), np.nan, dtype=float)
                x_lookup = {float(value): i for i, value in enumerate(x_unique)}
                y_lookup = {float(value): i for i, value in enumerate(y_unique)}
                for x_value, y_value, rms in zip(display_x, display_y, rms_values):
                    grid[y_lookup[round(float(y_value), 12)], x_lookup[round(float(x_value), 12)]] = rms
                if not np.any(np.isfinite(grid)):
                    raise RuntimeError("No finite field-map RMS values")
                if x_unique.size == 1:
                    x_extent = [float(x_unique[0]) - 0.5, float(x_unique[0]) + 0.5]
                else:
                    x_step = float(np.median(np.diff(x_unique)))
                    x_extent = [float(x_unique[0] - 0.5 * x_step), float(x_unique[-1] + 0.5 * x_step)]
                if y_unique.size == 1:
                    y_extent = [float(y_unique[0]) - 0.5, float(y_unique[0]) + 0.5]
                else:
                    y_step = float(np.median(np.diff(y_unique)))
                    y_extent = [float(y_unique[0] - 0.5 * y_step), float(y_unique[-1] + 0.5 * y_step)]
                cmap = colormaps.get_cmap("magma").copy()
                cmap.set_bad("#f3f4f6")
                im = analysis_ax.imshow(
                    grid,
                    origin="lower",
                    extent=[x_extent[0], x_extent[1], y_extent[0], y_extent[1]],
                    aspect="auto",
                    interpolation="nearest",
                    cmap=cmap,
                )
                analysis_ax.set_title("Wide-Field Spot RMS Map")
                unit = str(field_samples[0]["unit"])
                basis = str(field_samples[0]["basis"])
                label = f"{basis} [{unit}]" if unit else basis
                analysis_ax.set_xlabel(f"Field X: {label}")
                analysis_ax.set_ylabel(f"Field Y: {label}")
                cbar = analysis_ax.figure.colorbar(im, ax=analysis_ax, fraction=0.046, pad=0.04)
                cbar.set_label("Spot RMS [mm]")
                if grid.size <= 49:
                    for y_index, y_value in enumerate(y_unique):
                        for x_index, x_value in enumerate(x_unique):
                            value = grid[y_index, x_index]
                            if np.isfinite(value):
                                analysis_ax.text(
                                    float(x_value),
                                    float(y_value),
                                    f"{value:.3g}",
                                    ha="center",
                                    va="center",
                                    color="white",
                                    fontsize=7,
                                )
                analysis_ax.set_box_aspect(0.85)
                self.append_debug(
                    f"FieldMap ok: samples={len(field_samples)}, finite={int(np.isfinite(grid).sum())}, "
                    f"min={float(np.nanmin(grid)):.6g}, max={float(np.nanmax(grid)):.6g}, workers={worker_max}"
                )
                self._set_analysis_parallel_status("Field map", worker_max, True)
                self._finish_analysis_progress("Field map", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("Field map", 1, True)
                self.append_debug(f"FieldMap error: {exc}")
                analysis_ax.text(0.5, 0.5, "Field map unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Field map", success=False)
            return

        if self.analysis_mode == "illum_map":
            try:
                self._set_analysis_parallel_status("Illumination map", 1, True)
                self._begin_analysis_progress("Illumination map")
                if self._current_source_model() != SOURCE_MODEL_DEFAULT:
                    analysis_ax.text(
                        0.5,
                        0.5,
                        "IllumMap uses Pupil / field sampling.\nUse Illum for random-source throughput.",
                        ha="center",
                        va="center",
                    )
                    analysis_ax.set_axis_off()
                    self._finish_analysis_progress("Illumination map", success=False)
                    return
                field_samples = self._resolved_field_grid_samples()
                if not field_samples:
                    raise RuntimeError("No valid illumination-map samples")
                sample_count = max(8, self._current_ray_count() * 2)
                total_steps = len(field_samples)
                transmission_values: list[float] = []
                display_x: list[float] = []
                display_y: list[float] = []
                worker_max = 1
                for index, sample in enumerate(field_samples, start=1):
                    self._update_analysis_progress(f"Illum map {index}/{total_steps}", index, total_steps)
                    pupil = Kos.PupilCalc(
                        system,
                        self._analysis_surface_index(),
                        wavelength,
                        self._current_aperture_type(),
                        self._current_aperture_value(),
                    )
                    pupil.Samp = sample_count
                    pupil.Ptype = self._current_analysis_pupil_pattern()
                    pupil.FieldType = str(sample["field_type"])
                    pupil.FieldX = float(sample["field_x"])
                    pupil.FieldY = float(sample["field_y"])
                    bundle = self._pupil_pattern_bundle(pupil)
                    input_count = int(np.asarray(bundle[0]).size)
                    if input_count <= 0:
                        transmission = np.nan
                    else:
                        x_local, _y_local, worker_count = self._trace_pattern_chunks_parallel(wavelength, [bundle])
                        worker_max = max(worker_max, int(worker_count))
                        transmission = float(np.asarray(x_local).size) / float(input_count)
                    transmission_values.append(transmission)
                    display_x.append(float(sample["display_x"]))
                    display_y.append(float(sample["display_y"]))
                x_unique = np.asarray(sorted(set(round(value, 12) for value in display_x)), dtype=float)
                y_unique = np.asarray(sorted(set(round(value, 12) for value in display_y)), dtype=float)
                if x_unique.size == 0 or y_unique.size == 0:
                    raise RuntimeError("No valid illumination-map grid")
                grid = np.full((y_unique.size, x_unique.size), np.nan, dtype=float)
                x_lookup = {float(value): i for i, value in enumerate(x_unique)}
                y_lookup = {float(value): i for i, value in enumerate(y_unique)}
                for x_value, y_value, transmission in zip(display_x, display_y, transmission_values):
                    grid[y_lookup[round(float(y_value), 12)], x_lookup[round(float(x_value), 12)]] = transmission
                finite = grid[np.isfinite(grid)]
                if finite.size == 0:
                    raise RuntimeError("No finite illumination-map values")
                center_index = int(np.nanargmin(np.asarray(display_x) ** 2 + np.asarray(display_y) ** 2))
                reference = transmission_values[center_index] if center_index < len(transmission_values) else np.nan
                if not np.isfinite(reference) or float(reference) <= 1e-12:
                    reference = float(np.nanmax(grid))
                if not np.isfinite(reference) or float(reference) <= 1e-12:
                    raise RuntimeError("No valid illumination reference")
                grid = grid / float(reference)
                if x_unique.size == 1:
                    x_extent = [float(x_unique[0]) - 0.5, float(x_unique[0]) + 0.5]
                else:
                    x_step = float(np.median(np.diff(x_unique)))
                    x_extent = [float(x_unique[0] - 0.5 * x_step), float(x_unique[-1] + 0.5 * x_step)]
                if y_unique.size == 1:
                    y_extent = [float(y_unique[0]) - 0.5, float(y_unique[0]) + 0.5]
                else:
                    y_step = float(np.median(np.diff(y_unique)))
                    y_extent = [float(y_unique[0] - 0.5 * y_step), float(y_unique[-1] + 0.5 * y_step)]
                cmap = colormaps.get_cmap("viridis").copy()
                cmap.set_bad("#f3f4f6")
                im = analysis_ax.imshow(
                    grid,
                    origin="lower",
                    extent=[x_extent[0], x_extent[1], y_extent[0], y_extent[1]],
                    aspect="auto",
                    interpolation="nearest",
                    cmap=cmap,
                    vmin=0.0,
                    vmax=max(1.0, float(np.nanmax(grid))),
                )
                analysis_ax.set_title("Wide-Field Relative Illumination Map")
                unit = str(field_samples[0]["unit"])
                basis = str(field_samples[0]["basis"])
                label = f"{basis} [{unit}]" if unit else basis
                analysis_ax.set_xlabel(f"Field X: {label}")
                analysis_ax.set_ylabel(f"Field Y: {label}")
                cbar = analysis_ax.figure.colorbar(im, ax=analysis_ax, fraction=0.046, pad=0.04)
                cbar.set_label("Relative illumination")
                if grid.size <= 49:
                    for y_index, y_value in enumerate(y_unique):
                        for x_index, x_value in enumerate(x_unique):
                            value = grid[y_index, x_index]
                            if np.isfinite(value):
                                analysis_ax.text(
                                    float(x_value),
                                    float(y_value),
                                    f"{value:.3g}",
                                    ha="center",
                                    va="center",
                                    color="white",
                                    fontsize=7,
                                )
                analysis_ax.set_box_aspect(0.85)
                self.append_debug(
                    f"IllumMap ok: samples={len(field_samples)}, finite={int(np.isfinite(grid).sum())}, "
                    f"min={float(np.nanmin(grid)):.6g}, max={float(np.nanmax(grid)):.6g}, workers={worker_max}"
                )
                self._set_analysis_parallel_status("Illumination map", worker_max, True)
                self._finish_analysis_progress("Illumination map", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("Illumination map", 1, True)
                self.append_debug(f"IllumMap error: {exc}")
                analysis_ax.text(0.5, 0.5, "Illumination map unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Illumination map", success=False)
            return

        if self.analysis_mode == "wavefront_map":
            try:
                self._set_analysis_parallel_status("Wavefront map", 1, True)
                self._begin_analysis_progress("Wavefront map")
                if self._current_source_model() != SOURCE_MODEL_DEFAULT:
                    analysis_ax.text(
                        0.5,
                        0.5,
                        "WfeMap uses Pupil / field sampling.\nSwitch Source model to Pupil / field.",
                        ha="center",
                        va="center",
                    )
                    analysis_ax.set_axis_off()
                    self._finish_analysis_progress("Wavefront map", success=False)
                    return
                field_samples = self._resolved_field_grid_samples()
                if not field_samples:
                    raise RuntimeError("No valid wavefront-map samples")
                total_steps = len(field_samples)
                wfe_values: list[float] = []
                display_x: list[float] = []
                display_y: list[float] = []

                def _phase_arrays_for_sample(sample: dict[str, float | str]):
                    pupil = Kos.PupilCalc(
                        system,
                        self._analysis_surface_index(),
                        wavelength,
                        self._current_aperture_type(),
                        self._current_aperture_value(),
                    )
                    pupil.Samp = max(5, min(11, self._current_ray_count()))
                    pupil.Ptype = "hexapolar"
                    pupil.FieldType = str(sample["field_type"])
                    pupil.FieldX = float(sample["field_x"])
                    pupil.FieldY = float(sample["field_y"])
                    phase_method = "Phase2" if str(sample["field_type"]).strip().lower() == "height" else "Phase"
                    if phase_method == "Phase2":
                        capture = io.StringIO()
                        with redirect_stdout(capture), redirect_stderr(capture):
                            px, py, phase, _p2v = Kos.Phase2(pupil)
                        phase2_log = capture.getvalue().strip()
                        if phase2_log:
                            self.append_debug(phase2_log)
                    else:
                        try:
                            px, py, phase, _p2v = Kos.Phase(pupil)
                        except Exception:
                            capture = io.StringIO()
                            with redirect_stdout(capture), redirect_stderr(capture):
                                px, py, phase, _p2v = Kos.Phase2(pupil)
                            phase2_log = capture.getvalue().strip()
                            if phase2_log:
                                self.append_debug(phase2_log)
                    phase = np.asarray(phase, dtype=float).ravel()
                    return phase[np.isfinite(phase)]

                for index, sample in enumerate(field_samples, start=1):
                    self._update_analysis_progress(f"Wavefront map {index}/{total_steps}", index, total_steps)
                    try:
                        phase = _phase_arrays_for_sample(sample)
                        if phase.size < 3:
                            rms = np.nan
                        else:
                            centered = phase - float(np.mean(phase))
                            rms = float(np.sqrt(np.mean(centered * centered)))
                    except Exception as exc:
                        self.append_debug(f"WfeMap sample failed at ({sample['display_x']}, {sample['display_y']}): {exc}")
                        rms = np.nan
                    wfe_values.append(rms)
                    display_x.append(float(sample["display_x"]))
                    display_y.append(float(sample["display_y"]))
                x_unique = np.asarray(sorted(set(round(value, 12) for value in display_x)), dtype=float)
                y_unique = np.asarray(sorted(set(round(value, 12) for value in display_y)), dtype=float)
                if x_unique.size == 0 or y_unique.size == 0:
                    raise RuntimeError("No valid wavefront-map grid")
                grid = np.full((y_unique.size, x_unique.size), np.nan, dtype=float)
                x_lookup = {float(value): i for i, value in enumerate(x_unique)}
                y_lookup = {float(value): i for i, value in enumerate(y_unique)}
                for x_value, y_value, rms in zip(display_x, display_y, wfe_values):
                    grid[y_lookup[round(float(y_value), 12)], x_lookup[round(float(x_value), 12)]] = rms
                finite = grid[np.isfinite(grid)]
                if finite.size == 0:
                    raise RuntimeError("No finite wavefront-map values")
                if x_unique.size == 1:
                    x_extent = [float(x_unique[0]) - 0.5, float(x_unique[0]) + 0.5]
                else:
                    x_step = float(np.median(np.diff(x_unique)))
                    x_extent = [float(x_unique[0] - 0.5 * x_step), float(x_unique[-1] + 0.5 * x_step)]
                if y_unique.size == 1:
                    y_extent = [float(y_unique[0]) - 0.5, float(y_unique[0]) + 0.5]
                else:
                    y_step = float(np.median(np.diff(y_unique)))
                    y_extent = [float(y_unique[0] - 0.5 * y_step), float(y_unique[-1] + 0.5 * y_step)]
                cmap = colormaps.get_cmap("cividis").copy()
                cmap.set_bad("#f3f4f6")
                im = analysis_ax.imshow(
                    grid,
                    origin="lower",
                    extent=[x_extent[0], x_extent[1], y_extent[0], y_extent[1]],
                    aspect="auto",
                    interpolation="nearest",
                    cmap=cmap,
                )
                analysis_ax.set_title("Wide-Field Wavefront RMS Map")
                unit = str(field_samples[0]["unit"])
                basis = str(field_samples[0]["basis"])
                label = f"{basis} [{unit}]" if unit else basis
                analysis_ax.set_xlabel(f"Field X: {label}")
                analysis_ax.set_ylabel(f"Field Y: {label}")
                cbar = analysis_ax.figure.colorbar(im, ax=analysis_ax, fraction=0.046, pad=0.04)
                cbar.set_label("Wavefront RMS [waves]")
                if grid.size <= 49:
                    for y_index, y_value in enumerate(y_unique):
                        for x_index, x_value in enumerate(x_unique):
                            value = grid[y_index, x_index]
                            if np.isfinite(value):
                                analysis_ax.text(
                                    float(x_value),
                                    float(y_value),
                                    f"{value:.3g}",
                                    ha="center",
                                    va="center",
                                    color="white",
                                    fontsize=7,
                                )
                analysis_ax.set_box_aspect(0.85)
                self.append_debug(
                    f"WfeMap ok: samples={len(field_samples)}, finite={int(np.isfinite(grid).sum())}, "
                    f"min={float(np.nanmin(grid)):.6g}, max={float(np.nanmax(grid)):.6g}"
                )
                self._set_analysis_parallel_status("Wavefront map", 1, True)
                self._finish_analysis_progress("Wavefront map", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("Wavefront map", 1, True)
                self.append_debug(f"WfeMap error: {exc}")
                analysis_ax.text(0.5, 0.5, "Wavefront map unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Wavefront map", success=False)
            return

        if self.analysis_mode == "relative_illumination":
            try:
                self._set_analysis_parallel_status("Relative illumination", 1, True)
                self._begin_analysis_progress("Relative illumination")
                if self._current_source_model() != SOURCE_MODEL_DEFAULT:
                    sample_count = max(24, self._current_ray_count() * 4)
                    wavelength_ri = 0.46
                    self._update_analysis_progress("Tracing random source", 1, 2)
                    bundle = self._build_random_source_bundle(sample_count)
                    if bundle is None:
                        raise RuntimeError("Random source bundle unavailable")
                    input_count = int(np.asarray(bundle[0]).size)
                    if input_count <= 0:
                        raise RuntimeError("No random source rays")
                    x_local, _y_local, worker_count = self._trace_pattern_chunks_parallel(wavelength_ri, [bundle])
                    output_count = int(np.asarray(x_local).size)
                    transmission = float(output_count) / float(input_count)
                    stats = self._source_statistics(input_count)
                    source_power = float(stats.get("power", 0.0))
                    collected_power = source_power * transmission
                    analysis_ax.bar(
                        ["Image plane"],
                        [transmission],
                        color="#111827",
                        width=0.5,
                    )
                    analysis_ax.set_title("Random Source Illumination")
                    analysis_ax.set_ylabel("Transmission")
                    analysis_ax.set_ylim(0.0, max(1.05, transmission * 1.1))
                    analysis_ax.grid(True, axis="y", alpha=0.2)
                    analysis_ax.text(
                        0.03,
                        0.94,
                        (
                            f"Input rays: {input_count}\n"
                            f"Image rays: {output_count}\n"
                            f"Source power: {source_power:.6g}\n"
                            f"Collected power: {collected_power:.6g}\n"
                            f"Power/ray: {float(stats.get('power_per_ray', 0.0)):.6g}"
                        ),
                        transform=analysis_ax.transAxes,
                        va="top",
                        ha="left",
                        fontsize=8,
                        bbox={
                            "boxstyle": "round,pad=0.35",
                            "facecolor": "white",
                            "edgecolor": "#d1d5db",
                            "alpha": 0.92,
                        },
                    )
                    self._update_analysis_progress("Random source illumination complete", 2, 2)
                    self.append_debug(
                        "Random source illumination ok: "
                        f"input={input_count}, image={output_count}, transmission={transmission:.6g}, "
                        f"source_power={source_power:.6g}, collected_power={collected_power:.6g}, workers={int(worker_count)}"
                    )
                    self._set_analysis_parallel_status("Relative illumination", int(worker_count), True)
                    self._finish_analysis_progress("Relative illumination", success=True)
                    return
                field_samples = self._resolved_positive_field_samples()
                if not field_samples:
                    raise RuntimeError("No valid field samples")
                sample_count = max(24, self._current_ray_count() * 4)
                wavelength_ri = 0.46
                illum_x: list[float] = []
                illum_y: list[float] = []
                worker_max = 1
                total_steps = len(field_samples)
                reference = None
                for index, sample in enumerate(field_samples, start=1):
                    self._update_analysis_progress(
                        f"Illumination field {index}/{len(field_samples)}",
                        index,
                        total_steps,
                    )
                    pupil = Kos.PupilCalc(
                        system,
                        self._analysis_surface_index(),
                        wavelength_ri,
                        self._current_aperture_type(),
                        self._current_aperture_value(),
                    )
                    pupil.Samp = sample_count
                    pupil.Ptype = self._current_analysis_pupil_pattern()
                    pupil.FieldType = str(sample["field_type"])
                    pupil.FieldX = float(sample["field_x"])
                    pupil.FieldY = float(sample["field_y"])
                    bundle = self._pupil_pattern_bundle(pupil)
                    input_count = int(np.asarray(bundle[0]).size)
                    if input_count <= 0:
                        continue
                    x_local, y_local, worker_count = self._trace_pattern_chunks_parallel(wavelength_ri, [bundle])
                    worker_max = max(worker_max, int(worker_count))
                    transmission = float(x_local.size) / float(input_count)
                    if reference is None:
                        reference = max(transmission, 1e-12)
                    rel = transmission / max(reference, 1e-12)
                    illum_x.append(float(sample["display_y"]))
                    illum_y.append(float(rel))
                if not illum_x:
                    raise RuntimeError("No relative illumination samples")
                analysis_ax.plot(illum_x, illum_y, color="#111827", linewidth=1.8, marker="o", markersize=4.0)
                if len(illum_x) >= 4:
                    smooth_x = np.linspace(float(min(illum_x)), float(max(illum_x)), 200)
                    deg = min(3, len(illum_x) - 1)
                    try:
                        poly = np.poly1d(np.polyfit(illum_x, illum_y, deg=deg))
                        analysis_ax.plot(smooth_x, np.clip(poly(smooth_x), 0.0, 1.05), color="#374151", linewidth=1.2, alpha=0.85)
                    except Exception:
                        pass
                basis = str(field_samples[0]["basis"])
                unit = str(field_samples[0]["unit"])
                analysis_ax.set_title("Relative Illumination")
                analysis_ax.set_xlabel(f"{basis} [{unit}]".strip())
                analysis_ax.set_ylabel("Relative illumination")
                analysis_ax.set_ylim(0.0, 1.05)
                analysis_ax.set_box_aspect(0.48)
                analysis_ax.grid(True, alpha=0.2)
                self.append_debug(
                    f"Relative illumination ok: samples={len(illum_x)}, wavelength={wavelength_ri:.3f} um, workers={worker_max}"
                )
                self._set_analysis_parallel_status("Relative illumination", worker_max, True)
                self._finish_analysis_progress("Relative illumination", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("Relative illumination", 1, True)
                self.append_debug(f"Relative illumination error: {exc}")
                analysis_ax.text(0.5, 0.5, "Relative illumination unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Relative illumination", success=False)
            return

        if self.analysis_mode == "lateral_color":
            try:
                self._set_analysis_parallel_status("Lateral color", 1, True)
                self._begin_analysis_progress("Lateral color")
                field_samples = self._resolved_positive_field_samples()
                if not field_samples:
                    raise RuntimeError("No valid field samples")
                wavelengths = [0.64, 0.546, 0.46]
                reference_wavelength = 0.546
                sample_count = max(20, self._current_ray_count() * 3)
                color_map = {0.64: "#d62728", 0.546: "#2ca02c", 0.46: "#1f77b4"}
                series: dict[float, tuple[list[float], list[float]]] = {wl: ([], []) for wl in wavelengths}
                worker_max = 1
                total_steps = len(field_samples) * len(wavelengths)
                done = 0
                for sample in field_samples:
                    centroids: dict[float, tuple[float, float]] = {}
                    for wl in wavelengths:
                        done += 1
                        self._update_analysis_progress(
                            f"Lateral color {done}/{total_steps}",
                            done,
                            total_steps,
                        )
                        x_local, y_local, _z, _l, _m, _n, worker_count = self._build_geometric_image_samples_full(
                            system,
                            wl,
                            sample_count=sample_count,
                            pattern="hexapolar",
                            surface_index=self._analysis_surface_index(),
                            aperture_type=self._current_aperture_type(),
                            aperture_value=self._current_aperture_value(),
                            field_type=str(sample["field_type"]),
                            field_x=float(sample["field_x"]),
                            field_y=float(sample["field_y"]),
                        )
                        worker_max = max(worker_max, int(worker_count))
                        if x_local.size < 3:
                            continue
                        centroids[wl] = (float(np.mean(x_local)), float(np.mean(y_local)))
                    if reference_wavelength not in centroids:
                        continue
                    ref_x, ref_y = centroids[reference_wavelength]
                    field_value = float(sample["display_y"])
                    for wl in wavelengths:
                        if wl not in centroids:
                            continue
                        cx, cy = centroids[wl]
                        delta_um = 1000.0 * float(np.hypot(cx - ref_x, cy - ref_y))
                        series[wl][0].append(field_value)
                        series[wl][1].append(delta_um)
                plotted = 0
                for wl in wavelengths:
                    x_vals, y_vals = series[wl]
                    if not x_vals:
                        continue
                    plotted += 1
                    analysis_ax.plot(
                        x_vals,
                        y_vals,
                        color=color_map[wl],
                        linewidth=1.5,
                        marker="o",
                        markersize=3.8,
                        label=f"{wl:.3f} um",
                    )
                if plotted == 0:
                    raise RuntimeError("No lateral color samples")
                basis = str(field_samples[0]["basis"])
                unit = str(field_samples[0]["unit"])
                analysis_ax.set_title("Lateral Color")
                analysis_ax.set_xlabel(f"{basis} [{unit}]".strip())
                analysis_ax.set_ylabel("Lateral color vs 0.546 um [um]")
                analysis_ax.set_box_aspect(0.48)
                analysis_ax.grid(True, alpha=0.2)
                analysis_ax.legend(loc="best", fontsize=8)
                self.append_debug(
                    f"Lateral color ok: fields={len(field_samples)}, wavelengths={len(wavelengths)}, workers={worker_max}"
                )
                self._set_analysis_parallel_status("Lateral color", worker_max, True)
                self._finish_analysis_progress("Lateral color", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("Lateral color", 1, True)
                self.append_debug(f"Lateral color error: {exc}")
                analysis_ax.text(0.5, 0.5, "Lateral color unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("Lateral color", success=False)
            return

        if self.analysis_mode == "mtf":
            try:
                self._set_analysis_parallel_status("MTF", 1, True)
                self._begin_analysis_progress("MTF analysis")
                mtf_settings = self._mtf_analysis_settings()
                wavelength = float(mtf_settings["wavelength"])
                mtf_mode = self._operand_mtf_mode("MTF @ freq")
                mtf_algorithm = str(mtf_settings.get("algorithm", "psf_fft"))
                target_freq = self._current_mtf_frequency()
                field_samples = self._resolved_mtf_field_samples("MTF @ freq")
                if not field_samples:
                    raise RuntimeError("No valid MTF field samples")

                sample_results: list[dict[str, object]] = []
                max_workers = 1
                accelerators: set[str] = set()
                geometric_pending: list[tuple[dict[str, float | str], str]] = []
                total_steps = max(2, len(field_samples) + 1)
                for index, sample in enumerate(field_samples, start=1):
                    legend = str(sample["legend"])
                    self._update_analysis_progress(
                        f"MTF field {index}/{len(field_samples)}: {legend}",
                        index,
                        total_steps,
                    )
                    try:
                        result = self._compute_diffraction_mtf_sample(
                            system,
                            wavelength=wavelength,
                            surface_index=int(mtf_settings["surface_index"]),
                            aperture_type=str(mtf_settings["aperture_type"]),
                            aperture_value=float(mtf_settings["aperture_value"]),
                            field_type=str(sample["field_type"]),
                            field_x=float(sample["field_x"]),
                            field_y=float(sample["field_y"]),
                        )
                        self.append_debug(
                            f"MTF sample {legend}: diffraction ok: method={result.get('phase_method', 'Phase')}, terms={result['used_terms']}, samples={result['sample_count']}"
                        )
                    except Exception as diff_exc:
                        self.append_debug(f"MTF sample {legend}: diffraction failed: {diff_exc}")
                        geometric_pending.append((sample, legend))
                        continue

                    plot_freq = np.asarray(result["plot_freq"], dtype=float)
                    plot_tan = np.asarray(result["plot_tan"], dtype=float)
                    plot_sag = np.asarray(result["plot_sag"], dtype=float)
                    if plot_freq.size == 0 or plot_tan.size == 0 or plot_sag.size == 0:
                        continue

                    tan_value = float(np.interp(target_freq, plot_freq, plot_tan, left=plot_tan[0], right=plot_tan[-1]))
                    sag_value = float(np.interp(target_freq, plot_freq, plot_sag, left=plot_sag[0], right=plot_sag[-1]))
                    if mtf_mode == "tangential":
                        selected_value = tan_value
                        selected_label = "Tangential"
                    elif mtf_mode == "sagittal":
                        selected_value = sag_value
                        selected_label = "Sagittal"
                    else:
                        selected_value = 0.5 * (tan_value + sag_value)
                        selected_label = "Average"

                    result.update(
                        {
                            "legend": legend,
                            "basis": str(sample["basis"]),
                            "unit": str(sample["unit"]),
                            "display_x": float(sample["display_x"]),
                            "display_y": float(sample["display_y"]),
                            "tan_value": tan_value,
                            "sag_value": sag_value,
                            "selected_value": float(selected_value),
                            "selected_label": selected_label,
                        }
                    )
                    sample_results.append(result)
                    max_workers = max(max_workers, int(result.get("worker_count", 1)))
                    accelerators.add(str(result.get("accelerator", "CPU")))

                if geometric_pending:
                    geometric_samples = [item[0] for item in geometric_pending]
                    dense_count = max(24, self._current_ray_count() * 6)
                    geometric_results, geometric_workers = self._build_geometric_image_samples_for_field_samples(
                        wavelength,
                        sample_count=dense_count,
                        pattern="hexapolar",
                        surface_index=int(mtf_settings["surface_index"]),
                        aperture_type=str(mtf_settings["aperture_type"]),
                        aperture_value=float(mtf_settings["aperture_value"]),
                        field_samples=geometric_samples,
                    )
                    max_workers = max(max_workers, int(geometric_workers))
                    for (sample, legend), (x_local, y_local) in zip(geometric_pending, geometric_results):
                        try:
                            result = self._geometric_mtf_result_from_image_samples(
                                x_local,
                                y_local,
                                worker_count=int(geometric_workers),
                                sample_count=int(dense_count),
                                algorithm=mtf_algorithm,
                            )
                            self.append_debug(
                                "MTF sample {legend}: geometric ok: rays={rays}, pupil_samp={pupil_samp}, workers={workers}, accel={accel}".format(
                                    legend=legend,
                                    rays=int(result["sample_count"]),
                                    pupil_samp=int(result.get("pupil_samp", 0)),
                                    workers=int(result["worker_count"]),
                                    accel=str(result["accelerator"]),
                                )
                            )
                        except Exception as geom_exc:
                            self.append_debug(f"MTF sample {legend}: geometric failed: {geom_exc}")
                            continue

                        plot_freq = np.asarray(result["plot_freq"], dtype=float)
                        plot_tan = np.asarray(result["plot_tan"], dtype=float)
                        plot_sag = np.asarray(result["plot_sag"], dtype=float)
                        if plot_freq.size == 0 or plot_tan.size == 0 or plot_sag.size == 0:
                            continue

                        tan_value = float(np.interp(target_freq, plot_freq, plot_tan, left=plot_tan[0], right=plot_tan[-1]))
                        sag_value = float(np.interp(target_freq, plot_freq, plot_sag, left=plot_sag[0], right=plot_sag[-1]))
                        if mtf_mode == "tangential":
                            selected_value = tan_value
                            selected_label = "Tangential"
                        elif mtf_mode == "sagittal":
                            selected_value = sag_value
                            selected_label = "Sagittal"
                        else:
                            selected_value = 0.5 * (tan_value + sag_value)
                            selected_label = "Average"

                        result.update(
                            {
                                "legend": legend,
                                "basis": str(sample["basis"]),
                                "unit": str(sample["unit"]),
                                "display_x": float(sample["display_x"]),
                                "display_y": float(sample["display_y"]),
                                "tan_value": tan_value,
                                "sag_value": sag_value,
                                "selected_value": float(selected_value),
                                "selected_label": selected_label,
                            }
                        )
                        sample_results.append(result)
                        accelerators.add(str(result.get("accelerator", "CPU")))

                if not sample_results:
                    raise RuntimeError("MTF analysis unavailable for all selected field samples")
                sample_results.sort(key=lambda result: float(result.get("display_y", 0.0)))

                colors = self._field_colors(len(sample_results))
                max_plot_freq = 0.0
                label_specs: list[dict[str, object]] = []
                for color, result in zip(colors, sample_results):
                    plot_freq = np.asarray(result["plot_freq"], dtype=float)
                    plot_tan = np.asarray(result["plot_tan"], dtype=float)
                    plot_sag = np.asarray(result["plot_sag"], dtype=float)
                    max_plot_freq = max(max_plot_freq, float(plot_freq[-1]))
                    legend = str(result["legend"])
                    overlap = bool(
                        np.allclose(
                            plot_tan,
                            plot_sag,
                            rtol=1e-3,
                            atol=max(1e-4, 5e-3 * float(max(np.max(np.abs(plot_tan)), np.max(np.abs(plot_sag)), 1e-9))),
                        )
                    )
                    result["ts_overlap"] = overlap
                    if overlap:
                        analysis_ax.plot(
                            plot_freq,
                            plot_tan,
                            label=f"T=S {legend}",
                            color=color,
                            linewidth=1.1,
                            alpha=1.0,
                            linestyle="-",
                            zorder=3,
                        )
                        label_specs.append(
                            {
                                "label": f"T=S {legend}",
                                "curve_x": plot_freq,
                                "curve_y": plot_tan,
                                "color": color,
                                "linestyle": (0, (2, 2)),
                            }
                        )
                    else:
                        analysis_ax.plot(
                            plot_freq,
                            plot_tan,
                            label=f"T {legend}",
                            color=color,
                            linewidth=1.1,
                            alpha=1.0,
                            linestyle="-",
                            zorder=3,
                        )
                        analysis_ax.plot(
                            plot_freq,
                            plot_sag,
                            label=f"S {legend}",
                            color=color,
                            linewidth=1.0,
                            alpha=1.0,
                            linestyle=(0, (6, 3)),
                            zorder=4,
                        )
                        label_specs.extend(
                            [
                                {
                                    "label": f"T {legend}",
                                    "curve_x": plot_freq,
                                    "curve_y": plot_tan,
                                    "color": color,
                                    "linestyle": (0, (2, 2)),
                                },
                                {
                                    "label": f"S {legend}",
                                    "curve_x": plot_freq,
                                    "curve_y": plot_sag,
                                    "color": color,
                                    "linestyle": (0, (1, 2)),
                                },
                            ]
                        )
                analysis_ax.plot(
                    [target_freq, target_freq],
                    [0.0, 0.08],
                    color="#2c3e50",
                    linewidth=0.9,
                    linestyle="-",
                    alpha=0.9,
                    zorder=1.8,
                )
                analysis_ax.text(
                    target_freq,
                    0.085,
                    f"ref {target_freq:.1f}",
                    ha="center",
                    va="bottom",
                    fontsize=6.5,
                    color="#2c3e50",
                    bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.45, "pad": 0.2},
                )
                basis = str(sample_results[0]["basis"])
                unit = str(sample_results[0]["unit"])
                x_text = self._format_field_sample_value(float(sample_results[0]["display_x"]))
                method_label = str(sample_results[0].get("method", "MTF"))
                dl_fc = None
                x_limit_upper = max_plot_freq if max_plot_freq > 0.0 else max(10.0, target_freq * 2.5)
                if not method_label.lower().startswith("geometric"):
                    try:
                        effl, _ppa, _ppp = self._exact_paraxial_cardinals(wavelength)
                        pupil_ref = Kos.PupilCalc(
                            system,
                            int(mtf_settings["surface_index"]),
                            wavelength,
                            str(mtf_settings["aperture_type"]),
                            float(mtf_settings["aperture_value"]),
                        )
                        ep_diameter = max(2.0 * abs(float(getattr(pupil_ref, "RadPupInp", 0.0))), 1e-9)
                        f_number = abs(float(effl)) / ep_diameter
                        if np.isfinite(f_number) and f_number > 1e-12:
                            dl_fc = 1.0 / (max(wavelength, 1e-12) * 1e-3 * f_number)
                            if np.isfinite(dl_fc) and dl_fc > 0.0:
                                x_limit_upper = max(target_freq * 1.1, float(dl_fc) * 1.02)
                                dl_freq = np.linspace(0.0, x_limit_upper, 512)
                                nu = np.clip(dl_freq / dl_fc, 0.0, 1.0)
                                dl_curve = (2.0 / np.pi) * (
                                    np.arccos(nu) - nu * np.sqrt(np.clip(1.0 - nu * nu, 0.0, 1.0))
                                )
                                dl_curve = np.where(dl_freq <= dl_fc, dl_curve, 0.0)
                                analysis_ax.plot(
                                    dl_freq,
                                    dl_curve,
                                    color="#475569",
                                    linewidth=1.3,
                                    linestyle=(0, (4, 2)),
                                    alpha=0.9,
                                    label="DL ref",
                                    zorder=2,
                                )
                    except Exception:
                        dl_fc = None
                analysis_ax.set_title(
                    f"MTF ({method_label})  |  {basis} samples  |  ref {target_freq:.1f} cy/mm  |  {wavelength:.4g} um"
                )
                analysis_ax.set_xlabel("Spatial frequency [cycles/mm]")
                analysis_ax.set_ylabel("MTF")
                analysis_ax.set_ylim(0.0, 1.05)
                analysis_ax.set_xlim(0.0, x_limit_upper)
                analysis_ax.set_aspect("auto")
                analysis_ax.set_box_aspect(0.62)
                analysis_ax.grid(True, alpha=0.2)
                y_top = analysis_ax.get_ylim()[1]
                if label_specs:
                    x_min, x_max = [float(v) for v in analysis_ax.get_xlim()]
                    y_min, _ = [float(v) for v in analysis_ax.get_ylim()]
                    active_x_max = x_max
                    for spec in label_specs:
                        curve_x = np.asarray(spec["curve_x"], dtype=float)
                        curve_y = np.asarray(spec["curve_y"], dtype=float)
                        nonzero = curve_x[curve_y > 0.03]
                        if nonzero.size:
                            active_x_max = min(active_x_max, float(np.max(nonzero)))
                    label_left = max(x_min + 0.06 * (x_max - x_min), min(target_freq + 1.5, active_x_max * 0.25))
                    label_right = max(label_left + 1.0, min(x_max - 0.06 * (x_max - x_min), active_x_max * 0.98))
                    label_x_positions = np.linspace(label_left, label_right, len(label_specs))
                    row_levels = [y_top - 0.07, y_top - 0.13, y_top - 0.19, y_top - 0.25]
                    for index, (spec, label_x) in enumerate(zip(label_specs, label_x_positions)):
                        curve_x = np.asarray(spec["curve_x"], dtype=float)
                        curve_y = np.asarray(spec["curve_y"], dtype=float)
                        marker_value = float(np.interp(label_x, curve_x, curve_y, left=curve_y[0], right=curve_y[-1]))
                        if not np.isfinite(marker_value):
                            continue
                        row_y = row_levels[index % len(row_levels)]
                        if marker_value >= y_top - 0.12:
                            label_y = row_y
                        else:
                            label_y = min(y_top - 0.04, max(row_y, marker_value + 0.06))
                        connector_end = label_y - 0.015 if label_y >= marker_value else label_y + 0.015
                        analysis_ax.plot(
                            [label_x, label_x],
                            [marker_value, connector_end],
                            color=str(spec["color"]),
                            linewidth=0.75,
                            linestyle=spec["linestyle"],
                            alpha=0.8,
                            zorder=2.5,
                        )
                        analysis_ax.text(
                            label_x,
                            label_y,
                            str(spec["label"]),
                            rotation=0,
                            ha="center",
                            va="top",
                            fontsize=6.1,
                            color=str(spec["color"]),
                            bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.45, "pad": 0.2},
                        )
                if dl_fc is not None and np.isfinite(dl_fc):
                    dl_x = float(np.clip(dl_fc, analysis_ax.get_xlim()[0], analysis_ax.get_xlim()[1]))
                    analysis_ax.axvline(
                        dl_x,
                        color="#475569",
                        linewidth=0.9,
                        linestyle=(0, (1, 2)),
                        alpha=0.7,
                        zorder=1.5,
                    )
                    label_x = min(dl_x, analysis_ax.get_xlim()[1] - 0.5)
                    analysis_ax.text(
                        label_x,
                        0.035,
                        f"DL cutoff {float(dl_fc):.1f} cy/mm",
                        ha="right" if dl_x >= analysis_ax.get_xlim()[1] - 1.0 else "center",
                        va="bottom",
                        fontsize=7,
                        color="#475569",
                        bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.45, "pad": 0.2},
                    )

                self._set_analysis_parallel_status("MTF", max_workers, max_workers > 1)
                if accelerators:
                    accel_summary = "/".join(sorted(accelerators))
                    self._set_analysis_accelerator(accel_summary)
                self._update_analysis_progress("Rendering MTF", total_steps, total_steps)
                self._finish_analysis_progress("MTF analysis", success=True)
            except Exception as exc:
                self._set_analysis_parallel_status("MTF", 1, True)
                self.append_debug(f"MTF analysis error: {exc}")
                analysis_ax.text(0.5, 0.5, "MTF analysis unavailable", ha="center", va="center")
                analysis_ax.set_axis_off()
                self._finish_analysis_progress("MTF analysis", success=False)
            return

    def _plot_analysis_for_mode(self, analysis_ax, system, rays, wavelength: float, mode: str) -> None:
        previous_mode = self.analysis_mode
        try:
            self.analysis_mode = str(mode)
            self._plot_analysis(analysis_ax, system, rays, wavelength)
        finally:
            self.analysis_mode = previous_mode

    def _analysis_surface_index(self) -> int:
        selected = self.analysis_surface_var.get().strip()
        if selected and selected != "Auto":
            try:
                return int(selected.split(":", 1)[0])
            except ValueError:
                pass
        if len(self.rows) <= 2:
            return max(0, len(self.rows) - 1)
        candidate_indices = [i for i, row in enumerate(self.rows[1:-1], start=1)]
        if not candidate_indices:
            return 1
        return min(candidate_indices, key=lambda i: max(self.rows[i].diameter, 1e-9))

    def _current_object_mode(self) -> str:
        mode = self._left_mode_text("object_mode_var", "Finite")
        return mode if mode in {"Finite", "Infinity"} else "Finite"

    def _current_object_distance(self) -> float:
        if self.rows:
            try:
                if any(row.surface == "Mirror" for row in self.rows):
                    distance, _first_source_index = self._paraxial_total_object_gap(self.rows)
                else:
                    distance = float(self.rows[0].thickness)
            except Exception:
                distance = float(self.rows[0].thickness)
        else:
            distance = 100.0
        return max(distance, 1e-6)

    def _current_field_count(self) -> int:
        try:
            return max(1, int(self.field_count_var.get()))
        except ValueError:
            return 1

    def _current_field_type(self) -> str:
        return self._normalize_field_type(self.field_type_var.get().strip())

    def _current_spot_view_mode(self) -> str:
        value = getattr(self, "spot_view_mode_var", None)
        if value is None:
            return "Grid"
        mode = value.get().strip()
        if mode in {"Grid", "Absolute", "Centroid"}:
            return mode
        return "Grid"

    def _current_detector_bin_count(self, sample_count: int, *, coherent: bool = False) -> int:
        sample_count = max(1, int(sample_count or 1))
        auto_min = 24 if coherent else 16
        auto_max = 128 if coherent else 96
        auto_scale = 5 if coherent else 4
        auto_bins = int(np.clip(max(auto_min, round(np.sqrt(sample_count) * auto_scale)), auto_min, auto_max))
        text = self._left_mode_text("detector_bins_var", DETECTOR_BINS_DEFAULT).strip()
        if not text or text.lower() in {"auto", "default"}:
            return auto_bins
        try:
            bins = int(float(text))
        except Exception:
            return auto_bins
        return int(np.clip(bins, 4, 512))

    def _current_wavefront_style(self) -> str:
        value = getattr(self, "wavefront_style_var", None)
        if value is None:
            return WAVEFRONT_STYLE_DEFAULT
        style = value.get().strip()
        if style in WAVEFRONT_STYLE_VALUES:
            return style
        return WAVEFRONT_STYLE_DEFAULT

    def _wavefront_function_grid(
        self,
        x_pupil: np.ndarray,
        y_pupil: np.ndarray,
        phase_waves: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
        x = np.asarray(x_pupil, dtype=float).ravel()
        y = np.asarray(y_pupil, dtype=float).ravel()
        values = np.asarray(phase_waves, dtype=float).ravel()
        finite = np.isfinite(x) & np.isfinite(y) & np.isfinite(values)
        x = x[finite]
        y = y[finite]
        values = values[finite]
        if values.size < 4:
            raise RuntimeError("Not enough finite wavefront samples for Wavefront Function plot")

        x_scale = float(np.nanmax(np.abs(x)))
        y_scale = float(np.nanmax(np.abs(y)))
        if not np.isfinite(x_scale) or x_scale <= 1e-12:
            x_scale = 1.0
        if not np.isfinite(y_scale) or y_scale <= 1e-12:
            y_scale = 1.0
        x_norm = np.clip(x / x_scale, -1.0, 1.0)
        y_norm = np.clip(y / y_scale, -1.0, 1.0)
        grid_count = max(35, min(90, int(np.sqrt(max(values.size, 1)) * 6)))
        grid_axis = np.linspace(-1.0, 1.0, grid_count)
        xx, yy = np.meshgrid(grid_axis, grid_axis)
        pupil_mask = (xx * xx + yy * yy) <= 1.0
        zz = np.full_like(xx, np.nan, dtype=float)
        if np.ptp(x_norm) > 1e-6 and np.ptp(y_norm) > 1e-6 and values.size >= 10:
            for term_count in (min(28, max(10, values.size // 2)), 21, 15, 10, 6):
                if term_count < 4 or term_count > values.size:
                    continue
                try:
                    active_terms = np.ones(int(term_count), dtype=float)
                    coefficients, *_ = Kos.Zernike_Fitting(x_norm, y_norm, values, active_terms)
                    reconstructed = np.asarray(
                        Kos.Wavefront_Zernike_Phase(xx[pupil_mask], yy[pupil_mask], coefficients),
                        dtype=float,
                    ).ravel()
                    if reconstructed.size == int(np.count_nonzero(pupil_mask)) and np.any(np.isfinite(reconstructed)):
                        zz[pupil_mask] = reconstructed
                        break
                except Exception:
                    continue
        try:
            if not np.any(np.isfinite(zz)):
                from matplotlib.tri import LinearTriInterpolator, Triangulation

                triangulation = Triangulation(x_norm, y_norm)
                interpolator = LinearTriInterpolator(triangulation, values)
                zz = np.ma.asarray(interpolator(xx, yy)).filled(np.nan).astype(float)
        except Exception:
            # Keep the plot usable with sparse/degenerate pupil sets by using a
            # nearest-neighbour surface only inside the normalized pupil.
            sample_xy = np.column_stack([x_norm, y_norm])
            grid_xy = np.column_stack([xx[pupil_mask], yy[pupil_mask]])
            if grid_xy.size:
                diff = grid_xy[:, None, :] - sample_xy[None, :, :]
                nearest = np.argmin(np.sum(diff * diff, axis=2), axis=1)
                zz[pupil_mask] = values[nearest]
        zz[~pupil_mask] = np.nan
        if np.count_nonzero(np.isfinite(zz)) < 8:
            raise RuntimeError("Wavefront Function interpolation produced no finite surface")
        return xx, yy, zz

    def _remove_wavefront_reference_plane(
        self,
        x_pupil: np.ndarray,
        y_pupil: np.ndarray,
        values: np.ndarray,
    ) -> np.ndarray:
        x = np.asarray(x_pupil, dtype=float).ravel()
        y = np.asarray(y_pupil, dtype=float).ravel()
        wavefront = np.asarray(values, dtype=float).ravel()
        finite = np.isfinite(x) & np.isfinite(y) & np.isfinite(wavefront)
        corrected = np.full_like(wavefront, np.nan, dtype=float)
        if np.count_nonzero(finite) < 4:
            return wavefront - float(np.nanmean(wavefront))
        design = np.column_stack([np.ones(np.count_nonzero(finite)), x[finite], y[finite]])
        coeffs, *_ = np.linalg.lstsq(design, wavefront[finite], rcond=None)
        corrected[finite] = wavefront[finite] - (coeffs[0] + coeffs[1] * x[finite] + coeffs[2] * y[finite])
        return corrected

    @staticmethod
    def _plot_axes_nan_segments(axis, x_values: np.ndarray, y_values: np.ndarray, **kwargs) -> None:
        x_values = np.asarray(x_values, dtype=float).ravel()
        y_values = np.asarray(y_values, dtype=float).ravel()
        finite = np.isfinite(x_values) & np.isfinite(y_values)
        start: int | None = None
        for index, is_finite in enumerate(finite):
            if is_finite and start is None:
                start = index
            if (not is_finite or index == finite.size - 1) and start is not None:
                end = index + 1 if is_finite and index == finite.size - 1 else index
                if end - start >= 2:
                    axis.plot(x_values[start:end], y_values[start:end], **kwargs)
                start = None

    def _wavefront_projected_axes_coordinates(
        self,
        xx: np.ndarray,
        yy: np.ndarray,
        zz: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray]:
        finite_z = zz[np.isfinite(zz)]
        z_scale = float(np.nanpercentile(np.abs(finite_z), 95.0)) if finite_z.size else 1.0
        if not np.isfinite(z_scale) or z_scale <= 1e-12:
            z_scale = float(np.nanmax(np.abs(finite_z))) if finite_z.size else 1.0
        if not np.isfinite(z_scale) or z_scale <= 1e-12:
            z_scale = 1.0
        z_norm = np.clip(zz / z_scale, -1.6, 1.6)

        # Orthographic projection tuned to resemble Zemax's Wavefront Function
        # printout: waterfall slices with strong OPD relief, no 3D axes.
        projected_x = 1.04 * xx + 0.08 * yy
        projected_y = 0.20 * yy + 0.82 * z_norm
        finite = np.isfinite(projected_x) & np.isfinite(projected_y)
        if not np.any(finite):
            raise RuntimeError("Wavefront Function projection produced no finite samples")

        plot_left, plot_right = 0.065, 0.945
        plot_bottom, plot_top = 0.265, 0.925
        x_min = float(np.nanmin(projected_x[finite]))
        x_max = float(np.nanmax(projected_x[finite]))
        y_min = float(np.nanmin(projected_y[finite]))
        y_max = float(np.nanmax(projected_y[finite]))
        x_span = max(x_max - x_min, 1e-12)
        y_span = max(y_max - y_min, 1e-12)
        scale = min((plot_right - plot_left) / x_span, (plot_top - plot_bottom) / y_span)
        x_mid = 0.5 * (x_min + x_max)
        y_mid = 0.5 * (y_min + y_max)
        plot_x_mid = 0.5 * (plot_left + plot_right)
        plot_y_mid = 0.5 * (plot_bottom + plot_top)
        axis_x = plot_x_mid + (projected_x - x_mid) * scale
        axis_y = plot_y_mid + (projected_y - y_mid) * scale
        axis_x[~finite] = np.nan
        axis_y[~finite] = np.nan
        return axis_x, axis_y

    @staticmethod
    def _wavefront_slice_curvature(values: np.ndarray) -> float:
        values = np.asarray(values, dtype=float)
        if values.ndim != 2 or min(values.shape) < 3:
            return 0.0
        curvatures: list[float] = []
        for line in values:
            finite = np.isfinite(line)
            if np.count_nonzero(finite) < 5:
                continue
            segment = line[finite]
            second = np.diff(segment, n=2)
            if second.size:
                curvatures.append(float(np.nanmean(np.abs(second))))
        return float(np.nanmedian(curvatures)) if curvatures else 0.0

    def _orient_wavefront_waterfall_grid(
        self,
        xx: np.ndarray,
        yy: np.ndarray,
        zz: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
        row_curvature = self._wavefront_slice_curvature(zz)
        column_curvature = self._wavefront_slice_curvature(zz.T)
        if column_curvature > row_curvature * 1.15:
            return yy.T, xx.T, zz.T
        return xx, yy, zz

    def _plot_wavefront_function_analysis(
        self,
        analysis_ax,
        x_pupil: np.ndarray,
        y_pupil: np.ndarray,
        phase_waves_centered: np.ndarray,
        *,
        phase_pv: float,
        phase_rms: float,
        phase_method: str,
        reference_note: str,
    ):
        xx, yy, zz = self._wavefront_function_grid(
            x_pupil,
            y_pupil,
            phase_waves_centered,
        )
        finite_z = zz[np.isfinite(zz)]
        z_span = float(np.nanmax(finite_z) - np.nanmin(finite_z)) if finite_z.size else 0.0
        max_slice_curvature = max(
            self._wavefront_slice_curvature(zz),
            self._wavefront_slice_curvature(zz.T),
        )
        shape_note = ""
        if z_span > 1e-12 and max_slice_curvature / z_span < 1e-5:
            shape_note = "near-flat/cylindrical samples"
        xx, yy, zz = self._orient_wavefront_waterfall_grid(xx, yy, zz)
        axis_x, axis_y = self._wavefront_projected_axes_coordinates(xx, yy, zz)
        analysis_ax.clear()
        analysis_ax.set_xlim(0.0, 1.0)
        analysis_ax.set_ylim(0.0, 1.0)
        analysis_ax.set_axis_off()

        border_color = "#111111"
        # Outer Zemax-style frame and bottom report/title table.
        analysis_ax.add_patch(Rectangle((0.03, 0.03), 0.94, 0.92, fill=False, linewidth=0.85, edgecolor=border_color))
        analysis_ax.plot([0.03, 0.97], [0.235, 0.235], color=border_color, linewidth=0.7)
        analysis_ax.plot([0.03, 0.97], [0.195, 0.195], color=border_color, linewidth=0.7)
        analysis_ax.plot([0.68, 0.68], [0.03, 0.195], color=border_color, linewidth=0.7)
        analysis_ax.text(0.5, 0.214, "WAVEFRONT FUNCTION", ha="center", va="center", fontsize=9.2)

        row_step = 1 if axis_x.shape[0] <= 58 else 2
        for row_index in range(0, axis_x.shape[0], row_step):
            self._plot_axes_nan_segments(
                analysis_ax,
                axis_x[row_index, :],
                axis_y[row_index, :],
                color="#111827",
                linewidth=0.42,
                alpha=0.96,
            )

        analysis_ax.text(
            0.045,
            0.118,
            f"P-V: {phase_pv:.4g} waves   RMS: {phase_rms:.4g} waves",
            ha="left",
            va="center",
            fontsize=7.2,
        )
        analysis_ax.text(0.045, 0.072, "SURFACE: IMAGE", ha="left", va="center", fontsize=7.2)
        analysis_ax.text(0.69, 0.118, "KRAKENOS UI", ha="left", va="center", fontsize=7.2)
        analysis_ax.text(0.69, 0.072, f"{phase_method}; piston/tilt removed", ha="left", va="center", fontsize=6.4)
        if shape_note:
            analysis_ax.text(0.045, 0.165, shape_note, ha="left", va="center", fontsize=6.4, color="#7f1d1d")
        analysis_ax.set_box_aspect(0.78)
        return analysis_ax

    def _current_field_value(self) -> float:
        try:
            return float(self.field_value_var.get())
        except ValueError:
            return 0.0

    def _current_field_angle_deg(self) -> float:
        return float(self._field_metrics().get("angle_deg", 0.0))

    def _current_field_height(self) -> float:
        return float(self._field_metrics().get("object_height", 0.0))

    def _field_metrics_for_value(self, field_type: str, raw_value: float) -> dict[str, float]:
        object_distance = self._current_object_distance()
        effl = self._current_effl_estimate()
        image_distance = self._current_image_distance()
        finite_magnification = self._current_finite_paraxial_magnification()

        with np.errstate(divide="ignore", invalid="ignore", over="ignore"):
            if finite_magnification is not None:
                mag = max(abs(float(finite_magnification)), 1e-9)
                if field_type == "Angle":
                    angle_deg = raw_value
                    object_height = object_distance * np.tan(np.deg2rad(angle_deg))
                elif field_type == "Object Height":
                    object_height = raw_value
                    angle_deg = np.rad2deg(np.arctan2(object_height, object_distance))
                else:
                    object_height = raw_value / mag
                    angle_deg = np.rad2deg(np.arctan2(object_height, object_distance))
                paraxial_image_height = mag * object_height
                real_image_height = paraxial_image_height
            else:
                if field_type == "Angle":
                    angle_deg = raw_value
                    object_height = object_distance * np.tan(np.deg2rad(angle_deg))
                elif field_type == "Object Height":
                    object_height = raw_value
                    angle_deg = np.rad2deg(np.arctan2(object_height, object_distance))
                elif field_type == "Paraxial Image Height":
                    paraxial_image_height = raw_value
                    angle_deg = np.rad2deg(np.arctan2(paraxial_image_height, max(effl, 1e-6)))
                    object_height = object_distance * np.tan(np.deg2rad(angle_deg))
                else:
                    real_image_height = raw_value
                    angle_deg = np.rad2deg(np.arctan2(real_image_height, max(image_distance, 1e-6)))
                    object_height = object_distance * np.tan(np.deg2rad(angle_deg))

                paraxial_image_height = effl * np.tan(np.deg2rad(angle_deg))
                real_image_height = image_distance * np.tan(np.deg2rad(angle_deg))

        if not np.isfinite(angle_deg):
            angle_deg = 0.0
        if not np.isfinite(object_height):
            object_height = 0.0
        if not np.isfinite(paraxial_image_height):
            paraxial_image_height = 0.0
        if not np.isfinite(real_image_height):
            real_image_height = 0.0
        return {
            "angle_deg": float(angle_deg),
            "object_height": float(object_height),
            "paraxial_image_height": float(paraxial_image_height),
            "real_image_height": float(real_image_height),
        }

    def _field_metrics(self) -> dict[str, float]:
        return self._field_metrics_for_value(self._current_field_type(), self._current_field_value())

    def _field_metrics_summary(self) -> dict[str, float]:
        field_type = self._current_field_type()
        sample_values = self._sample_field_values(self._current_field_value())
        if not sample_values:
            sample_values = [self._current_field_value()]
        metrics = [self._field_metrics_for_value(field_type, value) for value in sample_values]
        current_metrics = self._field_metrics()
        max_paraxial = max(abs(float(item.get("paraxial_image_height", 0.0))) for item in metrics) if metrics else 0.0
        max_real = max(abs(float(item.get("real_image_height", 0.0))) for item in metrics) if metrics else 0.0
        traced_image_diameter = self._traced_image_diameter_value()
        field_image_radius = max_paraxial if self._current_object_mode() == "Infinity" else max_real
        required_image_diameter = max(
            2.0 * field_image_radius,
            float(traced_image_diameter) if traced_image_diameter is not None else 0.0,
            1.0,
        )
        return {
            "current_angle_deg": float(current_metrics.get("angle_deg", 0.0)),
            "current_object_height": float(current_metrics.get("object_height", 0.0)),
            "current_paraxial_image_height": float(current_metrics.get("paraxial_image_height", 0.0)),
            "current_real_image_height": float(current_metrics.get("real_image_height", 0.0)),
            "max_paraxial_image_height": float(max_paraxial),
            "max_real_image_height": float(max_real),
            "image_diameter": float(required_image_diameter),
        }

    def _current_effl_estimate(self) -> float:
        try:
            effl, _ppa, _ppp = self._exact_paraxial_cardinals(self._current_wavelength())
            return max(abs(float(effl)), 1e-6)
        except Exception:
            pass
        if self.last_system is not None:
            try:
                with warnings.catch_warnings():
                    warnings.simplefilter("ignore", RuntimeWarning)
                    _a, _b, _c, _d, effl, *_rest = self.last_system.EFL(self._current_wavelength())  # type: ignore[misc]
                return max(abs(float(effl)), 1e-6)
            except Exception:
                pass
        return 100.0

    def _current_image_distance(self) -> float:
        if len(self.rows) >= 2:
            try:
                if any(row.surface == "Mirror" for row in self.rows):
                    distance, _last_source_index, _reference_rows = self._paraxial_total_image_gap(self.rows)
                else:
                    distance = float(self.rows[-2].thickness)
            except Exception:
                distance = float(self.rows[-2].thickness)
            return max(float(distance), 1e-6)
        return 100.0

    def _current_finite_paraxial_magnification(self) -> float | None:
        if self._current_object_mode() != "Finite" or len(self.rows) < 3:
            return None
        try:
            solve_rows = self.rows
            if any(row.surface == "Mirror" for row in self.rows):
                solve_rows, _last_source_index = self._paraxial_reference_rows_for_layout(self.rows)
            _a, _b, _c, _d, _effl, ppa, ppp = self._exact_paraxial_solution_for_rows(solve_rows)
            h1_vertex_z, h2_vertex_z = self._paraxial_vertex_zs(solve_rows)
            h1_z = h1_vertex_z + float(ppa)
            h2_z = h2_vertex_z + float(ppp)
            image_z = sum(float(row.thickness) for row in solve_rows[:-1])
            object_principal = float(h1_z)
            image_principal = float(image_z - h2_z)
            if (
                np.isfinite(object_principal)
                and np.isfinite(image_principal)
                and abs(object_principal) > 1e-9
            ):
                return float(image_principal / object_principal)
        except Exception:
            return None
        return None

    def _schedule_refresh_plot(self, *_args) -> None:
        if not self.winfo_exists():
            return
        if hasattr(self, "_refresh_after_id") and self._refresh_after_id is not None:
            self.after_cancel(self._refresh_after_id)
        self._refresh_after_id = self.after(120, self._refresh_plot_from_controls)

    def _refresh_plot_from_controls(self) -> None:
        self._refresh_after_id = None
        if self.optimization_running:
            return
        self.refresh_plot()

    # _style_embedded_plot removed — now in scene_renderer_2d._style_surface_lines

    def _field_colors(self, count: int) -> list[str]:
        if count <= 1:
            return ["#39FF14"]
        cmap = [
            "#39FF14",
            "#00E5FF",
            "#FF9F1C",
            "#FF4D6D",
            "#9B5DE5",
            "#FFD166",
            "#2EC4B6",
            "#E71D36",
        ]
        return [cmap[i % len(cmap)] for i in range(count)]

    # _build_world_ray_paths, _build_display_ray_paths, _render_display_surface_paths
    # removed — now in scene_builder and scene_renderer_2d

    def _current_folded_surface_geometry(
        self,
        *,
        system=None,
    ) -> tuple[np.ndarray, np.ndarray, float, list[np.ndarray], list[tuple[str, np.ndarray, SurfaceRow, np.ndarray]]] | None:
        trace_state = self._resolved_trace_mode(system=system)
        if not bool(trace_state.get("use_folded")) or not self.rows:
            return None
        return self._compute_folded_layout_geometry()

    def _reference_plane_overrides(self, *, system=None) -> dict[int, tuple[np.ndarray, np.ndarray]]:
        trace_state = self._resolved_trace_mode(system=system)
        if bool(trace_state.get("use_folded")):
            return self._folded_plane_overrides()
        if system is not None and self._has_off_axis_geometry():
            overrides = self._transform_reference_plane_overrides(system)
            if overrides:
                return overrides
        return {}

    def _transform_reference_plane_overrides(self, system) -> dict[int, tuple[np.ndarray, np.ndarray]]:
        transforms = self._system_transform_list(system)
        if transforms is None:
            return {}
        overrides: dict[int, tuple[np.ndarray, np.ndarray]] = {}
        for row_index, row in enumerate(self.rows):
            if row.surface not in {"Object", "Image", "Aperture"} or row_index >= len(transforms):
                continue
            try:
                transform = np.asarray(transforms[row_index], dtype=float)
                center_z = float(transform[2, 3])
                center_y = float(transform[1, 3])
                axis_z = float(transform[2, 2])
                axis_y = float(transform[1, 2])
                axis_norm = float(np.hypot(axis_z, axis_y))
                if axis_norm <= 1e-12:
                    continue
                x0, y0 = self._project_xy([center_z], [center_y])
                x1, y1 = self._project_xy([center_z + axis_z / axis_norm], [center_y + axis_y / axis_norm])
                center = np.array([float(x0[0]), float(y0[0])], dtype=float)
                along = np.array([float(x1[0] - x0[0]), float(y1[0] - y0[0])], dtype=float)
                along_norm = float(np.linalg.norm(along))
                if along_norm <= 1e-12:
                    continue
                overrides[row_index] = (center, along / along_norm)
            except Exception:
                continue
        return overrides

    # _reference_plane_display_points, _build_reference_plane_surface_paths
    # removed — now in scene_builder

    @staticmethod
    def _unit_display_vector(vector, fallback: np.ndarray | None = None) -> np.ndarray:
        try:
            arr = np.asarray(vector, dtype=float).ravel()
        except Exception:
            arr = np.empty(0, dtype=float)
        if arr.size >= 2 and np.all(np.isfinite(arr[:2])):
            candidate = np.asarray(arr[:2], dtype=float)
        elif fallback is not None:
            candidate = np.asarray(fallback, dtype=float).ravel()[:2]
        else:
            candidate = np.asarray((1.0, 0.0), dtype=float)
        norm = float(np.linalg.norm(candidate))
        if norm <= 1e-12:
            candidate = np.asarray((1.0, 0.0), dtype=float)
            norm = 1.0
        return candidate / norm

    def _source_display_frame(self) -> tuple[np.ndarray, np.ndarray, float]:
        try:
            source_x, source_y, source_z = self._current_source_origin()
            del source_x
        except Exception:
            source_y, source_z = 0.0, 0.0
        x_vals, y_vals = self._project_xy([source_z], [source_y])
        center = np.asarray((float(x_vals[0]), float(y_vals[0])), dtype=float)
        try:
            _source_l, source_m, source_n = self._current_source_direction()
        except Exception:
            source_m, source_n = 0.0, 1.0
        axis_x, axis_y = self._project_xy([source_n], [source_m])
        axis = np.asarray((float(axis_x[0]), float(axis_y[0])), dtype=float)
        axis = self._unit_display_vector(axis, np.asarray((1.0, 0.0), dtype=float))
        tangent = self._unit_display_vector(np.asarray((-axis[1], axis[0]), dtype=float), np.asarray((0.0, 1.0)))
        source_radius = self._current_source_radius()
        if getattr(self, "rows", None):
            try:
                source_radius = max(source_radius, 0.5 * abs(float(self.rows[0].diameter)))
            except Exception:
                pass
        return center, tangent, float(max(source_radius, 0.0))

    def _branch_output_display_targets(self) -> dict[str, np.ndarray]:
        targets: dict[str, np.ndarray] = {}
        for row in getattr(self, "rows", []) or []:
            advanced = getattr(row, "advanced", {}) or {}
            if not isinstance(advanced, dict):
                continue
            display_settings = advanced.get("Display2D", {})
            if not isinstance(display_settings, dict):
                continue
            raw_targets = display_settings.get("branch_output_targets")
            if not isinstance(raw_targets, dict):
                continue
            for raw_code, raw_point in raw_targets.items():
                code = str(raw_code or "").strip().upper()
                if not code:
                    continue
                try:
                    point = np.asarray(raw_point, dtype=float).ravel()
                except Exception:
                    continue
                if point.size < 2 or not np.all(np.isfinite(point[:2])):
                    continue
                targets[code] = np.asarray(point[:2], dtype=float)
        return targets

    def _branch_output_display_target_frames(self) -> dict[str, tuple[np.ndarray, np.ndarray, float]]:
        source_center, source_tangent, source_radius = self._source_display_frame()
        frames: dict[str, tuple[np.ndarray, np.ndarray, float]] = {}
        for row in getattr(self, "rows", []) or []:
            advanced = getattr(row, "advanced", {}) or {}
            if not isinstance(advanced, dict):
                continue
            display_settings = advanced.get("Display2D", {})
            if not isinstance(display_settings, dict):
                continue
            raw_targets = display_settings.get("branch_output_targets")
            if not isinstance(raw_targets, dict):
                continue
            try:
                row_radius = 0.5 * abs(float(row.diameter))
            except Exception:
                row_radius = 0.0
            raw_tangent = display_settings.get("plane_tangent")
            for raw_code, raw_point in raw_targets.items():
                code = str(raw_code or "").strip().upper()
                if not code:
                    continue
                try:
                    point = np.asarray(raw_point, dtype=float).ravel()
                except Exception:
                    continue
                if point.size < 2 or not np.all(np.isfinite(point[:2])):
                    continue
                target = np.asarray(point[:2], dtype=float)
                if code in {"TT", "RR"}:
                    frames[code] = (target, source_tangent, source_radius)
                    continue
                fallback_axis = target - source_center
                fallback_tangent = np.asarray((-fallback_axis[1], fallback_axis[0]), dtype=float)
                tangent = self._unit_display_vector(raw_tangent, fallback_tangent)
                frames[code] = (target, tangent, max(row_radius, source_radius))
        return frames

    def _branch_output_display_path_overrides(self, rays) -> list[np.ndarray] | None:
        target_frames = self._branch_output_display_target_frames()
        if not target_frames or rays is None:
            return None
        source_center, source_tangent, _source_radius = self._source_display_frame()
        overrides: list[np.ndarray] = []
        used_override = False
        ray_paths = getattr(rays, "CC", ())
        if ray_paths is None:
            return None
        for ray_index, ray in enumerate(ray_paths):
            points_world = np.asarray(ray, dtype=float)
            if points_world.ndim != 2 or points_world.shape[0] < 2 or points_world.shape[1] < 3:
                overrides.append(np.empty((0, 2), dtype=float))
                continue
            x_vals, y_vals = self._project_xy(points_world[:, 2], points_world[:, 1])
            points_2d = np.column_stack((x_vals, y_vals)).astype(float)
            branch_path = str(self._raykeeper_value(rays, "BRANCH_PATH", ray_index, "") or "")
            code = "".join(self._branch_path_selector_sequence(branch_path))[-2:]
            target_frame = target_frames.get(code)
            if target_frame is not None and points_2d.shape[0] >= 2:
                target, target_tangent, max_offset = target_frame
                source_offset = float(np.dot(points_2d[0] - source_center, source_tangent))
                if abs(source_offset) <= 1e-12:
                    raw_offset = float(np.dot(points_2d[-1] - target, target_tangent))
                    if np.isfinite(raw_offset):
                        source_offset = raw_offset
                if np.isfinite(max_offset) and max_offset > 1e-9:
                    source_offset = float(np.clip(source_offset, -max_offset, max_offset))
                points_2d = np.asarray(points_2d, dtype=float).copy()
                points_2d[-1] = target + target_tangent * source_offset
                used_override = True
            overrides.append(points_2d)
        return overrides if used_override else None

    def _build_scene_bundle(self, system, rays, max_radius: float) -> SceneBundle:
        """Build a SceneBundle using the new Phase 3 pipeline."""
        orientation = self._current_display_orientation()
        trace_state = self._resolved_trace_mode(system=system)
        trace_note = str(trace_state.get("note", ""))
        trace_runtime_note = str(getattr(self, "_last_preview_trace_note", "") or "").strip()
        if trace_runtime_note:
            trace_note = f"{trace_note} {trace_runtime_note}".strip()
        folded_geometry = self._current_folded_surface_geometry(system=system)


        # Compute folded ray display overrides (pre-projected paths for folded layouts)
        folded_ray_display_paths = None
        folded_elements = None
        if folded_geometry is not None:
            _point, _direction, _mh, _ep, folded_elements = folded_geometry
            folded_ray_display_paths = self._display_path_overrides_for_current_layout(
                rays, max_radius,
                folded_elements=folded_elements,
                folded_orientation=orientation,
                system=system,
            )
        elif bool(trace_state.get("use_folded")) and orientation == "Vertical":
            folded_ray_display_paths = self._display_path_overrides_for_current_layout(
                rays, max_radius,
                system=system,
            )
        if folded_ray_display_paths is None:
            folded_ray_display_paths = self._branch_output_display_path_overrides(rays)

        field_count = max(
            1,
            int(getattr(self, "_preview_field_bundle_count", self._current_field_count())),
        )

        return build_scene_bundle(
            rows=self.rows,
            system=system,
            rays=rays,
            display_orientation=orientation,
            show_clipped_rays=self.show_clipped_rays_var.get(),
            field_count=field_count,
            ray_count_per_field=max(1, self._preview_field_ray_count),
            field_colors=self._field_colors(field_count),
            folded_geometry=folded_geometry,
            row_polylines_fn=self._row_layout_polylines,
            surface_meshes_fn=(
                (lambda current_system: self._iter_3d_surface_meshes(current_system, include_reference_surfaces=True))
                if pv is not None
                else None
            ),
            project_fn=self._project_xy,
            reference_plane_overrides=self._reference_plane_overrides(system=system),
            folded_ray_display_paths=folded_ray_display_paths,
            trace_mode_requested=str(trace_state.get("requested", "Auto")),
            trace_mode_active=str(trace_state.get("active", "Sequential")),
            trace_mode_note=trace_note,
            target_surface=(
                self._current_nonseq_target_surface_index()
                if bool(trace_state.get("use_nonseq"))
                else None
            ),
        )

    # _current_surface_scene, _render_current_layout_surfaces removed —
    # now in scene_builder.build_scene_bundle()

    # _build_folded_surface_paths, _surface_style_for_row, _polyline_vertical_extents,
    # _polyline_endpoints, _build_row_surface_groups, _build_curve_group_edge_paths,
    # _build_sequential_lens_edge_paths, _build_sequential_surface_paths
    # removed — now in scene_builder.py
    # _draw_colored_rays removed — now in scene_renderer_2d._draw_rays

    def _current_display_orientation(self) -> str:
        value = getattr(self, "display_orientation_var", None)
        if value is None:
            return "Vertical"
        mode = value.get().strip()
        return mode if mode in {"Vertical", "Horizontal"} else "Vertical"

    def _project_xy(self, z, y):
        z_arr = np.asarray(z, dtype=float)
        y_arr = np.asarray(y, dtype=float)
        if self._current_display_orientation() == "Horizontal":
            return -y_arr, -z_arr
        return z_arr, y_arr

    def _apply_display_orientation_to_lines(self, start_index: int = 0) -> None:
        if self._current_display_orientation() == "Vertical":
            return
        for line in self.ax.lines[start_index:]:
            xdata = np.asarray(line.get_xdata(orig=False), dtype=float)
            ydata = np.asarray(line.get_ydata(orig=False), dtype=float)
            if xdata.size == 0 or ydata.size == 0:
                continue
            proj_x, proj_y = self._project_xy(xdata, ydata)
            line.set_xdata(proj_x)
            line.set_ydata(proj_y)

    def _has_off_axis_geometry(self) -> bool:
        # AxisMove=1 is the default for sequential surfaces and only takes effect
        # in the presence of a real tilt/decenter, so it is not by itself a sign
        # of off-axis geometry. Mirrors and explicit tilts/decenters are.
        for row in self.rows:
            if row.surface == "Mirror":
                return True
            if any(
                abs(value) > 1e-9
                for value in (row.tilt_x, row.tilt_y, row.tilt_z, row.desp_x, row.desp_y, row.desp_z)
            ):
                return True
        return False

    def _has_beam_splitter_surface(self) -> bool:
        for row in self.rows:
            advanced = row.advanced or {}
            if row.surface == BEAM_SPLITTER_SURFACE or BEAM_SPLITTER_ADVANCED_ATTR in advanced:
                return True
        return False

    def _has_optical_stl_solid(self) -> bool:
        for row in self.rows:
            advanced = row.advanced or {}
            if isinstance(advanced, dict) and self._scene_graph_value_present(advanced.get("Solid_3d_stl")):
                return True
        return False

    def _can_build_folded_layout(self) -> bool:
        mirror_count = 0
        for row in self.rows:
            if row.surface == "Mirror":
                mirror_count += 1
            elif row.surface not in {"Object", "Image", "Standard", "Aperture"}:
                return False
        return mirror_count >= 1

    @staticmethod
    def _reflect_2d(direction: np.ndarray, line_angle_deg: float) -> np.ndarray:
        theta = np.deg2rad(float(line_angle_deg))
        tangent = np.array([np.cos(theta), np.sin(theta)], dtype=float)
        tangent_norm = np.linalg.norm(tangent)
        if tangent_norm <= 1e-12:
            return direction
        tangent /= tangent_norm
        normal = np.array([-tangent[1], tangent[0]], dtype=float)
        reflected = direction - 2.0 * np.dot(direction, normal) * normal
        norm = np.linalg.norm(reflected)
        if norm <= 1e-12:
            return direction
        return reflected / norm

    @staticmethod
    def _display_mirror_angle_deg(row: SurfaceRow) -> float:
        # KrakenOS TiltX projects with the opposite sign in the Z-Y folded
        # cross-section used by the 2D layout preview.
        return -float(row.tilt_x)

    @staticmethod
    def _mirror_line_angle_deg(
        row: SurfaceRow,
        mirror_tangent: np.ndarray | None = None,
    ) -> float:
        if mirror_tangent is not None:
            tangent = np.asarray(mirror_tangent, dtype=float)
            if tangent.shape == (2,) and np.linalg.norm(tangent) > 1e-12:
                return float(np.rad2deg(np.arctan2(tangent[1], tangent[0])))
        return KrakenLayoutEditor._display_mirror_angle_deg(row)

    @staticmethod
    def _snap_display_direction(direction: np.ndarray, tolerance: float = 0.03) -> np.ndarray:
        d = np.asarray(direction, dtype=float)
        norm = np.linalg.norm(d)
        if norm <= 1e-12:
            return np.array([0.0, 1.0], dtype=float)
        d /= norm
        if abs(d[0]) <= tolerance:
            return np.array([0.0, 1.0 if d[1] >= 0.0 else -1.0], dtype=float)
        if abs(d[1]) <= tolerance:
            return np.array([1.0 if d[0] >= 0.0 else -1.0, 0.0], dtype=float)
        return d

    def _folded_initial_frame(self, orientation: str | None = None) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
        """Return display-space object point, chief direction, and transverse axis."""
        mode = orientation or self._current_display_orientation()
        point = np.array([0.0, 0.0], dtype=float)
        if mode == "Horizontal":
            direction = np.array([0.0, -1.0], dtype=float)
        else:
            direction = np.array([1.0, 0.0], dtype=float)
        tangent = np.array([-direction[1], direction[0]], dtype=float)
        return point, direction, tangent

    @classmethod
    def _folded_mirror_slant_deg_for_branch(
        cls,
        row: SurfaceRow,
        branch_dir: np.ndarray,
        *,
        orientation: str | None = None,
    ) -> float:
        branch = np.asarray(branch_dir, dtype=float)
        branch /= max(np.linalg.norm(branch), 1e-12)
        branch_angle = float(np.rad2deg(np.arctan2(branch[1], branch[0])))
        if orientation == "Horizontal":
            # Horizontal display is read left-to-right.  Flip the display slant
            # convention so a positive 45 deg mirror sends the folded path to
            # the right instead of back toward negative display X.
            return cls._normalize_mirror_slant_deg(branch_angle + 90.0 - float(row.tilt_x))
        return cls._normalize_mirror_slant_deg(branch_angle - 90.0 + float(row.tilt_x))

    @staticmethod
    def _intersect_ray_with_line(
        origin: np.ndarray,
        direction: np.ndarray,
        center: np.ndarray,
        line_angle_deg: float,
    ) -> tuple[np.ndarray | None, float | None]:
        theta = np.deg2rad(float(line_angle_deg))
        tangent = np.array([np.cos(theta), np.sin(theta)], dtype=float)
        matrix = np.column_stack((direction, -tangent))
        try:
            t_ray, t_line = np.linalg.solve(matrix, center - origin)
        except np.linalg.LinAlgError:
            return None, None
        if t_ray < 0:
            return None, None
        point = origin + direction * t_ray
        return point, float(t_line)

    @staticmethod
    def _glass_index_for_preview(name: str) -> float:
        glass = str(name).strip()
        key = glass.upper()
        if key in _PREVIEW_GLASS_INDEX_CACHE:
            return _PREVIEW_GLASS_INDEX_CACHE[key]
        parts = [part.strip() for part in glass.split(",")]
        compact = parts[0].upper() if parts else key
        if glass in {"", "AIR", "NULL"}:
            return 1.0
        if compact in {"", "AIR", "NULL"}:
            return 1.0
        if compact == "MIRROR":
            return 1.0
        if compact == "NVK" and len(parts) >= 2:
            try:
                value = float(parts[1])
                _PREVIEW_GLASS_INDEX_CACHE[key] = value
                return value
            except Exception:
                pass
        if compact == "___BLANK" and len(parts) >= 4:
            try:
                value = float(parts[3])
                _PREVIEW_GLASS_INDEX_CACHE[key] = value
                return value
            except Exception:
                pass
        alias = {
            "BK7": "H-K9L",
            "K9": "H-K9L",
            "FS": "F_SILICA",
            "SILICA": "F_SILICA",
        }.get(compact, compact)
        catalog_value = _glass_nd_vd_from_setup(alias)
        if catalog_value is not None:
            value = float(catalog_value[0])
            _PREVIEW_GLASS_INDEX_CACHE[key] = value
            return value
        fallback = {
            "BK7": 1.5168,
            "H-K9L": 1.5168,
            "F2": 1.6200,
            "FS": 1.4585,
            "F_SILICA": 1.4585,
            "SILICA": 1.4585,
            "ZF13": 1.78472,
            "H-ZF13": 1.78472,
        }.get(alias, 1.5)
        _PREVIEW_GLASS_INDEX_CACHE[key] = float(fallback)
        return float(fallback)

    @staticmethod
    def _intersect_ray_with_spherical_surface(
        origin: np.ndarray,
        direction: np.ndarray,
        vertex: np.ndarray,
        axis_dir: np.ndarray,
        radius: float,
    ) -> tuple[np.ndarray | None, float | None]:
        if abs(radius) <= 1e-9:
            return None, None
        axis = np.asarray(axis_dir, dtype=float)
        axis /= max(np.linalg.norm(axis), 1e-12)
        tangent = np.array([-axis[1], axis[0]], dtype=float)
        center = vertex + axis * float(radius)
        oc = origin - center
        a = float(np.dot(direction, direction))
        b = 2.0 * float(np.dot(direction, oc))
        c = float(np.dot(oc, oc) - radius * radius)
        disc = b * b - 4.0 * a * c
        if disc < 0.0:
            return None, None
        root = np.sqrt(disc)
        candidates = [(-b - root) / (2.0 * a), (-b + root) / (2.0 * a)]
        candidates = [t for t in candidates if t >= 1e-9]
        if not candidates:
            return None, None
        t_ray = min(candidates)
        point = origin + direction * t_ray
        local = point - vertex
        return point, float(np.dot(local, tangent))

    @staticmethod
    def _intersect_ray_with_plane(
        origin: np.ndarray,
        direction: np.ndarray,
        center: np.ndarray,
        axis_dir: np.ndarray,
    ) -> tuple[np.ndarray | None, float | None]:
        axis = np.asarray(axis_dir, dtype=float)
        axis /= max(np.linalg.norm(axis), 1e-12)
        tangent = np.array([-axis[1], axis[0]], dtype=float)
        angle = np.rad2deg(np.arctan2(tangent[1], tangent[0]))
        return KrakenLayoutEditor._intersect_ray_with_line(origin, direction, center, angle)

    @staticmethod
    def _refract_ray_2d(direction: np.ndarray, normal: np.ndarray, n_before: float, n_after: float) -> np.ndarray:
        d = np.asarray(direction, dtype=float)
        d /= max(np.linalg.norm(d), 1e-12)
        n = np.asarray(normal, dtype=float)
        n /= max(np.linalg.norm(n), 1e-12)
        if np.dot(d, n) > 0.0:
            n = -n
        eta = float(n_before) / float(n_after)
        cos_i = -float(np.dot(n, d))
        k = 1.0 - eta * eta * (1.0 - cos_i * cos_i)
        if k < 0.0:
            reflected = d + 2.0 * cos_i * n
            return reflected / max(np.linalg.norm(reflected), 1e-12)
        refracted = eta * d + (eta * cos_i - np.sqrt(k)) * n
        return refracted / max(np.linalg.norm(refracted), 1e-12)

    def _compute_folded_layout_geometry(self):
        return self._compute_folded_layout_geometry_for_rows(self.rows, orientation=self._current_display_orientation())

    def _compute_folded_layout_geometry_for_rows(
        self,
        rows: list[SurfaceRow],
        *,
        orientation: str | None = None,
    ):
        point, direction, tangent0 = self._folded_initial_frame(orientation)
        max_half = max((max(row.diameter / 2.0, 0.5) for row in rows), default=1.0)
        extent_points = [point.copy()]
        elements: list[tuple[str, np.ndarray, SurfaceRow, np.ndarray]] = []
        if not rows:
            return point, direction, max_half, extent_points, elements
        display_orientation = orientation or self._current_display_orientation()

        current_dir = direction.copy()
        current_point = point + current_dir * max(float(rows[0].thickness), 0.0)
        extent_points.append(current_point.copy())

        for row_index, row in enumerate(rows[1:], start=1):
            travel = max(float(row.thickness), 0.0)
            branch_dir = current_dir / max(np.linalg.norm(current_dir), 1e-12)
            branch_tangent = np.array([-branch_dir[1], branch_dir[0]], dtype=float)
            center_point = current_point + branch_dir * float(row.desp_z) + branch_tangent * float(row.desp_y)
            if row.surface == "Image" and travel > 0.0:
                center_point = center_point + branch_dir * travel
                travel = 0.0

            mirror_tangent = None
            if row.surface == "Mirror":
                slant_angle = self._folded_mirror_slant_deg_for_branch(
                    row,
                    branch_dir,
                    orientation=display_orientation,
                )
                mirror_tangent = np.array(
                    [np.cos(np.deg2rad(slant_angle)), np.sin(np.deg2rad(slant_angle))],
                    dtype=float,
                )

            elements.append((row.surface, center_point.copy(), row, branch_dir.copy(), mirror_tangent, False))
            extent_points.append(center_point.copy())

            if row.surface == "Mirror":
                slant_angle = self._folded_mirror_slant_deg_for_branch(
                    row,
                    branch_dir,
                    orientation=display_orientation,
                )
                current_dir = self._snap_display_direction(self._reflect_2d(branch_dir, slant_angle))
            else:
                current_dir = branch_dir
            current_point = center_point + current_dir * travel
            extent_points.append(current_point.copy())

        _unused = tangent0
        return point, direction, max_half, extent_points, elements

    def _compute_world_folded_layout_geometry(self, *, system=None):
        return self._compute_world_folded_layout_geometry_for_rows(self.rows, system=system)

    def _compute_world_folded_layout_geometry_for_rows(self, rows: list[SurfaceRow], *, system=None):
        _unused = system
        return self._compute_folded_layout_geometry_for_rows(rows, orientation=self._current_display_orientation())

    def _world_folded_geometry_from_transforms(
        self,
        rows: list[SurfaceRow],
        trans: list,
        max_half: float,
    ):
        """Build folded geometry using the system's actual TRANS_2A transforms."""
        point = np.array([0.0, 0.0], dtype=float)
        direction = np.array([1.0, 0.0], dtype=float)
        extent_points: list[np.ndarray] = [point.copy()]
        elements: list[tuple[str, np.ndarray, SurfaceRow, np.ndarray]] = []

        for row_index, row in enumerate(rows):
            t = np.asarray(trans[row_index], dtype=float)
            # TRANS_2A is a 4×4 matrix; translation is in the last column.
            # World-space position in (Z, Y) for Vertical display:
            z_world = float(t[2, 3])
            y_world = float(t[1, 3])
            center = np.array([z_world, y_world], dtype=float)
            extent_points.append(center.copy())
            if row_index == 0:
                # Object row — skip (not in elements list)
                continue

            # Always compute t_prev for row_index >= 1 (used for both
            # last-surface branch_dir and mirror tangent computation).
            t_prev = np.asarray(trans[row_index - 1], dtype=float)

            # Determine the local propagation direction from consecutive
            # surface positions (finite difference).
            if row_index + 1 < len(rows):
                t_next = np.asarray(trans[row_index + 1], dtype=float)
                dz = float(t_next[2, 3]) - z_world
                dy = float(t_next[1, 3]) - y_world
                branch_dir = np.array([dz, dy], dtype=float)
                norm = np.linalg.norm(branch_dir)
                if norm > 1e-9:
                    branch_dir /= norm
                else:
                    branch_dir = direction.copy()
            else:
                # Last surface — use direction from previous surface
                dz = z_world - float(t_prev[2, 3])
                dy = y_world - float(t_prev[1, 3])
                branch_dir = np.array([dz, dy], dtype=float)
                norm = np.linalg.norm(branch_dir)
                branch_dir = branch_dir / norm if norm > 1e-9 else direction.copy()
            branch_dir = self._snap_display_direction(branch_dir)

            mirror_tangent = None
            if row.surface == "Mirror":
                slant_angle = self._mirror_display_slant_deg_for_rows(rows, row_index)
                mirror_tangent = np.array(
                    [np.cos(np.deg2rad(slant_angle)), np.sin(np.deg2rad(slant_angle))],
                    dtype=float,
                )

            elements.append((row.surface, center.copy(), row, branch_dir.copy(), mirror_tangent, False))

        return point, direction, max_half, extent_points, elements

    def _world_folded_preview_ray_paths(self, max_half: float) -> list[np.ndarray]:
        return self._world_folded_preview_ray_paths_for_rows(self.rows, max_half)

    def _world_folded_preview_ray_paths_for_rows(self, rows: list[SurfaceRow], max_half: float) -> list[np.ndarray]:
        if not rows or not any(row.surface == "Mirror" for row in rows):
            return []
        point, direction, _max_half, _extent_points, elements = self._compute_world_folded_layout_geometry_for_rows(rows)
        tangent0 = np.array([-direction[1], direction[0]], dtype=float)
        paths: list[np.ndarray] = []
        field_values = self._sample_field_values(
            self._current_field_angle_deg() if self._current_object_mode() == "Infinity" else self._current_field_height()
        )
        pupil_samples = self._sample_ray_heights(self._resolved_preview_pupil_radius(max_half))
        if self._current_object_mode() == "Infinity":
            for field_value in field_values:
                angle = np.deg2rad(float(field_value))
                d = np.cos(angle) * direction + np.sin(angle) * tangent0
                d /= max(np.linalg.norm(d), 1e-12)
                for pupil_y in pupil_samples:
                    origin = point + tangent0 * float(pupil_y)
                    path, _reached_image = self._trace_folded_preview_ray(origin, d, elements)
                    paths.append(np.asarray(path, dtype=float))
        else:
            object_distance = max(float(rows[0].thickness), 1e-9) if rows else 1.0
            for field_value in field_values:
                origin = point + tangent0 * float(field_value)
                for pupil_y in pupil_samples:
                    target = point + direction * object_distance + tangent0 * float(pupil_y)
                    d = target - origin
                    d /= max(np.linalg.norm(d), 1e-12)
                    path, _reached_image = self._trace_folded_preview_ray(origin, d, elements)
                    paths.append(np.asarray(path, dtype=float))
        return paths

    def _folded_preview_spot_rms_for_rows(self, rows: list[SurfaceRow]) -> float:
        point, direction, max_half, _extent_points, elements = self._compute_world_folded_layout_geometry_for_rows(rows)
        _unused = (point, direction)
        if not elements or elements[-1][0] != "Image":
            raise RuntimeError("Folded best-focus solve requires an Image row after the mirror")
        _surface_type, image_center, image_row, branch_dir, *_rest = elements[-1]
        tangent = np.array([-branch_dir[1], branch_dir[0]], dtype=float)
        tangent /= max(np.linalg.norm(tangent), 1e-12)
        half = max(float(image_row.diameter) / 2.0, 0.5)
        hits: list[float] = []
        for path in self._world_folded_preview_ray_paths_for_rows(rows, max_half):
            if path.shape[0] < 2:
                continue
            hit = np.asarray(path[-1], dtype=float)
            along = float(np.dot(hit - image_center, tangent))
            if abs(along) <= half + 1e-9:
                hits.append(along)
        if not hits:
            raise RuntimeError("No folded image-plane ray hits")
        values = np.asarray(hits, dtype=float)
        centered = values - float(np.mean(values))
        return float(np.sqrt(np.mean(centered * centered)))

    def _folded_plane_overrides(self) -> dict[int, tuple[np.ndarray, np.ndarray]]:
        if not self._can_build_folded_layout() or not self.rows:
            return {}
        point, direction, _max_half, _extent_points, elements = self._compute_folded_layout_geometry()
        overrides: dict[int, tuple[np.ndarray, np.ndarray]] = {0: (point.copy(), direction.copy())}
        for index, (surface_type, center, _row, branch_dir, *_rest) in enumerate(elements, start=1):
            if surface_type in {"Image", "Aperture"}:
                overrides[index] = (np.asarray(center, dtype=float).copy(), np.asarray(branch_dir, dtype=float).copy())
        return overrides

    def _world_folded_plane_overrides(self, *, system=None) -> dict[int, tuple[np.ndarray, np.ndarray]]:
        if not self.rows:
            return {}
        if not any(row.surface == "Mirror" for row in self.rows):
            return {}
        # Reuse the folded geometry (which uses TRANS_2A when available)
        try:
            geom = self._compute_world_folded_layout_geometry(system=system)
        except Exception:
            return {}
        if geom is None:
            return {}
        point, direction, _mh, _ep, elements = geom
        overrides: dict[int, tuple[np.ndarray, np.ndarray]] = {0: (point.copy(), direction.copy())}
        for index, (surface_type, center, _row, branch_dir, *_rest) in enumerate(elements, start=1):
            if surface_type in {"Image", "Aperture"}:
                overrides[index] = (np.asarray(center, dtype=float).copy(), np.asarray(branch_dir, dtype=float).copy())
        return overrides

    def _trace_folded_preview_ray(
        self,
        origin: np.ndarray,
        initial_dir: np.ndarray,
        elements: list,
    ) -> tuple[list[np.ndarray], bool]:
        p = np.asarray(origin, dtype=float).copy()
        path = [p.copy()]
        current_dir = np.asarray(initial_dir, dtype=float).copy()
        current_medium = 1.0
        reached_image = False
        for surface_type, center, row, branch_dir, *_rest in elements:
            if surface_type == "Mirror":
                mirror_tangent = _rest[0] if _rest else None
                reverse_reflection = bool(_rest[1]) if len(_rest) > 1 else False
                mirror_angle = self._mirror_line_angle_deg(row, mirror_tangent)
                hit, along = self._intersect_ray_with_line(p, current_dir, center, mirror_angle)
                if hit is None:
                    break
                half = max(row.diameter / 2.0, 0.5)
                if along is not None and abs(along) > half:
                    break
                if np.linalg.norm(hit - path[-1]) > 1e-9:
                    path.append(hit.copy())
                p = hit
                current_dir = self._reflect_2d(current_dir, mirror_angle)
                if reverse_reflection:
                    current_dir = -current_dir
            elif surface_type == "Standard":
                if abs(float(row.rc)) <= 1e-9:
                    hit, along = self._intersect_ray_with_plane(p, current_dir, center, branch_dir)
                    normal = np.asarray(branch_dir, dtype=float)
                else:
                    hit, along = self._intersect_ray_with_spherical_surface(
                        p, current_dir, center, branch_dir, float(row.rc)
                    )
                    if hit is not None:
                        axis = branch_dir / max(np.linalg.norm(branch_dir), 1e-12)
                        sphere_center = center + axis * float(row.rc)
                        normal = hit - sphere_center
                    else:
                        normal = np.asarray(branch_dir, dtype=float)
                if hit is None:
                    break
                half = max(row.diameter / 2.0, 0.5)
                if along is not None and abs(along) > half:
                    break
                if np.linalg.norm(hit - path[-1]) > 1e-9:
                    path.append(hit.copy())
                next_medium = self._glass_index_for_preview(row.glass)
                current_dir = self._refract_ray_2d(current_dir, normal, current_medium, next_medium)
                current_medium = next_medium
                p = hit
            elif surface_type in {"Image", "Aperture"}:
                tangent = np.array([-branch_dir[1], branch_dir[0]], dtype=float)
                angle = np.rad2deg(np.arctan2(tangent[1], tangent[0]))
                hit, along = self._intersect_ray_with_line(p, current_dir, center, angle)
                if hit is None:
                    break
                half = max(row.diameter / 2.0, 0.5)
                if surface_type != "Image" and along is not None and abs(along) > half:
                    break
                if np.linalg.norm(hit - path[-1]) > 1e-9:
                    path.append(hit.copy())
                p = hit
                if surface_type == "Image":
                    reached_image = True
                    break
        return path, reached_image

    def _preview_ray_start_specs(self, max_half: float, *, system=None) -> list[tuple[np.ndarray, np.ndarray]]:
        point, direction, tangent0 = self._folded_initial_frame("Horizontal")
        starts: list[tuple[np.ndarray, np.ndarray]] = []
        field_values = self._sample_field_values(
            self._current_field_angle_deg() if self._current_object_mode() == "Infinity" else self._current_field_height()
        )
        pupil_samples = self._sample_ray_heights(
            self._resolved_preview_pupil_radius(
                max_half,
                system=system,
            )
        )
        if self._current_object_mode() == "Infinity":
            for field_value in field_values:
                angle = np.deg2rad(float(field_value))
                d = np.cos(angle) * direction + np.sin(angle) * tangent0
                d /= max(np.linalg.norm(d), 1e-12)
                for pupil_y in pupil_samples:
                    origin = point + tangent0 * float(pupil_y)
                    starts.append((origin, d.copy()))
        else:
            object_distance = max(float(self.rows[0].thickness), 1e-9) if self.rows else 1.0
            for field_value in field_values:
                origin = point + tangent0 * float(field_value)
                for pupil_y in pupil_samples:
                    target = point + direction * object_distance + tangent0 * float(pupil_y)
                    d = target - origin
                    d /= max(np.linalg.norm(d), 1e-12)
                    starts.append((origin.copy(), d))
        return starts

    def _world_preview_ray_start_specs(self, max_half: float, *, system=None) -> list[tuple[np.ndarray, np.ndarray]]:
        point, direction, tangent0 = self._folded_initial_frame("Vertical")
        starts: list[tuple[np.ndarray, np.ndarray]] = []
        field_values = self._sample_field_values(
            self._current_field_angle_deg() if self._current_object_mode() == "Infinity" else self._current_field_height()
        )
        pupil_samples = self._sample_ray_heights(
            self._resolved_preview_pupil_radius(
                max_half,
                system=system,
            )
        )
        if self._current_object_mode() == "Infinity":
            for field_value in field_values:
                angle = np.deg2rad(float(field_value))
                d = np.cos(angle) * direction + np.sin(angle) * tangent0
                d /= max(np.linalg.norm(d), 1e-12)
                for pupil_y in pupil_samples:
                    origin = point + tangent0 * float(pupil_y)
                    starts.append((origin, d.copy()))
        else:
            object_distance = max(float(self.rows[0].thickness), 1e-9) if self.rows else 1.0
            for field_value in field_values:
                origin = point + tangent0 * float(field_value)
                for pupil_y in pupil_samples:
                    target = point + direction * object_distance + tangent0 * float(pupil_y)
                    d = target - origin
                    d /= max(np.linalg.norm(d), 1e-12)
                    starts.append((origin.copy(), d))
        return starts

    def _folded_display_ray_paths_for_elements(
        self,
        max_half: float,
        elements,
        *,
        orientation: str | None = None,
        system=None,
    ) -> list[np.ndarray]:
        if elements is None:
            return []
        point, direction, tangent0 = self._folded_initial_frame(orientation)
        source_starts = self._folded_source_display_start_specs(orientation=orientation)
        if source_starts is not None:
            paths = []
            for origin, ray_dir in source_starts:
                path, _reached_image = self._trace_folded_preview_ray(origin, ray_dir, elements)
                paths.append(np.asarray(path, dtype=float))
            return paths
        pupil_radius = self._resolved_preview_pupil_radius(max_half, system=system)
        pupil_samples = self._sample_ray_heights(pupil_radius)
        field_values = self._sample_field_values(
            self._current_field_angle_deg() if self._current_object_mode() == "Infinity" else self._current_field_height()
        )
        paths: list[np.ndarray] = []
        if self._current_object_mode() == "Infinity":
            for field_value in field_values:
                angle = np.deg2rad(float(field_value))
                chief_dir = np.cos(angle) * direction + np.sin(angle) * tangent0
                chief_dir /= max(np.linalg.norm(chief_dir), 1e-12)
                for pupil_y in pupil_samples:
                    origin = point + tangent0 * float(pupil_y)
                    path, _reached_image = self._trace_folded_preview_ray(origin, chief_dir, elements)
                    paths.append(np.asarray(path, dtype=float))
                # Keep parity with the native off-axis preview, which traces a
                # second orthogonal fan.  In this 2-D section that fan projects
                # to the chief ray, so it intentionally overlays the center path.
                for _pupil_x in pupil_samples:
                    path, _reached_image = self._trace_folded_preview_ray(point.copy(), chief_dir, elements)
                    paths.append(np.asarray(path, dtype=float))
        else:
            object_distance = max(float(self.rows[0].thickness), 1e-9) if self.rows else 1.0
            for field_value in field_values:
                origin_base = point + tangent0 * float(field_value)
                for pupil_y in pupil_samples:
                    target = point + direction * object_distance + tangent0 * float(pupil_y)
                    ray_dir = target - origin_base
                    ray_dir /= max(np.linalg.norm(ray_dir), 1e-12)
                    path, _reached_image = self._trace_folded_preview_ray(origin_base, ray_dir, elements)
                    paths.append(np.asarray(path, dtype=float))
                for _pupil_x in pupil_samples:
                    target = point + direction * object_distance
                    ray_dir = target - origin_base
                    ray_dir /= max(np.linalg.norm(ray_dir), 1e-12)
                    path, _reached_image = self._trace_folded_preview_ray(origin_base, ray_dir, elements)
                    paths.append(np.asarray(path, dtype=float))
        return paths

    def _build_element_display_paths(
        self,
        rays,
        elements,
        starts: list[tuple[np.ndarray, np.ndarray]],
    ) -> list[np.ndarray]:
        if elements is None:
            return []
        element_map = {index + 1: item for index, item in enumerate(elements)}
        paths: list[np.ndarray] = []
        for ray_index, surface_ids_raw in enumerate(rays.SURFACE):
            if ray_index >= len(starts):
                break
            origin, current_dir = starts[ray_index]
            current_point = np.asarray(origin, dtype=float).copy()
            current_medium = 1.0
            path = [current_point.copy()]
            surface_ids = [int(v) for v in np.asarray(surface_ids_raw, dtype=int).ravel().tolist()]
            last_id: int | None = None
            for surface_index in surface_ids:
                if surface_index == last_id:
                    continue
                element = element_map.get(surface_index)
                if element is None:
                    continue
                surface_type, center, row, branch_dir, *_rest = element
                success = False
                if surface_type == "Mirror":
                    mirror_tangent = _rest[0] if _rest else None
                    reverse_reflection = bool(_rest[1]) if len(_rest) > 1 else False
                    mirror_angle = self._mirror_line_angle_deg(row, mirror_tangent)
                    hit, along = self._intersect_ray_with_line(current_point, current_dir, center, mirror_angle)
                    if hit is None:
                        break
                    half = max(row.diameter / 2.0, 0.5)
                    if along is not None and abs(along) > half:
                        break
                    if np.linalg.norm(hit - path[-1]) > 1e-9:
                        path.append(hit.copy())
                    current_point = hit
                    current_dir = self._reflect_2d(current_dir, mirror_angle)
                    if reverse_reflection:
                        current_dir = -current_dir
                    success = True
                elif surface_type == "Standard":
                    if abs(float(row.rc)) <= 1e-9:
                        hit, along = self._intersect_ray_with_plane(current_point, current_dir, center, branch_dir)
                        normal = np.asarray(branch_dir, dtype=float)
                    else:
                        hit, along = self._intersect_ray_with_spherical_surface(
                            current_point, current_dir, center, branch_dir, float(row.rc)
                        )
                        if hit is not None:
                            axis = branch_dir / max(np.linalg.norm(branch_dir), 1e-12)
                            sphere_center = center + axis * float(row.rc)
                            normal = hit - sphere_center
                        else:
                            normal = np.asarray(branch_dir, dtype=float)
                    if hit is None:
                        break
                    half = max(row.diameter / 2.0, 0.5)
                    if along is not None and abs(along) > half:
                        break
                    if np.linalg.norm(hit - path[-1]) > 1e-9:
                        path.append(hit.copy())
                    next_medium = self._glass_index_for_preview(row.glass)
                    current_dir = self._refract_ray_2d(current_dir, normal, current_medium, next_medium)
                    current_medium = next_medium
                    current_point = hit
                    success = True
                elif surface_type in {"Image", "Aperture"}:
                    tangent = np.array([-branch_dir[1], branch_dir[0]], dtype=float)
                    angle = np.rad2deg(np.arctan2(tangent[1], tangent[0]))
                    hit, along = self._intersect_ray_with_line(current_point, current_dir, center, angle)
                    if hit is None:
                        break
                    half = max(row.diameter / 2.0, 0.5)
                    if surface_type != "Image" and along is not None and abs(along) > half:
                        break
                    if np.linalg.norm(hit - path[-1]) > 1e-9:
                        path.append(hit.copy())
                    current_point = hit
                    success = True
                    if surface_type == "Image":
                        last_id = surface_index
                        break
                if not success:
                    break
                last_id = surface_index
            if last_id is not None and 0 < last_id < len(elements):
                trailing = list(range(last_id + 1, len(elements) + 1))
                if trailing and all(elements[idx - 1][0] in {"Image", "Aperture"} for idx in trailing):
                    for surface_index in trailing:
                        surface_type, center, row, branch_dir, *_rest = element_map[surface_index]
                        tangent = np.array([-branch_dir[1], branch_dir[0]], dtype=float)
                        angle = np.rad2deg(np.arctan2(tangent[1], tangent[0]))
                        hit, along = self._intersect_ray_with_line(current_point, current_dir, center, angle)
                        if hit is None:
                            break
                        half = max(row.diameter / 2.0, 0.5)
                        if surface_type != "Image" and along is not None and abs(along) > half:
                            break
                        if np.linalg.norm(hit - path[-1]) > 1e-9:
                            path.append(hit.copy())
                        current_point = hit
                        if surface_type == "Image":
                            break
            paths.append(np.asarray(path, dtype=float))
        return paths

    def _folded_source_display_start_specs(
        self,
        *,
        orientation: str | None = None,
    ) -> list[tuple[np.ndarray, np.ndarray]] | None:
        if self._current_source_model() == SOURCE_MODEL_DEFAULT:
            return None
        try:
            source_bundle = self._build_random_source_bundle()
        except Exception as exc:
            self.append_debug(f"Folded source display fallback: {_short_error_message(exc)}")
            return None
        if source_bundle is None:
            return None
        _x_values, y_values, z_values, _l_values, m_values, n_values = (
            np.asarray(values, dtype=float).reshape(-1) for values in source_bundle
        )
        count = min(len(y_values), len(z_values), len(m_values), len(n_values))
        if count <= 0:
            return None
        mode = orientation or self._current_display_orientation()
        starts: list[tuple[np.ndarray, np.ndarray]] = []
        for index in range(count):
            if mode == "Horizontal":
                origin = np.array([-float(y_values[index]), -float(z_values[index])], dtype=float)
                direction = np.array([-float(m_values[index]), -float(n_values[index])], dtype=float)
            else:
                origin = np.array([float(z_values[index]), float(y_values[index])], dtype=float)
                direction = np.array([float(n_values[index]), float(m_values[index])], dtype=float)
            norm = float(np.linalg.norm(direction))
            if norm <= 1e-12:
                continue
            starts.append((origin, direction / norm))
        return starts or None

    def _build_mapped_display_paths_from_actual_hits(
        self,
        rays,
        elements,
        starts: list[tuple[np.ndarray, np.ndarray]],
        system,
    ) -> list[np.ndarray]:
        trans = getattr(system, "TRANS_2A", None)
        if trans is None:
            return self._build_element_display_paths(rays, elements, starts)
        element_map = {index + 1: item for index, item in enumerate(elements)}
        paths: list[np.ndarray] = []
        for ray_index, surface_ids_raw in enumerate(rays.SURFACE):
            if ray_index >= len(starts):
                break
            path = [np.asarray(starts[ray_index][0], dtype=float).copy()]
            previous_actual = path[-1].copy()
            surface_ids = [int(v) for v in np.asarray(surface_ids_raw, dtype=int).ravel().tolist()]
            hit_points = np.asarray(rays.CC[ray_index], dtype=float)
            if hit_points.ndim != 2 or hit_points.shape[0] < 2:
                paths.append(np.asarray(path, dtype=float))
                continue
            for surface_index, hit_world in zip(surface_ids, hit_points[1:]):
                element = element_map.get(surface_index)
                if element is None:
                    continue
                surface_type, center, _row, branch_dir, *_rest = element
                hit_actual = np.array([float(hit_world[2]), float(hit_world[1])], dtype=float)
                hit_display = hit_actual.copy()
                if surface_type in {"Mirror", "Image", "Aperture"} and surface_index < len(trans):
                    t = np.asarray(trans[surface_index], dtype=float)
                    actual_center = np.array([float(t[2, 3]), float(t[1, 3])], dtype=float)
                    actual_tangent = np.array([float(t[2, 1]), float(t[1, 1])], dtype=float)
                    actual_norm = np.linalg.norm(actual_tangent)
                    if actual_norm > 1e-12:
                        actual_tangent /= actual_norm
                        if surface_type == "Mirror" and _rest:
                            display_tangent = np.asarray(_rest[0], dtype=float).copy()
                        else:
                            display_tangent = np.array([-branch_dir[1], branch_dir[0]], dtype=float)
                        display_norm = np.linalg.norm(display_tangent)
                        if display_norm > 1e-12:
                            display_tangent /= display_norm
                            if np.dot(actual_tangent, display_tangent) < 0.0:
                                display_tangent = -display_tangent
                            along = float(np.dot(hit_display - actual_center, actual_tangent))
                            candidate_a = np.asarray(center, dtype=float) + display_tangent * along
                            candidate_b = np.asarray(center, dtype=float) - display_tangent * along
                            actual_dir = hit_actual - previous_actual
                            actual_dir_norm = np.linalg.norm(actual_dir)
                            if actual_dir_norm > 1e-12:
                                actual_dir /= actual_dir_norm
                                candidate_dirs = []
                                for candidate in (candidate_a, candidate_b):
                                    disp_dir = candidate - path[-1]
                                    disp_norm = np.linalg.norm(disp_dir)
                                    if disp_norm > 1e-12:
                                        disp_dir /= disp_norm
                                        candidate_dirs.append((float(np.dot(disp_dir, actual_dir)), candidate))
                                    else:
                                        candidate_dirs.append((-np.inf, candidate))
                                hit_display = max(candidate_dirs, key=lambda item: item[0])[1]
                            else:
                                hit_display = candidate_a
                if np.linalg.norm(hit_display - path[-1]) > 1e-9:
                    path.append(hit_display)
                previous_actual = hit_actual
                if surface_type == "Image":
                    break
            paths.append(np.asarray(path, dtype=float))
        return paths

    def _project_world_ray_paths_for_display(self, rays) -> list[np.ndarray]:
        paths: list[np.ndarray] = []
        for ray in getattr(rays, "CC", ()):
            pts = np.asarray(ray, dtype=float)
            if pts.ndim != 2 or pts.shape[0] < 2:
                paths.append(np.empty((0, 2), dtype=float))
                continue
            proj_x, proj_y = self._project_xy(pts[:, 2], pts[:, 1])
            paths.append(np.column_stack((proj_x, proj_y)))
        return paths

    def _display_path_overrides_for_current_layout(
        self,
        rays,
        max_half: float,
        *,
        folded_elements=None,
        folded_orientation: str | None = None,
        system=None,
    ) -> list[np.ndarray] | None:
        if folded_elements is not None:
            orientation = folded_orientation or self._current_display_orientation()
            return self._folded_display_ray_paths_for_elements(
                max_half,
                folded_elements,
                orientation=orientation,
                system=system,
            )
        if self._can_build_folded_layout():
            geom = self._compute_world_folded_layout_geometry(system=system)
            if geom is not None:
                return self._folded_display_ray_paths_for_elements(
                    max_half,
                    geom[-1],
                    orientation=self._current_display_orientation(),
                    system=system,
                )
        return None

    @staticmethod
    def _galvo_scan_overlay_values(row: SurfaceRow) -> list[float]:
        advanced = getattr(row, "advanced", {}) or {}
        if not isinstance(advanced, dict):
            return []
        display_settings = advanced.get("Display2D", {})
        if not isinstance(display_settings, dict):
            return []
        raw_values = display_settings.get(GALVO_SCAN_OVERLAY_KEY)
        if raw_values in (None, "", "None"):
            return []
        try:
            if isinstance(raw_values, str):
                return _parse_float_sequence_text(raw_values)
            if isinstance(raw_values, (int, float)):
                return [float(raw_values)]
            return _dedupe_float_values([float(value) for value in raw_values])
        except Exception:
            return []

    @staticmethod
    def _combined_plot_bounds(*bounds_items: BoundsRect | None) -> BoundsRect:
        points: list[np.ndarray] = []
        for bounds in bounds_items:
            if bounds is None or bounds.is_empty:
                continue
            points.append(
                np.asarray(
                    [
                        [float(bounds.x_min), float(bounds.y_min)],
                        [float(bounds.x_max), float(bounds.y_max)],
                    ],
                    dtype=float,
                )
            )
        return BoundsRect.from_points(points)

    def _draw_folded_scan_overlay(self, max_half: float, *, system=None) -> BoundsRect:
        if not self.rows or not self._can_build_folded_layout():
            return BoundsRect()
        scan_rows = [
            (index, self._galvo_scan_overlay_values(row))
            for index, row in enumerate(self.rows)
            if row.surface == "Mirror"
        ]
        scan_rows = [(index, values) for index, values in scan_rows if values]
        if not scan_rows:
            return BoundsRect()
        orientation = self._current_display_orientation()
        palette = ("#f97316", "#0ea5e9", "#e11d48", "#8b5cf6", "#14b8a6")
        ray_count_hint = max(1, int(getattr(self, "_preview_field_ray_count", 5) or 5))
        if ray_count_hint <= 9:
            overlay_linewidth = 1.1
            overlay_alpha = 0.92
        elif ray_count_hint <= 16:
            overlay_linewidth = 0.7
            overlay_alpha = 0.48
        else:
            overlay_linewidth = 0.55
            overlay_alpha = 0.32
        bounds_points: list[np.ndarray] = []
        try:
            # A galvo scan changes the reflected ray direction, not the fixed
            # downstream F-theta lens and detector geometry.
            _point, _direction, _mh, _extent_points, fixed_elements = self._compute_folded_layout_geometry_for_rows(
                self.rows,
                orientation=orientation,
            )
        except Exception as exc:
            self.append_debug(f"Galvo scan overlay geometry failed: {_short_error_message(exc)}")
            return BoundsRect()
        for mirror_index, values in scan_rows:
            display_values = self._mirror_overlay_display_slants_for_rows(self.rows, mirror_index)
            nominal_display_tilt = self._mirror_display_slant_deg_for_rows(self.rows, mirror_index)
            if not (0 < mirror_index <= len(fixed_elements)):
                continue
            mirror_surface, mirror_center, mirror_row, _incoming_dir, *_mirror_rest = fixed_elements[mirror_index - 1]
            if mirror_surface != "Mirror":
                continue
            downstream_elements = fixed_elements[mirror_index:]
            upstream_elements = fixed_elements[:mirror_index]
            pupil_radius = self._resolved_preview_pupil_radius(max_half, system=system)
            pupil_samples = self._sample_ray_heights(pupil_radius)
            source_starts = self._folded_source_display_start_specs(orientation=orientation)
            if source_starts is None:
                point, direction, tangent0 = self._folded_initial_frame(orientation)
                field_values = self._sample_field_values(
                    self._current_field_angle_deg()
                    if self._current_object_mode() == "Infinity"
                    else self._current_field_height()
                )
                source_starts = []
                if self._current_object_mode() == "Infinity":
                    for field_value in field_values:
                        angle = np.deg2rad(float(field_value))
                        chief_dir = np.cos(angle) * direction + np.sin(angle) * tangent0
                        chief_dir /= max(np.linalg.norm(chief_dir), 1e-12)
                        for pupil_y in pupil_samples:
                            source_starts.append((point + tangent0 * float(pupil_y), chief_dir.copy()))
                else:
                    object_distance = max(float(self.rows[0].thickness), 1e-9) if self.rows else 1.0
                    for field_value in field_values:
                        origin_base = point + tangent0 * float(field_value)
                        for pupil_y in pupil_samples:
                            target = point + direction * object_distance + tangent0 * float(pupil_y)
                            ray_dir = target - origin_base
                            ray_dir /= max(np.linalg.norm(ray_dir), 1e-12)
                            source_starts.append((origin_base.copy(), ray_dir))
            incoming_states = []
            for start_point, start_dir in source_starts:
                nominal_path, _reached = self._trace_folded_preview_ray(start_point, start_dir, upstream_elements)
                if len(nominal_path) < 2:
                    continue
                previous = np.asarray(nominal_path[-2], dtype=float)
                nominal_hit = np.asarray(nominal_path[-1], dtype=float)
                ray_dir = nominal_hit - previous
                ray_norm = np.linalg.norm(ray_dir)
                if ray_norm <= 1e-12:
                    continue
                incoming_states.append((previous, ray_dir / ray_norm))
            for value_index, tilt_x in enumerate(values[:25]):
                display_tilt = display_values[value_index] if value_index < len(display_values) else float(tilt_x)
                field_theta = 2.0 * (float(display_tilt) - float(nominal_display_tilt))
                draw_overlay_geometry = abs(field_theta) > 1e-9
                paths = []
                try:
                    for previous, ray_dir in incoming_states:
                        hit, along = self._intersect_ray_with_line(
                            previous,
                            ray_dir,
                            np.asarray(mirror_center, dtype=float),
                            float(display_tilt),
                        )
                        if hit is None:
                            continue
                        half = max(float(mirror_row.diameter) / 2.0, 0.5)
                        if along is not None and abs(along) > half:
                            continue
                        scan_dir = self._reflect_2d(ray_dir, float(display_tilt))
                        path, _reached_image = self._trace_folded_preview_ray(hit, scan_dir, downstream_elements)
                        paths.append(np.asarray(path, dtype=float))
                except Exception as exc:
                    self.append_debug(f"Galvo scan overlay failed for TiltX={tilt_x:g}: {_short_error_message(exc)}")
                    continue
                color = palette[value_index % len(palette)]
                for path in paths:
                    pts = np.asarray(path, dtype=float)
                    if pts.ndim != 2 or pts.shape[0] < 2:
                        continue
                    bounds_points.append(pts)
                    if not draw_overlay_geometry:
                        continue
                    self.ax.plot(
                        pts[:, 0],
                        pts[:, 1],
                        color=color,
                        linewidth=overlay_linewidth,
                        alpha=overlay_alpha,
                        zorder=24.0,
                    )
                if draw_overlay_geometry:
                    tangent = np.array([np.cos(np.deg2rad(float(display_tilt))), np.sin(np.deg2rad(float(display_tilt)))], dtype=float)
                    tangent /= max(np.linalg.norm(tangent), 1e-12)
                    half = max(float(mirror_row.diameter) / 2.0, 0.5)
                    line = np.vstack(
                        (
                            np.asarray(mirror_center, dtype=float) - tangent * half,
                            np.asarray(mirror_center, dtype=float) + tangent * half,
                        )
                    )
                    bounds_points.append(line)
                    self.ax.plot(
                        line[:, 0],
                        line[:, 1],
                        color=color,
                        linewidth=1.5,
                        linestyle=(0, (4, 2)),
                        alpha=0.78,
                        zorder=58.0,
                    )
                hits = [np.asarray(path[-1], dtype=float) for path in paths if np.asarray(path).ndim == 2 and len(path) >= 2]
                if hits:
                    hit = np.mean(np.vstack(hits), axis=0)
                    bounds_points.append(np.asarray([hit], dtype=float))
                    prev_hits = [
                        np.asarray(path[-2], dtype=float)
                        for path in paths
                        if np.asarray(path).ndim == 2 and len(path) >= 2
                    ]
                    if prev_hits:
                        previous = np.mean(np.vstack(prev_hits), axis=0)
                        final_dir = hit - previous
                        final_dir /= max(np.linalg.norm(final_dir), 1e-12)
                        label_point = hit - final_dir * 12.0
                    else:
                        label_point = hit + np.array([0.0, 5.0], dtype=float)
                    bounds_points.append(np.asarray([label_point], dtype=float))
                    self.ax.text(
                        float(label_point[0]),
                        float(label_point[1]),
                        f"theta={field_theta:g} deg",
                        fontsize=7,
                        color=color,
                        ha="center",
                        va="center",
                        zorder=62.0,
                        bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.72, "pad": 0.25},
                    )
        return BoundsRect.from_points(bounds_points)

    # _build_current_display_ray_paths removed — now in scene_builder + scene_projector
    # _draw_reference_plane_labels removed — now in scene_builder + scene_renderer_2d

    def _clear_cardinal_marker_artists(self) -> None:
        for artist in self._cardinal_marker_artists:
            try:
                artist.remove()
            except Exception:
                pass
        self._cardinal_marker_artists.clear()

    def _on_toggle_cardinal_markers(self) -> None:
        self._clear_cardinal_marker_artists()
        if not self.show_cardinals_var.get():
            self.canvas.draw_idle()
            self.status_var.set("PP / EP / XP hidden")
            return

        if self._last_optics_info is None and self.last_system is not None and self.last_rays is not None:
            try:
                with warnings.catch_warnings():
                    warnings.simplefilter("ignore", RuntimeWarning)
                    self._last_optics_info = self._collect_optics_info(
                        self.last_system,
                        self.last_rays,
                        self._current_wavelength(),
                    )
            except Exception:
                self._last_optics_info = None

        if self._last_optics_info is None:
            self.canvas.draw_idle()
            self.status_var.set("PP / EP / XP unavailable for current view")
            return

        self._draw_optics_markers(self._last_optics_info)
        self.canvas.draw_idle()
        self.status_var.set("PP / EP / XP updated")
        self._autosave_plot()

    def _draw_optics_markers(self, optics_info: dict) -> None:
        self._clear_cardinal_marker_artists()
        if not self.show_cardinals_var.get():
            return
        if bool(self._resolved_trace_mode().get("use_folded")) and self._draw_folded_optics_markers(optics_info):
            return
        x0, x1 = self.ax.get_xlim()
        y0, y1 = self.ax.get_ylim()
        x_min, x_max = min(x0, x1), max(x0, x1)
        y_min, y_max = min(y0, y1), max(y0, y1)
        span_x = max(x_max - x_min, 1e-9)
        span_y = max(y_max - y_min, 1e-9)
        marker_specs = [
            ("Front PP", optics_info.get("h1_z"), None, "#ff9f1c"),
            ("Back PP", optics_info.get("h2_z"), None, "#ff9f1c"),
            ("EP", optics_info.get("ep_z"), optics_info.get("ep_radius"), "#00bcd4"),
            ("XP", optics_info.get("xp_z"), optics_info.get("xp_radius"), "#e91e63"),
        ]

        visible_markers = []
        for label, z_pos, half_length, color in marker_specs:
            if z_pos is None:
                continue
            z_val = float(z_pos)
            if self._current_display_orientation() == "Horizontal":
                _, y_vals = self._project_xy([z_val, z_val], [0.0, 0.0])
                y_mark = float(y_vals[0])
                if y_mark < y_min or y_mark > y_max:
                    continue
                visible_markers.append((label, z_val, half_length, color))
            else:
                if z_val < x_min or z_val > x_max:
                    continue
                visible_markers.append((label, z_val, half_length, color))

        cap_half = max(0.8, min(0.025 * span_x, 0.035 * span_y))
        for index, (label, marker_pos, half_length, color) in enumerate(visible_markers):
            use_extent = (
                label in {"EP", "XP"}
                and half_length is not None
                and np.isfinite(float(half_length))
                and float(half_length) > 1e-9
            )
            if self._current_display_orientation() == "Horizontal":
                z_mark = float(marker_pos)
                if use_extent:
                    seg_x, seg_y = self._project_xy(
                        [z_mark, z_mark],
                        [-float(half_length), float(half_length)],
                    )
                    p0 = np.array([float(seg_x[0]), float(seg_y[0])], dtype=float)
                    p1 = np.array([float(seg_x[1]), float(seg_y[1])], dtype=float)
                    artists = self._draw_cardinal_extent_marker(
                        p0,
                        p1,
                        color,
                        cap_half=cap_half,
                    )
                    y_mark = 0.5 * (p0[1] + p1[1])
                else:
                    _, y_vals = self._project_xy([z_mark, z_mark], [0.0, 0.0])
                    y_mark = float(y_vals[0])
                    artists = [
                        self.ax.axhline(y_mark, color=color, linewidth=1.0, linestyle=":", alpha=0.9, zorder=70.0)
                    ]
                x_label = x_min + (0.04 + 0.10 * (index % 4)) * span_x
                y_offsets = (0.015, 0.055, -0.035, 0.095)
                y_label = y_mark + y_offsets[index % len(y_offsets)] * span_y
                y_label = min(max(y_label, y_min + 0.04 * span_y), y_max - 0.04 * span_y)
                text = self.ax.text(
                    x_label,
                    y_label,
                    label,
                    color=color,
                    fontsize=8,
                    ha="left",
                    va="bottom",
                    zorder=71.0,
                    bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.65, "pad": 0.6},
                )
                self._cardinal_marker_artists.extend((*artists, text))
            else:
                z_val = float(marker_pos)
                if use_extent:
                    seg_x, seg_y = self._project_xy(
                        [z_val, z_val],
                        [-float(half_length), float(half_length)],
                    )
                    p0 = np.array([float(seg_x[0]), float(seg_y[0])], dtype=float)
                    p1 = np.array([float(seg_x[1]), float(seg_y[1])], dtype=float)
                    artists = self._draw_cardinal_extent_marker(
                        p0,
                        p1,
                        color,
                        cap_half=cap_half,
                    )
                else:
                    artists = [
                        self.ax.axvline(z_val, color=color, linewidth=1.0, linestyle=":", alpha=0.9, zorder=70.0)
                    ]
                y_label = y_max - (0.10 + 0.065 * (index % 4)) * span_y
                text = self.ax.text(
                    z_val,
                    y_label,
                    label,
                    color=color,
                    fontsize=8,
                    ha="center",
                    va="top",
                    zorder=71.0,
                    bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.65, "pad": 0.6},
                )
                self._cardinal_marker_artists.extend((*artists, text))

    def _draw_arm_labels(self, projected) -> None:
        if self._draw_physical_ray_segment_labels(projected):
            return
        catalog = self._arm_catalog()
        if not catalog:
            return
        view_key = self._arm_key_for_view_label(str(self.arm_view_var.get() or ARM_VIEW_DEFAULT))
        palette = ("#0f766e", "#b45309", "#2563eb", "#be123c", "#6d28d9", "#047857")
        labeled_keys = self._draw_arm_ray_labels(projected, catalog, view_key, palette)
        key_to_entry = {entry["key"]: entry for entry in catalog}
        row_to_key: dict[int, str] = {}
        index = 1
        while index < len(self.rows) - 1:
            start, end = self._element_block_for_index(self.rows, index)
            key = self._arm_key_from_metadata(self._element_metadata(self.rows[start]))
            if key in key_to_entry:
                for row_index in range(start, end + 1):
                    row_to_key[row_index] = key
            index = max(end + 1, index + 1)
        if not row_to_key:
            return

        y0, y1 = self.ax.get_ylim()
        span_y = max(abs(float(y1) - float(y0)), 1.0)
        arm_points: dict[str, list[np.ndarray]] = {entry["key"]: [] for entry in catalog}
        for curve in getattr(projected, "curves", []):
            key = row_to_key.get(int(curve.row_index))
            if not key:
                continue
            pts = np.asarray(curve.points_2d, dtype=float)
            if pts.ndim != 2 or pts.shape[0] < 2:
                continue
            finite = np.isfinite(pts[:, 0]) & np.isfinite(pts[:, 1])
            if np.any(finite):
                arm_points[key].append(np.mean(pts[finite], axis=0))

        for index, entry in enumerate(catalog):
            if view_key and entry["key"] != view_key:
                continue
            if entry["key"] in labeled_keys:
                continue
            points = arm_points.get(entry["key"]) or []
            if not points:
                continue
            center = np.mean(np.vstack(points), axis=0)
            detail = entry["detail"]
            label = entry["short_label"] if not detail else f"{entry['short_label']}\n{detail}"
            y_offset = (0.035 + 0.018 * (index % 3)) * span_y
            color = palette[index % len(palette)]
            self.ax.text(
                float(center[0]),
                float(center[1]) + y_offset,
                label,
                color=color,
                fontsize=8,
                ha="center",
                va="bottom",
                zorder=72.0,
                clip_on=True,
                bbox={
                    "facecolor": "white",
                    "edgecolor": color,
                    "alpha": 0.78,
                    "boxstyle": "round,pad=0.25",
                    "linewidth": 0.8,
                },
            )

    def _projected_scene_for_layout_render(self, projected: ProjectedScene2D) -> ProjectedScene2D:
        if not self._uses_michelson_leg_workflow():
            return projected
        return ProjectedScene2D(
            curves=list(projected.curves),
            rays=list(projected.rays),
            planes=list(projected.planes),
            labels=[],
            pick_regions=list(projected.pick_regions),
            bounds=projected.bounds,
        )

    def _plot_leg_label_text(self, leg_id: str, short_label: str, detail: str) -> str:
        workflow = self._physical_leg_workflow()
        compact_labels = {
            "michelson": {
                "input": "P1 Input",
                "transmit": "P2 Transmit",
                "reflect": "P3 Reflect",
                "detector": "P4 Detector",
            },
            "mach_zehnder": {
                "input": "P1 Input",
                "transmit": "P2 BS1-BS2 T",
                "reflect": "P3 BS1-BS2 R",
                "cross": "P4 Output A",
                "return": "P5 Output B",
            },
        }
        text = compact_labels.get(workflow, {}).get(str(leg_id or "").strip().lower())
        if text:
            return text
        detail_text = str(detail or "").strip()
        short_text = str(short_label or "Path").strip()
        if detail_text and len(detail_text) <= 18:
            return f"{short_text}: {detail_text}"
        return short_text

    def _projected_center_for_row(self, projected, row_index: int) -> np.ndarray | None:
        if 0 <= row_index < len(self.rows):
            display_settings = (self.rows[row_index].advanced or {}).get("Display2D", {})
            if isinstance(display_settings, dict):
                center_value = display_settings.get("plane_center")
                try:
                    center = np.asarray(center_value, dtype=float).ravel()
                except Exception:
                    center = np.empty(0, dtype=float)
                if center.size >= 2 and np.all(np.isfinite(center[:2])):
                    return np.asarray(center[:2], dtype=float)
        points: list[np.ndarray] = []
        for curve in getattr(projected, "curves", []) or []:
            if int(getattr(curve, "row_index", -1)) != int(row_index):
                continue
            curve_points = np.asarray(getattr(curve, "points_2d", []), dtype=float)
            if curve_points.ndim != 2 or curve_points.shape[0] < 1:
                continue
            finite = np.isfinite(curve_points[:, 0]) & np.isfinite(curve_points[:, 1])
            if np.any(finite):
                points.append(curve_points[finite])
        if points:
            return np.mean(np.vstack(points), axis=0)
        return None

    def _first_row_index_matching(self, predicate) -> int | None:
        for index, row in enumerate(self.rows):
            try:
                if predicate(index, row):
                    return index
            except Exception:
                continue
        return None

    @staticmethod
    def _leg_geometry_from_points(points: list[np.ndarray]) -> dict[str, object] | None:
        clean_points: list[np.ndarray] = []
        for point in points:
            arr = np.asarray(point, dtype=float).ravel()
            if arr.size >= 2 and np.all(np.isfinite(arr[:2])):
                clean_points.append(np.asarray(arr[:2], dtype=float))
        if len(clean_points) < 2:
            return None
        segments: list[tuple[np.ndarray, np.ndarray]] = []
        total_length = 0.0
        for p0, p1 in zip(clean_points[:-1], clean_points[1:]):
            length = float(np.linalg.norm(p1 - p0))
            if length <= 1e-9:
                continue
            segments.append((p0, p1))
            total_length += length
        if not segments:
            return None
        first = segments[0][0]
        last = segments[-1][1]
        vector = last - first
        length = float(np.linalg.norm(vector))
        unit = vector / length if length > 1e-9 else (segments[0][1] - segments[0][0]) / max(float(np.linalg.norm(segments[0][1] - segments[0][0])), 1e-12)
        return {
            "points": clean_points,
            "segments": segments,
            "hub": first,
            "endpoint": last,
            "unit": unit,
            "length": np.asarray([total_length], dtype=float),
        }

    @staticmethod
    def _leg_geometry_point_at_fraction(leg: dict[str, object], fraction: float) -> np.ndarray | None:
        segments = list(leg.get("segments", []) or [])
        if not segments:
            return None
        lengths = [float(np.linalg.norm(np.asarray(p1, dtype=float) - np.asarray(p0, dtype=float))) for p0, p1 in segments]
        total = float(sum(lengths))
        if total <= 1e-9:
            return None
        target = min(max(float(fraction), 0.0), 1.0) * total
        accumulated = 0.0
        for (p0, p1), length in zip(segments, lengths):
            if length <= 1e-12:
                continue
            if accumulated + length >= target:
                local = (target - accumulated) / length
                return np.asarray(p0, dtype=float) + (np.asarray(p1, dtype=float) - np.asarray(p0, dtype=float)) * local
            accumulated += length
        return np.asarray(segments[-1][1], dtype=float)

    def _first_beam_splitter_indices(self) -> list[int]:
        return [index for index, row in enumerate(self.rows) if row.surface == BEAM_SPLITTER_SURFACE]

    def _first_detector_index_matching(self, predicate) -> int | None:
        return self._first_row_index_matching(
            lambda index, row: row.surface in {"Aperture", "Image", "Standard"} and predicate(index, row)
        )

    def _auto_leg_geometry(self) -> dict[str, dict[str, object]]:
        geometry: dict[str, dict[str, object]] = {}
        for entry in self._auto_leg_entries():
            leg_id = str(entry.get("leg_id", "") or "").strip().lower()
            polyline = np.asarray(entry.get("polyline", []), dtype=float)
            if not leg_id or polyline.ndim != 2 or polyline.shape[0] < 2:
                continue
            leg = self._leg_geometry_from_points([point for point in polyline])
            if leg is not None:
                geometry[leg_id] = leg
        return geometry

    def _michelson_leg_geometry(self, projected) -> dict[str, dict[str, object]]:
        if not self._uses_michelson_leg_workflow() or not self.rows:
            return {}
        workflow = self._physical_leg_workflow()
        if workflow not in {"mach_zehnder", "michelson"}:
            return self._auto_leg_geometry()
        splitter_indices = self._first_beam_splitter_indices()
        splitter_index = splitter_indices[0] if splitter_indices else None
        if splitter_index is None:
            return {}
        hub = self._projected_center_for_row(projected, splitter_index)
        if hub is None:
            return {}

        def row_selector(row: SurfaceRow) -> str:
            return str(self._element_metadata(row).get("branch_selector", "") or "").strip().lower()

        def row_role(row: SurfaceRow) -> str:
            return str(self._element_metadata(row).get("arm_role", ELEMENT_ARM_ROLE_DEFAULT) or ELEMENT_ARM_ROLE_DEFAULT)

        if workflow == "mach_zehnder":
            bs2_index = splitter_indices[1] if len(splitter_indices) >= 2 else None
            bs2 = self._projected_center_for_row(projected, bs2_index) if bs2_index is not None else None
            if bs2 is None:
                return {}
            transmit_mirror_index = self._first_row_index_matching(
                lambda _index, row: row.surface == "Mirror"
                and (
                    row_selector(row) == "transmit"
                    or "transmit" in str(getattr(row, "name", "") or "").lower()
                    or "transmit" in str(getattr(row, "element", "") or "").lower()
                )
            )
            reflect_mirror_index = self._first_row_index_matching(
                lambda _index, row: row.surface == "Mirror"
                and (
                    row_selector(row) == "reflect"
                    or "reflect" in str(getattr(row, "name", "") or "").lower()
                    or "reflect" in str(getattr(row, "element", "") or "").lower()
                )
            )
            cross_detector_index = self._first_detector_index_matching(
                lambda _index, row: (
                    "cross" in str(getattr(row, "name", "") or "").lower()
                    or (
                        row_role(row) == "Detector"
                        and row_selector(row) == "transmit"
                    )
                )
            )
            return_detector_index = self._first_detector_index_matching(
                lambda _index, row: (
                    "return" in str(getattr(row, "name", "") or "").lower()
                    or (
                        row_role(row) == "Detector"
                        and row_selector(row) == "reflect"
                    )
                )
            )
            target_points: dict[str, list[np.ndarray]] = {
                "input": [self._projected_center_for_row(projected, 0), hub],
                "transmit": [
                    hub,
                    self._projected_center_for_row(projected, transmit_mirror_index)
                    if transmit_mirror_index is not None
                    else None,
                    bs2,
                ],
                "reflect": [
                    hub,
                    self._projected_center_for_row(projected, reflect_mirror_index)
                    if reflect_mirror_index is not None
                    else None,
                    bs2,
                ],
                "cross": [
                    bs2,
                    self._projected_center_for_row(projected, cross_detector_index)
                    if cross_detector_index is not None
                    else None,
                ],
                "return": [
                    bs2,
                    self._projected_center_for_row(projected, return_detector_index)
                    if return_detector_index is not None
                    else None,
                ],
            }
            geometry: dict[str, dict[str, object]] = {}
            for leg_id, points in target_points.items():
                leg = self._leg_geometry_from_points([point for point in points if point is not None])
                if leg is not None:
                    geometry[leg_id] = leg
            return geometry

        detector_index = self._first_row_index_matching(
            lambda _index, row: row.surface == "Image" and row_role(row) == "Detector"
        )
        if detector_index is None:
            detector_index = self._first_row_index_matching(
                lambda _index, row: row_role(row) == "Detector"
            )
        if detector_index is None:
            detector_index = self._first_row_index_matching(
                lambda _index, row: row.surface == "Image" and self._row_has_detector_output_metadata(row)
            )

        target_indices: dict[str, int | None] = {
            "input": 0,
            "reflect": self._first_row_index_matching(
                lambda _index, row: row.surface == "Mirror"
                and (
                    row_selector(row) == "reflect"
                    or "reflect" in str(getattr(row, "name", "") or "").lower()
                    or "reference" in str(getattr(row, "name", "") or "").lower()
                    or "reference" in str(getattr(row, "element", "") or "").lower()
                )
                and (row_role(row) in {"Reflect", "Return"} or row_selector(row) == "")
            ),
            "transmit": self._first_row_index_matching(
                lambda _index, row: row.surface == "Mirror"
                and (
                    row_selector(row) == "transmit"
                    or "transmit" in str(getattr(row, "name", "") or "").lower()
                    or "test optic" in str(getattr(row, "name", "") or "").lower()
                    or "test optic" in str(getattr(row, "element", "") or "").lower()
                )
                and (row_role(row) in {"Transmit", "Return"} or row_selector(row) == "")
            ),
            "detector": detector_index,
        }
        geometry: dict[str, dict[str, object]] = {}
        for leg_id, target_index in target_indices.items():
            if target_index is None:
                continue
            endpoint = self._projected_center_for_row(projected, target_index)
            if endpoint is None:
                continue
            leg = self._leg_geometry_from_points([hub, endpoint])
            if leg is not None:
                geometry[leg_id] = leg
        return geometry

    def _physical_ray_leg_segments(self, projected) -> tuple[dict[str, list[dict[str, object]]], np.ndarray] | None:
        if not self._uses_michelson_leg_workflow():
            return None
        rays = list(getattr(projected, "rays", []) or [])
        if not rays:
            return None
        geometry = self._michelson_leg_geometry(projected)
        if not geometry:
            return None

        finite_points: list[np.ndarray] = []
        for ray in rays:
            points = np.asarray(getattr(ray, "points_2d", []), dtype=float)
            if points.ndim == 2 and points.shape[0] >= 2:
                finite = np.isfinite(points[:, 0]) & np.isfinite(points[:, 1])
                if np.any(finite):
                    finite_points.append(points[finite])
        if not finite_points:
            return None
        all_points = np.vstack(finite_points)
        x_min, x_max = float(np.min(all_points[:, 0])), float(np.max(all_points[:, 0]))
        y_min, y_max = float(np.min(all_points[:, 1])), float(np.max(all_points[:, 1]))
        span_x = max(x_max - x_min, 1.0)
        span_y = max(y_max - y_min, 1.0)
        min_segment = max(0.25, 0.003 * min(span_x, span_y))
        raw_segments: list[dict[str, object]] = []
        for ray in rays:
            points = np.asarray(getattr(ray, "points_2d", []), dtype=float)
            if points.ndim != 2 or points.shape[0] < 2:
                continue
            finite = np.isfinite(points[:, 0]) & np.isfinite(points[:, 1])
            if not np.all(finite):
                points = points[finite]
            if points.shape[0] < 2:
                continue
            for index in range(points.shape[0] - 1):
                p0 = np.asarray(points[index], dtype=float)
                p1 = np.asarray(points[index + 1], dtype=float)
                length = float(np.linalg.norm(p1 - p0))
                if length <= min_segment:
                    continue
                raw_segments.append(
                    {
                        "ray": ray,
                        "p0": p0,
                        "p1": p1,
                        "length": length,
                    }
                )
        if not raw_segments:
            return None

        groups: dict[str, list[dict[str, object]]] = {leg_id: [] for leg_id, _short, _detail in self._physical_leg_definitions()}
        for segment in raw_segments:
            p0 = np.asarray(segment["p0"], dtype=float)
            p1 = np.asarray(segment["p1"], dtype=float)
            tangent = p1 - p0
            tangent_norm = float(np.linalg.norm(tangent))
            if tangent_norm <= min_segment:
                continue
            tangent = tangent / tangent_norm
            midpoint = 0.5 * (p0 + p1)
            best: tuple[float, str] | None = None
            for leg_id, leg in geometry.items():
                for seg0, seg1 in list(leg.get("segments", []) or []):
                    seg0 = np.asarray(seg0, dtype=float)
                    seg1 = np.asarray(seg1, dtype=float)
                    axis = seg1 - seg0
                    length = float(np.linalg.norm(axis))
                    if length <= 1e-9:
                        continue
                    unit = axis / length
                    offset = midpoint - seg0
                    projection = float(np.dot(offset, unit))
                    t = projection / max(length, 1e-12)
                    if t < -0.10 or t > 1.12:
                        continue
                    alignment = abs(float(np.dot(tangent, unit)))
                    if alignment < 0.45:
                        continue
                    perpendicular = float(np.linalg.norm(offset - unit * projection))
                    tolerance = max(3.0, 0.24 * min(length, 90.0))
                    if perpendicular > tolerance:
                        continue
                    score = perpendicular / tolerance + 0.25 * (1.0 - alignment)
                    if best is None or score < best[0]:
                        best = (score, leg_id)
            if best is None:
                continue
            leg_id = best[1]
            segment_with_leg = dict(segment)
            segment_with_leg["leg_id"] = leg_id
            groups[leg_id].append(segment_with_leg)

        groups = {leg_id: segments for leg_id, segments in groups.items() if segments}
        if not groups:
            return None
        first_leg = next(iter(geometry.values()))
        return groups, np.asarray(first_leg["hub"], dtype=float)

    def _draw_physical_ray_segment_labels(self, projected) -> bool:
        geometry = self._michelson_leg_geometry(projected)
        if not geometry:
            return False
        definitions = self._physical_leg_definitions()
        workflow = self._physical_leg_workflow()
        x0, x1 = self.ax.get_xlim()
        y0, y1 = self.ax.get_ylim()
        x_min, x_max = min(float(x0), float(x1)), max(float(x0), float(x1))
        y_min, y_max = min(float(y0), float(y1)), max(float(y0), float(y1))
        span_x = max(x_max - x_min, 1.0)
        span_y = max(y_max - y_min, 1.0)
        if workflow == "mach_zehnder":
            offsets = {
                "input": np.array([-0.020 * span_x, 0.060 * span_y], dtype=float),
                "transmit": np.array([0.030 * span_x, 0.060 * span_y], dtype=float),
                "reflect": np.array([-0.050 * span_x, -0.030 * span_y], dtype=float),
                "cross": np.array([0.050 * span_x, 0.050 * span_y], dtype=float),
                "return": np.array([0.055 * span_x, -0.020 * span_y], dtype=float),
            }
            marker_fraction = {
                "input": 0.45,
                "transmit": 0.28,
                "reflect": 0.62,
                "cross": 0.55,
                "return": 0.55,
            }
        elif workflow == "michelson":
            offsets = {
                "input": np.array([-0.020 * span_x, 0.060 * span_y], dtype=float),
                "reflect": np.array([0.075 * span_x, 0.000 * span_y], dtype=float),
                "transmit": np.array([0.030 * span_x, 0.055 * span_y], dtype=float),
                "detector": np.array([0.075 * span_x, -0.010 * span_y], dtype=float),
            }
            marker_fraction = {
                "input": 0.50,
                "reflect": 0.46,
                "transmit": 0.48,
                "detector": 0.72,
            }
        else:
            offsets = {}
            marker_fraction = {leg_id: 0.50 for leg_id, _short_label, _detail in definitions}
        view_leg_id = self._leg_id_from_arm_key(self._current_arm_view_key())
        drawn_any = False
        for leg_id, short_label, detail in definitions:
            if view_leg_id and leg_id != view_leg_id:
                continue
            leg = geometry.get(leg_id)
            if leg is None:
                continue
            fraction = float(marker_fraction.get(leg_id, 0.5))
            point = self._leg_geometry_point_at_fraction(leg, min(max(fraction, 0.05), 0.95))
            if point is None:
                continue
            if leg_id in offsets:
                offset = offsets[leg_id]
            else:
                direction = np.asarray(leg.get("unit", np.array([1.0, 0.0])), dtype=float).ravel()
                if direction.size < 2 or float(np.linalg.norm(direction[:2])) <= 1e-9:
                    direction = np.array([1.0, 0.0], dtype=float)
                direction = direction[:2] / max(float(np.linalg.norm(direction[:2])), 1e-12)
                normal = np.array([-direction[1], direction[0]], dtype=float)
                offset = normal * (0.055 * min(span_x, span_y)) + direction * (0.020 * min(span_x, span_y))
            text_point = point + offset
            text_point[0] = min(max(float(text_point[0]), x_min + 0.03 * span_x), x_max - 0.03 * span_x)
            text_point[1] = min(max(float(text_point[1]), y_min + 0.04 * span_y), y_max - 0.04 * span_y)
            label = self._plot_leg_label_text(leg_id, short_label, detail)
            self.ax.annotate(
                label,
                xy=(float(point[0]), float(point[1])),
                xytext=(float(text_point[0]), float(text_point[1])),
                color="#334155",
                fontsize=7.8,
                ha="center",
                va="center",
                zorder=82.0,
                clip_on=True,
                arrowprops={
                    "arrowstyle": "-|>",
                    "color": "#334155",
                    "linewidth": 0.85,
                    "alpha": 0.9,
                    "shrinkA": 3,
                    "shrinkB": 2,
                },
                bbox={
                    "facecolor": "white",
                    "edgecolor": "#334155",
                    "alpha": 0.86,
                    "boxstyle": "round,pad=0.22",
                    "linewidth": 0.75,
                },
            )
            self.ax.plot(
                [float(point[0])],
                [float(point[1])],
                marker="o",
                markersize=3.2,
                color="#111827",
                alpha=0.95,
                zorder=81.0,
            )
            drawn_any = True
        return drawn_any

    def _arm_ray_label_targets(self, projected, catalog: list[dict[str, str]], view_key: str = "") -> list[dict[str, object]]:
        targets: list[dict[str, object]] = []
        rays = list(getattr(projected, "rays", []) or [])
        if not rays:
            return targets
        for arm_index, entry in enumerate(catalog):
            arm_key = entry["key"]
            if view_key and arm_key != view_key:
                continue
            arm_indices = set(self._indices_for_arm_key(arm_key))
            target_path = self._branch_path_for_arm_key(arm_key)
            candidates: list[tuple[np.ndarray, np.ndarray]] = []
            for ray in rays:
                points = np.asarray(getattr(ray, "points_2d", []), dtype=float)
                if points.ndim != 2 or points.shape[0] < 2:
                    continue
                surface_ids = np.asarray(getattr(ray, "surface_ids", []), dtype=int).ravel()
                ray_matches_arm = self._ray_matches_arm_key(ray, arm_key)
                matching_hit_positions = [
                    hit_index
                    for hit_index, surface_id in enumerate(surface_ids.tolist())
                    if int(surface_id) in arm_indices
                ]
                if target_path:
                    if not ray_matches_arm:
                        continue
                    start_index = max(0, points.shape[0] - 2)
                    end_index = points.shape[0] - 1
                    selector_code = "".join(self._branch_path_selector_sequence(target_path))[-2:]
                    marker_fraction = {
                        "TT": 0.36,
                        "RR": 0.64,
                        "TR": 0.36,
                        "RT": 0.64,
                    }.get(selector_code, 0.5)
                elif matching_hit_positions:
                    hit_index = int(matching_hit_positions[0])
                    start_index = max(0, min(hit_index, points.shape[0] - 1))
                    end_index = max(0, min(hit_index + 1, points.shape[0] - 1))
                    marker_fraction = 0.5
                elif ray_matches_arm:
                    start_index = 1 if points.shape[0] > 2 else 0
                    end_index = min(points.shape[0] - 1, max(start_index + 1, points.shape[0] // 2))
                    marker_fraction = 0.5
                else:
                    continue
                p0 = np.asarray(points[start_index], dtype=float)
                p1 = np.asarray(points[end_index], dtype=float)
                if not np.all(np.isfinite(p0)) or not np.all(np.isfinite(p1)):
                    continue
                tangent = p1 - p0
                if np.linalg.norm(tangent) <= 1e-9:
                    tangent = np.asarray(points[-1], dtype=float) - np.asarray(points[0], dtype=float)
                if np.linalg.norm(tangent) <= 1e-9:
                    continue
                marker_fraction = min(max(float(marker_fraction), 0.05), 0.95)
                candidates.append((p0 + (p1 - p0) * marker_fraction, tangent))
            if not candidates:
                continue
            candidate_points = np.vstack([point for point, _tangent in candidates])
            median_point = np.median(candidate_points, axis=0)
            point, tangent = min(candidates, key=lambda candidate: float(np.linalg.norm(candidate[0] - median_point)))
            targets.append(
                {
                    "entry": entry,
                    "point": point,
                    "tangent": tangent,
                    "arm_index": arm_index,
                    "branch_code": "".join(self._branch_path_selector_sequence(target_path))[-2:] if target_path else "",
                }
            )
        return targets

    def _draw_arm_ray_labels(
        self,
        projected,
        catalog: list[dict[str, str]],
        view_key: str,
        palette: tuple[str, ...],
    ) -> set[str]:
        targets = self._arm_ray_label_targets(projected, catalog, view_key)
        if not targets:
            return set()
        x0, x1 = self.ax.get_xlim()
        y0, y1 = self.ax.get_ylim()
        x_min, x_max = min(float(x0), float(x1)), max(float(x0), float(x1))
        y_min, y_max = min(float(y0), float(y1)), max(float(y0), float(y1))
        span_x = max(x_max - x_min, 1.0)
        span_y = max(y_max - y_min, 1.0)
        labeled: set[str] = set()
        point_tolerance = max(5.0, 0.035 * min(span_x, span_y))
        clusters: list[dict[str, object]] = []
        for target in targets:
            point = np.asarray(target.get("point"), dtype=float)
            tangent = np.asarray(target.get("tangent"), dtype=float)
            tangent_norm = float(np.linalg.norm(tangent))
            if tangent_norm <= 1e-9:
                continue
            tangent = tangent / tangent_norm
            entry = target.get("entry")
            entry_key = str(entry.get("key", "") or "") if isinstance(entry, dict) else ""
            if entry_key.startswith("path|"):
                clusters.append(
                    {
                        "targets": [target],
                        "point": point,
                        "tangent": tangent,
                        "count": 1,
                    }
                )
                continue
            matched_cluster = False
            for cluster in clusters:
                cluster_point = np.asarray(cluster["point"], dtype=float)
                cluster_tangent = np.asarray(cluster["tangent"], dtype=float)
                same_line = abs(float(np.dot(tangent, cluster_tangent))) >= 0.985
                if same_line and float(np.linalg.norm(point - cluster_point)) <= point_tolerance:
                    cluster_targets = cluster["targets"]
                    if isinstance(cluster_targets, list):
                        cluster_targets.append(target)
                    count = int(cluster.get("count", 1)) + 1
                    cluster["count"] = count
                    cluster["point"] = cluster_point + (point - cluster_point) / float(count)
                    matched_cluster = True
                    break
            if not matched_cluster:
                clusters.append(
                    {
                        "targets": [target],
                        "point": point,
                        "tangent": tangent,
                        "count": 1,
                    }
                )

        output_port_index = 1
        for cluster in clusters:
            cluster_targets = cluster.get("targets")
            if not isinstance(cluster_targets, list) or not cluster_targets:
                continue
            point = np.asarray(cluster["point"], dtype=float)
            tangent = np.asarray(cluster["tangent"], dtype=float)
            branch_code = ""
            if len(cluster_targets) == 1:
                branch_code = str(cluster_targets[0].get("branch_code", "") or "").upper()
            branch_offsets = {
                "TT": np.array([0.060 * span_x, 0.048 * span_y], dtype=float),
                "RR": np.array([-0.060 * span_x, -0.048 * span_y], dtype=float),
                "TR": np.array([0.060 * span_x, -0.052 * span_y], dtype=float),
                "RT": np.array([0.060 * span_x, 0.052 * span_y], dtype=float),
            }
            if branch_code in branch_offsets:
                offset = branch_offsets[branch_code]
            else:
                # Put the text beside the ray, not on top of it. Horizontal
                # arms label above and downstream; vertical/folded arms label
                # to the right and downstream.
                if abs(float(tangent[0])) >= abs(float(tangent[1])):
                    downstream = 1.0 if float(tangent[0]) >= 0.0 else -1.0
                    offset = np.array([0.035 * span_x * downstream, 0.045 * span_y], dtype=float)
                else:
                    downstream = 1.0 if float(tangent[1]) >= 0.0 else -1.0
                    offset = np.array([0.045 * span_x, 0.035 * span_y * downstream], dtype=float)
            arm_index = min(int(target.get("arm_index", 0)) for target in cluster_targets)
            if not branch_code:
                offset *= 1.0 + 0.18 * (arm_index % 3)
            text_point = point + offset
            text_point[0] = min(max(float(text_point[0]), x_min + 0.03 * span_x), x_max - 0.03 * span_x)
            text_point[1] = min(max(float(text_point[1]), y_min + 0.04 * span_y), y_max - 0.04 * span_y)
            entries: list[dict[str, object]] = []
            for target in cluster_targets:
                entry = target.get("entry")
                if isinstance(entry, dict) and str(entry.get("key", "") or ""):
                    entries.append(entry)
            if not entries:
                continue
            is_branch_output = all(str(entry.get("key", "") or "").startswith("path|") for entry in entries)
            is_branch_group = len(entries) > 1 and is_branch_output
            color = "#334155" if is_branch_output else palette[arm_index % len(palette)]
            if len(entries) == 1:
                entry = entries[0]
                detail = str(entry.get("detail", "") or "").strip()
                short_label = str(entry.get("short_label", "") or "Path").strip()
                label = f"{short_label}: {detail}" if detail else short_label
            else:
                branch_codes = {
                    "".join(self._branch_path_selector_sequence(self._branch_path_for_arm_key(str(entry.get("key", "") or ""))))[-2:]
                    for entry in entries
                    if str(entry.get("key", "") or "").startswith("path|")
                }
                if branch_codes == {"TR", "RT"}:
                    title = "Detector output"
                elif branch_codes == {"TT", "RR"}:
                    title = "Source return"
                else:
                    title = f"Output {output_port_index}" if is_branch_group else "Shared ray"
                if is_branch_group:
                    output_port_index += 1
                lines = [title]
                for entry in entries[:5]:
                    detail = str(entry.get("detail", "") or "").strip()
                    short_label = str(entry.get("short_label", "") or "Path").strip()
                    lines.append(f"{short_label}: {detail}" if detail else short_label)
                if len(entries) > 5:
                    lines.append(f"+{len(entries) - 5} more")
                label = "\n".join(lines)
            self.ax.annotate(
                label,
                xy=(float(point[0]), float(point[1])),
                xytext=(float(text_point[0]), float(text_point[1])),
                color=color,
                fontsize=8,
                ha="center",
                va="center",
                zorder=82.0,
                clip_on=True,
                arrowprops={
                    "arrowstyle": "-|>",
                    "color": color,
                    "linewidth": 0.9,
                    "alpha": 0.9,
                    "shrinkA": 3,
                    "shrinkB": 2,
                },
                bbox={
                    "facecolor": "white",
                    "edgecolor": color,
                    "alpha": 0.86,
                    "boxstyle": "round,pad=0.25",
                    "linewidth": 0.8,
                },
            )
            for entry in entries:
                labeled.add(str(entry.get("key", "") or ""))
            self.ax.plot(
                [float(point[0])],
                [float(point[1])],
                marker="o",
                markersize=3.2,
                color="#111827" if branch_code else color,
                alpha=0.95,
                zorder=81.0,
            )
        return labeled

    def _common_arm_surface_indices(self) -> set[int]:
        indices = {0} if self.rows else set()
        if not self.rows:
            return indices
        index = 1
        while index < len(self.rows) - 1:
            start, end = self._element_block_for_index(self.rows, index)
            role = self._element_arm_role_for_index(self.rows, start)
            if role == "Common":
                indices.update(range(start, end + 1))
            index = max(end + 1, index + 1)
        return indices

    def _context_surface_indices_for_arm_key(self, arm_key: str) -> set[int]:
        leg_id = self._leg_id_from_arm_key(arm_key)
        if not leg_id:
            return self._common_arm_surface_indices()
        indices = {0} if self.rows else set()
        auto_entry = self._auto_leg_entry_for_id(leg_id)
        if auto_entry is not None:
            return indices | {
                int(index)
                for index in set(auto_entry.get("context_indices", set()) or set())
                if 0 <= int(index) < len(self.rows)
            }
        if self._physical_leg_workflow() != "mach_zehnder":
            return indices | self._common_arm_surface_indices()
        splitters = self._first_beam_splitter_indices()
        bs1 = splitters[0] if len(splitters) >= 1 else None
        bs2 = splitters[1] if len(splitters) >= 2 else None
        if leg_id in {"input", "transmit", "reflect"} and bs1 is not None:
            indices.add(bs1)
        if leg_id in {"transmit", "reflect", "cross", "return"} and bs2 is not None:
            indices.add(bs2)
        return indices

    def _default_parent_splitter_id(self) -> str:
        for index, row in enumerate(self.rows):
            if row.surface != BEAM_SPLITTER_SURFACE:
                continue
            metadata = self._element_metadata(row)
            return (
                str(metadata.get("element_id", "") or "").strip()
                or self._element_key(row)
                or str(row.name or f"S{index}").strip()
            )
        return ""

    def _splitter_id_by_ordinal(self, ordinal: int) -> str:
        target = int(ordinal)
        seen = 0
        for index, row in enumerate(self.rows):
            if row.surface != BEAM_SPLITTER_SURFACE:
                continue
            if seen != target:
                seen += 1
                continue
            metadata = self._element_metadata(row)
            return (
                str(metadata.get("element_id", "") or "").strip()
                or self._element_key(row)
                or str(row.name or f"S{index}").strip()
            )
        return self._default_parent_splitter_id()

    def _branch_selector_for_arm_key(self, arm_key: str) -> str:
        path = self._branch_path_for_arm_key(arm_key)
        if path:
            return self._branch_path_leaf_selector(path)
        leg_id = self._leg_id_from_arm_key(arm_key)
        if leg_id:
            workflow = self._physical_leg_workflow()
            if workflow == "mach_zehnder":
                return {
                    "input": "primary",
                    "transmit": "transmit",
                    "reflect": "reflect",
                    "cross": "transmit",
                    "return": "reflect",
                }.get(leg_id, "")
            if leg_id == "input":
                return "primary"
            if leg_id in {"reflect", "transmit"}:
                return leg_id
            if leg_id == "detector":
                return "reflect"
        parts = str(arm_key or "").split("|")
        if len(parts) >= 3 and parts[0] == "branch":
            selector = parts[2].strip().lower()
            if selector in {"transmit", "reflect", "primary", "return"}:
                return selector
        return ""

    def _ray_matches_arm_key(self, ray, arm_key: str) -> bool:
        key = str(arm_key or "").strip()
        if not key:
            return False
        if self._leg_id_from_arm_key(key):
            return False
        branch_path = str(getattr(ray, "branch_path", "") or "").strip()
        target_path = self._branch_path_for_arm_key(key)
        if target_path:
            return branch_path == target_path
        if branch_path and self._metadata_arm_key_matches_branch_path(key, branch_path):
            return True
        selector = self._branch_selector_for_arm_key(key)
        branch_label = str(getattr(ray, "branch_label", "") or "").strip().lower()
        return bool(selector and branch_label == selector)

    def _apply_arm_key_metadata_to_row(self, row: SurfaceRow, arm_key: str) -> None:
        label = self._next_manual_element_label()
        metadata = self._element_metadata_for_arm_key(arm_key, label)
        if metadata is None:
            return
        row.element = label
        self._set_element_metadata(row, metadata)

    def _projected_rays_for_leg_view(self, projected: ProjectedScene2D, arm_key: str) -> list[ProjectedRay2D]:
        leg_id = self._leg_id_from_arm_key(arm_key)
        if not leg_id:
            return []
        segment_data = self._physical_ray_leg_segments(projected)
        if segment_data is None:
            return []
        groups, _hub = segment_data
        rays: list[ProjectedRay2D] = []
        for segment_index, segment in enumerate(groups.get(leg_id, []) or []):
            ray = segment.get("ray")
            if ray is None:
                continue
            p0 = np.asarray(segment.get("p0"), dtype=float)
            p1 = np.asarray(segment.get("p1"), dtype=float)
            if p0.shape[0] < 2 or p1.shape[0] < 2:
                continue
            rays.append(
                ProjectedRay2D(
                    ray_index=int(getattr(ray, "ray_index", segment_index)),
                    field_index=int(getattr(ray, "field_index", 0)),
                    color=str(getattr(ray, "color", "#39FF14") or "#39FF14"),
                    points_2d=np.vstack([p0[:2], p1[:2]]),
                    reaches_image=bool(getattr(ray, "reaches_image", False)),
                    surface_ids=np.asarray(getattr(ray, "surface_ids", []), dtype=int),
                    branch_label=str(getattr(ray, "branch_label", "") or ""),
                    branch_path=str(getattr(ray, "branch_path", "") or ""),
                )
            )
        return rays

    def _filter_projected_scene_for_arm_view(self, projected: ProjectedScene2D) -> ProjectedScene2D:
        arm_key = self._arm_key_for_view_label(str(self.arm_view_var.get() or ARM_VIEW_DEFAULT))
        if not arm_key:
            return projected
        arm_indices = set(self._indices_for_arm_key(arm_key))
        allowed_indices = self._context_surface_indices_for_arm_key(arm_key) | self._surface_indices_for_arm_key(arm_key)

        curves = [
            curve
            for curve in projected.curves
            if int(curve.row_index) in allowed_indices
        ]
        labels = [
            label
            for label in projected.labels
            if label.row_index is not None and int(label.row_index) in allowed_indices
        ]
        pick_regions = [
            region
            for region in projected.pick_regions
            if int(region.row_index) in allowed_indices
        ]
        rays = self._projected_rays_for_leg_view(projected, arm_key)
        if not rays:
            for ray in projected.rays:
                surface_ids = set(np.asarray(getattr(ray, "surface_ids", []), dtype=int).ravel().tolist())
                if self._ray_matches_arm_key(ray, arm_key):
                    rays.append(ray)
                elif arm_indices and surface_ids & arm_indices:
                    rays.append(ray)

        bound_points: list[np.ndarray] = []
        for curve in curves:
            points = np.asarray(curve.points_2d, dtype=float)
            if points.ndim == 2 and points.shape[0]:
                bound_points.append(points)
        for ray in rays:
            points = np.asarray(ray.points_2d, dtype=float)
            if points.ndim == 2 and points.shape[0]:
                bound_points.append(points)
        bounds = BoundsRect.from_points(bound_points)
        return ProjectedScene2D(
            curves=curves,
            rays=rays,
            planes=list(projected.planes),
            labels=labels,
            pick_regions=pick_regions,
            bounds=bounds,
        )

    def _draw_cardinal_extent_marker(
        self,
        p0: np.ndarray,
        p1: np.ndarray,
        color: str,
        *,
        cap_half: float,
    ) -> list:
        tangent = np.asarray(p1, dtype=float) - np.asarray(p0, dtype=float)
        norm = np.linalg.norm(tangent)
        if norm <= 1e-12:
            return []
        tangent /= norm
        normal = np.array([-tangent[1], tangent[0]], dtype=float)
        normal /= max(np.linalg.norm(normal), 1e-12)
        artists = [
            self.ax.plot(
                [float(p0[0]), float(p1[0])],
                [float(p0[1]), float(p1[1])],
                color=color,
                linewidth=1.35,
                linestyle="-",
                alpha=0.95,
                zorder=70.0,
            )[0]
        ]
        for point in (np.asarray(p0, dtype=float), np.asarray(p1, dtype=float)):
            c0 = point - normal * cap_half
            c1 = point + normal * cap_half
            artists.append(
                self.ax.plot(
                    [float(c0[0]), float(c1[0])],
                    [float(c0[1]), float(c1[1])],
                    color=color,
                    linewidth=1.1,
                    linestyle="-",
                    alpha=0.95,
                    zorder=70.0,
                )[0]
            )
        return artists

    def _folded_path_plane_at_distance(self, path_distance: float) -> tuple[np.ndarray, np.ndarray] | None:
        if not np.isfinite(path_distance):
            return None
        try:
            point, direction, _max_half, _extent_points, elements = self._compute_folded_layout_geometry()
        except Exception:
            return None
        if not elements:
            return None
        vertices: list[tuple[float, np.ndarray]] = [(0.0, np.asarray(point, dtype=float).copy())]
        distance = 0.0
        for row_index, element in enumerate(elements, start=1):
            center = np.asarray(element[1], dtype=float)
            distance += max(float(self.rows[row_index - 1].thickness), 0.0)
            vertices.append((float(distance), center.copy()))
        s = float(path_distance)
        tolerance = max(1e-6, 1e-6 * max(vertices[-1][0], 1.0))
        if s < vertices[0][0] - tolerance or s > vertices[-1][0] + tolerance:
            return None
        s = min(max(s, vertices[0][0]), vertices[-1][0])
        for (d0, p0), (d1, p1) in zip(vertices, vertices[1:]):
            if s <= d1 + tolerance:
                span = max(d1 - d0, 1e-12)
                t = min(max((s - d0) / span, 0.0), 1.0)
                center = p0 + (p1 - p0) * t
                axis = p1 - p0
                norm = np.linalg.norm(axis)
                if norm <= 1e-12:
                    axis = np.asarray(direction, dtype=float)
                    norm = np.linalg.norm(axis)
                axis = axis / max(norm, 1e-12)
                tangent = np.array([-axis[1], axis[0]], dtype=float)
                tangent /= max(np.linalg.norm(tangent), 1e-12)
                return center, tangent
        return None

    def _draw_folded_optics_markers(self, optics_info: dict) -> bool:
        marker_specs = [
            ("Front PP", optics_info.get("h1_z"), None, "#ff9f1c"),
            ("Back PP", optics_info.get("h2_z"), None, "#ff9f1c"),
            ("EP", optics_info.get("ep_z"), optics_info.get("ep_radius"), "#00bcd4"),
            ("XP", optics_info.get("xp_z"), optics_info.get("xp_radius"), "#e91e63"),
        ]
        x0, x1 = self.ax.get_xlim()
        y0, y1 = self.ax.get_ylim()
        x_min, x_max = min(x0, x1), max(x0, x1)
        y_min, y_max = min(y0, y1), max(y0, y1)
        span_x = max(x_max - x_min, 1e-9)
        span_y = max(y_max - y_min, 1e-9)
        marker_half = max(2.0, min(0.09 * span_x, 0.16 * span_y))
        cap_half = max(0.8, min(0.025 * span_x, 0.035 * span_y))
        drawn = 0
        for index, (label, path_distance, half_length, color) in enumerate(marker_specs):
            if path_distance is None:
                continue
            plane = self._folded_path_plane_at_distance(float(path_distance))
            if plane is None:
                continue
            center, tangent = plane
            if not (x_min <= float(center[0]) <= x_max and y_min <= float(center[1]) <= y_max):
                continue
            use_extent = (
                label in {"EP", "XP"}
                and half_length is not None
                and np.isfinite(float(half_length))
                and float(half_length) > 1e-9
            )
            half_span = float(half_length) if use_extent else marker_half
            p0 = center - tangent * half_span
            p1 = center + tangent * half_span
            if use_extent:
                artists = self._draw_cardinal_extent_marker(
                    p0,
                    p1,
                    color,
                    cap_half=cap_half,
                )
            else:
                artists = [
                    self.ax.plot(
                        [p0[0], p1[0]],
                        [p0[1], p1[1]],
                        color=color,
                        linewidth=1.15,
                        linestyle=":",
                        alpha=0.95,
                        zorder=70.0,
                    )[0]
                ]
            normal = np.array([-tangent[1], tangent[0]], dtype=float)
            normal /= max(np.linalg.norm(normal), 1e-12)
            offsets = (0.030, 0.060, -0.040, 0.090)
            tangent_stagger = ((index % 2) - 0.5) * 0.75 * marker_half
            label_pos = center + normal * offsets[index % len(offsets)] * span_y + tangent * tangent_stagger
            label_pos[0] = min(max(float(label_pos[0]), x_min + 0.02 * span_x), x_max - 0.02 * span_x)
            label_pos[1] = min(max(float(label_pos[1]), y_min + 0.04 * span_y), y_max - 0.04 * span_y)
            text = self.ax.text(
                float(label_pos[0]),
                float(label_pos[1]),
                label,
                color=color,
                fontsize=8,
                ha="center",
                va="bottom",
                zorder=71.0,
                bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.65, "pad": 0.6},
            )
            self._cardinal_marker_artists.extend((*artists, text))
            drawn += 1
        return drawn > 0

    # --- Physical Distance overlay -------------------------------------------

    def _clear_physical_distance_artists(self) -> None:
        for artist in self._physical_distance_artists:
            try:
                artist.remove()
            except Exception:
                pass
        self._physical_distance_artists.clear()

    def _on_toggle_physical_distances(self) -> None:
        self._clear_physical_distance_artists()
        if not self.show_physical_distances_var.get():
            self.canvas.draw_idle()
            self.status_var.set("Physical distances hidden")
            return
        self._draw_physical_distances()
        self.canvas.draw_idle()
        self.status_var.set("Physical distances updated")
        self._autosave_plot()

    def _draw_physical_distances(self) -> None:
        self._clear_physical_distance_artists()
        if not self.show_physical_distances_var.get():
            return
        if not self.rows or len(self.rows) < 3:
            return

        # Find the housing datum surfaces by name (the mechanical barrel edges).
        # These are flat reference planes — not the optical element edges.
        z_positions: list[float] = [0.0]
        z = 0.0
        for row in self.rows[:-1]:
            z += float(row.thickness)
            z_positions.append(z)
        if len(z_positions) < len(self.rows):
            z_positions.append(z)

        housing_front_z: float | None = None
        housing_rear_z: float | None = None
        for i, row in enumerate(self.rows):
            name_lower = row.name.lower()
            if housing_front_z is None and "front" in name_lower and "datum" in name_lower:
                housing_front_z = z_positions[i]
            if housing_rear_z is None and "rear" in name_lower and "datum" in name_lower:
                housing_rear_z = z_positions[i]

        # Fallback: use first/last optical surface edge if no datum surfaces
        if housing_front_z is None:
            for i, row in enumerate(self.rows):
                if row.surface not in {"Object", "Image", "Aperture"}:
                    housing_front_z = z_positions[i]
                    break
        if housing_front_z is None:
            return

        object_z = 0.0
        image_z = self._current_image_plane_z()
        camera_front_z = image_z - self._current_camera_front_to_sensor_mm()

        # Get plot bounds for positioning the arrows
        x0, x1 = self.ax.get_xlim()
        y0, y1 = self.ax.get_ylim()
        span_y = abs(y1 - y0)
        span_x = abs(x1 - x0)

        orientation = self._current_display_orientation()
        color_obj = "#2196f3"   # blue for object-to-front
        color_cam = "#4caf50"   # green for front-to-camera
        color_edge = "#ff5722"  # orange-red for camera edge marker
        color_led = "#f59e0b"   # amber for object-to-LED edge

        dist1 = abs(housing_front_z - object_z)
        dist2 = abs(camera_front_z - housing_front_z)
        led_edge_z: float | None = None
        led_dist = 0.0
        if self.imported_led_step_path is not None:
            try:
                led_dist = max(float(getattr(self, "led_object_edge_distance_mm", 0.0)), 0.0)
                led_edge_z = object_z + led_dist if led_dist > 1e-9 else None
            except Exception:
                led_edge_z = None

        if orientation == "Horizontal":
            _, obj_proj = self._project_xy([object_z], [0.0])
            _, front_proj = self._project_xy([housing_front_z], [0.0])
            _, cam_proj = self._project_xy([camera_front_z], [0.0])

            obj_y = float(obj_proj[0])
            front_y = float(front_proj[0])
            cam_y = float(cam_proj[0])

            # Both arrows at the same x offset (side by side)
            arrow_x = x0 + 0.08 * span_x

            # Object to Front Datum
            ann1 = self.ax.annotate(
                "", xy=(arrow_x, front_y), xytext=(arrow_x, obj_y),
                arrowprops=dict(arrowstyle="<->", color=color_obj, lw=1.8, shrinkA=0, shrinkB=0),
                zorder=72.0,
            )
            txt1 = self.ax.text(
                arrow_x + 0.01 * span_x, (obj_y + front_y) / 2.0,
                f"{dist1:.1f} mm",
                color=color_obj, fontsize=8, ha="left", va="center", zorder=73.0,
                bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.7, "pad": 0.6},
            )
            self._physical_distance_artists.extend((ann1, txt1))

            # Front Datum to Camera Front
            ann2 = self.ax.annotate(
                "", xy=(arrow_x, cam_y), xytext=(arrow_x, front_y),
                arrowprops=dict(arrowstyle="<->", color=color_cam, lw=1.8, shrinkA=0, shrinkB=0),
                zorder=72.0,
            )
            txt2 = self.ax.text(
                arrow_x + 0.01 * span_x, (front_y + cam_y) / 2.0,
                f"{dist2:.1f} mm",
                color=color_cam, fontsize=8, ha="left", va="center", zorder=73.0,
                bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.7, "pad": 0.6},
            )
            self._physical_distance_artists.extend((ann2, txt2))

            # Camera edge indicator line
            cam_line = self.ax.axhline(cam_y, color=color_edge, linewidth=1.2, linestyle="--", alpha=0.9, zorder=70.0)
            cam_label = self.ax.text(
                x0 + 0.04 * span_x, cam_y,
                "Camera Edge",
                color=color_edge, fontsize=8, ha="left", va="bottom", zorder=71.0,
                bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.65, "pad": 0.6},
            )
            self._physical_distance_artists.extend((cam_line, cam_label))

            if led_edge_z is not None:
                _, led_proj = self._project_xy([led_edge_z], [0.0])
                led_y = float(led_proj[0])
                led_arrow_x = x0 + 0.16 * span_x
                ann_led = self.ax.annotate(
                    "", xy=(led_arrow_x, led_y), xytext=(led_arrow_x, obj_y),
                    arrowprops=dict(arrowstyle="<->", color=color_led, lw=1.8, shrinkA=0, shrinkB=0),
                    zorder=74.0,
                )
                txt_led = self.ax.text(
                    led_arrow_x + 0.01 * span_x, (obj_y + led_y) / 2.0,
                    f"LED {led_dist:.1f} mm",
                    color=color_led, fontsize=8, ha="left", va="center", zorder=75.0,
                    bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.72, "pad": 0.6},
                )
                led_line = self.ax.axhline(led_y, color=color_led, linewidth=1.2, linestyle="--", alpha=0.9, zorder=70.0)
                led_label = self.ax.text(
                    x0 + 0.04 * span_x, led_y,
                    "LED Edge",
                    color=color_led, fontsize=8, ha="left", va="top", zorder=71.0,
                    bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.65, "pad": 0.6},
                )
                self._physical_distance_artists.extend((ann_led, txt_led, led_line, led_label))
        else:
            # Vertical orientation: z is the x-axis, y is transverse
            # Both arrows at the same y offset (side by side)
            arrow_y = y0 + 0.08 * span_y
            led_arrow_y = y0 + 0.16 * span_y

            # Object to Lens Front Edge
            ann1 = self.ax.annotate(
                "", xy=(housing_front_z, arrow_y), xytext=(object_z, arrow_y),
                arrowprops=dict(arrowstyle="<->", color=color_obj, lw=1.8, shrinkA=0, shrinkB=0),
                zorder=72.0,
            )
            txt1 = self.ax.text(
                (object_z + housing_front_z) / 2.0, arrow_y + 0.01 * span_y,
                f"{dist1:.1f} mm",
                color=color_obj, fontsize=8, ha="center", va="bottom", zorder=73.0,
                bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.7, "pad": 0.6},
            )
            self._physical_distance_artists.extend((ann1, txt1))

            # Lens Front Edge to Camera Front
            ann2 = self.ax.annotate(
                "", xy=(camera_front_z, arrow_y), xytext=(housing_front_z, arrow_y),
                arrowprops=dict(arrowstyle="<->", color=color_cam, lw=1.8, shrinkA=0, shrinkB=0),
                zorder=72.0,
            )
            txt2 = self.ax.text(
                (housing_front_z + camera_front_z) / 2.0, arrow_y + 0.01 * span_y,
                f"{dist2:.1f} mm",
                color=color_cam, fontsize=8, ha="center", va="bottom", zorder=73.0,
                bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.7, "pad": 0.6},
            )
            self._physical_distance_artists.extend((ann2, txt2))

            # Camera edge indicator line
            cam_line = self.ax.axvline(camera_front_z, color=color_edge, linewidth=1.2, linestyle="--", alpha=0.9, zorder=70.0)
            cam_label = self.ax.text(
                camera_front_z, y1 - 0.05 * span_y,
                "Camera Edge",
                color=color_edge, fontsize=8, ha="center", va="top", zorder=71.0,
                bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.65, "pad": 0.6},
            )
            self._physical_distance_artists.extend((cam_line, cam_label))

            if led_edge_z is not None:
                ann_led = self.ax.annotate(
                    "", xy=(led_edge_z, led_arrow_y), xytext=(object_z, led_arrow_y),
                    arrowprops=dict(arrowstyle="<->", color=color_led, lw=1.8, shrinkA=0, shrinkB=0),
                    zorder=74.0,
                )
                txt_led = self.ax.text(
                    (object_z + led_edge_z) / 2.0, led_arrow_y + 0.01 * span_y,
                    f"LED {led_dist:.1f} mm",
                    color=color_led, fontsize=8, ha="center", va="bottom", zorder=75.0,
                    bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.72, "pad": 0.6},
                )
                led_line = self.ax.axvline(led_edge_z, color=color_led, linewidth=1.2, linestyle="--", alpha=0.9, zorder=70.0)
                led_label = self.ax.text(
                    led_edge_z, y1 - 0.11 * span_y,
                    "LED Edge",
                    color=color_led, fontsize=8, ha="center", va="top", zorder=71.0,
                    bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.65, "pad": 0.6},
                )
                self._physical_distance_artists.extend((ann_led, txt_led, led_line, led_label))

    # _set_plot_limits_from_layout removed — now in scene_renderer_2d.set_plot_limits

    def _set_plot_limits_from_drawn_data(self) -> None:
        x_values: list[float] = []
        y_values: list[float] = []
        for line in self.ax.lines:
            xdata = np.asarray(line.get_xdata(orig=False), dtype=float)
            ydata = np.asarray(line.get_ydata(orig=False), dtype=float)
            finite = np.isfinite(xdata) & np.isfinite(ydata)
            if np.any(finite):
                x_values.extend(xdata[finite].tolist())
                y_values.extend(ydata[finite].tolist())
        if not x_values or not y_values:
            return
        x_min = min(x_values)
        x_max = max(x_values)
        y_min = min(y_values)
        y_max = max(y_values)
        span_x = max(x_max - x_min, 1.0)
        span_y = max(y_max - y_min, 1.0)
        self.ax.set_xlim(x_min - 0.08 * span_x, x_max + 0.08 * span_x)
        self.ax.set_ylim(y_min - 0.12 * span_y, y_max + 0.12 * span_y)

    def _draw_input_ray_overlay(self, max_radius: float) -> None:
        if not self.rows:
            return
        if self._current_object_mode() == "Infinity":
            return
        object_distance = self._current_object_distance()
        if object_distance <= 1e-9:
            return
        field_samples = self._sample_field_values(self._current_field_height())
        angle_samples = self._sample_fan_angles_deg()
        colors = self._field_colors(len(field_samples))
        for field_index, field_height in enumerate(field_samples):
            color = colors[field_index]
            for angle_deg in angle_samples:
                angle_rad = np.deg2rad(angle_deg)
                pupil_y = float(field_height) + float(np.tan(angle_rad) * object_distance)
                x_vals, y_vals = self._project_xy([0.0, object_distance], [float(field_height), float(pupil_y)])
                self.ax.plot(
                    x_vals,
                    y_vals,
                    color=color,
                    linewidth=1.8,
                    alpha=0.95,
                )

    @staticmethod
    def _gaussian_radius_from_q(q_value: complex, wavelength_mm: float, m2: float, refractive_index: float) -> float:
        if not (np.isfinite(q_value.real) and np.isfinite(q_value.imag)) or abs(q_value) <= 1e-18:
            return np.nan
        inverse_q = 1.0 / q_value
        imag_inverse = float(np.imag(inverse_q))
        if imag_inverse >= 0.0:
            return np.nan
        return float(np.sqrt(-(wavelength_mm * m2) / (np.pi * max(float(refractive_index), 1e-12) * imag_inverse)))

    def _draw_gaussian_beam_overlay(self, system, wavelength: float) -> float | None:
        if self._current_source_model() != "Gaussian beam":
            return None
        source_direction = np.asarray(self._current_source_direction(), dtype=float)
        if np.linalg.norm(source_direction - np.asarray((0.0, 0.0, 1.0), dtype=float)) > 1e-9:
            self.append_debug(
                "Gaussian beam envelope skipped for non-+Z source direction; "
                "use traced source rays and Gaussian Beam Report data."
            )
            return None
        if any(row.surface == "Mirror" for row in self.rows) or self._has_off_axis_geometry():
            self.append_debug("Gaussian beam envelope skipped for folded/off-axis geometry; use Gaussian Beam Report for ABCD data.")
            return None
        try:
            paraxial_trace = system.ParaxMatrices(float(wavelength))
            input_beam = self._current_gaussian_beam_input(wavelength)
            beam_trace = Kos.propagate_gaussian_beam(paraxial_trace, input_beam)
        except Exception as exc:
            self.append_debug(f"Gaussian beam overlay unavailable: {_short_error_message(exc)}")
            return None

        wavelength_mm = float(beam_trace.wavelength_mm)
        m2 = float(input_beam.m2)
        current_z = 0.0
        source_x, source_y, source_z = self._current_source_origin()
        _unused_source_x = source_x
        q_before = complex(beam_trace.input_q)
        n_current = float(beam_trace.input_index)
        z_values: list[float] = [float(source_z)]
        radius_values: list[float] = [
            self._gaussian_radius_from_q(q_before, wavelength_mm, m2, n_current)
        ]

        for parax_step, beam_step in zip(paraxial_trace.steps, beam_trace.steps):
            q_after = complex(float(beam_step.q_real_mm), float(beam_step.q_imag_mm))
            n_after = max(float(beam_step.n_after), 1e-12)
            if str(getattr(parax_step, "kind", "")) == "translation":
                thickness = float(getattr(parax_step, "thickness", 0.0))
                sample_count = max(2, min(32, int(abs(thickness) / 5.0) + 2))
                for offset in np.linspace(0.0, thickness, sample_count)[1:]:
                    q_sample = q_before + float(offset)
                    z_values.append(float(source_z + current_z + float(offset)))
                    radius_values.append(self._gaussian_radius_from_q(q_sample, wavelength_mm, m2, n_after))
                current_z += thickness
            else:
                z_values.append(float(source_z + current_z))
                radius_values.append(self._gaussian_radius_from_q(q_after, wavelength_mm, m2, n_after))
            q_before = q_after
            n_current = n_after

        z_arr = np.asarray(z_values, dtype=float)
        r_arr = np.asarray(radius_values, dtype=float)
        finite = np.isfinite(z_arr) & np.isfinite(r_arr) & (r_arr >= 0.0)
        if np.count_nonzero(finite) < 2:
            return None
        z_arr = z_arr[finite]
        r_arr = r_arr[finite]
        y_center = float(source_y)
        upper_x, upper_y = self._project_xy(z_arr, y_center + r_arr)
        lower_x, lower_y = self._project_xy(z_arr, y_center - r_arr)
        center_x, center_y = self._project_xy(z_arr, np.full_like(z_arr, y_center))
        color = "#f59e0b"
        self.ax.plot(upper_x, upper_y, color=color, linewidth=1.8, linestyle="-", alpha=0.92, zorder=31.0)
        self.ax.plot(lower_x, lower_y, color=color, linewidth=1.8, linestyle="-", alpha=0.92, zorder=31.0)
        self.ax.plot(center_x, center_y, color=color, linewidth=0.85, linestyle=":", alpha=0.75, zorder=30.0)
        if self._current_display_orientation() == "Vertical":
            self.ax.fill_between(
                z_arr,
                y_center - r_arr,
                y_center + r_arr,
                color=color,
                alpha=0.08,
                linewidth=0.0,
                zorder=29.0,
            )
        label_index = min(max(int(len(z_arr) * 0.12), 0), len(z_arr) - 1)
        self.ax.text(
            float(upper_x[label_index]),
            float(upper_y[label_index]),
            "Gaussian 1/e^2",
            color=color,
            fontsize=8,
            ha="left",
            va="bottom",
            zorder=61.0,
            bbox={"facecolor": "white", "edgecolor": "none", "alpha": 0.7, "pad": 0.4},
        )
        return float(np.max(np.abs(y_center) + r_arr))

    def _apply_example_display_defaults(self, path: Path) -> None:
        code = path.read_text(encoding="utf-8", errors="ignore")
        self._apply_interferometer_example_defaults(path)

        wavelength_match = re.search(r"\bW\s*=\s*([0-9]*\.?[0-9]+)", code)
        if wavelength_match:
            self.wavelength_var.set(wavelength_match.group(1))

        aperture_type_match = re.search(r"\b(?:AperType|ApType)\s*=\s*['\"](STOP|EPD|FNO)['\"]", code)
        if aperture_type_match:
            self.aperture_type_var.set(aperture_type_match.group(1))

        aperture_value_match = re.search(r"\b(?:AperVal|ApVal)\s*=\s*([0-9]*\.?[0-9]+)", code)
        if aperture_value_match:
            self.aperture_value_var.set(aperture_value_match.group(1))

        surf_match = re.search(r"\b(?:Surf|sup)\s*=\s*([0-9]+)", code)
        if surf_match:
            surf_index = surf_match.group(1)
            label = None
            for option in self.analysis_surface_menu["values"]:
                if option.startswith(f"{surf_index}:"):
                    label = option
                    break
            if label is not None:
                self.analysis_surface_var.set(label)
            else:
                self.analysis_surface_var.set("Auto")
        else:
            self.analysis_surface_var.set("Auto")

        if self._example_requests_nonsequential(code) and hasattr(self, "trace_mode_var"):
            self.trace_mode_var.set("Non-Sequential Preview")
            self.trace_mode = "Non-Sequential Preview"

    def _apply_interferometer_example_defaults(self, path: Path) -> None:
        stem = path.stem.lower()
        is_michelson = stem == "examp_michelson_interferometer"
        is_twyman = stem == "examp_twyman_green_interferometer"
        is_mach_zehnder = stem == "examp_mach_zehnder_interferometer"
        if not (is_michelson or is_twyman or is_mach_zehnder):
            return

        def _set_text_var(name: str, value: str) -> None:
            var = getattr(self, name, None)
            if var is not None:
                try:
                    var.set(value)
                except Exception:
                    pass

        _set_text_var("object_mode_var", "Infinity")
        _set_text_var("display_orientation_var", "Vertical")
